RG.HK["23"] = [{"id":"23_nagoya_jo","n":"名古屋城（金鯱と本丸御殿）","yomi":"なごやじょう","cat":"城","rank":"S","y":1612,"era":["edo","showa","heisei"],"sh":"国指定特別史跡","ad":"名古屋市中区本丸","st":"地下鉄名城線 市役所駅から歩いて約5分","la":35.1856,"lo":136.899,"hook":"天守のてっぺんで光る «金鯱»。尾張名古屋は城でもつ、とうたわれた徳川の巨城は、空襲で焼けてもなお名古屋の顔であり続けている。","lead":"名古屋城は、徳川家康が全国の大名に手伝わせて築いた大きなお城です。家康の子・徳川義直が住み、江戸時代を通して尾張徳川家の城でした。1945年の空襲で天守と本丸御殿は焼けましたが、天守は1959年に再建され、本丸御殿は2018年に木造で復元されました。","story":["1610年、家康は大坂の豊臣家ににらみをきかせるため、尾張に新しい城を築くと決めました。工事を命じられたのは、加藤清正や福島正則など西国の大名たち。«なぜ自分の家来でなく他の大名に?» 答えは、お金と人手を出させて力を弱めるため。これを «天下普請» といいます。石垣には、どの大名が運んだかを示す «刻印» が今もたくさん残っています。","城ができると、それまで尾張の中心だった清洲の町は、家も寺も町人も、まるごと名古屋へ引っ越しました。これが «清洲越し»。«思いがけない名古屋ができて、花の清洲は野となろう» とうたわれたと伝わります。名古屋城の «西北隅櫓» は、清洲城の天守などの材木を使ったといわれ、«清洲櫓» とも呼ばれます。","天守の屋根に輝く «金鯱» は、火事を防ぐおまじないとされる想像上の魚です。江戸時代、財政が苦しくなった尾張藩は金鯱の金の純度を下げて改鋳したともいわれます。明治になると金鯱は城から下ろされ、1873年のウィーン万国博覧会にも出品されました。海を渡った «城の魚» は、名古屋の自慢の宝でした。","1930年、名古屋城は城として初めて当時の国宝に指定されます。けれども1945年5月14日の空襲で、天守と本丸御殿は燃えてしまいました。焼け跡に立った市民の «もう一度天守を» という願いから、1959年に鉄骨鉄筋コンクリートの天守が再建されます。その費用の一部は市民の寄付でまかなわれました。","本丸御殿は、将軍が泊まるときにも使われた豪華な建物でした。空襲の前に写真や実測図が残され、ふすま絵の多くは外して疎開させていたため焼けずにすみました。その記録をもとに、2009年から木造での復元が始まり、2018年に全体が公開されました。天守は木造で建て直す計画が進められており、2018年から中に入れなくなっています。"],"tl":[["1610年","家康が名古屋城の築城を命じる（天下普請）"],["1612年","天守がほぼ完成"],["1615年","本丸御殿が完成し、徳川義直が入る"],["1873年","金鯱がウィーン万国博覧会に出品される"],["1930年","城として初めて当時の国宝に指定"],["1945年5月14日","空襲で天守・本丸御殿が焼失"],["1959年","天守が再建される"],["2018年","本丸御殿の復元が完成し全面公開。天守は閉館"]],"who":[["徳川家康","築城を命じた。大坂の豊臣家に備える拠点とした"],["徳川義直","家康の九男。尾張藩の初代藩主"],["加藤清正","天守台の石垣づくりを担当したと伝わる"],["柿木金助","金鯱の鱗を盗もうとした大泥棒として芝居で有名になった人物。話の多くは創作"]],"deep":["«特別史跡»: 名古屋城跡は1952年に国の特別史跡に指定。焼け残った西南隅櫓・東南隅櫓・西北隅櫓や表二之門などは国の重要文化財です。","石垣の刻印: 丸や三角、家紋のような印が石に刻まれています。持ち場の境目を示したり、石を取られないように目印にしたと考えられています。","金鯱の盗難事件: 1937年、本物の金鯱の鱗が盗まれる事件が実際に起きました。江戸時代の «柿木金助» の話は芝居や講談による創作が大きい話です。","本丸御殿の «上洛殿» は、3代将軍家光が京都へ上るときの宿として1634年に増築された部分。絵や彫刻が特にぜいたくです。","再建天守は外観を元の姿に近づけていますが、中はエレベーターのある博物館でした。木造復元をめぐっては、エレベーターをつけるかどうかなど、バリアフリーをめぐる議論も続いています。","焼失前に撮られた大量のガラス乾板写真と、昭和初期の実測図は、日本の城の復元でも特に詳しい記録として知られます。"],"look":["本丸御殿の玄関から上洛殿へ続くふすま絵と欄間","天守台の石垣と刻印（石に彫られた印をさがしてみよう）","清洲櫓とも呼ばれる西北隅櫓","堀に残る石垣の «反り» と、空襲で焼けた跡が残る石"],"q":["名古屋城の本丸御殿が木造で正確に復元できたのはなぜ?","空襲の前に写真と実測図がたくさん残され、ふすま絵の多くも外して避難させていたから。"],"koji":[{"w":"尾張名古屋は城でもつ","m":"名古屋の町の誇りは名古屋城にある、という意味。伊勢音頭の一節として知られる"}],"myth":"清洲櫓が清洲城の材木を使ったという話、柿木金助の話は伝承・創作を含む。","img":["本丸御殿","金鯱","徳川義直"],"wp":"名古屋城","rel":{"ev":[],"grave":[]},"ph":[["c:5/56/Nagoya_Castle_7.jpg",5957,3964,"名古屋城"],["c:9/93/Tokugawa_Yoshinao.jpg",808,657,"徳川義直"]]},{"id":"23_atsuta_jingu","n":"熱田神宮（草薙剣と信長塀）","yomi":"あつたじんぐう","cat":"寺社","rank":"S","y":113,"era":["kofun","azuchi","meiji"],"sh":"","ad":"名古屋市熱田区神宮1丁目","st":"名鉄 神宮前駅から歩いて約3分／地下鉄名城線 神宮西駅から約7分","la":35.1277,"lo":136.9087,"hook":"三種の神器のひとつ «草薙剣» をまつる森。桶狭間へ向かう信長も、ここで勝利を祈った。","lead":"熱田神宮は、ヤマトタケルノミコトが残した «草薙剣» をまつると伝わる、とても古い神社です。名古屋の人は «熱田さん» と呼んで親しんでいます。織田信長が戦いの前に勝利を祈り、お礼に寄進した «信長塀» も残っています。","story":["むかし、ヤマトタケルノミコトは東の国へ戦いに出るとき、草を薙ぎはらって火攻めから身を守った剣を持っていたと伝わります。これが «草薙剣»。帰り道、尾張で妻となったミヤズヒメのもとに剣を置いたまま伊吹山へ向かい、病に倒れてしまいました。ミヤズヒメが剣をまつったのが熱田神宮の始まり、と伝えられています。","«日本書紀» には、668年に新羅の僧・道行が草薙剣を盗み出して国外へ持ち出そうとしたが、嵐で失敗したと書かれています。その後、剣はしばらく宮中に置かれました。ところが天武天皇が病気になると «草薙剣のたたり» と占われ、686年に熱田へ戻されたと記録されています。","1560年5月、今川義元の大軍が尾張に攻めこみました。清洲城を出た織田信長は、まず熱田に立ち寄り、兵が集まるのを待ちながら勝利を祈ったと «信長公記» は伝えます。«このわずかな兵で本当に勝てるのか?» そんな不安の中で、信長は何を願ったのでしょう。桶狭間で勝った信長は、お礼として土と瓦を重ねた塀を寄進しました。これが «信長塀» です。","熱田の神職の家からは、源頼朝の母・由良御前が出ています。熱田大宮司・藤原季範の娘で、頼朝は熱田で生まれたという説もあります。1945年の空襲で社殿は焼けましたが、1955年に再建されました。今も初詣や祭りに多くの人が集まる、名古屋を代表する «鎮守の森» です。"],"tl":[["伝承","ミヤズヒメが草薙剣をまつったのが始まりと伝わる"],["668年","草薙剣が盗み出されるが取り戻される（日本書紀）"],["686年","天武天皇の病のため、草薙剣が熱田に戻される（日本書紀）"],["1147年","源頼朝が生まれる。母は熱田大宮司の娘"],["1560年","信長が桶狭間の戦いの前に戦勝を祈る"],["1893年","社殿を伊勢神宮と同じ神明造に改める"],["1945年","空襲で社殿が焼失"],["1955年","社殿が再建される"]],"who":[["日本武尊","草薙剣を持って東征したと伝わる英雄"],["宮簀媛","尾張の姫。草薙剣をまつったと伝わる"],["織田信長","桶狭間の戦い前に祈り、勝利後に塀を寄進"],["由良御前","源頼朝の母。熱田大宮司・藤原季範の娘"]],"deep":["«信長塀» は、兵庫・西宮神社の «大練塀»、京都・三十三間堂の «太閤塀» と並んで «日本三大土塀» といわれます。","草薙剣は神体として奥深くにまつられ、見ることはできません。天皇の即位のときの «剣璽» の «剣» は形代（身代わり）とされています。","もとの社殿は «尾張造» という独特の形でしたが、明治時代に伊勢神宮と同じ «神明造» に改められました。","境内の «大楠» は、弘法大師（空海）が植えたと伝わる大木。樹齢は1000年を超えるといわれます。","宝物館（草薙館）には、刀剣類など多くの奉納品が収められ、国宝や重要文化財も含まれています。","5月4日の «酔笑人神事»（通称 «オホホ祭り»）は、神職が灯りを消した闇の中で笑い合う、いっぷう変わった神事です。草薙剣が熱田に戻ったことを喜ぶ祭りと伝わります。"],"look":["信長塀（本宮へ向かう参道の近く）","大楠（弘法大師お手植えと伝わる）","本宮と、その手前の神楽殿","宝物館（草薙館）の刀剣","境内の «清水社» など、森の中の小さな社"],"q":["信長塀は、何のお礼に信長が寄進したものと伝わる?","桶狭間の戦いの勝利のお礼。戦いの前、信長は熱田で勝利を祈ったとされます。"],"koji":[{"w":"草を薙ぐ","m":"草をなぎはらうこと。草薙剣の名の由来になった伝説から"}],"myth":"創建の年（113年とされる）、草薙剣の伝説、頼朝の熱田生誕説は伝承・諸説。","img":["草薙剣","ヤマトタケル","宮簀媛"],"wp":"熱田神宮","rel":{"ev":["okehazama_r"],"grave":[]},"ph":[["c:7/71/Atsuta-jingu_Shrine_Haiden%2C_Jingu_Atsuta_Ward_Nagoya_2023.jpg",1500,1000,"熱田神宮"],["c:3/3e/Yamato_Takeru%28bronze_statue%2COsaka%2901.jpg",768,1024,"ヤマトタケル"]]},{"id":"23_okehazama","n":"桶狭間古戦場（今川義元討死の地）","yomi":"おけはざまこせんじょう","cat":"古戦場","rank":"S","y":1560,"era":["muromachi"],"sh":"国指定史跡","ad":"豊明市栄町南舘","st":"名鉄 中京競馬場前駅から歩いて約5分","la":35.0548,"lo":136.98,"hook":"数では何倍もの今川軍。27歳の信長は、どしゃ降りの雨のあとに大将・今川義元の本陣をついた。","lead":"1560年、駿河の今川義元が大軍で尾張に攻めこみ、織田信長の軍にやぶれて命を落としました。これが «桶狭間の戦い»。信長が一気に有名になった戦いです。戦いの場所とされる地は、豊明市と名古屋市緑区の2か所にあります。","story":["1560年5月、今川義元は駿河・遠江・三河の兵をひきいて西へ進みました。兵の数は2万を超えたともいわれます。尾張の織田信長は、兵が少なく、家臣たちは «城にこもって守りましょう» と言いました。けれども信長は何も決めないまま夜を過ごしたと «信長公記» は伝えています。","夜明け前、丸根砦と鷲津砦が今川軍に攻められたという知らせが届きます。信長は «敦盛» の «人間五十年、下天のうちをくらぶれば…» を舞い、立ったまま食事をとって、わずかな家来と清洲城を飛び出しました。途中の熱田神宮で祈り、善照寺砦、中島砦と進むうちに兵が集まります。丸根砦を攻めたのは、今川方にいた若き松平元康、のちの徳川家康でした。","昼ごろ、激しい雨が降り出しました。«雨がやんだら突っこめ»。信長の軍は、休んでいた義元の本陣に向かってまっすぐ攻めかかりました。義元の旗本は崩れ、義元は服部小平太に槍をつけられ、毛利新介に討ち取られたと «信長公記» にあります。大将を失った今川軍は国へ引き上げました。","«なぜ少ない兵で勝てたのか?» 昔は «山道を回りこんで奇襲した» と語られてきました。しかし «信長公記» を読み直すと、正面から攻めかかったと読めるという説が出て、今も議論が続いています。この戦いのあと、家康は今川から独立し、信長と手を結びます。日本の歴史の流れを変えた一日でした。"],"tl":[["1560年5月12日","今川義元が駿府を出発したとされる"],["1560年5月18日","松平元康が大高城に兵糧を運び入れる"],["1560年5月19日未明","丸根砦・鷲津砦が攻められる。信長が清洲城を出陣"],["1560年5月19日昼","豪雨のあと信長軍が本陣を攻め、義元が討死"],["1562年ごろ","信長と家康が手を結ぶ（清洲同盟）。年は諸説"],["1937年","豊明市の «桶狭間古戦場伝説地» が国の史跡に"]],"who":[["今川義元","駿河・遠江・三河を治めた大名。この戦いで討死"],["織田信長","尾張の大名。27歳でこの戦いに勝つ"],["松平元康（徳川家康）","今川方として大高城に兵糧を入れ、丸根砦を攻めた"],["毛利新介","義元を討ち取ったと «信長公記» に記される織田の武士"],["服部小平太","義元に最初に槍をつけたとされる"]],"deep":["2つの古戦場: 豊明市の «桶狭間古戦場伝説地»（国指定史跡）と、名古屋市緑区の «桶狭間古戦場公園» があり、どちらが本当の討死の地かは今も議論があります。","兵の数: 今川軍は «4万5千» とする史料もありますが、誇張ではないかという見方が強く、2万5千前後とする説などがあります。織田軍は2〜3千ほどとされます。","奇襲か正面攻撃か: 江戸時代の軍記物で広まった «迂回奇襲説» に対し、«信長公記» の記述から «正面攻撃説» が唱えられ、議論が続いています。","豊明の史跡には、今川方の武将が倒れた場所を示すといわれる «七石表» が立っています。江戸時代に建てられた石柱です。","«桶狭間» は谷あいの地名で、«田楽狭間» と呼ばれる場所で休んでいたという話も軍記物にあります。","義元の首は、のちに今川方へ返されたと伝わります。三河の東向寺など、首塚と伝わる場所があります。"],"look":["豊明市の史跡公園にある «今川義元墓» と «七石表»","名古屋市緑区の桶狭間古戦場公園の義元・信長の銅像","近くの高徳院（今川義元の本陣跡と伝わる）","丸根砦・鷲津砦の跡（名古屋市緑区）"],"q":["桶狭間の戦いのとき、のちの徳川家康はどちらの軍にいた?","今川軍。松平元康の名で大高城に兵糧を運び入れ、丸根砦を攻めました。"],"koji":[{"w":"人間五十年、下天のうちをくらぶれば、夢幻のごとくなり","m":"人の一生は、天の世界の時間に比べれば夢のように短い。信長が出陣前に舞った «敦盛» の一節"}],"myth":"討死の場所、兵の数、奇襲か正面攻撃かは諸説。田楽狭間の休息や首塚の話は伝承。","img":["今川義元","織田信長","信長公記"],"wp":"桶狭間の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"],["c:1/10/ImagawaYoshimoto.jpg",600,675,"今川義元"],["c:5/5a/Oda_Nobunaga_Kaou_3.jpg",249,164,"織田信長"]]},{"id":"23_shitaragahara","n":"設楽原古戦場（馬防柵と鉄砲隊）","yomi":"したらがはらこせんじょう","cat":"古戦場","rank":"S","y":1575,"era":["azuchi"],"sh":"","ad":"新城市竹広","st":"JR飯田線 三河東郷駅から歩いて約15分（設楽原歴史資料館）","la":34.9176,"lo":137.5347,"hook":"小川をはさんで延びる木の柵。その向こうから、武田の騎馬武者が次々に押し寄せた。","lead":"1575年、織田信長・徳川家康の連合軍が、武田勝頼の軍とこの設楽原で戦いました。一般に «長篠の戦い» と呼ばれる戦いです。連合軍は «馬防柵» という木の柵を作り、鉄砲をたくさん使って武田軍を破りました。","story":["1575年5月、武田勝頼は1万5千ほどの兵で三河に入り、長篠城を取り囲みました。城を守るのは奥平信昌と500ほどの兵。助けを求められた家康は信長に援軍をたのみ、両軍は長篠城の西、設楽原に陣をかまえます。","信長は、連吾川という小さな川にそって、木の柵を長く作らせました。これが «馬防柵»。柵のうしろには鉄砲を持った兵をならべます。«なぜ柵を?» 騎馬や足軽の突撃を止め、そこへ鉄砲を撃ちこむためでした。一方、信長は家康の家臣・酒井忠次に別動隊をあずけ、夜のうちに山を越えて長篠城を見張る鳶ヶ巣山砦を落とさせました。","5月21日の朝、うしろの砦を失った武田軍は、前に出るしかなくなります。山県昌景、馬場信春、内藤昌秀（昌豊）ら、信玄の時代から戦ってきた名将たちが次々に柵へ攻めかかり、ついに討死しました。戦いは昼すぎまで続き、武田軍は大きな損害を出して引き上げました。","この戦いは «鉄砲の時代を開いた戦い» といわれます。ただ、よく語られる «3000丁の鉄砲を三段に分けて撃った» という話には、確かな史料が少なく、今は疑問視する研究者も多くいます。設楽原には、敵味方の戦死者をとむらう塚がいくつも残り、地元の人々が長く供養を続けてきました。"],"tl":[["1575年5月","武田勝頼が長篠城を包囲"],["1575年5月18日","織田・徳川軍が設楽原に着陣"],["1575年5月20日夜","酒井忠次の別動隊が鳶ヶ巣山砦へ向かう"],["1575年5月21日","設楽原で決戦。武田軍が敗れる"],["1582年","武田氏が滅亡"],["1996年","新城市設楽原歴史資料館が開館"]],"who":[["織田信長","連合軍の大将。馬防柵と鉄砲で戦う"],["徳川家康","三河の大名。長篠城を助けるため信長と出陣"],["武田勝頼","信玄の子。この戦いで多くの重臣を失う"],["酒井忠次","家康の重臣。鳶ヶ巣山砦を奇襲した"],["山県昌景","武田の重臣。この戦いで討死"]],"deep":["«長篠の戦い» と «設楽原の戦い»: 決戦の場所は長篠城から西へ数kmの設楽原のため、地元では «設楽原の戦い» と呼ぶことも多いです。","鉄砲の数: «信長公記» には «千挺ばかり» とあり、«3000丁» は江戸時代の «甫庵信長記» などに出てくる数字です。","三段撃ち: 鉄砲隊が3列で入れかわって撃ったという話は、後の書物で広まったもので、実際にそうしたかは議論があります。","«武田の騎馬隊» も、当時の武田軍が馬に乗った兵だけで突撃する部隊を持っていたかどうかは疑問とされています。","新城市には «信玄塚»（大塚・小塚）があり、戦死者をまとめて葬ったと伝わります。夏には «火おんどり» という供養の行事が行われています。","連吾川ぞいに馬防柵が再現されていて、柵から敵陣までの距離感を体で感じることができます。"],"look":["連吾川ぞいに再現された馬防柵","設楽原歴史資料館（鉄砲の展示が充実）","信玄塚（大塚・小塚）","武将たちの戦死の地に立つ碑"],"q":["設楽原で織田・徳川軍が作った、敵の突撃をふせぐ木の柵を何という?","馬防柵。柵のうしろから鉄砲で攻撃しました。"],"koji":[],"myth":"鉄砲の数・三段撃ち・騎馬隊の実態、両軍の兵数は諸説。","img":["武田勝頼","酒井忠次","山県昌景"],"wp":"長篠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"],["c:e/e6/Sakai_Tadatsugu.jpg",710,595,"酒井忠次"],["c:0/0a/Yamagata_Masakage2.jpg",973,1455,"山県昌景"]]},{"id":"23_okazaki_jo","n":"岡崎城（徳川家康誕生の城）","yomi":"おかざきじょう","cat":"城","rank":"S","y":1542,"era":["muromachi","azuchi","edo"],"sh":"","ad":"岡崎市康生町","st":"愛知環状鉄道 中岡崎駅から歩いて約5分／名鉄 東岡崎駅から約15分","la":34.9562,"lo":137.159,"hook":"1542年の暮れ、この城で竹千代が生まれた。のちに260年続く江戸幕府を開く、徳川家康である。","lead":"岡崎城は、徳川家康が生まれた城です。家康の祖父・松平清康が本拠とし、家康も若いころここを拠点に三河をまとめました。今の天守は1959年に再建されたもので、城のまわりは岡崎公園になっています。","story":["岡崎城は、室町時代に西郷氏が築いた城が始まりとされます。のちに松平清康がここへ移り、松平家の本拠にしました。1542年12月26日、清康の孫として城内で竹千代が生まれます。のちの徳川家康です。城内には、産湯に使ったと伝わる «東照公産湯の井戸» が残っています。","けれども竹千代の子ども時代は苦労の連続でした。6歳で人質として送られる途中、織田方に連れ去られ、その後は今川家の駿府で暮らします。岡崎城には今川家の家来が入り、城主のいない岡崎の家臣たちは、苦しい暮らしにたえて主君の帰りを待ちました。","1560年、桶狭間で今川義元が討たれると、19歳の家康（当時は元康）は、今川の兵が引き上げた岡崎城に戻ります。«捨て城ならば拾おう» と言って入ったと伝わる場面です。ここから家康は三河の大名として歩き始め、信長と手を結びました。","1570年、家康は浜松へ移り、岡崎城は長男・信康にまかせます。しかし1579年、信康は自害に追いこまれました。理由は今も諸説あります。江戸時代、岡崎は «神君出生の城» として大切にされ、譜代大名が城主をつとめました。明治に入り建物は取りこわされ、1959年に天守が再建されました。"],"tl":[["15世紀中ごろ","西郷氏が築いた城が始まりとされる（年代は諸説）"],["1530年ごろ","松平清康が本拠とする"],["1542年12月26日","竹千代（徳川家康）が誕生"],["1560年","桶狭間の戦いのあと、家康が岡崎城に戻る"],["1570年","家康が浜松へ移り、信康が城主に"],["1617年","本多康紀が三重の天守を建てたとされる"],["1873年ごろ","廃城となり建物が取りこわされる"],["1959年","天守が再建される"]],"who":[["徳川家康","この城で生まれ、若いころの本拠とした"],["松平清康","家康の祖父。岡崎城を松平家の本拠にした"],["松平広忠","家康の父。岡崎城主"],["於大の方","家康の母。家康が幼いころに離縁され実家に戻る"],["松平信康","家康の長男。岡崎城主となるが自害"]],"deep":["«東照公産湯の井戸» と、家康のへその緒（胞衣）を埋めたと伝わる «東照公えな塚» が城内にあります。","信康事件: 信長の命令で信康が自害させられたという話が長く語られてきましたが、近年は家康と信康の対立など家中の問題を重く見る説もあります。","再建天守は、江戸時代の三重の天守の姿を参考に1959年に建てられた鉄筋コンクリート造。中は歴史資料館です。","城の近くには «三河武士のやかた家康館»（家康館）があり、家康と三河武士の歴史を紹介しています。","江戸時代の岡崎は東海道の宿場町でもあり、城下では道を何度も曲げた «二十七曲り» が作られました。敵の進みを遅らせる工夫といわれます。"],"look":["東照公産湯の井戸・えな塚","再建天守の最上階からの眺め","城の石垣と堀（龍城堀など）","三河武士のやかた家康館","若き家康の銅像"],"q":["徳川家康の子どものころの名前は?","竹千代。岡崎城で生まれ、のちに人質として他国で暮らしました。"],"koji":[{"w":"厭離穢土欣求浄土","m":"けがれたこの世を離れ、極楽浄土を願い求めるという意味。家康が旗印に使った言葉"}],"myth":"«捨て城ならば拾おう» の言葉、築城年、信康事件の真相は伝承・諸説。","img":["徳川家康","松平清康","松平信康"],"wp":"岡崎城","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Okazakijo-3-cropped.jpg",2621,1704,"岡崎城"],["c:5/5f/Matsudaira_Kiyoyasu.jpg",1552,3037,"松平清康"],["c:2/22/Matsudaira_Nobuyasu.jpg",790,1649,"松平信康"]]},{"id":"23_inuyama_jo","n":"犬山城（現存最古級の国宝天守）","yomi":"いぬやまじょう","cat":"城","rank":"S","y":1537,"era":["muromachi","azuchi","edo"],"sh":"国宝","ad":"犬山市犬山北古券","st":"名鉄 犬山遊園駅から歩いて約15分／犬山駅から約20分","la":35.3884,"lo":136.9392,"hook":"木曽川の崖の上に400年以上立ち続ける天守。2004年まで、日本でただ一つ «個人が持つ城» だった。","lead":"犬山城は、江戸時代かそれ以前に建てられた天守が今も残る «現存天守» のひとつで、国宝に指定された5つの城の一つです。木曽川を見下ろす高い崖の上に立ち、«白帝城» という別名もあります。","story":["犬山城は、1537年に織田信長の叔父・織田信康が築いたとされます。尾張と美濃の境目、木曽川のほとりにあるこの場所は、昔から戦いの要でした。信長の時代、そして豊臣秀吉と徳川家康が争った1584年の小牧・長久手の戦いでは、秀吉がこの城に入って本陣の足がかりにしました。","1617年、尾張藩の家老・成瀬正成が城主になりました。以後、明治まで成瀬家が代々この城を守ります。城から見下ろす木曽川は、中国の長江のほとりにある白帝城をよんだ詩を思わせることから、«白帝城» と呼ばれるようになったと伝わります。","明治になると多くの城が取りこわされましたが、犬山城の天守は残りました。1891年の濃尾地震で天守の一部がこわれると、«修理することを条件に» 愛知県から旧城主の成瀬家に譲られます。«なぜ城を個人に?» 当時の県には修理するお金がなく、地元の人々の願いもあって成瀬家が引き受けたのです。こうして犬山城は、2004年に財団法人へ移るまで、個人が持つ城でした。","天守の4階にはぐるりと回れる «廻縁» があり、手すりの外は崖と木曽川。足がすくむほどの眺めです。天守がいつ建てられたかは長く議論されてきましたが、近年の調査で、使われている木材が1580年代後半に切られたことがわかり、天守の建築もそれ以降と考えられるようになりました。"],"tl":[["1537年","織田信康が築いたとされる"],["1584年","小牧・長久手の戦いで羽柴秀吉が入城"],["1617年","成瀬正成が城主となり、以後成瀬家が代々治める"],["1891年","濃尾地震で天守の一部が損壊"],["1895年","修理を条件に成瀬家に譲与される"],["1952年","天守が国宝に指定される"],["2004年","財団法人犬山城白帝文庫の所有となる"]],"who":[["織田信康","信長の叔父。犬山城を築いたとされる"],["成瀬正成","尾張藩の付家老。犬山城主となった成瀬家の初代"],["豊臣秀吉","小牧・長久手の戦いで犬山城に入った"],["荻生徂徠","江戸時代の学者。«白帝城» の名づけ親と伝わる"]],"deep":["国宝の天守は犬山城・姫路城・松本城・彦根城・松江城の5つ。犬山城天守は1935年に当時の国宝、1952年に今の国宝に指定されました。","天守の建築年代は «1537年説»«1601年ごろ説» などさまざまでした。2019年ごろ公表された年輪年代調査で、部材の伐採が1585〜1590年ごろとわかり、議論が大きく進みました。","天守は外から見ると3重、中は地上4階・地下2階。石垣の中に地下階があるつくりです。","最上階の «廻縁» と «高欄» は、戦のためというより眺めをよくする飾りの意味が強いとされます。","城下町には江戸時代の町割りが残り、からくり人形をのせた山車が出る «犬山祭» は、ユネスコ無形文化遺産 «山・鉾・屋台行事» の一つです。"],"look":["天守4階の廻縁から見る木曽川と濃尾平野","天守内部の急な階段と太い梁","石垣の «野面積み»","城下町の町並み（どんでん館など）"],"q":["明治以降、犬山城が長く «個人の城» だったのはなぜ?","1891年の濃尾地震でこわれた天守を修理する条件で、旧城主の成瀬家に譲られたから。"],"koji":[],"myth":"築城者・築城年、«白帝城» の名づけ親を荻生徂徠とする話は伝承・諸説。","img":["成瀬正成","濃尾地震","犬山祭"],"wp":"犬山城","rel":{"ev":[],"grave":[]},"ph":[["c:4/4d/Inuyama_Castle_%281%29%2C_Kitakoken_Inuyama_Inuyama_City_2023.jpg",1500,1000,"犬山城"],["c:2/20/Naruse_Masanari.jpg",1018,878,"成瀬正成"],["c:3/3d/PSM_V47_D323_Cause_of_the_great_earthquake_in_central_japan_1891.jpg",2507,1681,"濃尾地震"],["c:4/40/Inuyamajo2.JPG",4608,3456,"犬山祭"]]},{"id":"23_kiyosu_jo","n":"清洲城（信長の本拠と清洲会議）","yomi":"きよすじょう","cat":"城","rank":"S","y":1555,"era":["muromachi","azuchi"],"sh":"","ad":"清須市朝日城屋敷","st":"JR東海道線 清洲駅から歩いて約15分／名鉄 新清洲駅から約15分","la":35.2176,"lo":136.8447,"hook":"信長が天下への一歩をふみ出した城。本能寺の変のあと、織田家のゆくえを決める会議もここで開かれた。","lead":"清洲城は、尾張の守護の城として始まり、織田信長が本拠にした城です。桶狭間の戦いへも、この城から出陣しました。江戸時代のはじめに町ごと名古屋へ引っ越したため、城は «跡» となり、今ある天守は1989年に建てられた模擬天守です。","story":["清洲は、尾張の真ん中を流れる五条川のほとりにあります。室町時代、尾張の守護・斯波氏が守護所を置き、城が築かれたとされます。のちに守護代の織田氏が力をのばし、1555年、若き信長が清洲城を手に入れて本拠にしました。","1560年5月、今川義元が攻めてきたとき、信長はこの城で «敦盛» を舞ってから出陣したと伝わります。勝利のあと、今川から独立した徳川家康と手を結びました。これを «清洲同盟» と呼びます。家康が清洲城を訪れて約束したという話もありますが、どのような形で結ばれたかは諸説あります。","1582年、本能寺の変で信長と長男・信忠が亡くなると、この城に柴田勝家、羽柴秀吉、丹羽長秀、池田恒興が集まりました。«織田家のあとつぎを誰にするか?» 話し合いの結果、信忠の子でまだ幼い三法師が選ばれ、それを支えた秀吉が力をのばしていきます。これが «清洲会議» です。","その後、信長の次男・信雄が城を大きく改修し、福島正則や家康の子・松平忠吉らが城主をつとめました。けれども1610年ごろから名古屋城が築かれると、町も城も名古屋へ移る «清洲越し» が行われ、清洲城は役目を終えました。今の模擬天守は、1989年に旧清洲町の町制100周年を記念して建てられたものです。"],"tl":[["1405年ごろ","守護・斯波義重が築いたとされる"],["1555年","織田信長が清洲城を本拠とする"],["1560年","信長が桶狭間へ出陣"],["1563年","信長が小牧山城へ移る"],["1582年","清洲会議が開かれる"],["1610年ごろ","«清洲越し» で町ごと名古屋へ移り、廃城に"],["1989年","模擬天守が建てられる"]],"who":[["織田信長","清洲城を本拠に尾張を統一した"],["羽柴秀吉","清洲会議で三法師を立て、主導権をにぎった"],["柴田勝家","織田家の重臣。清洲会議に出席"],["三法師（織田秀信）","信長の孫。清洲会議で織田家の跡継ぎとされた"],["福島正則","秀吉の家臣。のちに清洲城主"]],"deep":["模擬天守の位置: 今の模擬天守は五条川の西側にありますが、本来の本丸は川の東側の «清洲公園» 付近。そこに «清洲古城跡» の碑があります。","清洲会議で三法師を跡継ぎにしたのは、史料から見ると «もともと決まっていた筋» だったのではという見方もあり、秀吉がどこまで主導したかは議論があります。","«清須» と «清洲»: 市の名前は «清須市»、城の名前は «清洲城» と書かれることが多く、昔の史料でも両方の書き方が見られます。","発掘調査で、信雄の時代の石垣の跡や、城下町の遺構が見つかっています。","名古屋城の西北隅櫓は «清洲櫓» と呼ばれ、清洲城の建物の材木を使ったと伝わります。"],"look":["模擬天守からの眺めと展示","五条川の対岸の «清洲古城跡»（清洲公園）","信長と濃姫の像","川にかかる朱色の大手橋"],"q":["本能寺の変のあと清洲城で開かれ、織田家の跡継ぎを決めた話し合いを何という?","清洲会議。信長の孫・三法師が跡継ぎとされました。"],"koji":[],"myth":"築城年、清洲同盟の形、清洲会議の中身については諸説。今の天守は史実の天守を再現したものではない模擬天守。","img":["清洲会議","清洲同盟","三法師"],"wp":"清洲城","rel":{"ev":["kiyosu","okehazama_r"],"grave":[]},"ph":[["c:9/98/%E6%B8%85%E6%B4%B2%E5%9F%8E%E5%85%AC%E5%9C%92%E5%81%B4%E3%81%8B%E3%82%89%E3%81%AE%E6%B8%85%E6%B4%B2%E5%9F%8E.jpg",3828,2871,"清洲城"],["c:f/fc/Toyotomi_hideyoshi5.jpg",1000,1372,"清洲会議"],["c:e/ec/Oda_Hidenobu-2.jpg",2000,3700,"三法師"]]},{"id":"23_komakiyama","n":"小牧山城（信長の城と家康の本陣）","yomi":"こまきやまじょう","cat":"城","rank":"S","y":1563,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"小牧市堀の内","st":"名鉄小牧線 小牧駅から歩いて約20分","la":35.2926,"lo":136.912,"hook":"平野にぽつんと立つ小さな山。信長はここに石垣の城を築き、20年後には家康が秀吉とにらみ合った。","lead":"小牧山城は、織田信長が1563年に清洲から移って築いた城です。わずか4年ほどで岐阜へ移りましたが、発掘で本格的な石垣が見つかり、«信長の城づくりの出発点» として注目されています。1584年の小牧・長久手の戦いでは、徳川家康が本陣を置きました。","story":["小牧山は、高さ86mほどの小さな山。まわりは平らで、山の上からは美濃の方までよく見えます。1563年、信長は清洲城を出て、この山に新しい城を築きました。«なぜ引っ越したのか?» 北の美濃を攻めるための前線基地にするためと考えられています。","信長の家臣たちは、はじめ移転をいやがったといいます。«信長公記» には、信長がまず不便な山を移転先として示し、あとで小牧山ならまだ近いと思わせて、家臣たちを納得させたという話が書かれています。信長らしい人の動かし方です。","発掘調査で、山の上の方が大きな石を使った石垣で何段にも囲まれていたことがわかりました。山のふもとには、まっすぐな道で区切られた城下町も作られていました。のちの岐阜城、そして安土城へつながる «見せる城» の工夫が、ここから始まっていたのです。","1567年、信長が美濃を手に入れて岐阜へ移ると、小牧山城は使われなくなります。けれども1584年、羽柴秀吉と徳川家康・織田信雄が戦った小牧・長久手の戦いで、家康がこの山に本陣を置きました。土塁や堀を築き直し、秀吉の大軍と長くにらみ合ったのです。","今の小牧山は、木々におおわれた市民の公園です。けれども足もとには、信長の石垣と家康の土塁という、2人の天下人の跡が重なって眠っています。小牧市は長年発掘を続け、その成果をふもとの情報館で紹介しています。山を歩くと、«ここから美濃をにらんだ信長は、何を考えていたのだろう?» と思わずにはいられません。"],"tl":[["1563年","信長が清洲から小牧山に城を移す"],["1567年","信長が美濃を攻め取り、岐阜へ移る"],["1584年","小牧・長久手の戦いで家康が本陣を置く"],["1927年","国の史跡に指定"],["1968年","山頂に小牧市歴史館（模擬天守）ができる"],["2019年","ふもとに «れきしるこまき»（小牧山城史跡情報館）が開館"]],"who":[["織田信長","美濃攻めのため小牧山に城を築いた"],["徳川家康","小牧・長久手の戦いで本陣を置いた"],["羽柴秀吉","小牧山の家康と対峙した"],["織田信雄","信長の次男。家康と組んで秀吉と戦った"]],"deep":["小牧山城の石垣は、信長が築いた城の中でも早い時期の本格的な石垣として注目されています。大きな石を2段、3段と重ねています。","城下町は、短冊形に区切られた町割りの跡が発掘で確認されています。","山頂の «小牧市歴史館» は、京都の飛雲閣をモデルにした建物で、史実の天守ではありません。","小牧・長久手の戦いでは、家康が築き直した土塁や堀が山のまわりに残っていて、信長時代の遺構と重なっています。","«信長公記» に出てくる «二宮山» への移転の話は、家臣を動かす信長の知恵として有名です。"],"look":["山頂近くの石垣（発掘成果の展示）","れきしるこまき（小牧山城史跡情報館）","山頂の小牧市歴史館からの眺め","家康時代の土塁と堀の跡"],"q":["信長が小牧山に城を移したのは、どこの国を攻めるためと考えられている?","美濃（今の岐阜県南部）。1567年に美濃を攻め取り、岐阜へ移りました。"],"koji":[],"myth":"移転の理由や «信長公記» の二宮山の話の解釈には諸説。","img":["小牧・長久手の戦い","織田信長","小牧山"],"wp":"小牧山城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d9/Komakiyama_04.JPG",2048,981,"小牧山城"],["c:7/74/Komaki_Nagakute_Kassen_Zu_Byoubu%2C_Toyota.jpg",3274,1426,"小牧・長久手の戦い"],["c:5/5a/Oda_Nobunaga_Kaou_3.jpg",249,164,"織田信長"]]},{"id":"23_nagakute","n":"長久手古戦場（秀吉軍を家康が破る）","yomi":"ながくてこせんじょう","cat":"古戦場","rank":"S","y":1584,"era":["azuchi"],"sh":"国指定史跡","ad":"長久手市武蔵塚","st":"リニモ 長久手古戦場駅から歩いてすぐ","la":35.1766,"lo":137.0551,"hook":"秀吉と家康が一度だけ直接ぶつかった戦い。ここで家康は、天下人となる秀吉に一泡ふかせた。","lead":"1584年、羽柴秀吉と、徳川家康・織田信雄の連合軍が戦ったのが «小牧・長久手の戦い» です。長久手では、三河へ攻めこもうとした秀吉方の軍を家康が追いかけて打ち破り、池田恒興や森長可を討ち取りました。","story":["本能寺の変のあと、力をのばす秀吉に対し、信長の次男・信雄は家康をたよりました。1584年3月、両軍は尾張で向き合います。家康は小牧山に、秀吉は犬山や楽田に陣を置き、どちらも堀や土塁を築いてにらみ合いました。","動いたのは秀吉方です。池田恒興が «家康が小牧にいる間に、手うすな三河の岡崎を攻めては» と申し出たといわれます。秀吉の甥・羽柴秀次を大将に、池田恒興・森長可・堀秀政らの軍がこっそり南東へ向かいました。これを «三河中入り» と呼びます。","けれども家康はこの動きをつかみ、ひそかに小牧山を出て後を追いました。4月9日の朝、白山林で休んでいた秀次の軍を襲って打ち破ります。一方、先を行く池田軍は途中の岩崎城を落としていましたが、引き返して長久手で家康の本隊とぶつかりました。激しい戦いの末、池田恒興とその子・元助、森長可が討死しました。","長久手の戦いは家康の勝利でしたが、全体の戦いはその後、秀吉が信雄と和睦して終わります。«戦いに勝って政治で負けた» ともいわれる結末でした。それでも、秀吉に勝った武将としての家康の名は高まり、のちの天下取りにつながったといわれます。"],"tl":[["1584年3月","小牧・長久手の戦いが始まる。家康が小牧山に布陣"],["1584年4月9日朝","白山林で羽柴秀次の軍が敗れる"],["1584年4月9日","岩崎城が落ちる。長久手で池田恒興・森長可が討死"],["1584年11月","秀吉と織田信雄が和睦"],["1939年","«長久手古戦場 附 御旗山・首塚・色金山» が国の史跡に"]],"who":[["徳川家康","秀吉方の三河中入り軍を追撃して勝利"],["羽柴秀吉","家康と戦うが、のちに信雄と和睦"],["池田恒興","三河中入りを提案したとされ、長久手で討死"],["森長可","恒興の娘婿。鬼武蔵と呼ばれた猛将。長久手で討死"],["羽柴秀次","秀吉の甥。中入り軍の大将だったが白山林で敗れる"]],"deep":["古戦場公園には、池田恒興の討死の地とされる «勝入塚»（恒興の号が勝入）や、森長可の «武蔵塚»、池田元助の «庄九郎塚» があります。","«血の池公園» は、戦いのあと武将たちが血のついた槍や刀を洗ったため池が赤く染まったと伝わる場所です。","国の史跡の範囲は、古戦場のほか、家康が旗を立てたと伝わる «御旗山»、戦死者を葬ったとされる «首塚»、家康が本陣を置いた «色金山» なども含みます。","岩崎城（日進市）の戦いでは、城を守った丹羽氏重が討死しています。岩崎城には今、展望台風の模擬天守があります。","三河中入りを誰が言い出したかについては、池田恒興の提案とする話が有名ですが、秀吉自身の作戦だったとする見方もあります。","戦いの年、秀吉は48歳ごろ、家康は42歳ごろ。のちに家康は秀吉に臣従しますが、長久手での勝利は、豊臣政権の中で家康が特別な重みを持つ理由の一つになったといわれます。"],"look":["古戦場公園の勝入塚・庄九郎塚","武蔵塚（森長可が討たれた地と伝わる）","血の池公園","近くの色金山歴史公園と御旗山"],"q":["長久手の戦いで討死した «鬼武蔵» と呼ばれた武将は?","森長可。池田恒興の娘婿で、勇猛な武将として知られました。"],"koji":[],"myth":"血の池の話、三河中入りの提案者、塚の位置は伝承・諸説。","img":["池田恒興","森長可","岩崎城"],"wp":"小牧・長久手の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Komaki_Nagakute_Kassen_Zu_Byoubu%2C_Toyota.jpg",3274,1426,"小牧・長久手の戦い"],["c:8/86/Ikeda_Tsuneoki.jpg",1029,1873,"池田恒興"],["c:1/1a/Mori_Nagayoshi.jpg",272,497,"森長可"]]},{"id":"23_daijuji","n":"大樹寺（松平家菩提寺・「厭離穢土欣求浄土」）","yomi":"だいじゅじ","cat":"寺社","rank":"S","y":1475,"era":["muromachi","edo"],"sh":"国の重要文化財（多宝塔など）","ad":"岡崎市鴨田町広元","st":"名鉄 東岡崎駅から名鉄バスで «大樹寺» 下車、歩いてすぐ","la":34.9782,"lo":137.16,"hook":"桶狭間で敗れ、祖先の墓の前で死のうとした19歳の家康。その命を救ったのは、住職の一言だった。","lead":"大樹寺は、徳川家の祖先・松平家の菩提寺です。桶狭間の戦いのあと、ここに逃げこんだ若い家康が自害しようとしたとき、住職に «厭離穢土欣求浄土» の教えを説かれて思いとどまったと伝わります。歴代将軍の位牌がまつられています。","story":["大樹寺は1475年、松平家の4代目・松平親忠が建てた浄土宗の寺です。«大樹» とは、中国で将軍を指すことば。のちに松平家から将軍が出ることを思うと、ふしぎな縁を感じる名前です。境内には松平家の8代の墓が並んでいます。","1560年5月、桶狭間の戦いで今川義元が討たれました。今川方として戦っていた19歳の松平元康（のちの家康）は、敵に追われながら岡崎へ逃れ、この大樹寺に入ったと伝わります。«もはやこれまで» と、先祖の墓の前で腹を切ろうとしたとき、住職の登誉上人が止めました。","«厭離穢土欣求浄土»。けがれた世を離れ、浄土を願い求めよ。登誉上人は、«この乱れた世を浄土のように平和にするのが、あなたの役目ではないか» と説いたといわれます。家康はこの言葉を旗印にかかげ、生涯戦ったと伝わります。寺に迫った追っ手を、祖洞という力持ちの僧がかんぬきをふるって追い払ったという話も残っています。","江戸時代、大樹寺は徳川家から大切にされ、3代将軍家光が大きく建て直しました。本堂から山門・総門をまっすぐ通して、約3km南の岡崎城が見えるようにしたといわれます。この見通しは今も守られ、«ビスタライン» と呼ばれています。","境内は静かで、観光客でにぎわう岡崎城とはちがう空気が流れています。多宝塔の前に立つと、家康の祖父の時代から続く松平家の歴史が身近に感じられます。ここで生きる道を選び直した若者が、やがて戦乱を終わらせる幕府を開いたと思うと、この寺の重みがよくわかります。"],"tl":[["1475年","松平親忠が大樹寺を建てる"],["1535年","松平清康が多宝塔を建てる"],["1560年","桶狭間の戦いのあと家康が逃れ、登誉上人に諭される"],["1641年ごろ","徳川家光が伽藍を大きく再建"],["江戸時代","歴代将軍の位牌がまつられる"]],"who":[["松平親忠","松平家4代。大樹寺を建てた"],["登誉上人","大樹寺の住職。家康に «厭離穢土欣求浄土» を説いた"],["徳川家康","桶狭間のあと大樹寺で命を救われたと伝わる"],["徳川家光","3代将軍。大樹寺を再建した"]],"deep":["多宝塔は、家康の祖父・松平清康が1535年に建てたもので、国の重要文化財。戦国時代の建物がそのまま残る貴重な例です。","位牌堂には徳川歴代将軍の位牌がまつられ、その高さはそれぞれの将軍の亡くなったときの身長と同じだといわれます。将軍の体格を推定する手がかりとして話題になりますが、確かかどうかは議論があります。","«ビスタライン»: 大樹寺から岡崎城天守を見通す線上に高い建物を建てないよう、岡崎市は景観のルールを定めています。","«厭離穢土欣求浄土» は、平安時代の源信の «往生要集» に出てくる浄土教の言葉です。","家康が逃げこんだときの話は、江戸時代にまとめられた伝記などに出てくるもので、細かい場面は伝承です。"],"look":["多宝塔（国の重要文化財）","松平八代の墓","山門から岡崎城天守を望むビスタライン","位牌堂の歴代将軍の位牌（公開時期に注意）"],"q":["家康が旗印にした «厭離穢土欣求浄土» を説いた大樹寺の住職は?","登誉上人。桶狭間の戦いのあと、自害しようとした家康を止めたと伝わります。"],"koji":[{"w":"厭離穢土欣求浄土","m":"けがれた世を離れ、極楽浄土を心から願い求めること。家康の旗印として有名"}],"myth":"家康が自害しようとした話、祖洞の話、位牌の高さが身長と同じという話は伝承。","img":["松平親忠","厭離穢土欣求浄土","松平氏"],"wp":"大樹寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Daijuji_sanmon.jpg",6048,4024,"大樹寺"]]},{"id":"23_asahi_iseki","n":"朝日遺跡（弥生の巨大環濠集落）","yomi":"あさひいせき","cat":"遺跡","rank":"S","y":-200,"era":["yayoi"],"sh":"国指定史跡","ad":"清須市朝日貝塚（あいち朝日遺跡ミュージアム）","st":"最寄りの鉄道駅から歩いて20〜30分ほど。清須市の巡回バスや車が便利","la":35.2093,"lo":136.8555,"hook":"逆さにした木の枝と、斜めに打ちこんだ杭。2000年以上前のムラは、まるで要塞のように守られていた。","lead":"朝日遺跡は、清須市と名古屋市西区にまたがる、弥生時代の大きなムラの跡です。まわりを深い堀で囲んだ «環濠集落» で、東海地方で最大級とされます。見つかった土器や道具のうち2000点以上が国の重要文化財になっています。","story":["今から2000年以上前、この辺りは海に近い湿地でした。人々は米づくりをしながら、魚や貝もとって暮らしていました。ムラは少しずつ大きくなり、東西およそ1.4km、南北およそ0.8kmの範囲に遺跡が広がっています。","朝日遺跡でとくに有名なのは、ムラを守る仕かけです。ムラのまわりに何重もの堀をめぐらし、その外側に、枝を外に向けて並べた «逆茂木»、斜めに打ちこんだたくさんの杭 «乱杭» を置いていました。«なぜこんなに厳重に?» 弥生時代は、米や土地をめぐってムラどうしが争うこともあった時代だったと考えられています。","遺跡が本格的に掘られたのは、1970年代に道路（名古屋環状2号線）を作ることになってからでした。工事の前の調査で、土器、石器、木の道具、骨や角で作った道具などが大量に見つかりました。湿った土のおかげで、ふつうなら腐ってしまう木の道具もよく残っていたのです。","見つかった品々のうち2028点は、2012年に国の重要文化財に指定されました。2020年には «あいち朝日遺跡ミュージアム» がオープンし、実物の出土品や、逆茂木・乱杭を再現した屋外展示を見ることができます。ムラの一部だった «貝殻山貝塚» は、国の史跡として公園になっています。","弥生時代の人たちは、文字を残していません。でも、捨てられた貝がらや、使い古した道具、ていねいにかざられた土器が、«どんなものを食べ、どんなふうに暮らしていたか» を教えてくれます。朝日遺跡は、名古屋の町のすぐそばで弥生の暮らしを想像できる場所です。"],"tl":[["弥生時代前期","ムラが営まれ始める"],["弥生時代中期","環濠や逆茂木・乱杭など、ムラを守る設備が作られる"],["1971年","貝殻山貝塚が国の史跡に指定"],["1970年代〜","道路建設にともなう大規模な発掘調査"],["2012年","出土品2028点が国の重要文化財に指定"],["2020年","あいち朝日遺跡ミュージアムが開館"]],"who":[["弥生時代の朝日ムラの人々","米づくり・漁・貝とりをしながら暮らした"],["発掘調査にあたった研究者たち","道路工事前の調査で大量の遺物を記録した"]],"deep":["«逆茂木» と «乱杭» がセットで見つかった例は全国でも珍しく、弥生時代の «戦い» を考えるうえで重要な発見とされています。","遺跡の範囲は約80万㎡ともいわれ、居住域・墓域・貝塚などが見つかっています。","湿地の遺跡のため、木製の農具や容器など、ふつうは残りにくい木の道具が多く出土しています。","赤い色をぬった土器など、東海地方らしい特徴をもつ土器が多く、この地域の弥生文化を知るうえで基準になる遺跡です。","遺跡の上には今、清洲ジャンクションなどの道路が通っており、開発と保存をどう両立させるかが問われた遺跡でもあります。","国の史跡としての指定名は «貝殻山貝塚»。遺跡全体のごく一部が史跡として守られています。"],"look":["ミュージアムの屋外に再現された逆茂木・乱杭と環濠","重要文化財の土器や木製品","貝殻山貝塚の史跡公園","再現された竪穴建物"],"q":["朝日遺跡でムラを守るために使われた、枝を外に向けて並べた防御の仕かけを何という?","逆茂木（さかもぎ）。斜めに打ちこんだ «乱杭» とあわせて見つかりました。"],"koji":[],"myth":"ムラの規模・人口、争いの実態は推定を含む。","img":["環濠集落","弥生時代","逆茂木"],"wp":"朝日遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/%E6%9C%9D%E6%97%A5%E9%81%BA%E8%B7%A1%28%E6%84%9B%E7%9F%A5%E7%9C%8C%E6%B8%85%E9%A0%88%E5%B8%82%29.jpg",3583,2687,"朝日遺跡"],["c:7/76/%E5%90%89%E9%87%8E%E3%83%B6%E9%87%8C%E9%81%BA%E8%B7%A1%E7%92%B0%E6%BF%A0.JPG",3456,2304,"環濠集落"],["c:1/14/Abatis_in_Yoshinogari_Historical_Park_3.jpg",4032,3024,"逆茂木"]]},{"id":"23_miya_juku","n":"宮宿と七里の渡し跡","yomi":"みやじゅく","cat":"街道","rank":"S","y":1601,"era":["edo"],"sh":"","ad":"名古屋市熱田区神戸町（宮の渡し公園）","st":"地下鉄名城線 伝馬町駅から歩いて約7分／名鉄 神宮前駅から約15分","la":35.1206,"lo":136.9094,"hook":"東海道でただ一か所、海の上を行く区間。旅人は宮の浜から船に乗り、七里先の桑名をめざした。","lead":"宮宿は、東海道五十三次の41番目の宿場町で、熱田神宮の門前にあったことから «宮» と呼ばれました。ここから伊勢の桑名宿までは、海を船で渡る «七里の渡し»。その船着き場の跡が «宮の渡し公園» として残っています。","story":["1601年、徳川家康は東海道に宿場を置き、人や荷物を運ぶしくみを整えました。宮宿はその一つで、熱田神宮の門前町としても栄えました。江戸時代の後半には、旅籠が200軒を超え、東海道でいちばん大きな宿場だったといわれます。","宮宿のにぎわいの理由は «七里の渡し» です。宮から桑名までは、陸を行くと川がいくつもあって大回り。そこで旅人は船に乗り、海の上を約七里（およそ27km）進みました。潮の満ち引きや天気によって時間が変わり、ふつうは4時間ほどかかったといわれます。«船が出るまで待つ» 旅人で、宿はいつもにぎわいました。","海の道には危険もありました。«船が出られないほど荒れたらどうする?» 天気が悪い日は何日も足止めされることもあり、船酔いや事故をきらって、陸を回る «佐屋路» を選ぶ人もいました。船着き場には夜の船の目印となる常夜灯が立てられ、時刻を知らせる «時の鐘» の音が港に響いていました。","明治になって鉄道が通ると、船の渡しは使われなくなり、海もうめ立てられて遠くなりました。今の宮の渡し公園には、戦後に復元された常夜灯と時の鐘の鐘楼が立ち、歌川広重の浮世絵 «東海道五十三次・宮» に描かれた風景をしのぶことができます。","公園の近くには、江戸時代の宿場の建物の姿を伝える «丹羽家住宅» が残っています（個人の住宅のため中は見学できないことが多いです）。東海道の旅のドラマは、この小さな港から伊勢へ、京へと続いていったのです。"],"tl":[["1601年","東海道の宿場として宮宿が定められる"],["1625年ごろ","船着き場に常夜灯が立てられたと伝わる"],["江戸時代後期","旅籠200軒を超える東海道最大級の宿場に"],["1833年ごろ","歌川広重 «東海道五十三次» の刊行が始まる"],["明治時代","鉄道の開通で七里の渡しがすたれる"],["1955年","常夜灯が復元される"]],"who":[["徳川家康","東海道の宿駅制度を整えた"],["歌川広重","«東海道五十三次» で宮宿を描いた浮世絵師"],["東海道の旅人","宮から船に乗り、桑名へ渡った"]],"deep":["«七里» は約27.5km。宮宿と桑名宿の間は東海道で唯一の海路で、渡し船は宿場が管理しました。","宮宿の旅籠の数は、1843年ごろの記録で248軒とされ、東海道の宿場で最多とされます。","陸路の «佐屋路» は、宮から佐屋まで陸を行き、佐屋から桑名までは川船で «三里の渡し» を行くルートでした。","今の常夜灯は、空襲などで失われたあと1955年に復元されたもの。時の鐘の鐘楼も戦後の復元です。","熱田は古くから «熱田湊» として栄えた港町で、宮宿は神宮の門前町・港町・宿場町の3つの顔をもっていました。","桑名側の船着き場には «伊勢国一の鳥居» が立ち、七里の渡しを渡ることは伊勢参りの入り口でもありました。宮の渡しから船で渡った先は、もう伊勢の国だったのです。"],"look":["宮の渡し公園の常夜灯","時の鐘の鐘楼","丹羽家住宅の外観（非公開のことが多い）","近くの熱田神宮とあわせた散策"],"q":["宮宿から海を渡って向かった、伊勢の宿場はどこ?","桑名宿。海上約七里の «七里の渡し» で結ばれていました。"],"koji":[],"myth":"常夜灯の最初の建立年、所要時間は伝承・目安。","img":["七里の渡し","東海道五十三次","佐屋街道"],"wp":"宮宿","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:7/7c/Hiroshige42_miya.jpg",2153,1410,"宮宿"],["c:d/de/%E5%AE%AE%E3%81%AE%E6%B8%A1%E3%81%97%E5%85%AC%E5%9C%92.jpg",704,478,"七里の渡し"],["c:f/f7/Hiroshige_le_pont_Nihonbashi_%C3%A0_l%27aube.jpg",1618,1080,"東海道五十三次"],["c:d/d3/%E4%BD%90%E5%B1%8B%E8%B7%AF%E3%81%A8%E5%91%A8%E8%BE%BA%E3%81%AE%E4%B8%BB%E8%A6%81%E8%A1%97%E9%81%93.png",921,1013,"佐屋街道"]]},{"id":"23_meijimura","n":"博物館明治村","yomi":"はくぶつかんめいじむら","cat":"近代","rank":"S","y":1965,"era":["meiji","taisho","showa"],"sh":"","ad":"犬山市内山","st":"名鉄 犬山駅から路線バスで約20分","la":35.3419,"lo":136.9889,"hook":"フランク・ロイド・ライトの帝国ホテルに、漱石の住んだ家。消えゆく明治の建物が、湖のほとりに集められた。","lead":"博物館明治村は、明治時代を中心とする古い建物を全国から移して保存している野外博物館です。1965年に開村し、60を超える建物が並びます。国の重要文化財になっている建物もたくさんあります。","story":["昭和30年代、日本は高度経済成長のまっただなか。古い建物が次々にこわされていきました。建築家の谷口吉郎は、少年時代をすごした東京の «鹿鳴館» がこわされるのを見て、胸を痛めていたといいます。«このままでは明治の建物がなくなってしまう»。","谷口の思いに応えたのが、旧制第四高等学校（金沢）時代の同級生で名古屋鉄道の社長だった土川元夫でした。2人は協力して、こわされる予定の建物をばらばらにして運び、入鹿池のほとりに建て直すことを計画します。こうして1965年、博物館明治村が生まれました。","明治村の中を歩くと、時代をこえた町に迷いこんだようです。森鷗外や夏目漱石が住んだ家、京都の聖ヨハネ教会堂、三重県庁舎、金沢の監獄の建物…。京都で走っていた路面電車や、蒸気機関車に乗ることもできます。«建物は使われてこそ生きる» という考えから、実際に中に入れる建物が多いのも特色です。","いちばんの目玉は、アメリカの建築家フランク・ロイド・ライトが設計した «帝国ホテル中央玄関»。1923年に完成し、完成の日に起きた関東大震災にも耐えたといわれる建物です。東京で建て替えのため取りこわされることになり、玄関部分が明治村に運ばれて、長い年月をかけて建て直されました。","明治村は «明治» を名前にしていますが、大正や昭和初めの建物もあります。日本が西洋の技術をとり入れながら、自分たちの建物を作っていった道のりを、実物で確かめられる場所です。"],"tl":[["1923年","帝国ホテル（ライト館）が完成"],["1962年","博物館明治村の設立が決まる"],["1965年3月","博物館明治村が開村"],["1968年","帝国ホテル（ライト館）の取りこわしが始まる"],["1976年","帝国ホテル中央玄関の移築工事が始まる"],["1985年","帝国ホテル中央玄関が公開される"]],"who":[["谷口吉郎","建築家。明治村の創設を発案した初代館長"],["土川元夫","名古屋鉄道の社長。谷口とともに明治村を作った"],["フランク・ロイド・ライト","帝国ホテル（ライト館）を設計したアメリカの建築家"],["夏目漱石","明治村に移された家に住み «吾輩は猫である» を書いた"],["森鷗外","漱石より前に同じ家に住んでいた"]],"deep":["鷗外と漱石の住宅: 東京の千駄木にあった同じ家に、森鷗外がのちに夏目漱石が住みました。漱石はここで «吾輩は猫である» を書いたとされ、«猫の家» とも呼ばれます。","帝国ホテル中央玄関は、大谷石やスクラッチタイル（細い溝のある焼きものの タイル）を使った独特のデザインです。","明治村にある建物のうち、10件を超える建物が国の重要文化財に指定されています。","京都市電は、日本で最初の営業用電気鉄道として走った京都の路面電車の車両。明治村では実際に乗ることができます。","明治村はドラマや映画の撮影地としてもよく使われ、明治・大正が舞台の作品にたびたび登場します。"],"look":["帝国ホテル中央玄関","森鷗外・夏目漱石住宅","聖ヨハネ教会堂","京都市電とSL","入鹿池を見わたす景色"],"q":["明治村にある帝国ホテル中央玄関を設計した建築家は?","フランク・ロイド・ライト。アメリカを代表する建築家です。"],"koji":[],"myth":"帝国ホテルが関東大震災に耐えた話は、被害の程度について諸説ある。","img":["帝国ホテル","谷口吉郎","フランク・ロイド・ライト"],"wp":"博物館明治村","rel":{"ev":[],"grave":[]},"ph":[["c:4/43/Meijimura1.jpg",6048,4024,"博物館明治村"],["c:7/7f/Imperial_Hotel_Tokyo.JPG",2206,2500,"帝国ホテル"],["c:6/66/Frank_Lloyd_Wright_with_Crystal_Heights_plan.jpg",800,1020,"フランク・ロイド・ライト"]]},{"id":"23_toyota_kinenkan","n":"トヨタ産業技術記念館（豊田紡織の旧工場）","yomi":"とよたさんぎょうぎじゅつきねんかん","cat":"産業","rank":"S","y":1911,"era":["meiji","taisho","showa"],"sh":"","ad":"名古屋市西区則武新町","st":"名鉄名古屋本線 栄生駅から歩いて約3分","la":35.1827,"lo":136.8768,"hook":"赤レンガの工場で、織機がいっせいに動き出す。トヨタの物語は、自動車ではなく «布を織る機械» から始まった。","lead":"トヨタ産業技術記念館は、豊田佐吉が始めた紡織工場の赤レンガの建物を使った博物館です。1994年に開館しました。織機から自動車へと続く、ものづくりの歴史を動く機械で見ることができます。","story":["豊田佐吉は1867年、今の静岡県湖西市で大工の家に生まれました。母が手で機を織るすがたを見て育ち、«もっと楽に、もっとたくさん布を織れる機械を» と考えるようになったといいます。佐吉は若いころから発明にのめりこみ、1890年に木製の人力織機を作りました。","佐吉は明治の終わりごろ、名古屋の栄生に織布工場を作りました。この工場は、のちに «豊田紡織» の本社工場になります。記念館の赤レンガの建物は、その工場として大正時代に建てられたものです。«なぜ機械の会社が自分で布を織ったのか?» 自分の作った織機を工場で使い、改良を重ねるためでした。","佐吉の発明の中でもとくに有名なのが、1924年に完成した «G型自動織機» です。機械を止めずに横糸を自動で取りかえられ、1人でたくさんの織機を受けもつことができました。糸が切れると自動で止まるしくみもあり、«異常があれば機械が止まる» という考えは、のちのトヨタの生産方式にもつながったといわれます。","佐吉の長男・豊田喜一郎は、自動織機の会社の中に自動車部を作り、国産の自動車づくりに挑みます。織機の特許を売って得たお金の一部が、自動車の研究にあてられたともいわれます。こうして生まれたのが、今のトヨタ自動車です。記念館では、織機の実演から、自動車の組み立ての歴史までを見ることができます。"],"tl":[["1867年","豊田佐吉が生まれる"],["1890年","佐吉が豊田式木製人力織機を発明"],["1911年","名古屋・栄生に豊田自働織布工場をつくる"],["1918年","豊田紡織株式会社を設立"],["1924年","G型自動織機が完成"],["1926年","豊田自動織機製作所を設立"],["1937年","トヨタ自動車工業が設立される"],["1994年","トヨタ産業技術記念館が開館"]],"who":[["豊田佐吉","発明家。自動織機を完成させ、豊田グループの基礎を作った"],["豊田喜一郎","佐吉の長男。自動車事業を始めた"],["豊田利三郎","佐吉の娘婿。豊田紡織などの経営を支えた"]],"deep":["記念館の建物は、豊田紡織の本社工場として使われた大正時代の赤レンガ造。近代化産業遺産にも認定されています。","G型自動織機の «無停止杼換» は、横糸を巻いた部品（杼）を、織機を止めずに入れかえるしくみです。","G型自動織機の特許は、イギリスの織機メーカー、プラット社に譲られました。","«自働化»: 異常が起きると機械が自動で止まるという考え方で、トヨタでは «働» をにんべんのついた字で書きます。","喜一郎の自動車部が1935年に作った試作車（A1型）や、トヨダAA型乗用車（1936年）などが、トヨタの自動車づくりの始まりとして知られます。"],"look":["繊維機械館の織機の実演","G型自動織機","赤レンガの建物と «環状織機»","自動車館の組み立てラインの展示"],"q":["豊田佐吉が1924年に完成させた、止めずに横糸を取りかえられる織機は?","G型自動織機。1人で多くの織機を受けもてるようになりました。"],"koji":[{"w":"障子を開けてみよ、外は広いぞ","m":"豊田佐吉のことばとして伝わる。世界に目を向けよという意味"}],"myth":"特許料が自動車研究にあてられた話、佐吉のことばは伝承を含む。","img":["豊田佐吉","豊田喜一郎","豊田自動織機"],"wp":"トヨタ産業技術記念館","rel":{"ev":[],"grave":[]},"ph":[["c:b/b3/Toyota_tecno_museum.jpg",6048,4024,"トヨタ産業技術記念館"],["c:2/2b/Sakichi_Toyoda.jpg",908,1289,"豊田佐吉"],["c:a/af/Kiichiro_Toyoda.jpg",1654,2172,"豊田喜一郎"],["c:d/dd/Headquarters_of_Toyota_Industries.JPG",4000,1501,"豊田自動織機"]]},{"id":"23_nakamura","n":"中村公園（秀吉・清正の生まれた里）","yomi":"なかむらこうえん","cat":"町","rank":"S","y":1537,"era":["azuchi","meiji"],"sh":"","ad":"名古屋市中村区中村町","st":"地下鉄東山線 中村公園駅から歩いて約10分","la":35.1717,"lo":136.8581,"hook":"農民の子から天下人になった豊臣秀吉。そして熊本城を築いた加藤清正。2人のふるさとは、同じ村だった。","lead":"中村公園は、豊臣秀吉が生まれた地と伝わる尾張の中村に作られた公園です。秀吉をまつる豊国神社があり、近くには加藤清正が生まれたと伝わる妙行寺もあります。公園の南には、高さ24mの大鳥居が立っています。","story":["戦国時代、尾張の愛知郡中村。1537年（1536年説もあります）、この村の貧しい家に一人の男の子が生まれました。のちの豊臣秀吉です。幼いころの名は «日吉丸» だったといわれますが、これは後の時代の伝記が広めた話で、確かではありません。","秀吉は若いころに家を出て、今川方の武士に仕えたあと、織田信長の家来になりました。わらじを懐で温めたという有名な話も伝わります。«農民の子がどうして天下を取れたのか?» 知恵と行動力、そして人の心をつかむ力があったからだと、昔から語られてきました。","同じ中村から、もう一人の英雄が生まれます。1562年生まれの加藤清正です。清正の母は秀吉の母と親戚だったといわれ、清正は幼いころから秀吉に仕えました。のちに肥後（熊本）の大名となり、熊本城を築きます。名古屋城の天守台の石垣も、清正が手がけたと伝わります。","明治になると、秀吉をたたえる声が高まり、1885年に中村に豊国神社が建てられました。その周りが公園として整えられ、中村公園となりました。1929年には、地元の人々の力で、公園の入り口近くに大きな鳥居が建てられています。","公園の中の «秀吉清正記念館» には、2人に関わる資料が展示されています。近くの常泉寺には «豊公誕生之地» の碑があり、妙行寺は清正の生誕地と伝わります。1つの村から2人の大名が生まれた物語を、歩いてたどれる場所です。"],"tl":[["1537年","豊臣秀吉が中村に生まれる（1536年説も）"],["1562年","加藤清正が中村に生まれる"],["1590年","秀吉が全国を統一"],["1885年","豊国神社が建てられる"],["1901年","中村公園が開かれる"],["1929年","大鳥居が建てられる"]],"who":[["豊臣秀吉","中村の生まれと伝わる天下人"],["加藤清正","中村の生まれと伝わる。秀吉に仕え、熊本城を築いた"],["大政所（なか）","秀吉の母。中村の出身"]],"deep":["秀吉の生年: 1537年説と1536年説があります。«太閤素生記» などの史料で書かれ方がちがうためです。","«日吉丸» の名は、江戸時代の «絵本太閤記» などで広まったもので、同時代の史料では確かめられません。","常泉寺には «秀吉誕生の地» とする碑があり、境内には秀吉が産湯に使ったと伝わる井戸もあります。","妙行寺は、清正が名古屋城築城のときの余った材木を使って建て直したと伝わります。","大鳥居は高さ約24mで、名古屋でも有数の大きさの鳥居。地下鉄の駅から公園へ向かう目印になっています。","清正と秀吉の母の関係: 清正の母・伊都は、秀吉の母・なか（大政所）のいとこ、あるいは親戚だったといわれますが、はっきりした関係は諸説あります。"],"look":["豊国神社","秀吉清正記念館","常泉寺の «豊公誕生之地» 碑","妙行寺（清正生誕地と伝わる）","公園南の大鳥居","中村公園のまわりに残る、秀吉や清正にちなんだ町名や碑"],"q":["中村から生まれ、熊本城を築いた武将は誰?","加藤清正。秀吉と同じ中村の生まれと伝わります。"],"koji":[],"myth":"秀吉の生年・幼名、草履の話、誕生地の井戸・妙行寺の材木の話は伝承・諸説。","img":["豊臣秀吉","加藤清正","大政所"],"wp":"中村公園","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Nakamurakouen1.JPG",3648,2736,"中村公園"],["c:e/e8/Kat%C5%8D_Kiyomasa.jpg",1518,1968,"加藤清正"],["c:1/1d/Omandokoro.jpg",1598,3600,"大政所"]]},{"id":"23_nagashino_jo","n":"長篠城跡（奥平信昌の籠城）","yomi":"ながしのじょうあと","cat":"城","rank":"A","y":1575,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"新城市長篠市場","st":"JR飯田線 長篠城駅から歩いて約8分","la":34.9235,"lo":137.5594,"hook":"«援軍はすぐに来る。あと2、3日の辛抱だ!» 敵に捕らえられた鳥居強右衛門は、城に向かってそう叫んだと伝わる。","lead":"長篠城は、2つの川が合流する断崖の上に築かれた城です。1575年、奥平信昌がわずか500ほどの兵でこもり、1万5千ともいわれる武田勝頼の大軍から城を守りぬきました。この籠城が «長篠の戦い» のきっかけになりました。建物は残っておらず、今は «城跡» です。","story":["長篠城は、豊川（寒狭川）と宇連川が合わさる場所の、切り立った崖の上にあります。2つの川が天然の堀になり、攻めにくい城でした。戦国時代、この城は徳川と武田の境目にあり、何度も持ち主が変わりました。","1575年、家康は武田から徳川方にねがえった若い奥平信昌を長篠城の城主にしました。すると5月、武田勝頼の大軍が城を取り囲みます。城の兵は500ほど。食べ物もなくなりかけ、«このままでは城がもたない»。そこで名乗り出たのが、足軽の鳥居強右衛門でした。","強右衛門は夜の川にもぐって包囲をぬけ出し、岡崎にいた家康のもとへ走りました。そこで信長と家康の大軍が出陣の準備をしていることを知り、急いで城へ引き返します。ところが城の近くで武田軍に捕まってしまいました。","武田方は «援軍は来ないと城に向かって言えば命を助けよう» と持ちかけたといわれます。強右衛門はそれを受け入れたふりをして城の前に立ち、«援軍はもうすぐ来る!» と叫びました。怒った武田方によって、強右衛門は磔にされたと伝わります。城兵は勇気づけられ、城は援軍が来るまで持ちこたえました。","城のそばの «長篠城址史跡保存館» では、籠城と戦いの資料が展示されています。強右衛門が処刑された場所と伝わる所には碑が立ち、地元では今も強右衛門をたたえています。静かな城跡に立つと、500人の必死の籠城が目に浮かぶようです。"],"tl":[["1508年","菅沼元成が長篠城を築いたとされる"],["1573年","家康が長篠城を攻め取る"],["1575年2月","奥平信昌が城主となる"],["1575年5月","武田勝頼が長篠城を包囲。鳥居強右衛門が援軍を求めに城を出る"],["1575年5月21日","設楽原の決戦で武田軍が敗れ、包囲がとける"],["1929年","長篠城跡が国の史跡に指定"]],"who":[["奥平信昌","長篠城主。籠城をやりとげ、のちに家康の娘・亀姫を妻にした"],["鳥居強右衛門","城を抜け出して援軍を求め、捕らえられて磔にされたと伝わる"],["武田勝頼","長篠城を包囲した武田家の当主"],["徳川家康","信長とともに長篠城の救援に向かった"]],"deep":["強右衛門の磔の姿を描いた旗が伝わっています。武田方の落合左平次（道次）が、強右衛門の勇気に心を打たれて旗印にしたと伝わるもので、東京大学史料編纂所が所蔵しています。","籠城の功で、奥平信昌は家康の長女・亀姫と結婚しました。信長からも «信» の一字をもらったとされます。","長篠城跡は、飯田線の線路が城跡の中を通っています。鉄道が敷かれたとき、本丸の一部が削られたといわれます。","城の本丸跡には土塁と堀の跡が残り、断崖の上から川をのぞくと、攻めにくさがよくわかります。","強右衛門が援軍を知らせた合図として、雁峰山でのろしを上げたという話も伝わります。"],"look":["本丸跡の土塁と堀","長篠城址史跡保存館","豊川と宇連川の合流点の断崖","鳥居強右衛門ゆかりの碑と墓（新城市内）"],"q":["長篠城から抜け出して援軍を求め、城に向かって «援軍は来る» と叫んだ足軽は?","鳥居強右衛門。武田方に捕らえられ、磔にされたと伝わります。"],"koji":[],"myth":"強右衛門の言葉やのろしの話、旗の由来は伝承を含む。兵数は諸説。","img":["鳥居強右衛門","奥平信昌","長篠の戦い"],"wp":"長篠城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d5/%E5%8F%B2%E8%B7%A1_%E9%95%B7%E7%AF%A0%E5%9F%8E%E5%9D%80.jpg",4032,3024,"長篠城"],["c:b/b7/Crucified_Torii_Suneemon.jpg",427,450,"鳥居強右衛門"],["c:1/13/Okudaira_Nobumasa.jpg",1144,2250,"奥平信昌"]]},{"id":"23_shinto_masumida","n":"真清田神社（尾張国一宮）","yomi":"ますみだじんじゃ","cat":"寺社","rank":"A","y":1000,"era":["heian","showa"],"sh":"","ad":"一宮市真清田1丁目","st":"JR尾張一宮駅・名鉄一宮駅から歩いて約8分","la":35.3036,"lo":136.8032,"hook":"«一宮» という町の名前は、この神社から生まれた。尾張でいちばん格の高い神社である。","lead":"真清田神社は、尾張国でいちばん格の高い神社とされた «一宮» です。一宮市という市の名前も、この神社に由来します。尾張の豪族・尾張氏の祖先とされる天火明命をまつり、毎年夏の «一宮七夕まつり» の中心になっています。","story":["平安時代から、各国には «一宮» と呼ばれる特に大切にされた神社がありました。国司が国に着くと、まず一宮にお参りしたとも伝わります。尾張国の一宮が、この真清田神社です。町は神社の門前町として発展し、やがて町の名前も «一宮» になりました。","まつられている天火明命は、尾張氏という古代の豪族の祖先とされる神です。尾張氏は、熱田神宮をまつる一族とも関わりが深い有力な家でした。«なぜ尾張の人々はこの神を大切にしたのか?» 自分たちの祖先の神をまつることで、一族と土地を守ろうとしたのです。","神社の創建は、伝えでは神武天皇の時代とされますが、確かなことはわかっていません。平安時代にまとめられた «延喜式» の神名帳には名前がのっており、古くからの神社であることは確かです。","一宮のあたりは、昔から織物がさかんな土地です。境内には、機織りの神をまつる «服織神社» があります。戦後、焼け野原から立ち上がろうとした1956年、繊維の町の感謝をこめて «おりもの感謝祭一宮七夕まつり» が始まりました。今では毎年7月に、多くの人が集まる大きな祭りになっています。","1945年の空襲で、社殿の多くが焼けてしまいました。今の社殿は戦後に再建されたものです。朱色の楼門をくぐると、大きな拝殿が現れ、町の真ん中にありながら静かな空気に包まれます。","境内には、ほかにも多くの摂社・末社がならび、町の人々の日々の願いを受けとめてきました。«一宮さん» と呼ばれるこの神社は、1000年以上にわたって尾張の人々の暮らしのそばにあり続けているのです。"],"tl":[["伝承","神武天皇の時代に創建されたと伝わる"],["927年","«延喜式» 神名帳に名前が見える（延喜式の完成）"],["平安時代後期","尾張国の一宮とされる"],["1945年","空襲で社殿の多くが焼失"],["1956年","一宮七夕まつりが始まる"],["1957年ごろ","社殿が再建される"]],"who":[["天火明命","まつられている神。尾張氏の祖先とされる"],["尾張氏","尾張の古代豪族。熱田神宮とも関わりが深い"],["一宮の人々","七夕まつりで神社を中心に町を盛り上げてきた"]],"deep":["«延喜式» 神名帳では、尾張国中島郡の神社として名前がのっています。","«一宮» の制度は、朝廷が決めたものではなく、平安時代後期ごろから各国で自然に定まっていったと考えられています。","境内の «服織神社» は、機織りの神・萬幡豊秋津師比売命をまつっています。繊維の町らしい神社です。","毎年4月3日の «桃花祭» は、真清田神社の大切な例祭で、馬の行列が出る神事などが行われます。","一宮市の中心部は、神社を中心に道が通る門前町の町割りがよく残っています。","尾張には «一宮» のほかに «二宮»（犬山市の大縣神社）と «三宮»（熱田神宮）とされる神社もあり、一宮・二宮・三宮の順番にも古い信仰の歴史が表れています。"],"look":["朱色の楼門と拝殿","服織神社","境内の神水舎","七夕まつりの時期の飾り","神社の周りの門前町と、本町商店街のアーケード"],"q":["一宮市の «一宮» という名前は、何に由来する?","真清田神社が尾張国の «一宮» だったことに由来します。"],"koji":[],"myth":"創建年は伝承。一宮とされた時期は諸説。","img":["一宮","尾張氏","一宮七夕まつり"],"wp":"真清田神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/c0/Masumida_Shrine_Haiden.jpg",5953,3974,"真清田神社"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"],["c:7/7e/Ichinomiya_Tanabata_Festival_2014_-_21.jpg",2000,1500,"一宮七夕まつり"]]},{"id":"23_toga_jinja","n":"砥鹿神社（三河国一宮）","yomi":"とがじんじゃ","cat":"寺社","rank":"A","y":700,"era":["asuka","heian"],"sh":"","ad":"豊川市一宮町西垣内（里宮）","st":"JR飯田線 三河一宮駅から歩いて約5分（里宮）。奥宮は本宮山の山頂付近で、登山か車","la":34.8588,"lo":137.4143,"hook":"ふもとの里宮と、山の上の奥宮。三河の人々は、姿の美しい本宮山そのものを神の山としてあおいできた。","lead":"砥鹿神社は、三河国の «一宮» とされた神社です。大己貴命（大国主命）をまつり、ふもとの «里宮» と、本宮山の山頂近くの «奥宮» の2つからなります。豊川市一宮町という地名も、この神社に由来します。","story":["豊川市の北にそびえる本宮山は、高さ約789m。平野のどこからでも見えるこの山を、昔の人々は神が宿る山としてあおぎました。山の上にまつられたのが奥宮、そしてふもとで人々がお参りしやすいようにまつられたのが里宮です。","伝えによると、飛鳥時代の終わりごろ、文武天皇が病にかかったとき、三河の本宮山の神に祈るようにとのお告げがありました。天皇の使いが山の神に祈ると、病はたちまち治った。そこで里にも宮を建てたのが里宮の始まり、と伝わります。確かな史料はなく、神社に伝わる話です。","«砥鹿» というめずらしい名前には、いろいろな説があります。«なぜこの字なのか?» はっきりした答えはわかっていません。ただ、平安時代の «延喜式» の神名帳に名前がのっており、古くから三河で大切にされてきた神社であることは確かです。","戦国時代、三河は松平（徳川）家の本拠でした。一宮である砥鹿神社は、この地の武士たちからも敬われたといわれます。江戸時代には徳川家から領地を与えられて守られ、明治になると国幣小社とされました。","里宮は駅から近く、広い境内に大きな社殿が立ちます。奥宮へは、ふもとから登山道を歩くか、スカイラインを車で上ります。山頂近くからは、三河湾や豊橋の平野を一望できます。里と山、2つの宮をめぐると、この神社の «山をあおぐ心» がよくわかります。"],"tl":[["伝承（700年ごろ）","文武天皇の病気平癒の祈りに始まると伝わる"],["927年","«延喜式» 神名帳に名前が見える（延喜式の完成）"],["平安時代後期","三河国の一宮とされる"],["江戸時代","徳川家から社領を与えられる"],["1871年","国幣小社となる"]],"who":[["大己貴命","まつられている神。大国主命の別名"],["文武天皇","病気平癒の祈りの話に登場する天皇（伝承）"],["三河の人々","本宮山を神の山としてあおいできた"]],"deep":["里宮と奥宮の関係: 奥宮が本来の神の山の社、里宮はふもとでまつるための社という «山宮と里宮» の形は、日本の山岳信仰によく見られます。","本宮山の山頂付近には、奥宮のほかに岩をまつった場所もあり、山そのものを信仰した名残と考えられています。","«延喜式» 神名帳では、三河国宝飫郡の神社として名前がのっています。","神社の名前の «砥鹿» の由来には、地名説など複数の説がありますが、定説はありません。","里宮のある一宮町は、神社の門前として発達した集落で、町の名前そのものが一宮であることを示しています。","三河国では、砥鹿神社が一宮、知立神社が二宮、猿投神社が三宮とされ、三河の古い神社の順番が今に伝わっています。"],"look":["里宮の本殿・拝殿","奥宮へ向かう本宮山の参道","本宮山山頂付近からの三河平野の眺め","里宮境内の摂社・末社","本宮山の登山道の途中にある石の鳥居や道しるべ"],"q":["砥鹿神社の奥宮がある、豊川市の北にそびえる山の名前は?","本宮山。高さ約789mで、神が宿る山としてあおがれてきました。"],"koji":[],"myth":"文武天皇の病気平癒の話と創建年は伝承。社名の由来は諸説。","img":["本宮山","大国主","一宮"],"wp":"砥鹿神社","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/Toga-jinja%2C_haiden-2.jpg",5420,3592,"砥鹿神社"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"23_kounomiya","n":"尾張大国霊神社（国府宮・はだか祭）","yomi":"おわりおおくにたまじんじゃ","cat":"寺社","rank":"A","y":800,"era":["nara","heian","muromachi"],"sh":"国の重要文化財（楼門・拝殿）","ad":"稲沢市国府宮1丁目","st":"名鉄名古屋本線 国府宮駅から歩いて約3分","la":35.2349,"lo":136.8012,"hook":"真冬の境内に、数千人の裸の男たち。«神男» にふれて厄を落とそうと、白い湯気が立ちのぼる。","lead":"尾張大国霊神社は、«国府宮» の名で親しまれる神社です。奈良時代、尾張国の役所 «国府» の近くにあり、国の守り神 «尾張大国霊神» をまつりました。旧暦1月13日の «はだか祭»（儺追神事）で全国に知られています。","story":["奈良時代、各国には都から役人が来て «国府» という役所を置きました。尾張国の国府は、今の稲沢市のあたりにありました。その近くで、尾張の国の土地そのものの神 «尾張大国霊神» をまつったのがこの神社です。国府のそばの宮だから «国府宮»。駅の名前にもなっています。","この神社の名を全国に広めたのが «はだか祭» です。正式には «儺追神事» といい、1年の厄をはらう行事です。くじで選ばれた «神男» が、ただ一人、全身の毛をそって祭りにのぞみます。«なぜ神男にふれるのか?» 神男にふれると厄が落ちると信じられているからです。","祭りの日、ふんどし姿の男たちが «わっしょい» のかけ声とともに境内へなだれこみ、神男にふれようとして押し合います。冬の寒さの中、男たちの体から湯気が立ちのぼる光景は迫力満点です。神男は、押し合いの中をやっとのことで儺追殿へ運びこまれます。","祭りは奈良時代に国中の災いをはらうために始まった、という言い伝えがありますが、今の形になったのは江戸時代ごろと考えられています。2024年には、長い歴史の中で初めて、女性の団体が «なおいぎれ» を奉納する行事に参加し、話題になりました。","境内の楼門と拝殿は、国の重要文化財です。楼門は室町時代の建物と考えられ、戦乱や空襲をくぐりぬけて今に伝わっています。ふだんは静かな境内を歩くと、祭りの日の熱気が想像しにくいほどです。"],"tl":[["奈良時代","尾張国府の近くで尾張大国霊神がまつられる"],["927年","«延喜式» 神名帳に名前が見える（延喜式の完成）"],["室町時代","楼門が建てられたと考えられる"],["江戸時代","儺追神事が今に近い形で行われるようになったと考えられる"],["2024年","はだか祭に女性団体が初めて参加"]],"who":[["尾張大国霊神","まつられている神。尾張の国土の神"],["神男","はだか祭でくじで選ばれ、厄を一身に受ける男性"],["尾張国の国司","都から派遣された役人。国府で政治を行った"]],"deep":["尾張国府の正確な場所は長く議論されてきましたが、稲沢市松下付近とする説が有力です。","«儺追» は、鬼を追いはらう中国由来の «追儺» の行事と関わる言葉です。","はだか祭の前には «なおいぎれ» と呼ばれる布を結んだ笹を奉納する行事があり、参加できない人は布に願いを託します。","はだか祭のあと、神男は «土餅» を背負わされて境内から追い出される儀式があり、厄を持ち去る役割を最後まで果たします。","楼門は、室町時代の建物と考えられており、戦国時代の兵火をまぬがれたとされます。拝殿は江戸時代初めの建物です。","神男になる人は祭りの前から神社にこもり、身を清めて過ごします。1年の厄を一人で引き受ける、大変な役目です。"],"look":["楼門（国の重要文化財）","拝殿（国の重要文化財）","儺追殿","はだか祭の日の境内（旧暦1月13日）"],"q":["はだか祭で、男たちがふれると厄が落ちると信じられている人を何という?","神男（しんおとこ）。くじで選ばれ、全身の毛をそって祭りにのぞみます。"],"koji":[],"myth":"はだか祭の起源（奈良時代説）は伝承。国府の位置は諸説。","img":["儺追神事","尾張国府","稲沢市"],"wp":"尾張大国霊神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/97/Konomiya-jinja_Hall_of_Worship_ac_%281%29.jpg",5956,3960,"尾張大国霊神社"]]},{"id":"23_toyokawa_inari","n":"豊川稲荷（妙厳寺）","yomi":"とよかわいなり","cat":"寺社","rank":"A","y":1441,"era":["muromachi","edo"],"sh":"","ad":"豊川市豊川町","st":"JR飯田線 豊川駅・名鉄 豊川稲荷駅から歩いて約5分","la":34.8233,"lo":137.3924,"hook":"«稲荷» なのに神社ではなくお寺。千体をこえるきつねの像がならぶ «霊狐塚» は、見る人を別の世界へさそう。","lead":"豊川稲荷の正式な名前は «円福山豊川閣妙厳寺»。曹洞宗のお寺です。お寺の守り神 «豊川吒枳尼真天» が白いきつねに乗った姿であることから «稲荷» と呼ばれるようになりました。商売繁盛の神様として、全国から多くの人がお参りします。","story":["妙厳寺は、1441年に東海義易という僧が開いたお寺です。義易は、鎌倉時代の僧・寒巌義尹の流れをくむ人でした。寒巌が中国（宋）から船で帰るとき、海の上に白いきつねに乗った女神 «吒枳尼真天» が現れ、«私はあなたの教えを守ろう» と告げた、と伝わります。","寒巌がその姿を像にしてまつり、それが代々伝えられて、義易がこの地にお寺を開くときに守り神としたといわれます。«なぜお寺なのに鳥居があるのか?» 江戸時代まで、日本では神と仏がいっしょにまつられるのがふつうでした。明治の神仏分離のときも、豊川稲荷はお寺として続き、鳥居も境内に残りました。","戦国時代には今川義元が、江戸時代には徳川家や大名たちがこのお寺を敬いました。江戸の町奉行として有名な大岡越前守忠相も豊川稲荷を信仰し、江戸の屋敷にまつっていたと伝わります。これが今の東京・赤坂の «豊川稲荷東京別院» の始まりです。","江戸時代後半になると、商売繁盛・家内安全の神として庶民にも人気が広がり、東海道を旅する人たちも寄り道してお参りしました。参道には門前町ができ、今も «いなり寿司» の店が並びます。","境内の奥にある «霊狐塚» には、お礼として納められたきつねの像が、千体をこえてならんでいます。森の中にびっしり並ぶきつねたちの目に見つめられると、思わず背すじがのびます。"],"tl":[["鎌倉時代","寒巌義尹が宋からの帰りに吒枳尼真天を感得したと伝わる"],["1441年","東海義易が妙厳寺を開く"],["1536年","今川義元が山門を寄進したと伝わる"],["江戸時代","大岡忠相らの信仰を集める"],["明治時代","神仏分離の中でも寺として続く"],["1945年","豊川海軍工廠が空襲を受ける（近くの軍需工場）"]],"who":[["東海義易","妙厳寺を開いた曹洞宗の僧"],["寒巌義尹","鎌倉時代の僧。吒枳尼真天の像をもたらしたと伝わる"],["今川義元","山門を寄進したと伝わる戦国大名"],["大岡忠相","江戸の町奉行。豊川稲荷を信仰したと伝わる"]],"deep":["豊川稲荷は、京都の伏見稲荷大社などとともに «日本三大稲荷» の一つに数えられることがありますが、どこを三大とするかは諸説あります。","山門は、今川義元が寄進したと伝わる境内でも古い建物です。","«吒枳尼天» はもともとインドの仏教の神で、日本ではきつねに乗った姿で表され、稲荷の神と結びつきました。","霊狐塚のきつねの像は、願いがかなったお礼として信者が奉納したものです。","豊川市には太平洋戦争中、大きな海軍工廠がありました。1945年8月7日の空襲で多くの人が亡くなり、市内では今も慰霊が続けられています。","豊川稲荷の名前の «豊川» は、近くを流れる豊川から。お寺の山号は «円福山»、寺号は «妙厳寺» で、«豊川閣» は本殿を指す呼び名として使われます。"],"look":["総門と山門","本殿（豊川閣）","霊狐塚","門前町の参道と名物のいなり寿司"],"q":["豊川稲荷は神社? それともお寺?","お寺。正式名は妙厳寺という曹洞宗の寺で、守り神の吒枳尼真天がきつねに乗っていることから «稲荷» と呼ばれます。"],"koji":[],"myth":"寒巌義尹の感得の話、今川義元の山門寄進、大岡忠相の信仰は伝承。","img":["荼枳尼天","大岡忠相","豊川海軍工廠"],"wp":"豊川稲荷","rel":{"ev":[],"grave":[]},"ph":[["c:b/b4/Toyokawainari_honden.jpg",5535,3682,"豊川稲荷"],["c:d/d6/Dakini.png",360,722,"荼枳尼天"],["c:2/26/Oooka_tadasuke.jpg",1536,2048,"大岡忠相"]]},{"id":"23_horaiji","n":"鳳来寺（鳳来寺山の山岳寺院と東照宮）","yomi":"ほうらいじ","cat":"寺社","rank":"A","y":703,"era":["asuka","heian","edo"],"sh":"国の重要文化財（仁王門・鳳来山東照宮）","ad":"新城市門谷鳳来寺","st":"JR飯田線 本長篠駅からバスで約20分、終点付近から石段を登る。山頂付近へは車道（パークウェイ）もある","la":34.9761,"lo":137.5856,"hook":"杉木立の中にえんえんと続く1425段の石段。その先に、家康誕生の伝説をもつ山の寺と、家光が建てた東照宮が待っている。","lead":"鳳来寺は、奥三河の鳳来寺山にある山岳寺院です。飛鳥時代に利修仙人が開いたと伝わります。徳川家康の誕生にまつわる伝説があり、3代将軍家光の命で «鳳来山東照宮» も建てられました。山全体が国の名勝・天然記念物に指定されています。","story":["鳳来寺山は、高さ約695mの火山岩の山。切り立った岩壁と深い杉の森におおわれ、昔から修行の場とされてきました。伝えによると、703年、利修という仙人がこの山にこもり、山の杉の木から薬師如来の像を彫ってまつったのが鳳来寺の始まりです。利修は鳳凰に乗って山を行き来した、ともいわれ、それが «鳳来» の名の由来とされます。","もう一つの有名な言い伝えが、家康の誕生の話です。家康の母・於大の方が、子を授かるようにと鳳来寺の薬師如来に祈りました。すると、薬師如来を守る十二神将の一人が姿を消し、ほどなく竹千代（家康）が生まれた、と伝わります。«家康は薬師如来の使いの生まれ変わり»。江戸時代、この話は徳川家の人気とともに広まりました。","そんな縁から、3代将軍家光は鳳来寺山に東照宮を建てることを命じ、江戸時代の前半に完成しました。日光・久能山とならぶ «三大東照宮» の一つとされることもあります。鳳来寺も幕府から大切にされ、山にはたくさんの僧坊がならんでにぎわったといいます。","鳳来寺山は «声の仏法僧» の山としても知られます。夜の森から «ブッ・ポウ・ソウ» と聞こえる声は、昔は仏法僧という鳥の声だと信じられていました。昭和の初めにラジオでこの声が中継されたことをきっかけに、声の主は実はフクロウの仲間のコノハズクだとわかりました。«姿の仏法僧» と «声の仏法僧» の話として有名です。","長い石段を登るのは大変ですが、両側の杉の巨木や、苔むした石垣、昔の僧坊の跡を見ながら歩くと、1000年以上続く山の信仰の重みが伝わってきます。本堂の近くからは、奥三河の山々が見わたせます。"],"tl":[["703年","利修仙人が開いたと伝わる"],["1542年","於大の方の祈願によって家康が生まれたと伝わる"],["1651年ごろ","家光の命による鳳来山東照宮が完成"],["1931年","鳳来寺山が国の名勝・天然記念物に指定"],["1935年","鳴き声のラジオ中継をきっかけに «声の仏法僧» がコノハズクとわかる"],["1974年","本堂が再建される"]],"who":[["利修仙人","鳳来寺を開いたと伝わる仙人"],["於大の方","家康の母。鳳来寺で子授けを祈ったと伝わる"],["徳川家康","鳳来寺の薬師如来の縁で生まれたと伝わる"],["徳川家光","鳳来山東照宮の造営を命じた3代将軍"]],"deep":["石段は1425段といわれ、ふもとの門前から本堂まで続きます。途中に仁王門（国の重要文化財）があります。","鳳来山東照宮の本殿などは国の重要文化財。家康をまつる社として、江戸時代には参拝の人でにぎわいました。","«仏法僧» という鳥は、青く美しい鳥ですが «ゲッゲッ» としか鳴きません。«ブッ・ポウ・ソウ» と鳴くのはコノハズクで、愛知県の県鳥にもなっています。","鳳来寺山は、約1500万年前ごろの火山活動でできた岩の山とされ、松脂岩（しょうしがん）などめずらしい岩が見られます。","明治の神仏分離で、東照宮と寺は分けられました。寺の本堂は火事などで何度も失われ、今の本堂は昭和の再建です。"],"look":["1425段の石段と杉の巨木","仁王門（国の重要文化財）","鳳来山東照宮","鳳来寺山自然科学博物館（ふもと）"],"q":["«ブッ・ポウ・ソウ» と鳴く鳥の正体は?","コノハズク（フクロウの仲間）。昔は «仏法僧» という別の鳥の声と思われていました。"],"koji":[],"myth":"利修仙人の開山、家康誕生の伝説、«鳳来» の名の由来は伝承。","img":["鳳来山東照宮","鳳来寺山","コノハズク"],"wp":"鳳来寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/8f/Houraiji.jpg",6016,4016,"鳳来寺"],["c:f/f2/Houraisantoushouguu1.JPG",5968,3979,"鳳来山東照宮"],["c:5/52/Mount_Horaiji_from_Ichinomon.jpg",6000,4000,"鳳来寺山"],["c:d/d0/Oriental_Scops_Owl.jpg",1200,900,"コノハズク"]]},{"id":"23_tsushima_jinja","n":"津島神社（牛頭天王の総本社と信長の経済基盤）","yomi":"つしまじんじゃ","cat":"寺社","rank":"A","y":1591,"era":["muromachi","azuchi","edo"],"sh":"国の重要文化財（本殿・楼門など）","ad":"津島市神明町","st":"名鉄津島線 津島駅から歩いて約15分","la":35.179,"lo":136.7335,"hook":"«津島がなければ信長はいなかった?» 川港のにぎわいが織田家の財布を支え、夏の夜には提灯の船が川面をすべる。","lead":"津島神社は、疫病よけの神 «牛頭天王»（今は建速須佐之男命）をまつる神社で、全国の «天王社» の総本社とされています。門前の津島湊は戦国時代に大いに栄え、織田信長の家の経済を支えました。夏の «尾張津島天王祭» はユネスコ無形文化遺産です。","story":["津島は、昔は木曽川の支流に面した川の港町でした。伊勢と尾張を結ぶ船が行き来し、人と物とお金が集まりました。その町の中心にあったのが津島神社です。牛頭天王は疫病をはらう神として信じられ、全国から «津島の天王さま» にお参りする人が集まりました。","戦国時代、この豊かな津島に目をつけたのが、信長の父・織田信秀でした。信秀は近くの勝幡城を拠点に、津島の町を押さえて大きな財力を手に入れたと考えられています。«なぜ小さな織田家が強くなれたのか?» その秘密の一つが、港と商人の町・津島のお金だったといわれます。","若いころの信長も、津島と深く関わりました。«信長公記» には、信長が津島で踊りを催し、自分も天人の姿で踊ったので、津島の人々が大喜びして、お礼に清洲まで踊りに来たという話が書かれています。町の人々と近い距離にいた、若い信長の姿が浮かびます。","境内の楼門は、1591年に豊臣秀吉が寄進したものと伝わります。本殿は1605年、清洲城主・松平忠吉（家康の四男）の病気が治るよう、妻が寄進したとされます。戦国の英雄たちがこの神社を大切にしたことが、建物からもわかります。","毎年7月に行われる «尾張津島天王祭» では、宵祭に、たくさんの提灯を半円形にかざった «まきわら船» が天王川を静かに進みます。水面に映る灯りの美しさは、室町時代から続くといわれる祭りの伝統を今に伝えています。"],"tl":[["540年","欽明天皇の時代に創建されたと伝わる"],["戦国時代","織田信秀が津島を押さえ財力を得る"],["1591年","豊臣秀吉が楼門を寄進したと伝わる"],["1599年","豊臣秀頼が南門を寄進したと伝わる"],["1605年","本殿が建てられる"],["2016年","尾張津島天王祭の車楽舟行事がユネスコ無形文化遺産に（山・鉾・屋台行事）"]],"who":[["織田信秀","信長の父。津島の経済力を背景に勢力をのばした"],["織田信長","若いころ津島で踊りを催したと «信長公記» にある"],["豊臣秀吉","楼門を寄進したと伝わる"],["松平忠吉","家康の四男・清洲城主。本殿寄進の話に登場"]],"deep":["«牛頭天王» は疫病をはらう神で、京都の八坂神社（祇園社）と並ぶ天王信仰の中心でした。明治の神仏分離で、祭神は建速須佐之男命とされました。","全国にある «津島神社»«天王社» は数千社ともいわれ、津島からお札を配った «御師» の活動で信仰が広がりました。","本殿と楼門・南門などは国の重要文化財。本殿は «尾張造» と呼ばれる尾張地方特有の社殿配置の形を伝えています。","天王祭のまきわら船には、1年の日数にちなんだ数の提灯と、1か月の数にちなんだ提灯がかざられるといわれます。","神社のそばの «堀田家住宅» は、江戸時代の津島の豪商・神職の家として国の重要文化財に指定されています。"],"look":["楼門（国の重要文化財）","本殿・南門","天王川公園（天王祭の舞台）","門前町の古い町並みと堀田家住宅"],"q":["信長の父・織田信秀が財力を得たといわれる、川の港町はどこ?","津島。津島神社の門前町で、津島湊として栄えました。"],"koji":[],"myth":"創建年は伝承。楼門・南門の寄進者、提灯の数の意味は伝承を含む。","img":["尾張津島天王祭","牛頭天王","織田信秀"],"wp":"津島神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a1/Tsushima-jinja_Shrine_Haiden_%281%29%2C_Shimmei-cho_Tsushima_City_2023.jpg",1500,1000,"津島神社"],["c:4/49/Tsushimatennosai1.JPG",6000,4000,"尾張津島天王祭"],["c:f/f9/Gozu-ten-no.jpg",1375,1880,"牛頭天王"],["c:1/15/Statue_of_Oda_Nobuhide_at_Bansh%C5%8D-ji.jpg",1740,1849,"織田信秀"]]},{"id":"23_osu_kannon","n":"大須観音（真福寺文庫）","yomi":"おおすかんのん","cat":"寺社","rank":"A","y":1612,"era":["kamakura","edo"],"sh":"国宝（真福寺本古事記などを所蔵）","ad":"名古屋市中区大須2丁目","st":"地下鉄鶴舞線 大須観音駅から歩いて約2分","la":35.1592,"lo":136.8986,"hook":"にぎやかな大須商店街のとなり。この寺の書庫には、現存する最古の «古事記» の写本が眠っている。","lead":"大須観音の正式な名前は «北野山真福寺宝生院»。真言宗のお寺です。もとは今の岐阜県羽島市の «大須» という地にありましたが、江戸時代のはじめに家康の命で名古屋へ移されました。お寺の書庫 «大須文庫»（真福寺文庫）には、国宝の «古事記» の写本など、貴重な古い書物が数多く伝わります。","story":["鎌倉時代の終わりごろ、尾張国の大須郷（今の岐阜県羽島市）に、能信という僧がお寺を開きました。これが真福寺です。能信は学問を大切にし、たくさんの経典や書物を集めました。お寺は «大須観音» と呼ばれて栄えます。","大須の地は木曽川の近くで、たびたび洪水に苦しめられました。1612年、名古屋城を築いていた家康は、お寺を名古屋の城下に移すよう命じます。«なぜ移されたのか?» 洪水を避けるためと、新しい町・名古屋に人を集めるためだったと考えられています。こうして移ったお寺の地名が、今の名古屋の «大須» になりました。","このお寺の本当の宝物は、書庫の中にあります。とくに有名なのが、南北朝時代の1371〜1372年に、僧の賢瑜が書き写した «古事記» です。«真福寺本» と呼ばれるこの写本は、今残っている古事記の中でいちばん古いもので、国宝に指定されています。«もしこの写本がなかったら?» 日本の神話の研究は、ずっと難しかったかもしれません。","江戸時代、大須観音の門前は芝居小屋や見世物でにぎわう町になりました。明治の火事や戦争の空襲で建物は失われましたが、今の本堂は1970年に再建されました。門前の大須商店街は、今も古着やB級グルメ、電気街が入りまじる、名古屋でいちばん元気な商店街の一つです。","本堂の前では、はとがのんびりと歩き、観光客や地元の人がひっきりなしにお参りしています。にぎやかな町の真ん中で、700年近く前から集められてきた書物が大切に守られている。そのギャップも、大須観音の魅力です。"],"tl":[["鎌倉時代末","能信が尾張国大須郷に真福寺を開く"],["1371〜1372年","賢瑜が «古事記» を書き写す（真福寺本）"],["1612年","家康の命で名古屋の現在地へ移る"],["1892年","火事で本堂などが焼ける"],["1945年","空襲で被害を受ける"],["1970年","本堂が再建される"]],"who":[["能信","真福寺を開いた僧。多くの書物を集めた"],["賢瑜","«古事記» の写本（真福寺本）を書き写した僧"],["徳川家康","お寺を名古屋に移すよう命じた"]],"deep":["«大須文庫» には、国宝・重要文化財を含む1万点を超える典籍が伝わるといわれ、中世の仏教や神道、文学の研究にとって宝の山です。","真福寺本古事記は上・中・下の3冊からなり、国宝に指定されています。ふだんは公開されていません。","大須観音は、東京の浅草寺、三重県津市の津観音とあわせて «日本三大観音» と呼ばれることがあります。","毎月18日と28日には境内で骨董市が開かれ、たくさんの店がならびます。","羽島市には今も «大須» の地名が残り、お寺のもとの場所を伝えています。"],"look":["本堂（1970年再建）","境内の骨董市（毎月18日・28日）","大須商店街","本堂前の «大須文庫» についての案内"],"q":["大須観音に伝わる、現存最古の «古事記» の写本を何という?","真福寺本（しんぷくじぼん）。南北朝時代に書き写され、国宝です。"],"koji":[],"myth":"移転の理由、«日本三大観音» の数え方は諸説。","img":["古事記","大須商店街"],"wp":"大須観音","rel":{"ev":[],"grave":[]},"ph":[["c:2/21/Houshou-in_Hondou%2C_Osu_Naka_Ward_Nagoya_2022.jpg",1500,1000,"大須観音"],["c:0/05/Kojiki_Shinpukuji.jpg",246,350,"古事記"],["c:6/68/View_of_Osu_Intersection_%26_Monzen-cho-Dori_St.%2C_Monzen-cho_Naka_Ward_Nagoya_2022.jpg",1500,1000,"大須商店街"]]},{"id":"23_nittaiji","n":"覚王山日泰寺（釈迦の遺骨を祀る）","yomi":"かくおうざんにったいじ","cat":"寺社","rank":"A","y":1904,"era":["meiji","taisho"],"sh":"","ad":"名古屋市千種区法王町1丁目","st":"地下鉄東山線 覚王山駅から歩いて約7分","la":35.168,"lo":136.9555,"hook":"インドで見つかったお釈迦さまの遺骨が、タイの国王から日本へ。その «仏舎利» をまつるため、どの宗派にも属さないお寺が作られた。","lead":"覚王山日泰寺は、お釈迦さまの遺骨 «仏舎利» をまつるために、明治時代の終わりに作られたお寺です。タイ（当時のシャム）の国王から贈られた仏舎利が納められています。特定の宗派に属さず、多くの宗派が協力して運営している、日本でもめずらしいお寺です。","story":["1898年、インドとネパールの国境近くのピプラーワーという場所で、イギリス人のペッペが古い仏塔を発掘しました。中から出てきたつぼには、«これはお釈迦さまの遺骨である» という意味の古い文字が刻まれていました。","この遺骨は、仏教の国であるシャム（今のタイ）の国王、ラーマ5世（チュラーロンコーン王）に贈られました。国王は、仏教を信じる国々に遺骨を分けることにし、日本にも1900年に分けられました。«日本のどこにまつるか?» 各地が名乗りを上げ、話し合いの結果、名古屋にまつられることになりました。","1904年、覚王山の地に «日暹寺» が作られます。«暹» はシャムのことです。1939年にシャムが国名をタイに改めたことを受けて、1942年にお寺の名前も «日泰寺» と改められました。«日本とタイの寺» という名前には、両国の友好の思いがこめられています。","仏舎利は、境内の奥にある «奉安塔» に納められています。建築家の伊東忠太が設計した、ガンダーラ風の塔です。本堂には、タイの国王から贈られた金色の釈迦如来像がまつられています。日泰寺は、今も19の宗派が交代で住職をつとめるという、しくみそのものがめずらしいお寺です。","毎月21日の縁日には、参道に露店がならび、にぎわいます。覚王山の町には、お寺の縁で生まれたしゃれた店や古い邸宅も多く、仏舎利を迎えた明治の熱気が、今も町の雰囲気に残っています。"],"tl":[["1898年","ピプラーワーで仏舎利が発掘される"],["1900年","シャム国王から日本に仏舎利が贈られる"],["1904年","日暹寺として創建"],["1918年","仏舎利を納める奉安塔が完成"],["1939年","シャムの国名がタイに変わる"],["1942年","寺名を日泰寺に改める"]],"who":[["ラーマ5世（チュラーロンコーン王）","シャム国王。日本に仏舎利を分けた"],["ペッペ","ピプラーワーの仏塔を発掘したイギリス人"],["伊東忠太","奉安塔を設計した建築家"]],"deep":["仏舎利の入っていたつぼの文字は、古いブラーフミー文字で書かれ、釈迦族が遺骨をまつったことを示すと解釈されています。","日泰寺は、日本の仏教の19宗派が加わる超宗派の寺で、住職は各宗派から3年ごとに交代でつとめるとされています。","奉安塔は、1918年ごろに完成。ふだんは中に入れませんが、特別な日に参拝できることがあります。","本堂の釈迦如来像は、タイの国王から贈られたもので、タイ風の金色の仏像です。","«覚王» とはお釈迦さまのことで、地名の «覚王山» もこのお寺にちなんで生まれました。","ピプラーワーの仏舎利は、日本のほかスリランカやミャンマーなど、仏教の国々にも分けられたと伝わります。日泰寺にはタイの王族や政府関係者が訪れることもあり、両国の交流の場にもなっています。"],"look":["本堂の金色の釈迦如来像","奉安塔（仏舎利を納める塔）","参道と五重塔","毎月21日の縁日"],"q":["日泰寺の «泰» は、どこの国を表している?","タイ。もとはシャムを表す «暹» の字を使い «日暹寺» と呼ばれていました。"],"koji":[],"myth":"仏舎利の真偽については学問的な議論がある。","img":["仏舎利","ラーマ5世","伊東忠太"],"wp":"日泰寺","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Stupa_in_Gotemba.jpg",1536,2048,"仏舎利"],["c:d/d4/Chulalongkorn_LoC.jpg",3168,4036,"ラーマ5世"],["c:0/04/Ito_Chuta_01.jpg",1950,2600,"伊東忠太"]]},{"id":"23_banshoji","n":"万松寺（信長が父の位牌に抹香を投げた寺）","yomi":"ばんしょうじ","cat":"寺社","rank":"A","y":1540,"era":["muromachi","azuchi","edo"],"sh":"","ad":"名古屋市中区大須3丁目","st":"地下鉄 上前津駅から歩いて約5分／大須観音駅から約7分","la":35.1597,"lo":136.9043,"hook":"父の葬儀に、髪はぼさぼさ、刀を縄で巻いた姿で現れた18歳の信長。仏前の抹香をつかむと、ぱっと投げつけた。","lead":"万松寺は、織田信長の父・織田信秀が建てた曹洞宗のお寺です。信秀の葬儀で、若い信長が位牌に抹香を投げつけたという有名な話の舞台です。江戸時代のはじめに今の大須の地へ移り、今はにぎやかな商店街の中にあります。","story":["1540年、尾張の実力者・織田信秀は、織田家の菩提寺として万松寺を建てました。開山は大雲永瑞という僧で、信秀の叔父にあたるといわれます。もとの寺地は、のちに名古屋城が建てられるあたりに近い場所でした。","1551年（1552年説もあります）、信秀が亡くなり、万松寺で盛大な葬儀が行われました。僧が何百人も集まる中、跡継ぎの信長は、髪を茶せんのように結い、帯の代わりに縄を巻いた姿で現れたといいます。そして抹香をつかむと、仏前に投げつけて帰ってしまいました。«信長公記» に書かれている有名な場面です。","«大うつけ（大ばか者）だ» と人々はあきれました。一方、弟の信勝は、礼儀正しく振る舞ったといいます。«なぜ信長はそんなことをしたのか?» 父の死への怒りや悲しみ、古いしきたりへの反発など、さまざまな解釈がありますが、本当の気持ちはわかりません。ただ «信長公記» には、九州から来た僧が «あの方こそ国を持つ人だ» と言ったという話も書かれています。","信長を育てた家老・平手政秀は、その後まもなく自ら命を絶ちました。信長をいさめるためだったと伝わります。信長は深く悲しみ、政秀のために寺を建てました。万松寺は、若い信長の苦しい出発を見守った寺だったのです。","1610年ごろ、名古屋城を築くにあたって、万松寺は今の大須へ移されました。戦争の空襲などで古い建物は失われましたが、今も信長の抹香投げの場面を再現したからくり人形などで、その物語を伝えています。"],"tl":[["1540年","織田信秀が万松寺を建てる"],["1551年","信秀が亡くなり、葬儀で信長が抹香を投げる（1552年説も）"],["1553年","平手政秀が自害"],["1610年ごろ","名古屋城築城にともない現在地へ移る"],["1945年","空襲で被害を受ける"]],"who":[["織田信秀","信長の父。万松寺を建てた"],["織田信長","父の葬儀で抹香を投げたと «信長公記» にある"],["大雲永瑞","万松寺を開いた僧。信秀の叔父といわれる"],["平手政秀","信長の守役（教育係）の家老。信長をいさめて自害したと伝わる"],["織田信勝","信長の弟。葬儀で礼儀正しく振る舞った"]],"deep":["抹香投げの話は、信長の家臣だった太田牛一が書いた «信長公記» の首巻に出てきます。信長の若いころを知る人の記録として、比較的信頼されています。","信秀が亡くなった年は、1551年説と1552年説があり、研究者の間でも分かれています。","平手政秀の自害の理由は «信長をいさめるため» と伝わる一方、政秀の子と信長の間のいさかいが原因とする記録もあります。","信長が政秀のために建てた寺は «政秀寺» で、今も名古屋市中区にあります。","幼い徳川家康（竹千代）が織田家の人質だったころ、万松寺にいたという伝えもありますが、確かではありません。"],"look":["本堂","信長の抹香投げのからくり人形","境内の白雪稲荷","大須商店街とあわせた散策"],"q":["父・信秀の葬儀で信長が位牌に投げつけたものは?","抹香。仏前で焚く粉のお香で、«信長公記» にこの場面が書かれています。"],"koji":[{"w":"大うつけ","m":"とてもばかげたことをする人。若いころの信長はこう呼ばれた"}],"myth":"信秀の没年、平手政秀の自害の理由、竹千代の滞在は諸説・伝承。","img":["織田信秀","平手政秀","信長公記"],"wp":"万松寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/f9/Banshoji.jpg",6016,4016,"万松寺"],["c:1/15/Statue_of_Oda_Nobuhide_at_Bansh%C5%8D-ji.jpg",1740,1849,"織田信秀"],["c:2/26/Statue_of_Hirate_Masahide.jpg",1788,1330,"平手政秀"]]},{"id":"23_kenchuji","n":"建中寺（尾張徳川家の菩提寺）","yomi":"けんちゅうじ","cat":"墓所","rank":"A","y":1651,"era":["edo"],"sh":"","ad":"名古屋市東区筒井1丁目","st":"地下鉄桜通線 車道駅から歩いて約10分。市バス «建中寺» 停留所すぐ","la":35.1786,"lo":136.9243,"hook":"名古屋の真ん中に、尾張徳川家の歴代藩主がねむる巨大な寺がある。その門は、大火をくぐりぬけて江戸の姿のまま立っている。","lead":"建中寺は、尾張藩2代藩主・徳川光友が、父で初代藩主の徳川義直をとむらうために建てた浄土宗のお寺です。以後、尾張徳川家の «菩提寺»（先祖をまつる寺）となり、多くの藩主がここに葬られました。大きな総門と三門は、名古屋に残る江戸時代の建物の代表です。","story":["1650年、尾張藩の初代藩主・徳川義直が江戸で亡くなりました。家康の九男で、学問を愛し、名古屋の町の基礎を築いた殿さまです。跡をついだ息子の光友は «父上をまつる、尾張家にふさわしい寺をつくらねば» と考え、翌1651年、名古屋城の東に広い土地を用意して寺を建てました。それが建中寺です。","寺の境内はとても広く、たくさんの建物が並びました。本堂、経蔵、鐘楼、そして義直の霊をまつる御霊屋（おたまや）。まわりには家臣たちの屋敷が並び、寺そのものが一つの町のようだったといわれます。なぜこれほど大きいのか？ それは、御三家の筆頭・尾張徳川家の «格» を目に見える形で示す場所でもあったからです。","ところが1785年、城下を襲った大火が建中寺にも燃えうつり、本堂など多くの建物が焼けてしまいました。それでも総門と三門は焼け残ったと伝えられます。本堂などは藩の力で再建され、いま見られる伽藍の多くはこのときのものです。","明治になって藩がなくなると、寺の土地の多くは手放され、学校や住宅地に変わっていきました。第二次世界大戦の空襲の被害もありました。それでも、どっしりした三門をくぐると、江戸時代の尾張家の «重み» がふっと伝わってきます。","藩主たちの墓所は、いまは一般には公開されていません。見学するときは、静かに手を合わせる場所であることを忘れずに歩きましょう。"],"tl":[["1650年","初代藩主・徳川義直が亡くなる"],["1651年","2代藩主・徳川光友が建中寺を創建"],["江戸時代","以後、尾張藩主の多くがここに葬られる"],["1785年","大火で本堂など多くを焼失（総門・三門は焼け残ったと伝わる）"],["大火のあと","藩の手で本堂などを再建"],["明治以降","境内の土地が縮小し、周辺は町や学校に"]],"who":[["徳川光友","尾張藩2代藩主。父をとむらうため建中寺を建てた"],["徳川義直","初代藩主・家康の九男。この寺でまつられる"],["歴代の尾張藩主","多くがここに葬られた"]],"deep":["初代義直の墓そのものは建中寺ではなく、瀬戸市の定光寺にあります。建中寺はあくまで «義直をまつるために建てた寺» で、2代以降の藩主の多くの墓所がここに置かれました。","«菩提寺» と «祈願寺» はちがいます。菩提寺は先祖の供養をする寺。尾張徳川家の菩提寺として、藩が寺を手厚く守りました。","総門は道路に面した大きな門で、名古屋で江戸時代の門を目にできる数少ない場所です。三門は二階建ての楼門で、上層に仏像をまつる形式です。","境内にはかつて藩主の家族や家臣ゆかりの建物も多くありました。明治以降に土地が大きく減り、周辺の学校の敷地などに姿を変えています。","建中寺の周辺（東区の «白壁・主税・橦木» 地区など）は、江戸時代の武家屋敷町から明治・大正の実業家の住宅地へと移り変わった地域です。あわせて歩くと、名古屋の町の変化がよくわかります。","1785年の大火は «天明の大火» と呼ばれる名古屋城下の大火事の一つで、城下の東部が大きな被害を受けたと伝わります。焼け残った門は、それだけで貴重な «生き証人» です。"],"look":["総門（通りに面した大きな門）","三門（二階建ての楼門）","本堂（大火のあとに再建）","徳川家の家紋 «葵紋» が入った瓦や飾り","周辺の «文化のみち»（白壁・主税町の町並み）"],"q":["建中寺を建てた尾張藩2代藩主はだれ？","徳川光友です。父の徳川義直をとむらうために1651年に建てました。"],"koji":[],"myth":"総門・三門が天明の大火で焼け残った経緯には細かな説明の違いがある。墓所は非公開。","img":["徳川光友","徳川義直","尾張藩"],"wp":"建中寺","rel":{"ev":[],"grave":[]},"ph":[["c:2/21/Kenchu-ji_Temple_Hondou%2C_Tsutsui_Higashi_Ward_Nagoya_2021.jpg",1500,1000,"建中寺"],["c:d/d3/Tokugawa_Mitsutomo.jpg",536,623,"徳川光友"],["c:9/93/Tokugawa_Yoshinao.jpg",808,657,"徳川義直"]]},{"id":"23_tokugawa_bijutsukan","n":"徳川美術館と徳川園（尾張徳川家の大曽根屋敷）","yomi":"とくがわびじゅつかん","cat":"大名屋敷","rank":"A","y":1695,"era":["edo","showa"],"sh":"国の登録有形文化財（美術館本館）","ad":"名古屋市東区徳川町","st":"JR・名鉄・地下鉄 大曽根駅から歩いて約10〜15分。市バス «徳川園新出来» 停留所から歩いて約3分","la":35.1843,"lo":136.9335,"hook":"国宝 «源氏物語絵巻» が眠る美術館は、尾張の殿さまが隠居のために建てた屋敷の跡に立っている。","lead":"徳川美術館は、尾張徳川家に伝わった刀・よろい・茶道具・絵巻など1万件以上の宝物を公開する美術館です。となりの徳川園は、2代藩主・光友が隠居所として建てた «大曽根屋敷» の跡。空襲で焼けたあと、日本庭園としてよみがえりました。","story":["江戸時代の中ごろ、尾張藩2代藩主・徳川光友は藩主の座を息子にゆずり、名古屋城の東、大曽根の地に広い屋敷をかまえました。これが «大曽根屋敷» です。光友はここで晩年を過ごしたといわれ、屋敷は光友の死後、藩の重臣たちに分けあたえられました。","明治になり、この場所は尾張徳川家の邸宅となります。昭和のはじめ、19代当主の徳川義親（よしちか）は大きな決断をしました。«家の宝は、家の中にしまっておくだけでは守れない» 。義親は財団をつくって家宝を託し、1935年、邸宅の一部に徳川美術館を開きました。","大名家の宝物がまとめて一般に公開されるのは、当時としては画期的なことでした。家康の遺品 «駿府御分物»、刀剣やよろい、能の装束、そして国宝の «源氏物語絵巻» や «初音の調度»。義親は、戦争や相続で散らばってしまうのを防ぎたかったのだと考えられています。","1945年、名古屋を襲った空襲で、邸宅は大きな被害を受けました。しかし宝物は疎開させてあったため多くが守られました。戦後、邸宅の庭は «徳川園» として市民に開かれ、2004年に池泉回遊式の日本庭園として整えなおされました。","いま、美術館の本館は昭和の初めらしい重厚な建物として登録有形文化財になっています。庭園の滝や池を歩いたあとで館内の宝物を見ると、殿さまの暮らしの «表» と «奥» が一度に感じられます。"],"tl":[["1695年ごろ","徳川光友が大曽根屋敷を造営（元禄期）"],["1700年","光友が亡くなる"],["明治時代","尾張徳川家の邸宅となる"],["1931年","徳川義親が財団（徳川黎明会）を設立"],["1935年","徳川美術館が開館"],["1945年","空襲で邸宅が被害を受ける"],["2004年","徳川園が日本庭園としてリニューアル公開"]],"who":[["徳川光友","2代藩主。隠居所として大曽根屋敷を建てた"],["徳川義親","19代当主。財団をつくり美術館を開いた"],["徳川家康","多くの遺品がこの美術館に伝わる"],["千代姫","3代将軍家光の娘。光友に嫁ぐとき «初音の調度» を持参"]],"deep":["国宝 «源氏物語絵巻» は12世紀に描かれた現存最古級の絵巻で、徳川美術館と東京の五島美術館に分かれて伝わります。傷みやすいため、公開は期間を限って行われます。","«初音の調度» は、家光の長女・千代姫が1639年に光友へ嫁いだときの婚礼道具。源氏物語 «初音» の巻を題材にした蒔絵で、国宝に指定されています。","«駿府御分物（すんぷおわけもの）» は、家康の死後に遺品が御三家などに分けられたもの。尾張家に伝わった品が、将軍の «実際の持ち物» を知る手がかりになっています。","本館の建物は、鉄筋コンクリートに瓦屋根をのせた昭和初期の様式で、戦前の美術館建築として評価されています。","徳川義親は «殿様生物学者» とも呼ばれ、植物学の研究やマレー半島での «虎狩り» でも知られた、型破りな人物でした。","館内には名古屋城二之丸御殿の広間の一部や、茶室の再現などがあり、大名の «表向き» の生活空間を体感できる展示の工夫があります。"],"look":["美術館本館の外観（昭和初期の建物）","大名の書院・茶室を再現した展示室","期間限定の «源氏物語絵巻» 公開","徳川園の «黒門»（旧邸宅の門）","徳川園の龍仙湖と大曽根の滝"],"q":["徳川美術館を開いた尾張徳川家19代当主はだれ？","徳川義親です。1935年、家に伝わる宝物を守り公開するため美術館を開きました。"],"koji":[],"myth":"大曽根屋敷の造営年は資料により表記に幅がある（元禄期）。展示品は時期により入れかわる。","img":["源氏物語絵巻","徳川義親","徳川園","徳川光友"],"wp":"徳川美術館","rel":{"ev":[],"grave":[]},"ph":[["c:f/f3/View_of_Tokugawa_Art_Museum_%281%29%2C_Tokugawa-cho_Higashi_Ward_Nagoya_2021.jpg",1500,1000,"徳川美術館"],["c:d/d6/Genji_emaki_azumaya.jpg",4578,2501,"源氏物語絵巻"],["c:a/a5/%E5%BE%B3%E5%B7%9D%E7%BE%A9%E8%A6%AA.jpg",485,700,"徳川義親"],["c:f/f0/Tokugawaen_Ryusen-ko_01%2C_Tokugawa-cho_Higashi_Ward_Nagoya_2014.jpg",1500,1000,"徳川園"],["c:d/d3/Tokugawa_Mitsutomo.jpg",536,623,"徳川光友"]]},{"id":"23_nomadaibo","n":"野間大坊（源義朝最期の地と墓）","yomi":"のまだいぼう","cat":"墓所","rank":"A","y":1160,"era":["heian","kamakura"],"sh":"","ad":"知多郡美浜町野間","st":"名鉄知多新線 野間駅から歩いて約15分","la":34.787,"lo":136.8573,"hook":"«せめて木太刀の一本でもあれば» ——源氏の大将は湯殿で討たれた。墓には今も、無数の木太刀が供えられている。","lead":"野間大坊（正式名は大御堂寺）は、知多半島にある古いお寺です。1160年、平治の乱に敗れた源義朝がこの地で家臣に裏切られて討たれ、境内に墓がつくられました。のちに息子の頼朝が父の供養のため訪れたと伝わります。","story":["1159年の暮れ、京都で «平治の乱» が起こりました。源義朝は藤原信頼と組んで兵をあげましたが、平清盛に敗れます。義朝はわずかな家臣とともに東国をめざして逃げ、尾張の知多半島へたどりつきました。","たよったのは、家臣・鎌田政清の妻の父、長田忠致（おさだ ただむね）でした。«ここなら安心だ» と義朝は思ったでしょう。しかし忠致は、平家に味方して恩賞をもらおうと考えていました。年が明けた正月、義朝が風呂に入っているところを、忠致の手の者がおそったと伝わります。","武器を持たない義朝は «我に木太刀の一本なりともあれば» ——せめて木の太刀一本でもあれば——と叫んで討たれた、といい伝えられています。鎌田政清もその場で命を落としました。この言葉から、義朝の墓にはいまも参拝者が木太刀を供える習わしが続いています。","それから約30年後、義朝の子・頼朝は平家を倒して武家の頭となりました。1190年、頼朝は上洛の途中でこの地を訪れ、父の墓にお参りして寺に供養をささげたと伝わります。境内の «大門» は頼朝の寄進と伝わる門です。","野間大坊には、もう一人悲しい最期をむかえた人の墓があります。織田信長の三男・信孝です。1583年、羽柴秀吉と対立して追いつめられ、この寺で自害したと伝わります。二人の武将の無念が重なる、静かな寺です。"],"tl":[["1159年12月","平治の乱。源義朝が平清盛に敗れる"],["1160年正月","義朝が野間で長田忠致に討たれる（墓がつくられる）"],["1185年","平家が壇ノ浦で滅亡"],["1190年","源頼朝が上洛の途中、父の墓に参ったと伝わる"],["1583年","織田信孝がこの地で自害したと伝わる"],["現在","義朝の墓には木太刀が供えられ続けている"]],"who":[["源義朝","源氏の大将。頼朝・義経の父。この地で討たれた"],["鎌田政清","義朝の乳兄弟で家臣。ともに討たれた"],["長田忠致","政清の妻の父。義朝を裏切った"],["源頼朝","義朝の子。のちに父の墓を参ったと伝わる"],["織田信孝","信長の三男。この寺で自害したと伝わる"]],"deep":["義朝の最期は軍記物 «平治物語» にくわしく描かれています。湯殿で討たれた場面や «木太刀» の言葉は物語としての脚色も含まれると考えられ、史実と伝承を分けて読むことが大切です。","長田忠致はのちに頼朝のもとに身を寄せ、手柄を立てれば «美濃・尾張をあたえる» と言われたのに、最後は «身の終わり» をあたえられて処刑された、という語呂合わせの話が伝わります。これは伝承です。","織田信孝の辞世として «昔より主（しゅう）を討つ身の野間なれば 報いを待てや羽柴筑前» が伝わります。義朝の故事になぞらえて秀吉を呪った歌ですが、本当に信孝の作かは確かではありません。","義朝の墓の横には鎌田政清夫妻の墓もあり、主従がいっしょにまつられています。政清の妻は父の裏切りを知って自ら命を絶ったと伝わります。","寺は真言宗の古い寺で、境内には «血の池»（義朝の首を洗ったと伝わる池。異変があると赤くなるという言い伝え）など、伝承のある場所が点在します。"],"look":["源義朝の墓と、供えられた木太刀","鎌田政清夫妻の墓","頼朝寄進と伝わる大門","織田信孝の墓（安養院）","血の池（伝承地）"],"q":["源義朝の墓に参拝者が供えるものは？","木太刀（木でできた太刀）です。«木太刀一本でもあれば» という最期の言葉にちなむと伝わります。"],"koji":[{"w":"身の終わり（美濃・尾張）","m":"長田忠致が恩賞として «美濃・尾張» ではなく «身の終わり» を与えられたという、裏切り者の末路を語る語呂合わせの伝承"}],"myth":"湯殿での最期や «木太刀» の言葉、長田父子の処刑の語呂合わせ、血の池、信孝の辞世は伝承・軍記物由来。","img":["源義朝","平治の乱","長田忠致","織田信孝"],"wp":"大御堂寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/53/Nomataibo1.jpg",6016,4016,"大御堂寺"],["c:4/40/Minamoto_no_Yoshitomo.jpg",479,424,"源義朝"],["c:2/26/Heiji_no_ran.jpg",6064,2085,"平治の乱"],["c:b/b0/Oda_Nobutaka.jpg",950,1390,"織田信孝"]]},{"id":"23_honshoji","n":"本證寺（三河一向一揆の拠点・城郭寺院）","yomi":"ほんしょうじ","cat":"寺社","rank":"A","y":1563,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"安城市野寺町","st":"名鉄西尾線 桜井駅・南桜井駅方面から歩いて約25〜30分。車やバス利用が便利","la":34.918,"lo":137.066,"hook":"若き家康が «生涯の三大危機» の一つと語られる戦いの相手は、城ではなく «お寺» だった。","lead":"本證寺は、浄土真宗のお寺です。1563年から翌年にかけて起きた «三河一向一揆» では、一揆側の中心の一つとなりました。境内のまわりには今も堀がめぐり、見張り台のような鼓楼が立つ «城のような寺»。2015年に国の史跡に指定されました。","story":["戦国時代の三河では、浄土真宗（一向宗）の信仰が農民や武士に広く広がっていました。本證寺・上宮寺・勝鬘寺の三つの大寺は «三河三ヶ寺» と呼ばれ、多くの門徒をたばねていました。寺には «不入の権» ——領主でも勝手に立ち入れない特権——があったといわれます。","1563年、今川家から独立したばかりの若い松平家康（のちの徳川家康）の家臣が、寺の特権をおかす行動をとったことがきっかけとなり、門徒たちが立ち上がりました。«三河一向一揆» です。家康にとってつらかったのは、自分の家臣の中にも門徒が多く、半分近くが一揆側についたといわれることでした。","«殿を取るか、仏を取るか» ——家臣たちは深く悩んだでしょう。のちに家康の知恵袋となる本多正信も、このとき一揆側につき、戦いのあと三河を離れたと伝わります。戦いは激しく、家康自身も危うい目にあったと語られています。","翌1564年、和議が結ばれました。«寺は元のまま» という約束だったのに、家康は寺を壊し、«元は野原だった» と言ったという話が伝わります。真宗の寺はその後およそ20年、三河から姿を消しました。1585年ごろに再興が許され、本證寺も復興します。","いまの本證寺には、内堀と外堀の跡、そして鼓楼が残ります。お寺なのに城のような堀。なぜでしょう？ それは、この寺が信仰の場であると同時に、門徒が集まり身を守る «とりで» でもあったからです。"],"tl":[["室町時代","本證寺が三河の真宗の拠点として発展"],["1563年","三河一向一揆が起こる"],["1564年","和議。のちに真宗寺院が破却・追放される"],["1585年ごろ","真宗の再興が許され、寺も復興へ"],["江戸時代","堀を持つ寺として存続"],["2015年","«本證寺境内» が国指定史跡に"]],"who":[["徳川家康","三河一向一揆と戦った若き領主"],["本多正信","家康の家臣。一揆側につき、のちに帰参"],["空誓","本證寺の住職。一揆の中心人物の一人"],["三河の門徒","農民や武士。信仰を守るため戦った"]],"deep":["一揆のきっかけは、家康の家臣が寺内に入り米を取り立てた、あるいは寺の中の者を捕らえた、など諸説があります。«不入の権» をめぐる争いだった点では共通しています。","家康の «三大危機» として三河一向一揆・三方ヶ原の戦い・伊賀越えがあげられることがありますが、これは後世の整理で、家康自身の言葉ではありません。","本證寺の堀は、内堀と外堀の二重構造で、寺を守る «城郭寺院» の特徴をよく残しています。発掘調査で、中世の堀の跡も確認されています。","境内の鼓楼は江戸時代の建物で、太鼓で時を告げる建物ですが、高い櫓のような姿から «城の見張り台» のようにも見えます。","一揆側についた家臣の多くは、のちに許されて家康のもとに戻りました。この経験が、家康の家臣団の «結束の強さ» につながったとみる見方もあります。"],"look":["内堀と外堀の跡（寺をかこむ堀）","鼓楼（櫓のような太鼓楼）","本堂と山門","境内の案内板（一揆と寺の歴史）"],"q":["本證寺はどの一揆の拠点になった？","三河一向一揆（1563〜64年）です。若い家康の家臣の中にも一揆側についた人が多くいました。"],"koji":[],"myth":"一揆の発端、«元は野原» の逸話、家康の危機の具体的な場面は諸説・伝承。","img":["三河一向一揆","本多正信","空誓"],"wp":"本證寺","rel":{"ev":[],"grave":[]},"ph":[["c:6/67/Azukizaka_1564.JPG",1933,925,"三河一向一揆"],["c:0/02/Honda_Masanobu02.JPG",1500,1900,"本多正信"]]},{"id":"23_matsudaira_go","n":"松平郷（松平氏・徳川家発祥の地）","yomi":"まつだいらごう","cat":"町","rank":"A","y":1400,"era":["muromachi","edo"],"sh":"国指定史跡（松平氏遺跡）","ad":"豊田市松平町","st":"名鉄豊田市駅からとよたおいでんバスで «松平郷» 下車（約40分）。車が便利","la":35.0888,"lo":137.256,"hook":"山あいの小さな里から、260年以上続く将軍家が生まれた——その始まりは、一人の旅の僧だった。","lead":"松平郷は、徳川家康の先祖である松平氏が生まれた山里です。旅の僧が土地の有力者の婿となって «松平親氏» を名のったのが始まりと伝わります。館の跡、先祖をまつる松平東照宮、一族の墓がある高月院などがまとまって残り、国の史跡になっています。","story":["室町時代のはじめごろ、三河の山あいに一人の旅の僧がやってきました。名は «徳阿弥（とくあみ）»。各地を旅する時宗の僧で、もとは新田氏につながる家の出だったといわれます。","この里の有力者・松平太郎左衛門信重は、徳阿弥の人柄を見こんで、«娘の婿になってほしい» とたのんだと伝わります。徳阿弥は還俗して «松平親氏（ちかうじ）» と名のり、松平家の初代となりました。これが、のちの徳川将軍家の出発点といわれています。","親氏とその子孫は、山の中から少しずつ平野へと勢力を広げていきました。岩津、安城、そして岡崎へ。松平の一族はあちこちに分家をつくり、«十八松平» と呼ばれるほど広がりました。そのなかの安城松平家から、やがて家康が生まれます。","家康が岡崎城で生まれたとき、産湯に使う水をこの松平郷の井戸から運んだ、という話が伝わります。松平東照宮の境内には、その «産湯の井戸» が残っています。本当かどうかはわかりませんが、先祖の地を大切に思う気持ちが込められた伝承です。","いまの松平郷は、棚田と林にかこまれた静かな里です。«ここから天下人が？» と驚くほど小さな場所。だからこそ、一族が何代もかけて少しずつ大きくなっていった長い時間を感じることができます。"],"tl":[["14世紀後半ごろ","徳阿弥が松平家の婿となり松平親氏を名のると伝わる"],["15世紀","松平氏が岩津・安城などへ勢力を広げる"],["1542年","家康（竹千代）が岡崎城で生まれる"],["1603年","家康が征夷大将軍となる"],["江戸時代","松平郷の松平家（太郎左衛門家）は旗本として存続"]],"who":[["松平親氏","松平氏の初代と伝わる。もとは旅の僧・徳阿弥"],["松平太郎左衛門信重","松平郷の有力者。親氏を婿に迎えたと伝わる"],["徳川家康","松平氏の子孫。将軍家を開いた"]],"deep":["親氏の出自を新田氏の流れとする話は、徳川家が «源氏» の家柄であることを示すために江戸時代に整えられた系図と深く関わっており、歴史学では慎重に扱われています。","国指定史跡 «松平氏遺跡» は、松平氏館跡・高月院・松平城跡・大給城跡など複数の場所で構成されています。松平郷だけでなく周辺の山城もふくめた «一族の遺跡群» です。","高月院は松平氏の菩提寺で、親氏の墓と伝わる墓所があります。江戸時代には将軍家ゆかりの寺として保護されました。","松平郷に残った本家筋の松平太郎左衛門家は、江戸時代にはわずか数百石ほどの旗本でしたが、将軍家の «ふるさとの家» として特別な扱いを受けたといわれます。","«十八松平» は数え方に諸説あり、実際に18家だったとは限りません。«たくさんの分家» を表すことばと考えるとよいでしょう。"],"look":["松平東照宮と «産湯の井戸»","松平氏館跡の石垣・堀の跡","高月院（親氏の墓と伝わる墓所）","天下茶屋・松平郷園地の散策路"],"q":["松平氏の初代・松平親氏は、もとは何をしていた人と伝わる？","旅の僧（時宗の僧・徳阿弥）です。松平郷の有力者の婿になったと伝わります。"],"koji":[],"myth":"親氏の出自（新田氏の流れ）、婿入りの経緯、産湯の井戸の話は伝承・江戸時代の系譜による。松平東照宮は江戸時代以降に家康をまつった社。","img":["松平親氏","高月院","松平氏","徳川家康"],"wp":"松平郷","rel":{"ev":[],"grave":[]},"ph":[["c:a/a2/%E6%9D%BE%E5%B9%B3%E5%A4%AA%E9%83%8E%E5%B7%A6%E8%A1%9B%E9%96%80%E8%A6%AA%E6%B0%8F.jpg",3024,4032,"松平親氏"],["c:e/ee/Kogetsu-in_Temple_Hondou%2C_Matsudaira-cho_Toyota_2019.jpg",1500,1000,"高月院"]]},{"id":"23_mikawa_kokubunji","n":"三河国分寺跡","yomi":"みかわこくぶんじあと","cat":"遺跡","rank":"A","y":741,"era":["nara","heian"],"sh":"国指定史跡","ad":"豊川市八幡町","st":"JR飯田線 八幡駅から歩いて約15分。名鉄名古屋本線 国府駅からは約25分","la":34.8461,"lo":137.3676,"hook":"1300年近く前、国を守る祈りのために建てられた巨大な寺。今は大きな礎石が、塔の高さを想像させてくれる。","lead":"奈良時代、聖武天皇は国ごとに «国分寺» と «国分尼寺» を建てるよう命じました。三河国分寺跡はそのうち三河国（いまの愛知県東部）の国分寺の跡です。近くには尼寺の跡もあり、中門や回廊の一部が復元されています。","story":["奈良時代の中ごろ、日本では伝染病や反乱、飢饉があいつぎ、人々は不安の中にいました。741年、聖武天皇は «仏の力で国を守ろう» と、全国に国分寺と国分尼寺を建てるよう命じる詔を出しました。三河国でもその命令を受けて、大きな寺づくりが始まりました。","選ばれたのは、国の役所 «国府» の近く、いまの豊川市八幡町のあたりです。広い敷地に金堂や講堂、そして七重塔が建てられたと考えられています。高い塔は、まわりの田んぼのどこからでも見えたでしょう。«あれが都の力だ» と、人々は見上げたかもしれません。","国分寺には僧が住み、国の平和を祈るお経を読みました。すぐ近くには尼僧のための国分尼寺もつくられました。二つの寺と国府がならぶこの一帯は、三河国の «首都» のような場所だったのです。","平安時代になると律令の仕組みがゆるみ、国分寺も次第に衰えていきました。建物は失われ、いまは同じ場所に新しいお寺が建っています。それでも境内には塔の礎石が残り、発掘調査で古い寺の配置が少しずつわかってきました。","尼寺の跡は史跡公園として整備され、朱色の中門と回廊の一部が復元されています。資料館で出土品を見てから歩くと、奈良時代の三河の «都会» の姿が浮かんできます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","三河国分寺・国分尼寺が建てられる"],["平安時代","律令制のゆるみとともに衰える"],["1922年","三河国分寺跡・国分尼寺跡が国の史跡に指定"],["平成時代","国分尼寺跡の中門・回廊の一部を復元、史跡公園に"]],"who":[["聖武天皇","国分寺建立を命じた天皇"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の制度にかかわったとされる"],["三河国の国司","都から派遣された役人。寺づくりを進めた"]],"deep":["国分寺の正式名は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺»。お経の名前がそのまま寺の役目を表しています。","塔跡には大きな礎石が並び、七重塔クラスの大きな塔が建っていたと考えられています。高さは数十メートルと推定されますが、正確な数値は不明です。","近くには三河国府跡（白鳥遺跡）とされる場所があり、国府・国分寺・国分尼寺が近い距離にまとまる典型的な配置として知られています。","いま跡地に建つ国分寺には、平安時代前期とされる古い銅鐘が伝わり、古代の国分寺と後の寺をつなぐ手がかりになっています。","国分尼寺跡では、発掘調査で金堂・講堂・中門・回廊などの配置が確認され、その成果をもとに中門と回廊の一部が立体的に復元されました。","国分寺は国ごとに «僧20人»、国分尼寺は «尼10人» を置くと定められていました。お寺は国の «公的な祈りの機関» で、今のお寺とは役割がずいぶん違っていたのです。"],"look":["塔跡の礎石（国分寺跡）","国分尼寺跡の復元中門と回廊","三河天平の里資料館の出土品","周辺の国府跡・古墳めぐり"],"q":["国分寺・国分尼寺を全国に建てるよう命じた天皇は？","聖武天皇です。741年に詔を出し、仏の力で国を守ろうとしました。"],"koji":[],"myth":"塔の高さや建物の細かな配置は推定をふくむ。銅鐘の年代は研究による。","img":["国分寺","聖武天皇","三河国府"],"wp":"三河国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/1c/Mikawa_Kokubunji%2C_hondou.jpg",6008,3988,"三河国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"]]},{"id":"23_shidami_kofun","n":"志段味古墳群（歴史の里しだみ古墳群）","yomi":"しだみこふんぐん","cat":"遺跡","rank":"A","y":350,"era":["kofun"],"sh":"国指定史跡","ad":"名古屋市守山区上志段味","st":"JR中央本線 高蔵寺駅などからガイドウェイバス «ゆとりーとライン» で志段味方面へ、最寄りバス停から歩いて約10〜20分","la":35.241,"lo":137.051,"hook":"大都市・名古屋の中に、白く輝く石で覆われた古墳がよみがえっている。","lead":"志段味古墳群は、名古屋市守山区の東谷山のふもとにある古墳のグループです。4世紀から7世紀にかけて、約200年以上にわたって古墳がつくり続けられました。一部の古墳は築かれた当時の姿に復元され、古墳ミュージアムもあります。","story":["名古屋市の東のはし、庄内川が山あいから平野へ流れ出るところに、東谷山という山があります。その山すそ一帯に、大小たくさんの古墳が集まっています。これが志段味古墳群です。","いちばん古い大きな古墳は白鳥塚古墳です。4世紀前半ごろにつくられたと考えられる前方後円墳で、長さは約115メートル。発掘で、墳丘の表面が白い石英の石で飾られていたことがわかりました。«真っ白な山» が平野を見下ろしていたのです。なぜ白い石を？ 遠くからでも目立ち、力を示すためだったと考えられています。","5世紀後半になると、志段味大塚古墳がつくられました。ホタテ貝のような形の古墳で、鈴のついた鏡や馬具などが出土しています。馬に乗る新しい文化を持った人がここに眠っていたのでしょう。この古墳は、発掘の成果をもとに築造当時の姿に復元されています。","6〜7世紀には、小さな円墳がたくさんつくられ、横穴式の石室に家族が次々と葬られるようになりました。王の墓から、地域の有力な家の墓へ。一つの場所で古墳時代の移り変わりがまるごと見られるのが、志段味古墳群のすごいところです。","2019年には «体感！しだみ古墳群ミュージアム» が開館しました。古墳の上に登って景色を見わたし、昔の人が同じ場所で何を思ったのか想像してみましょう。"],"tl":[["4世紀前半ごろ","白鳥塚古墳がつくられる"],["4〜5世紀","東谷山の山頂などに古墳がつくられる"],["5世紀後半","志段味大塚古墳がつくられる"],["6〜7世紀","小さな円墳が多数つくられる"],["2014年","志段味古墳群が国の史跡に指定"],["2019年","しだみ古墳群ミュージアム開館"]],"who":[["古墳に眠る首長たち","この地を治めた有力者。名前は伝わっていない"],["ヤマト王権","白鳥塚古墳の形などから、王権とのつながりが考えられている"]],"deep":["白鳥塚古墳の墳形は、奈良県の大型前方後円墳と似た特徴を持つと指摘され、尾張の首長が早い段階からヤマト王権と結びついていた証拠と考えられています。","志段味大塚古墳から出土した «鈴鏡»（すずきょう）は、鏡のふちに鈴がついた日本独自の鏡です。馬具とあわせて、5世紀の新しい文化を物語ります。","古墳群は «前期の大型古墳» «中期の帆立貝形古墳» «後期の群集墳» がそろっていて、古墳時代300年の流れを一か所で追えることが高く評価されています。","東谷山の山頂には尾張戸神社があり、その社殿のある場所も古墳と考えられています。山頂からは濃尾平野が見わたせます。","«志段味» という地名の由来ははっきりしていません。いくつかの説がありますが、確かなことはわかっていません。","古墳ミュージアムでは、古墳づくりや当時の暮らしを体験するプログラムも行われ、子どもから大人まで古墳時代を «体で感じる» 工夫がされています。"],"look":["白鳥塚古墳（石英で飾られた墳丘）","復元された志段味大塚古墳","東谷山白鳥古墳の横穴式石室","しだみ古墳群ミュージアムの展示","東谷山山頂からのながめ"],"q":["白鳥塚古墳の表面をおおっていた白い石は何？","石英です。遠くからでも白く輝いて見えたと考えられています。"],"koji":[],"myth":"古墳の被葬者は不明。築造年代は研究による推定。","img":["白鳥塚古墳","志段味大塚古墳","東谷山"],"wp":"志段味古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:3/3c/Otsuka_and_Okute_kofun_group.jpg",440,440,"志段味古墳群"],["c:e/e2/Shidami_otsuka_kofun.jpg",5860,3907,"志段味大塚古墳"],["c:1/17/Distant_View_of_Mount_Togoku%2C_Togoku_Kamishidami_Moriyama_Ward_Nagoya_2021.jpg",1500,1000,"東谷山"]]},{"id":"23_danpusan","n":"断夫山古墳（尾張最大の前方後円墳）","yomi":"だんぷさんこふん","cat":"遺跡","rank":"A","y":530,"era":["kofun"],"sh":"国指定史跡","ad":"名古屋市熱田区旗屋","st":"名古屋市営地下鉄名城線 熱田神宮西駅から歩いて約5分","la":35.1312,"lo":136.9025,"hook":"名古屋のビル街のそばに、長さ約150メートル、東海地方で最大の前方後円墳が静かに横たわる。","lead":"断夫山古墳は、6世紀前半ごろにつくられた前方後円墳で、長さは約150メートル。東海地方で最も大きい古墳です。熱田神宮に仕えた尾張氏の首長の墓と考えられています。いまは熱田神宮公園の一部として保存され、墳丘には入れません。","story":["古墳時代の終わりが近づいたころ、熱田の台地の上に巨大な前方後円墳がつくられました。当時、このあたりは海に面していて、伊勢湾から見上げると、古墳の姿が大きく見えたことでしょう。","だれの墓なのでしょう？ 有力な候補は、熱田の地を拠点とした豪族 «尾張氏» の首長です。尾張氏の娘の目子媛（めのこひめ）は継体天皇の妃となり、のちの安閑天皇・宣化天皇を生んだと «日本書紀» にあります。尾張氏が都の天皇家と深くつながった、ちょうどそのころの古墳なのです。","一方で、地元には別の言い伝えもあります。日本武尊（やまとたけるのみこと）の妃・宮簀媛（みやずひめ）の墓だというものです。尊が亡くなったあと、宮簀媛は再婚せず «夫を断った» ——それで «断夫山» と名づけられた、という話です。美しい伝承ですが、古墳の年代とは合いません。","古墳は長いあいだ熱田神宮が守ってきました。やがて保存のため愛知県が所有し、1987年に国の史跡に指定されました。まわりが町になっても形がほぼ残っているのは、こうして大切にされてきたからです。","すぐ近くには、日本武尊の墓と伝わる白鳥古墳もあります。二つの古墳を歩いてめぐると、熱田が古代から «尾張の中心» だったことが実感できます。"],"tl":[["6世紀前半ごろ","断夫山古墳がつくられる"],["6世紀","尾張氏の目子媛が継体天皇の妃となる（日本書紀）"],["江戸時代","宮簀媛の墓とする伝承が広まる"],["1987年","国の史跡に指定"],["現在","熱田神宮公園の一部として保存"]],"who":[["尾張氏の首長","この古墳に葬られたと考えられる人物"],["目子媛","尾張氏の娘。継体天皇の妃"],["宮簀媛","日本武尊の妃。墓とする伝承がある"],["日本武尊","神話の英雄。草薙剣を宮簀媛にあずけた"]],"deep":["長さ約150メートルは、東海地方の古墳で最大級。後円部の高さは十数メートルあり、周りの濠（ほり）の跡も確認されています。","出土した埴輪や須恵器の特徴から、6世紀前半の築造と考えられています。これが被葬者を尾張氏の首長とみる根拠の一つです。","熱田神宮にまつられる草薙剣は、日本武尊が宮簀媛のもとにあずけたものと «古事記»«日本書紀» に語られ、宮簀媛は熱田の地と深く結びつけられてきました。","古墳の名は «断夫山» のほか «伊勢山» と呼ばれた時期もあるといわれ、呼び名にも諸説があります。","墳丘は保存のため立ち入り禁止です。公園の外周から形を眺め、案内板で全体像を確かめましょう。","«前方後円墳» は、ヤマト王権と結びついた有力者だけがつくれた形とされます。6世紀に入ると各地で大きな前方後円墳は減っていくため、この時期にこれほどの規模の古墳がつくられたことは、尾張氏の力の強さを物語ります。"],"look":["熱田神宮公園から見る墳丘の形","古墳の案内板","近くの白鳥古墳（日本武尊の墓と伝わる）","熱田神宮"],"q":["«断夫山» という名前は、だれのどんな伝承から来ている？","日本武尊の妃・宮簀媛が、夫の死後再婚しなかった（夫を断った）という伝承から来たといわれます。"],"koji":[],"myth":"宮簀媛の墓とする説は伝承で、古墳の年代とは合わない。被葬者は尾張氏の首長とみる説が有力だが確定ではない。","img":["熱田神宮","宮簀媛","尾張氏","目子媛"],"wp":"断夫山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/Danpusan_Kofun_zenkei.JPG",6016,4000,"断夫山古墳"],["c:7/71/Atsuta-jingu_Shrine_Haiden%2C_Jingu_Atsuta_Ward_Nagoya_2023.jpg",1500,1000,"熱田神宮"]]},{"id":"23_yoshigo_kaizuka","n":"吉胡貝塚（縄文人骨300体以上）","yomi":"よしごかいづか","cat":"遺跡","rank":"A","y":-1000,"era":["jomon"],"sh":"国指定史跡","ad":"田原市吉胡町","st":"豊橋鉄道渥美線 三河田原駅から歩いて約25分。車が便利","la":34.674,"lo":137.257,"hook":"貝がらの山の下から、300体をこえる縄文人が見つかった。歯をわざと抜いた人も多かった。なぜ？","lead":"吉胡貝塚は、縄文時代の終わりごろ（約3000年前）を中心とする貝塚です。大正時代の発掘で300体以上の人骨が見つかり、日本でも有数の «縄文人の墓地» として知られます。資料館 «シェルマ» で当時の暮らしを学べます。","story":["渥美半島のつけ根、三河湾に近い台地の上に、縄文時代の人々のむらがありました。人々は海で貝をとり、魚をつり、森で木の実を集めて暮らしていました。食べ終えた貝がらを捨てた場所が、長い年月で大きな «貝塚» になりました。","貝塚はただのごみ捨て場ではありません。貝がらのカルシウムのおかげで骨が溶けにくく、亡くなった人もここに葬られました。1922年から翌年にかけて、京都帝国大学の清野謙次らが発掘すると、なんと300体以上の人骨が見つかりました。","骨を調べると、ふしぎなことがわかりました。多くの人が、健康な前歯をわざと抜いていたのです。«抜歯» と呼ばれる風習です。大人になったしるし、結婚したしるし、むらの中での立場のしるし……いろいろな説がありますが、決まった答えはありません。","また、ひざを折り曲げて葬る «屈葬» や、子どもを土器に入れて葬った «土器棺» も見つかりました。一人ひとりの葬り方から、縄文人が死をどう考えていたかが少しずつ見えてきます。","1951年には国による発掘調査も行われ、同じ年に国の史跡に指定されました。いまは史跡公園と資料館があり、貝層の断面や人骨の出土状況の再現を見ることができます。ここに眠る人々へ敬意をもって訪れたい場所です。"],"tl":[["約3000年前","縄文時代晩期を中心に貝塚がつくられる"],["1922〜23年","清野謙次らの発掘で300体以上の人骨が出土"],["1951年","文化財保護委員会による発掘調査"],["1951年","国の史跡に指定"],["2006年","吉胡貝塚資料館（シェルマ）開館"]],"who":[["吉胡のむらの縄文人","この地で暮らし、葬られた人々"],["清野謙次","京都帝国大学の医学者。大正時代に大規模な発掘を行った"]],"deep":["吉胡貝塚の人骨の数は300体をこえ、同じ渥美半島の伊川津貝塚、保美貝塚とともに «縄文晩期の三大人骨出土地» ともいえる地域を形づくっています。","抜歯には抜く歯の組み合わせにいくつかの型があり、その違いが出身地や結婚のしかたと関係するという研究があります。ただし解釈は研究者によって異なります。","清野謙次の調査は人骨を集めることに重点がおかれ、出土状況の記録が十分でないという課題も指摘されています。のちの調査はその反省もふまえて行われました。","1951年の発掘は、1950年にできた文化財保護法のもとで、国が主体となって行った初期の発掘調査の一つとして知られています。","土器に子どもを入れる «土器棺葬» は、東海地方の縄文晩期にみられる特徴的な葬り方です。","同じ渥美半島の伊川津貝塚や保美貝塚でも多くの人骨が見つかっており、三河湾沿岸は縄文晩期の人々の暮らしと葬り方を研究するうえで全国的に重要な地域になっています。"],"look":["史跡公園の貝層の展示","資料館 «シェルマ» の人骨出土状況の再現","抜歯や屈葬についての展示","周辺の台地から見る三河湾の方向"],"q":["吉胡貝塚の縄文人に多く見られた、健康な歯をわざと抜く風習を何という？","抜歯です。大人になったしるしなど諸説がありますが、はっきりした理由はわかっていません。"],"koji":[],"myth":"抜歯の意味、人骨の正確な総数は研究により異なる。","img":["貝塚","清野謙次","縄文時代","伊川津貝塚"],"wp":"吉胡貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Yoshigo_kaizuka.JPG",6000,4000,"吉胡貝塚"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"]]},{"id":"23_yoshida_jo","n":"吉田城（池田輝政の城）","yomi":"よしだじょう","cat":"城","rank":"A","y":1590,"era":["muromachi","azuchi","edo"],"sh":"","ad":"豊橋市今橋町（豊橋公園）","st":"豊橋鉄道東田本線（市電）市役所前停留場から歩いて約5分","la":34.7695,"lo":137.391,"hook":"豊川のほとりにそびえた城は、姫路城の城主と同じ人が大きく育てた城だった。","lead":"吉田城は、いまの豊橋市にあった城で、戦国時代に «今橋城» として築かれたのが始まりです。1590年に池田輝政が城主となり、城を大きく広げました。江戸時代は東海道の要の城として譜代大名が治めました。いまは豊橋公園となり、石垣と復興した鉄櫓（くろがねやぐら）が残ります。","story":["1505年ごろ、牧野古白という武将が、豊川の流れを背にした台地に城を築きました。これが今橋城、のちの吉田城です。東三河は今川・武田・松平などの大名がせめぎ合う土地で、城の持ち主は何度も変わりました。","1590年、豊臣秀吉は家康を関東へ移し、そのあとの東海道に自分の信頼する大名を置きました。吉田城に入ったのが池田輝政です。輝政は城を大きく広げ、石垣を積み、城下町を整えました。のちに姫路城を今の姿に築く人物です。«吉田で腕をみがいた» と考えるとおもしろいですね。","江戸時代、吉田は東海道の宿場町であり、豊川の舟運の港町でもありました。城主は徳川家に近い譜代大名がつとめ、松平（大河内）家などが藩主となりました。旅人は城を見上げながら、吉田大橋で豊川を渡っていきました。","明治になると «吉田» という地名はほかの藩と紛らわしいとして «豊橋» に改められました。城は取りこわされ、やがて陸軍の歩兵連隊がおかれました。","1954年、本丸の隅に鉄櫓が復興されました。鉄筋コンクリート造の模擬的な建物ですが、上から見わたす豊川の流れは、城が «川を背にした守り» の城だったことを教えてくれます。"],"tl":[["1505年ごろ","牧野古白が今橋城を築く"],["16世紀","今川・松平などが城をめぐって争う"],["1590年","池田輝政が城主となり城を拡張"],["1600年","関ヶ原の戦いのあと輝政は播磨へ"],["江戸時代","譜代大名が吉田藩主をつとめる"],["1869年","吉田が豊橋と改称"],["1954年","鉄櫓が復興される"]],"who":[["牧野古白","今橋城を築いた武将"],["池田輝政","城を大きく拡張。のちに姫路城を築く"],["酒井忠次","家康の重臣。戦国時代に吉田城をあずかった"],["松平（大河内）家","江戸時代後期の吉田藩主"]],"deep":["本丸に残る石垣の一部は池田輝政の時代のものと考えられ、自然の石を積む «野面積み» の特徴が見られます。石には大名などの印とされる «刻印» がみられるものもあります。","吉田城は豊川を背にした «後堅固（うしろけんご）» の城です。川側に強い守りを持たせ、町側に堀や曲輪を重ねた構造でした。","江戸時代の吉田藩主は短い期間で交代することが多く、幕府の中で出世していく譜代大名の «通過点» となっていました。","«豊橋» の名は、豊川にかかる «吉田大橋» のことを «豊橋» とも呼んだことにちなむといわれます。","鉄櫓は昔の姿を正確に再現したものではなく、模擬的に建てられた建物です。中は資料展示になっています。","吉田は東海道の宿場であると同時に、豊川の舟運で三河の米や物資が集まる «港町» でもありました。城・宿場・港がそろう町は、東海道でも重要な «交通の十字路» だったのです。"],"look":["復興鉄櫓（くろがねやぐら）と展示","本丸の石垣と刻印石","豊川側から見た城の «後ろ»","豊橋公園の堀の跡"],"q":["吉田城を大きく広げ、のちに姫路城を築いた武将は？","池田輝政です。1590年に吉田城主となりました。"],"koji":[],"myth":"石垣の築造時期は部分によって異なる。«豊橋» の名の由来には諸説。","img":["池田輝政","豊橋公園","吉田藩","牧野古白"],"wp":"吉田城 (三河国)","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:b/b0/Yoshida_Castle_%28Aichi%29_3.jpg",2592,1944,"吉田城 (三河国)"],["c:d/de/Terumasa_Ikeda.jpg",601,550,"池田輝政"],["c:f/f7/View_of_Toyohashi_Park%2C_from_Toyohashi_City_Hall.jpg",3264,2448,"豊橋公園"]]},{"id":"23_tahara_jo","n":"田原城と渡辺崋山","yomi":"たはらじょう","cat":"城","rank":"A","y":1480,"era":["muromachi","edo"],"sh":"","ad":"田原市田原町巴江","st":"豊橋鉄道渥美線 三河田原駅から歩いて約15分","la":34.669,"lo":137.2665,"hook":"海に囲まれた小さな城で、国を思いすぎた一人の家老が、筆を置いて静かに世を去った。","lead":"田原城は、渥美半島のつけ根にあった城で、入り江にうかぶように見えたことから «巴江城（はこうじょう）» とも呼ばれました。江戸時代は小さな田原藩の城でした。ここは、画家であり学者でもあった家老・渡辺崋山のふるさとの藩として知られています。","story":["室町時代の終わりごろ、戸田宗光がこの地に城を築きました。三方を海に囲まれた城は、攻めにくい «海の城» でした。戦国時代には今川氏と織田氏のあいだで揺れ動き、幼い竹千代（のちの徳川家康）が今川氏へ送られる途中、戸田氏によって織田方へ渡されたと伝わる事件もありました。","江戸時代になると、田原は三宅氏が治める1万2千石ほどの小さな藩になりました。お金にも米にも余裕のない藩です。そこに生まれたのが渡辺崋山でした。江戸の藩邸で貧しい家に育ち、絵を描いて家計を助けながら学問にはげみ、やがて家老にまでなりました。","崋山は西洋の学問（蘭学）にも強い関心を持ち、«世界の中の日本» を考えました。そして外国船を打ち払う幕府の方針を心配し、ひそかに意見を書きました。«このままでは日本が危ない»。ところが1839年、その考えがとがめられ、崋山は捕らえられてしまいます。«蛮社の獄» です。","崋山は田原へ送られ、池ノ原の屋敷で謹慎しました。生活のために絵を売っていることが問題にされ、«藩主に迷惑がかかる» と考えた崋山は、1841年、自ら命を絶ちました。«不忠不孝 渡辺登» と書き残したと伝わります。","城跡にはいま、二の丸の櫓が復元され、田原市博物館で崋山の作品や手紙を見ることができます。小さな藩の、大きな志。城跡を歩くと、その重みがしみてきます。"],"tl":[["1480年ごろ","戸田宗光が田原城を築く"],["1547年","竹千代（家康）が今川へ送られる途中、織田方へ渡されたと伝わる"],["1664年","三宅氏が田原藩主となる"],["1793年","渡辺崋山が江戸の田原藩邸で生まれる"],["1832年","崋山が家老になる"],["1839年","蛮社の獄で崋山が捕らえられる"],["1841年","崋山が田原で亡くなる"],["1993年","二の丸櫓が復元される"]],"who":[["戸田宗光","田原城を築いた武将"],["渡辺崋山","田原藩の家老・画家・蘭学者"],["三宅氏","江戸時代の田原藩主"],["高野長英","崋山と交流した蘭学者。蛮社の獄で処罰された"]],"deep":["崋山の描いた «鷹見泉石像» は国宝で、東京国立博物館が所蔵しています。西洋画の陰影の技法を取り入れた肖像画として高く評価されています。","蛮社の獄のきっかけとなったのは、1837年のモリソン号事件をめぐる幕府の対応です。崋山は «慎機論» で幕府の打ち払い方針への懸念を書きましたが、公表はしていませんでした。","田原藩は小藩で財政が苦しく、崋山は家老として «報民倉» という飢饉にそなえた蔵をつくるなどの工夫をしたと伝わります。天保の飢饉のさい、田原藩から餓死者が出なかったという話も伝わります。","城の «巴江» の名は、城を囲む入り江の水が «巴» の形にうずを巻いていたことに由来するといわれます。","竹千代が織田方に渡された話は、戸田康光が関わったと伝わりますが、細かな経緯は史料によって違いがあり、近年はその真偽も議論されています。"],"look":["復元された二の丸櫓","城跡の石垣と堀","田原市博物館（崋山の作品）","池ノ原公園（崋山の幽居跡）","巴江神社"],"q":["渡辺崋山が捕らえられた1839年の事件は何と呼ばれる？","蛮社の獄です。外国船への幕府の方針を心配して書いた考えがとがめられました。"],"koji":[],"myth":"竹千代が織田方へ渡された経緯は諸説。報民倉と飢饉の逸話、崋山の遺書の文言は伝承をふくむ。","img":["渡辺崋山","蛮社の獄","鷹見泉石","田原藩"],"wp":"田原城","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/Watanabe_Kazan.jpg",1524,2248,"渡辺崋山"],["c:7/74/A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg",6829,13542,"鷹見泉石"],["c:e/ec/Tahara_Castle_SakuraMon.JPG",2048,1536,"田原藩"]]},{"id":"23_futagawa_juku","n":"二川宿本陣（東海道の本陣が残る）","yomi":"ふたがわじゅくほんじん","cat":"街道","rank":"A","y":1807,"era":["edo"],"sh":"豊橋市指定史跡","ad":"豊橋市二川町","st":"JR東海道本線 二川駅から歩いて約15分","la":34.7233,"lo":137.45,"hook":"大名が泊まった «本陣» が、東海道で今も残るのは、ここと草津宿のわずか二つだけ。","lead":"二川宿は、東海道五十三次の33番目の宿場町です。大名や公家が泊まった «本陣» の建物が今も残り、資料館として公開されています。庶民が泊まった旅籠屋 «清明屋» もあり、身分によって違う «旅の宿» をくらべて見られる、全国でもめずらしい場所です。","story":["江戸時代のはじめ、徳川家康は江戸と京都を結ぶ東海道に宿場を置きました。二川もその一つです。ところが小さな村だけでは宿場の仕事がまかないきれず、1644年、となりの大岩村と組み合わせて宿場が整えられました。","宿場には、大名が泊まる «本陣»、その予備の «脇本陣»、ふつうの旅人が泊まる «旅籠» がありました。二川宿の本陣は、1807年から明治のはじめまで馬場家がつとめました。大名行列が着くと、門には «○○様御宿» という札が立てられたといいます。","本陣の奥には、大名だけが使う «上段の間» があります。一段高い床、立派な床の間。«ここにお殿さまが座ったんだ» と思うと、背すじがのびます。でも本陣は大名のための特別な宿なのに、実は経営が苦しいことも多かったそうです。なぜでしょう？ 宿泊代は大名から «お礼» として受け取るもので、決まった料金ではなかったからです。","本陣のとなりには旅籠屋 «清明屋» が残ります。こちらは一般の旅人の宿。部屋は小さく、見知らぬ人と同じ部屋になることもありました。本陣と旅籠を続けて見ると、江戸時代の旅の «ちがい» がはっきりわかります。","本陣の建物は馬場家から豊橋市に寄贈され、1991年に復元整備されて資料館になりました。宿場の町並みには古い商家も残り、ゆっくり歩くと江戸の街道の雰囲気を味わえます。"],"tl":[["1601年","東海道に宿駅制度が整えられる"],["1644年","二川村と大岩村を合わせて宿場が整う"],["1807年","馬場家が二川宿の本陣となる"],["1870年","明治政府の改革で本陣制度が廃止される"],["1988年","本陣の建物などが豊橋市に寄贈される"],["1991年","二川宿本陣資料館として公開"]],"who":[["馬場家","1807年から本陣をつとめた家"],["大名・公家","参勤交代などで本陣に泊まった"],["徳川家康","東海道の宿駅制度を整えた"]],"deep":["東海道で本陣の建物が残るのは、二川宿と滋賀県の草津宿の2か所だけです。二川宿本陣は主屋・玄関棟・書院棟などが残り、復元整備されています。","«上段の間» は大名が座る部屋で、ほかの部屋より床が一段高くなっています。身分の上下が建物のつくりで表されていました。","旅籠屋 «清明屋» は、江戸時代後期の旅籠の建物が残り、本陣とあわせて公開されています。本陣と旅籠を一か所で見比べられるのは全国的にも貴重です。","二川宿は、東の白須賀宿（静岡県）と西の吉田宿（豊橋市中心部）のあいだにあります。愛知県に入って最初の宿場でした。","本陣の経営は、大名が支払う «御礼» にたよるため不安定で、本陣をつとめる家が交代することもありました。二川宿でも馬場家の前に別の家が本陣をつとめています。"],"look":["本陣の «上段の間»","本陣の玄関と門","旅籠屋 «清明屋»","資料館の東海道の展示","宿場の古い町並み（商家駒屋など）"],"q":["二川宿の本陣は、東海道ではほかにどこの宿場の本陣と並んで «2つだけ残る本陣» と言われている？","滋賀県の草津宿です。"],"koji":[],"myth":"市指定の範囲や名称は変わることがある。宿場成立の経緯には細かな諸説がある。","img":["草津宿","本陣","東海道五十三次"],"wp":"二川宿","rel":{"ev":[],"grave":[]},"ph":[["c:0/05/Tokaido33_Futagawa.jpg",923,600,"二川宿"],["c:6/60/Tokaido52_Kusatsu.jpg",876,600,"草津宿"],["c:f/f7/Hiroshige_le_pont_Nihonbashi_%C3%A0_l%27aube.jpg",1618,1080,"東海道五十三次"]]},{"id":"23_goyu_matsunamiki","n":"御油の松並木","yomi":"ごゆのまつなみき","cat":"街道","rank":"A","y":1604,"era":["edo"],"sh":"国指定天然記念物","ad":"豊川市御油町","st":"名鉄名古屋本線 御油駅から歩いて約10分","la":34.842,"lo":137.3165,"hook":"旅人を夏の日ざしから守った松並木。家康の命令から400年以上、今も東海道をいろどっている。","lead":"御油の松並木は、東海道の御油宿と赤坂宿のあいだに残る松並木です。江戸時代のはじめに植えられたと伝わり、約600メートルにわたって数百本の松が道の両側にならびます。国の天然記念物に指定されています。","story":["1604年、徳川家康は全国の街道に «一里塚» をつくり、道の両側に木を植えるよう命じたと伝わります。夏は日かげをつくり、冬は冷たい風をやわらげる。旅人を守るための並木でした。","御油宿と赤坂宿のあいだは、東海道の宿場と宿場のあいだで最も短い区間です。わずか2キロメートルたらず。«さっきの宿場からもう次の宿場？» と思うほどの近さでした。その短い道のりに、松並木が続いていました。","このあたりは、旅人を呼びこむ «留女（とめおんな）» の話でも有名です。歌川広重の浮世絵 «東海道五十三次 御油» には、旅人の腕や荷物をつかんで宿へ引きこもうとする女性たちが、ユーモラスに描かれています。","松尾芭蕉も、この短い区間をよんだと伝わる句を残しています。«夏の月 御油より出でて 赤坂や»。夏の夜はあっという間に明けてしまう、そのはかなさを、御油から赤坂までの近さになぞらえたとされます。","戦争中の1944年、この松並木は国の天然記念物に指定されました。いまも地元の人々が枯れた松を植え替え、大切に守っています。木かげを歩くと、江戸の旅人と同じ風を感じられるかもしれません。"],"tl":[["1601年","東海道に宿駅がおかれる（御油宿・赤坂宿）"],["1604年","家康が街道の並木・一里塚の整備を命じたと伝わる"],["1830年代","歌川広重が «東海道五十三次» を描く"],["1944年","国の天然記念物に指定"],["現在","地元の保存会などが植え替えをして守る"]],"who":[["徳川家康","街道の並木づくりを命じたと伝わる"],["歌川広重","浮世絵 «東海道五十三次 御油» を描いた"],["松尾芭蕉","御油と赤坂の近さを句によんだとされる"]],"deep":["御油宿と赤坂宿のあいだは約16町（約1.7キロメートル）とされ、東海道五十三次の宿場間で最も短い区間です。","広重の «御油 旅人留女» は、宿場の客引きの激しさを描いた作品として人気があります。となりの «赤坂 旅舎招婦図» とあわせると、宿場のにぎわいがよくわかります。","松の本数は時代によって変わり、枯れた木を補植しながら今の姿が保たれています。昔からの松と植え替えた若い松がまじっています。","天然記念物に指定されたのは1944年。戦争中は木材が不足し、各地の並木が切られることもあったなかで、指定が保存につながったと考えられています。","芭蕉の «夏の月…» の句は、実際にこの地で作られたかどうかははっきりしていませんが、御油と赤坂の近さを表す句として知られています。","家康が整えた街道の並木は、日よけだけでなく、雪や風の日に道すじがわかる «目じるし» にもなったといわれます。一里塚とセットで、旅人の安全を守る交通インフラでした。"],"look":["約600メートル続く松並木の道","松並木の案内碑","御油宿の町並み","赤坂宿の旅籠 «大橋屋»（見学時は開館情報を確認）"],"q":["御油宿と赤坂宿のあいだは、東海道の宿場間で何が一番？","距離が一番短い区間です（約1.7キロメートル）。"],"koji":[],"myth":"家康の並木整備命令の年、芭蕉の句の成立事情には諸説。","img":["御油宿","東海道五十三次","歌川広重","松並木"],"wp":"御油の松並木","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:a/a9/Goyuno-Matsunamiki-1.jpg",4032,3024,"御油の松並木"],["c:b/b7/Tokaido35_Goyu.jpg",878,600,"御油宿"],["c:f/f7/Hiroshige_le_pont_Nihonbashi_%C3%A0_l%27aube.jpg",1618,1080,"東海道五十三次"],["c:f/f1/Memorial_Portrait_of_Hiroshige%2C_by_Kunisada.jpg",2631,3841,"歌川広重"]]},{"id":"23_arimatsu","n":"有松（絞りの町並み）","yomi":"ありまつ","cat":"町","rank":"A","y":1608,"era":["edo"],"sh":"重要伝統的建造物群保存地区","ad":"名古屋市緑区有松","st":"名鉄名古屋本線 有松駅から歩いてすぐ","la":35.068,"lo":136.971,"hook":"何もなかった丘の道に、手ぬぐいの模様一つから «絞りの町» が生まれた。","lead":"有松は、江戸時代のはじめ、東海道沿いにつくられた町です。«有松・鳴海絞り» という布の染め物で栄え、旅人のおみやげとして全国に知られました。大火のあとに建てられた重厚な町家が並び、国の重要伝統的建造物群保存地区に選ばれています。","story":["1608年、尾張藩は東海道の鳴海宿と池鯉鮒宿のあいだ、人家のない丘の道に新しい町をつくることにしました。旅人の安全のためです。知多半島の阿久比から人々が移り住み、有松の町が始まりました。","でも、宿場でもない小さな町では暮らしが立ちません。そこで考えられたのが «絞り染め» でした。竹田庄九郎という人が、名古屋城を築く工事に来ていた九州の人々の手ぬぐいの染め方を見て、絞りを始めたと伝わります。«これを旅人に売ろう!» ——アイデアは大当たりしました。","布をつまみ、糸でしばって染めると、しばったところだけ白く残り、ふしぎな模様ができます。有松の絞りは、その技法の種類の多さで知られるようになりました。尾張藩も特産品として保護し、有松の絞りは東海道の名物になりました。","ところが1784年、大火が町を襲い、ほとんどが焼けてしまいます。人々は火事に強い町をつくろうと、壁を土で塗りこめた «塗籠造» の家を建てました。いま見られる重厚な町並みは、この再建の姿を受けついでいます。","有松は1560年の «桶狭間の戦い» の古戦場にも近い場所です。戦国のあらそいの地が、江戸時代には平和な «ものづくりの町» になった。その変化を感じながら歩いてみましょう。"],"tl":[["1560年","近くで桶狭間の戦いが起こる"],["1608年","尾張藩が東海道沿いに有松の町をつくる"],["江戸時代前期","竹田庄九郎が絞り染めを始めたと伝わる"],["1784年","大火で町の大部分が焼ける"],["大火のあと","塗籠造の町家で町が再建される"],["1976年","有松・鳴海絞りが国の伝統的工芸品に指定"],["2016年","重要伝統的建造物群保存地区に選定"]],"who":[["竹田庄九郎","絞り染めを始めたと伝わる人物"],["尾張藩","町をつくり、絞りを特産品として保護した"],["有松の絞り職人たち","多くの技法を生み、受けついできた"]],"deep":["有松・鳴海絞りは、«くくり» の技法が100種類をこえるともいわれ、技法の多さでは日本一とも称されます。","町並みには «卯建（うだつ）»（隣家との境の防火壁）や、黒漆喰の塗籠造、虫籠窓など、防火を意識したつくりが多く見られます。","服部家住宅や竹田家住宅、岡家住宅などの大きな商家が残り、一部は県や市の文化財に指定されています（内部は非公開の家も多い）。","«鳴海絞り» の名は、となりの鳴海宿で多く売られたことに由来するといわれます。有松で作り、鳴海でも売った、という関係です。","桶狭間の戦いの古戦場とされる場所は、有松の南の «桶狭間古戦場公園»（名古屋市緑区）と、豊明市の «桶狭間古戦場伝説地» の二つがあり、どちらが本当の戦場か議論が続いています。"],"look":["東海道沿いの町並み（塗籠造・卯建）","有松・鳴海絞会館（実演や展示）","服部家住宅など大きな商家の外観","有松山車会館と祭りの山車","桶狭間古戦場公園（少し足をのばして）"],"q":["有松の町並みが、土で塗りこめた重厚なつくりなのはなぜ？","1784年の大火で町が焼けたあと、火事に強い家を建てたからです。"],"koji":[],"myth":"竹田庄九郎が絞りを始めた経緯は伝承。桶狭間の戦いの場所は諸説あり。","img":["桶狭間の戦い","絞り染め","鳴海宿"],"wp":"有松・鳴海絞り","rel":{"ev":[],"grave":[]},"ph":[["c:1/18/Arimatsu_Shibori%28%E6%9C%89%E6%9D%BE%29%E6%89%8B%E8%9C%98%E8%9B%9B%E7%B5%9E.jpg",3648,2736,"有松・鳴海絞り"],["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"],["c:3/36/Sunlight_filters_through_tied-and-indigo-dyed_%28shibori%29_fabric.jpg",2560,1920,"絞り染め"],["c:0/01/Tokaido40_Narumi.jpg",864,600,"鳴海宿"]]},{"id":"23_asuke","n":"足助の町並み（塩の道・中馬街道）","yomi":"あすけのまちなみ","cat":"町","rank":"A","y":1775,"era":["muromachi","edo"],"sh":"重要伝統的建造物群保存地区","ad":"豊田市足助町","st":"名鉄豊田市駅・東岡崎駅方面からバスで «香嵐渓» 下車（約40分〜1時間）","la":35.1335,"lo":137.317,"hook":"海のない信州へ、塩は山道を運ばれた。その中継地が、紅葉で有名なこの山あいの町だった。","lead":"足助は、三河の海でとれた塩を信州（長野県）へ運ぶ «中馬街道（伊那街道）» の宿場町・商人の町として栄えました。塩はここで詰めかえられ «足助塩» と呼ばれたといいます。江戸時代の町家が残る町並みは、愛知県で最初の重要伝統的建造物群保存地区です。","story":["信州は海のない国です。生きていくのに欠かせない塩を、人々は遠い海から手に入れなければなりませんでした。三河湾の塩は矢作川の舟で上流へ運ばれ、足助で馬の背に積みかえられて、山道を北へ向かいました。","足助の商人は、運ばれてきた塩をいったんほどき、信州向けの俵に詰めなおしたといわれます。こうして送り出された塩は «足助塩» と呼ばれました。«塩の道» の中継地として、町は大いににぎわいました。","山道の運送を担ったのが «中馬（ちゅうま）» です。農民が副業として馬を使い、荷物を運ぶ仕組みでした。馬の背にゆられた塩は、何日もかけて伊那谷へと運ばれていきました。帰りの馬には、信州の産物が積まれました。","江戸時代の中ごろ、町は大火で焼けたと伝わります。そのあと建てなおされた白壁や板張りの町家が、いまの町並みのもとになっています。細い路地 «マンリン小路» の土蔵の壁は、写真好きの人にも人気です。","町のすぐそばには、紅葉で有名な香嵐渓があります。江戸時代、香積寺の和尚が参道にカエデを植えたのが始まりと伝わります。戦国時代には足助氏や鈴木氏の山城がありました。«塩の道の町» と «紅葉の名所» ——二つの顔を持つ町を、ゆっくり歩いてみましょう。"],"tl":[["鎌倉〜室町時代","足助氏がこの地を治めたと伝わる"],["戦国時代","鈴木氏の足助城（真弓山城）が築かれる"],["江戸時代","塩の道・中馬街道の中継地として繁栄"],["1634年","香積寺の和尚が参道にカエデを植えたと伝わる（香嵐渓の始まり）"],["江戸時代中ごろ","大火のあと町並みが再建される"],["2011年","愛知県で初めて重要伝統的建造物群保存地区に選定"]],"who":[["足助の商人たち","塩を詰めかえ、信州へ送り出した"],["中馬の馬方","農民の副業として荷物を運んだ"],["三栄和尚","香積寺の和尚。カエデを植えたと伝わる"],["鈴木氏","戦国時代に足助城を拠点にした一族"]],"deep":["«中馬» は、江戸時代の中ごろに信州の伊那谷を中心に発達した農民の運送業で、幕府から公認されたものでした。宿場ごとに荷物を積みかえる公式の «伝馬» とちがい、一頭の馬で目的地まで通して運べるのが強みでした。","足助から信州へ向かう道は «伊那街道» とも «中馬街道» とも呼ばれ、呼び名は時代や地域によってちがいます。","町並みには、妻入りと平入りの町家がまじり、白い漆喰の土蔵や格子戸が残ります。三州足助屋敷では、昔のくらしや手仕事の実演を見ることができます。","足助城は発掘調査をもとに、戦国時代の山城の建物を復元した城として知られます。天守ではなく、物見やぐらや長屋など «中世の山城» らしい姿です。","足助の大火は1775年とされることが多いですが、火災の規模や年についての記録は資料によって違いがあります。"],"look":["足助の町並み（白壁と格子の町家）","マンリン小路の土蔵","香嵐渓と香積寺","足助城（復元された戦国の山城）","三州足助屋敷"],"q":["足助で信州向けに詰めなおされた塩は何と呼ばれた？","«足助塩» です。三河の塩を山道で信州へ運ぶ中継地でした。"],"koji":[],"myth":"«足助塩» の詰めかえの仕組み、大火の年、カエデ植樹の年は伝承・諸説をふくむ。","img":["香嵐渓","足助城","中馬"],"wp":"足助町","rel":{"ev":[],"grave":[]},"ph":[["c:3/39/K%C5%8Drankei.jpg",6016,4016,"足助町"],["c:f/f9/Asuke_Castle_-_Hommaru_Area%2C_Asuke-cho_Toyota_2009.jpg",1500,1000,"足助城"]]},{"id":"23_hatcho_miso","n":"八丁味噌の郷（八帖町）","yomi":"はっちょうみそのさと","cat":"産業","rank":"A","y":1645,"era":["edo","showa"],"sh":"国の登録有形文化財（蔵・事務所など）","ad":"岡崎市八帖町","st":"名鉄名古屋本線 岡崎公園前駅・愛知環状鉄道 中岡崎駅から歩いて約5分","la":34.954,"lo":137.1545,"hook":"岡崎城から西へ «八丁»。その村の名が、日本を代表する黒い味噌の名前になった。","lead":"八丁味噌は、大豆と塩だけでつくる «豆味噌» の一種で、大きな木桶に石を山のように積んで2年以上じっくり熟成させます。名前は、岡崎城から西へ八丁（約870メートル）の «八丁村»（いまの八帖町）で造られたことに由来します。今も2軒の老舗が伝統の製法を守っています。","story":["徳川家康が生まれた岡崎城。そこから西へ八丁ほど行ったところに、旧東海道と矢作川が交わる村がありました。«八丁村» です。この村で江戸時代から造られてきた味噌が «八丁味噌» です。","八丁味噌の造り方は独特です。蒸した大豆で «豆麹» をつくり、塩と水を合わせて、高さ2メートルほどもある大きな杉の木桶に仕込みます。その上に、川原の石を円すい形に高く積み上げます。重さはおよそ3トン。«地震が来ても崩れない» 積み方は、職人の技そのものです。","そして、二夏二冬——2年以上の長い時間をかけて熟成させます。できあがる味噌は、色が濃く、固く、うまみと渋みのある深い味。«なぜこんなに長く?» それは、水分の少ない豆味噌は、ゆっくり時間をかけることで味がまとまるからだといわれます。","旧東海道と矢作川の舟運に恵まれた八丁村の味噌は、江戸へも運ばれて広く知られるようになりました。今も «まるや八丁味噌» と «カクキュー（合資会社八丁味噌）» の2軒が、道をはさんで向かい合い、伝統の製法を守っています。","カクキューの本社事務所や味噌蔵は、昭和初期などの建物が国の登録有形文化財になっています。蔵の中に入ると、ずらりと並ぶ木桶と石の山、そして味噌の香り。まさに «生きている歴史» です。"],"tl":[["江戸時代初期","八丁村で味噌造りが行われていたと伝わる"],["1645年","カクキュー（早川家）の創業と伝わる"],["江戸時代","旧東海道と矢作川の舟運で各地へ運ばれる"],["昭和初期","カクキューの本社事務所などが建てられる"],["2006年","NHK連続テレビ小説 «純情きらり» の舞台のモデルとなる"],["現在","2軒の老舗が伝統製法を続ける"]],"who":[["早川家","カクキュー（合資会社八丁味噌）の家"],["大田家","まるや八丁味噌の家"],["徳川家康","岡崎城で生まれた。八丁味噌との関わりが語られることがある"]],"deep":["«八丁» は距離の単位で、1丁は約109メートル。八丁は約870メートルです。地名は «八丁村» から、のちに «八帖町» と表記されるようになりました。","木桶は高さ・直径ともに約2メートル、仕込む味噌は1桶で約6トンといわれます。石の重しは約3トンで、職人が一つひとつ手で積み上げます。","八丁味噌は大豆と塩だけで造り、米や麦の麹を使いません。水分が少なく固いのが特徴で、名古屋の «味噌煮込み» や «味噌カツ» の味の土台にもなっています。","2017年、«八丁味噌» が国の地理的表示（GI）に登録された際、登録の条件をめぐって老舗2社が加わらず、議論となりました。名前と伝統をどう守るかという、現代の問題です。","«家康の軍勢が八丁味噌を兵糧にした» という話がよく語られますが、確かな史料で裏づけられた話ではありません。"],"look":["味噌蔵の木桶と石積み（工場見学）","カクキューの本社事務所（昭和初期の洋館）","まるや八丁味噌の蔵","旧東海道の道すじ","岡崎城（西へ約870メートル）"],"q":["«八丁味噌» の «八丁» はどこからどこまでの距離？","岡崎城から西へ八丁（約870メートル）です。そこにあった八丁村の名前に由来します。"],"koji":[],"myth":"創業年は各社の伝承による。家康の兵糧の話は伝承。GIの問題は現在も議論がある。","img":["岡崎城","味噌","純情きらり"],"wp":"八丁味噌","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Hatcho-Miso_Kakukyu_2019_ac_%281%29.jpg",5839,3883,"八丁味噌"],["c:7/74/Okazakijo-3-cropped.jpg",2621,1704,"岡崎城"],["c:e/ed/Miso_paste_by_wilbanks_in_Nishiki_Ichiba%2C_Kyoto.jpg",2304,1728,"味噌"]]},{"id":"23_seto","n":"瀬戸の窯垣の小径（せともの）","yomi":"せとのかまがきのこみち","cat":"産業","rank":"A","y":1807,"era":["kamakura","edo"],"sh":"","ad":"瀬戸市仲洞町・東郷町ほか","st":"名鉄瀬戸線 尾張瀬戸駅から歩いて約15分","la":35.2305,"lo":137.105,"hook":"焼き物を焼くための道具が、石垣になった。«せともの» の町の路地は、それ自体が作品だ。","lead":"瀬戸は1000年以上つづく焼き物の町で、焼き物全体を «せともの» と呼ぶほど有名になりました。«窯垣の小径» は、窯で使い終わった道具を積み重ねて作った垣根が続く散歩道です。鎌倉時代の «陶祖» と江戸時代の «磁祖» の物語が残ります。","story":["瀬戸の山からは、焼き物に向いた良い土がとれました。平安時代には焼き物づくりが始まり、鎌倉時代になると、中国の焼き物をまねて、うわぐすり（釉薬）をかけた «古瀬戸» が作られるようになります。当時、釉薬をかけた陶器を作っていたのは、日本で瀬戸だけだったといわれます。","この技術を中国から持ち帰ったのが «加藤四郎左衛門景正（藤四郎）» だと伝わります。人々は彼を «陶祖» とあがめました。ただし、藤四郎が実在したかどうかは、はっきりしていません。«伝説の人» なのです。","江戸時代、瀬戸は大ピンチをむかえます。九州の有田でつくられる白くて硬い «磁器» が人気になり、瀬戸の陶器が売れなくなったのです。そこで1804年ごろ、加藤民吉という若者が九州へ行き、苦労のすえ磁器の技術を学んで帰ってきました。民吉は «磁祖» としてまつられ、瀬戸は磁器の町としてよみがえりました。","窯では、器をのせる板や柱、器を守るケースなど、たくさんの «窯道具» を使います。何度も焼くと道具はこわれてしまいます。瀬戸の人々は、それを捨てずに積み上げ、家の塀や坂道の土どめにしました。«窯垣» です。","洞町の «窯垣の小径» を歩くと、丸や四角の道具が幾何学模様のように組み合わさった壁が続きます。«もったいない» の知恵が、美しい町の景色を生んだのです。"],"tl":[["平安時代","瀬戸で焼き物づくりが始まる"],["鎌倉時代","釉薬をかけた «古瀬戸» が作られ始める"],["鎌倉時代","加藤四郎左衛門景正（藤四郎）が陶祖になったと伝わる"],["1804年ごろ","加藤民吉が九州で磁器の技術を学ぶ"],["1807年ごろ","民吉が瀬戸へもどり、磁器づくりを広める"],["明治時代","洋食器や輸出品の生産で発展"],["2017年","«六古窯» が日本遺産に認定（瀬戸もその一つ）"]],"who":[["加藤四郎左衛門景正（藤四郎）","瀬戸焼の «陶祖» と伝わる人物"],["加藤民吉","九州で磁器の技を学び «磁祖» とされる"],["瀬戸の職人たち","窯道具を積んで窯垣をつくった"]],"deep":["«古瀬戸» は鎌倉時代から室町時代にかけて作られた施釉陶器で、中国の青磁や白磁をお手本にしていました。茶入れなど茶道具の «瀬戸物» も高く評価されました。","窯垣に使われているのは、器をのせる棚板 «エブ»、棚を支える柱 «ツク»、器を入れる «サヤ» などの窯道具です。形のちがう道具を組み合わせて模様にしています。","加藤民吉の九州修業は、他国に技術を教えないようにしていた九州の窯で、身分を隠して学んだという «産業スパイ» のような話として語られますが、細部は伝承です。","瀬戸市の深川神社の境内には «陶彦社» があり、陶祖・藤四郎がまつられています。窯神神社には磁祖・民吉がまつられています。","«せともの» が焼き物の代名詞になったのは、江戸時代に瀬戸の製品が東日本を中心に大量に出回ったためといわれます。西日本では «からつもの»（唐津焼）と呼ぶ地域もありました。"],"look":["窯垣の小径（窯道具の垣根）","窯垣の小径資料館","洞本業窯（登り窯）","深川神社と陶彦社","瀬戸蔵ミュージアム"],"q":["九州で磁器の技を学び、瀬戸の «磁祖» とされる人物は？","加藤民吉です。1804年ごろ九州へ行き、磁器の技術を持ち帰りました。"],"koji":[],"myth":"藤四郎の実在や中国渡航、民吉の修業の細部は伝承をふくむ。","img":["加藤民吉","加藤四郎左衛門","六古窯"],"wp":"瀬戸焼","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/Found_MUJI_Setoyaki_%286910176253%29.jpg",3344,2224,"瀬戸焼"],["c:3/3f/Kato_Tamikichi.jpg",540,570,"加藤民吉"],["c:d/dd/Large_jar%2C_Tokoname_ware%2C_Japan%2C_Heian_period%2C_1100s_AD%2C_natural_glaze_-_Tokyo_National_Museum_-_Tokyo%2C_Japan_-_DSC08941.jpg",3648,4005,"六古窯"]]},{"id":"23_tokoname","n":"常滑やきもの散歩道（土管坂）","yomi":"とこなめやきものさんぽみち","cat":"産業","rank":"A","y":1100,"era":["heian","meiji"],"sh":"国の重要有形民俗文化財（登窯）","ad":"常滑市栄町","st":"名鉄常滑線 常滑駅から歩いて約5〜10分","la":34.8855,"lo":136.8395,"hook":"壁には土管と焼酎びん、足もとには焼き物の輪。坂道そのものが焼き物の町の歴史書だ。","lead":"常滑は、平安時代の終わりから焼き物を作り続けてきた町で、«日本六古窯» の一つです。とくに大きなかめや壺を得意とし、明治以降は土管やタイルで日本の近代化を支えました。«やきもの散歩道» では、土管坂や巨大な煙突の登窯を見て歩けます。","story":["平安時代の終わりごろ、知多半島の丘の上に、たくさんの窯が築かれました。焼かれたのは大きなかめや壺。水や穀物をたくわえるのに欠かせない道具です。常滑の焼き物は船で運ばれ、東北から九州まで、全国の遺跡から見つかっています。","«なぜ常滑の焼き物はそんなに広まったの?» 理由の一つは «海» です。常滑は伊勢湾に面した港町。重い焼き物も、船なら一度にたくさん運べました。海の道が、常滑焼を日本中に届けたのです。","江戸時代の終わりから明治にかけて、常滑では朱色の «朱泥の急須» が生まれ、名物になりました。そして明治になると、鯉江方寿らが焼き物の «土管» を大量に作る方法を広めます。町に水道や下水が整えられていく時代、常滑の土管は日本の近代化を足もとから支えました。","«土管坂» を歩くと、坂の両側の壁に、土管と焼酎びんがびっしり埋めこまれています。足もとには «ケサワ» と呼ばれる、土管を焼くときに使った輪っかが敷かれ、すべり止めになっています。売れ残りや失敗作も、町の風景として生まれ変わったのです。","散歩道の途中には、明治時代に築かれた «登窯（陶栄窯）» が残ります。坂に沿って窯が階段のように連なり、10本の煙突が空へのびます。昭和の中ごろまで実際に使われていた窯で、国の重要有形民俗文化財です。"],"tl":[["平安時代末期","知多半島で大きなかめ・壺の生産が始まる"],["鎌倉・室町時代","常滑焼が全国に運ばれる"],["江戸時代後期","朱泥の急須づくりが始まる"],["明治時代","土管の大量生産が広がる"],["1887年ごろ","登窯（陶栄窯）が築かれたとされる"],["1982年","登窯が国の重要有形民俗文化財に指定"],["2017年","«六古窯» が日本遺産に認定"]],"who":[["鯉江方寿","明治時代に土管の量産などを進めた陶業家"],["常滑の陶工たち","大がめから土管・タイルまで作り続けた"],["伊奈初之烝・伊奈長三郎","伊奈製陶（のちのINAX）を興した父子"]],"deep":["日本六古窯は、瀬戸・常滑・越前・信楽・丹波・備前の6つ。中世から今まで生産が続く産地で、2017年に日本遺産 «きっと恋する六古窯» に認定されました。","中世の常滑焼は、奥州平泉の遺跡からもたくさん見つかっていて、東北地方と海の道でつながっていたことがわかります。","登窯（陶栄窯）は、傾斜地に焼成室を連ねた «連房式登窯» で、8つの焼成室と10本の煙突を持つとされます。1974年まで使われていたといわれます。","常滑の伊奈製陶は、タイルや衛生陶器で発展し、のちにINAX（現在のLIXILの一部）となりました。«INAXライブミュージアム» でタイルの歴史を学べます。","朱泥の急須は、鉄分の多い土を焼きしめて朱色に仕上げたもので、中国の宜興の急須を手本にしたといわれます。"],"look":["土管坂（土管・焼酎びん・ケサワの坂道）","登窯（陶栄窯）と10本の煙突","陶磁器会館","散歩道の窯元・ギャラリー","INAXライブミュージアム（少し離れた場所）"],"q":["土管坂の足もとに敷かれた、土管を焼くときに使った輪っかを何という？","«ケサワ» です。すべり止めとして坂道に敷かれています。"],"koji":[],"myth":"登窯の築造年・使用終了年は資料により表記に差がある。","img":["六古窯","INAX","朱泥"],"wp":"常滑焼","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Yakimonosanpomichi2.JPG",6000,4000,"常滑焼"],["c:d/dd/Large_jar%2C_Tokoname_ware%2C_Japan%2C_Heian_period%2C_1100s_AD%2C_natural_glaze_-_Tokyo_National_Museum_-_Tokyo%2C_Japan_-_DSC08941.jpg",3648,4005,"六古窯"],["c:8/84/Inax-office.jpg",1024,768,"INAX"]]},{"id":"23_handa_unga","n":"半田運河と蔵の町（醸造の町）","yomi":"はんだうんが","cat":"産業","rank":"A","y":1804,"era":["edo","meiji"],"sh":"","ad":"半田市中村町","st":"JR武豊線 半田駅から歩いて約5分。名鉄河和線 知多半田駅から約10分","la":34.8895,"lo":136.9395,"hook":"江戸の «すし» を変えたのは、この運河沿いの黒い蔵で造られた酢だった。","lead":"半田運河は、江戸時代から酢や酒の «醸造の町» として栄えた半田の港をつなぐ運河です。岸には黒い板で囲まれた蔵が並び、ミツカンの酢や酒が船で江戸へ運ばれました。近くには明治のビール工場だった赤レンガ建物も残ります。","story":["知多半島の半田は、江戸時代から酒づくりがさかんな町でした。港から船に積まれた酒は、遠く江戸まで運ばれていきました。当時、知多の酒は «中国酒» などと呼ばれ、灘や伊丹の酒とならぶ存在だったといわれます。","1804年、酒づくりをしていた中野又左衛門は、酒をしぼったあとに残る «酒粕» から酢を造ることを思いつきました。«捨てるはずの酒粕で、おいしい酢ができないか?» ——これが大当たり。赤みがかった «粕酢» は、ちょうど江戸で流行しはじめた «早ずし»（にぎりずし）にぴったりだったのです。","粕酢は運河から船で江戸へ運ばれ、江戸前ずしの味を支えました。いまのミツカンの始まりです。運河沿いに黒い板張りの蔵が並ぶ風景は、醸造の町のシンボルとして今に残っています。黒い板は、焼いた杉板やコールタールで木を守るためのものでした。","明治になると、半田では新しい挑戦も始まります。1898年、ビール工場が建てられ、«カブトビール» が造られました。その赤レンガの建物は、明治の建築家・妻木頼黄が設計し、戦争中は軍需工場にも使われました。今は «半田赤レンガ建物» として公開されています。","運河のほとりには、酢の歴史を紹介する «MIZKAN MUSEUM»、酒の文化館などもあります。黒い蔵と水面、赤レンガ——色のちがう建物が、半田の «ものづくり» の歴史を語っています。"],"tl":[["江戸時代","半田で酒づくりがさかんになる"],["1804年","中野又左衛門が酒粕から酢を造り始める"],["江戸時代後期","粕酢が江戸へ運ばれ、すしに使われる"],["1898年","ビール工場（のちの半田赤レンガ建物）が完成"],["2015年","MIZKAN MUSEUMが開館"],["現在","運河沿いの黒い蔵の景観が残る"]],"who":[["中野又左衛門","ミツカンの初代。酒粕から酢を造った"],["妻木頼黄","半田赤レンガ建物（カブトビール工場）を設計"],["新美南吉","半田出身の童話作家（«ごんぎつね»）"]],"deep":["«粕酢» は酒粕を原料にした赤っぽい酢で «赤酢» とも呼ばれます。江戸時代の後期に流行した早ずしのすし飯に合い、急速に広まったといわれます。","ミツカンの社名は、«三つの線» と «丸» を組み合わせたマークに由来します。マークの意味には、会社の説明による由来があります。","半田赤レンガ建物は、明治時代に建てられた赤レンガの建物として国内でも大規模なもので、国の登録有形文化財になっています。建物の壁には、戦争中の機銃掃射のあとも残っています。","半田は童話作家・新美南吉のふるさとでもあり、市内に新美南吉記念館や生家があります。«ごんぎつね» の舞台とされる風景も残ります。","半田の «山車まつり» は、市内各地に大きな山車が数十台あることで知られ、醸造でうるおった町の豊かさを今に伝えています。"],"look":["運河沿いの黒板囲いの蔵","MIZKAN MUSEUM（予約制の場合あり）","國盛 酒の文化館","半田赤レンガ建物","蔵の町の山車蔵"],"q":["ミツカンの初代・中野又左衛門は、何から酢を造った？","酒粕（さけかす）です。酒づくりのあとに残る酒粕から «粕酢» を造りました。"],"koji":[],"myth":"«中国酒» の呼び名、江戸前ずしへの影響の大きさは伝承・説明をふくむ。","img":["ミツカン","半田赤レンガ建物","新美南吉","粕酢"],"wp":"半田運河","rel":{"ev":[],"grave":[]},"ph":[["c:a/af/Handa_Canal_ac.jpg",5995,3987,"半田運河"],["c:4/4a/Handa_MIZKAN_headquarters_ac_%281%29.jpg",5591,3716,"ミツカン"],["c:9/9e/Handaakarenga.JPG",5953,3968,"半田赤レンガ建物"],["c:a/a9/NiimiNankichi-Portrait-ca1941-42.png",1067,1191,"新美南吉"]]},{"id":"23_noritake","n":"ノリタケの森（近代陶磁器の工場跡）","yomi":"のりたけのもり","cat":"産業","rank":"A","y":1904,"era":["meiji","taisho","heisei"],"sh":"","ad":"名古屋市西区則武新町","st":"地下鉄東山線 亀島駅から歩いて約5分。名古屋駅から歩いて約15分","la":35.18,"lo":136.88,"hook":"一枚の皿がまっすぐに焼けない——その悩みを10年かけて乗りこえ、日本の洋食器が世界へ出ていった。","lead":"ノリタケの森は、1904年に創業した日本陶器（今のノリタケ）の工場の跡地につくられた公園・施設です。明治の赤レンガの工場や、6本の煙突のモニュメントが残ります。ここから、日本製の洋食器が世界へ輸出されていきました。","story":["明治時代、森村市左衛門はアメリカのニューヨークに店を開き、日本の雑貨や陶磁器を売っていました。やがて «アメリカ人が毎日使う洋食器を、日本で作れないだろうか» と考えるようになります。そして1904年、名古屋の «則武» という地に «日本陶器合名会社» をつくりました。","でも、これが大変でした。とくにむずかしかったのが、直径25センチほどの大きな白い皿。焼くとゆがんだり、へこんだりしてしまうのです。«どうしてもまっすぐ焼けない» ——技術者たちは何年も試行錯誤を続けました。","1914年、ついに日本で初めてのディナーセットが完成しました。«ノリタケ» のブランドで売られた洋食器は、アメリカで大人気になり、日本の輸出を支える商品になりました。","この会社からは、ほかにも大切な会社が生まれました。トイレなど衛生陶器の東洋陶器（今のTOTO）、電気を送るための碍子を作る日本碍子、そこから分かれた日本特殊陶業などです。名古屋が «ものづくりの町» になった背景には、ここでつちかわれた陶磁器の技術がありました。","2001年、工場の跡地に «ノリタケの森» が開かれました。赤レンガの旧製土工場、窯の煙突を残したモニュメント。都会の真ん中で、明治の産業の息づかいを感じることができます。"],"tl":[["1876年","森村市左衛門らが森村組を創業（ニューヨークに店）"],["1904年","名古屋・則武に日本陶器合名会社を創立"],["1914年","日本初のディナーセットが完成"],["1917年","東洋陶器（今のTOTO）が分かれて創立"],["1919年","日本碍子（今の日本ガイシ）が分かれて創立"],["2001年","工場跡地に «ノリタケの森» が開業"]],"who":[["森村市左衛門","森村組・日本陶器を興した実業家"],["大倉孫兵衛・大倉和親","森村組の仲間。洋食器づくりや関連会社の創立にかかわった"],["飛鳥井孝太郎","初期の技術者として洋食器開発にかかわったとされる"]],"deep":["«ノリタケ» の名前は、工場のあった地名 «則武（のりたけ）» に由来します。","大皿の開発が難しかったのは、焼くときの縮みやゆがみを制御するのが難しかったためです。素地の配合や焼き方、窯の改良を重ねてようやく完成しました。","森村グループからは、ノリタケ・TOTO・日本ガイシ・日本特殊陶業など、今も続く大企業が生まれました。«陶磁器から自動車部品や電子部品へ» という名古屋のものづくりの流れがここに見えます。","敷地内の赤レンガ建物は、創業当時の工場の建物を生かしたもので、経済産業省の «近代化産業遺産» にも認定されています。","6本の煙突のモニュメントは、かつて工場で使われていた窯の煙突の一部を残したものです。戦後の名古屋の町に、工場の煙突は «ものづくりの象徴» として立っていました。"],"look":["6本煙突のモニュメント","赤レンガの旧製土工場","クラフトセンター（製造工程の見学）","ミュージアムの «オールドノリタケ»"],"q":["«ノリタケ» という名前の由来は？","工場のあった名古屋の地名 «則武（のりたけ）» です。"],"koji":[],"myth":"初期の技術者の役割分担は資料によって書き方に差がある。","img":["ノリタケカンパニーリミテド","森村市左衛門","TOTO","日本ガイシ"],"wp":"ノリタケの森","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/Noritake_Garden02%2C_Nishi_Ward_Nagoya_2014.jpg",1500,1000,"ノリタケの森"],["c:d/dd/%E3%83%8E%E3%83%AA%E3%82%BF%E3%82%B1%E3%82%AB%E3%83%B3%E3%83%91%E3%83%8B%E3%83%BC%E3%83%AA%E3%83%9F%E3%83%86%E3%83%89%E6%9C%AC%E7%A4%BE.jpg",591,348,"ノリタケカンパニーリミテド"],["c:9/90/Morimura_ichibeimon.jpg",410,498,"森村市左衛門"],["c:b/b6/NGK_Insulators_LTD_03.JPG",3648,2736,"日本ガイシ"]]},{"id":"23_meiji_yosui","n":"明治用水（日本デンマークを生んだ用水）","yomi":"めいじようすい","cat":"産業","rank":"A","y":1880,"era":["edo","meiji","taisho"],"sh":"","ad":"豊田市水源町（取水口）〜安城市ほか","st":"取水口の水源公園へは名鉄豊田市駅から車で約10分。安城市内では用水沿いの緑道を歩ける","la":35.059,"lo":137.164,"hook":"水のない台地を、日本一の農業地帯に変えた用水。計画した人は、完成を見ることなく世を去った。","lead":"明治用水は、矢作川から水を引き、安城市などが広がる «碧海台地» をうるおす用水です。江戸時代に都築弥厚が計画し、明治になって1880年に水が通りました。この水のおかげで台地は豊かな農村となり、のちに «日本デンマーク» と呼ばれるほどになりました。","story":["江戸時代、矢作川の西に広がる碧海台地は、水が乏しく、ほとんどが荒れ地や林でした。«川はすぐそばにあるのに、台地の上まで水が来ない» ——農民たちはくやしい思いをしていました。","この台地に水を引こうと考えたのが、和泉村（今の安城市）の豪農・都築弥厚です。弥厚は私財をつぎこんで測量を行い、用水の計画をつくりました。しかし、下流の村々の反対や資金不足で工事は進まず、弥厚は1833年、夢をはたせないまま亡くなりました。","その計画を受けついだのが、岡本兵松と伊予田与八郎でした。明治になって新しい政府の支援も得て、ついに工事が始まります。1880年、矢作川の水が台地の上を流れはじめました。«明治» の時代にできた用水なので «明治用水» と名づけられました。","水が来た台地では、田んぼが一気に広がりました。大正から昭和のはじめには、米づくりだけでなく、野菜・果物・養鶏などを組み合わせた «多角形農業» が進みます。そのようすが農業国デンマークに似ているとして、安城は «日本デンマーク» と呼ばれるようになりました。","2022年には、取水口の «明治用水頭首工» で大きな漏水が起こり、農業や工業の水が止まる事態になりました。140年以上前にできた施設が、今も地域の暮らしと産業を支えていることを改めて示した出来事でした。"],"tl":[["1822年ごろ","都築弥厚が用水の測量・計画を始めたと伝わる"],["1833年","都築弥厚が亡くなる"],["1879年","用水の工事が始まる"],["1880年","通水。«明治用水» と名づけられる"],["大正〜昭和初期","安城が «日本デンマーク» と呼ばれる"],["2016年","世界かんがい施設遺産に登録"],["2022年","頭首工で大規模な漏水が起こる"]],"who":[["都築弥厚","用水を計画した豪農。完成前に亡くなった"],["岡本兵松","計画を受けつぎ、実現に尽くした"],["伊予田与八郎","岡本とともに用水の実現に尽くした"],["山崎延吉","愛知県立農林学校の校長。安城の農業を指導した"]],"deep":["明治用水は、那須疏水（栃木県）・安積疏水（福島県）とならんで «日本三大疏水» に数えられることがあります（数え方には諸説）。","«日本デンマーク» の言葉は、農業の協同組合や農業教育が発達したデンマークを手本とした、大正〜昭和初期の安城の農業を指す呼び名です。","山崎延吉は、安城の愛知県立農林学校で農業教育に力を注ぎ、農民の自立をうながしたことで知られます。","用水の水は今、農業用水だけでなく、自動車関連を中心とする工業用水や水道にも使われ、地域の産業を支えています。","都築弥厚の計画は、測量の正確さでも評価されています。彼の遺した計画が、のちの工事の基礎となったといわれます。"],"look":["水源公園と明治用水頭首工（豊田市）","明治用水の記念碑","安城市内の明治用水緑道","安城市歴史博物館の展示"],"q":["明治用水のおかげで豊かな農村になった安城は、どこの国の名前をとって呼ばれた？","デンマークです。«日本デンマーク» と呼ばれました。"],"koji":[],"myth":"都築弥厚の計画開始年、工事の経緯の細部は資料により差がある。«三大疏水» の数え方も諸説。","img":["都築弥厚","日本デンマーク","矢作川"],"wp":"明治用水","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/%E6%98%8E%E6%B2%BB%E7%94%A8%E6%B0%B403.jpg",1024,365,"明治用水"],["c:1/11/Anjo-Tanabata-Matsuri-2023-2.jpg",4032,3024,"日本デンマーク"],["c:c/c7/View_of_Yahagi_River%2C_Yanadaira-cho_Toyota_2013.jpg",1500,1000,"矢作川"]]},{"id":"23_joan","n":"有楽苑 国宝茶室「如庵」","yomi":"じょあん","cat":"学び","rank":"A","y":1618,"era":["azuchi","edo"],"sh":"国宝","ad":"犬山市御門先（有楽苑）","st":"名鉄犬山線 犬山遊園駅から歩いて約8分","la":35.3845,"lo":136.943,"hook":"信長の弟がつくった、わずか «二畳半台目» の茶室。国宝の茶室は、日本にたった三つしかない。","lead":"如庵は、織田信長の弟で茶人の織田有楽斎が、京都の建仁寺の塔頭に建てた茶室です。国宝の茶室3つのうちの一つで、1972年に犬山の «有楽苑» に移されました。竹をびっしり並べた «有楽窓» や、古い暦を貼った壁など、有楽斎の工夫がつまっています。","story":["織田有楽斎（長益）は、織田信長の弟です。1582年の本能寺の変のとき、有楽斎は信長の長男・信忠と同じ二条御所にいましたが、脱出して生きのびました。«織田の源五（有楽斎）は人ではないよ» と皮肉る歌がはやったと伝わります。","けれども有楽斎は、武将としてより «茶の湯» の人として名を残しました。千利休に学んだ «利休七哲» の一人ともいわれ、晩年は京都の建仁寺の中に «正伝院» を再興して、静かに茶を楽しんで暮らしました。そこに建てた茶室が «如庵» です。","如庵の広さは «二畳半台目»。とても小さな部屋ですが、ふしぎと窮屈ではありません。なぜでしょう？ 壁の一部を斜めにして空間を広く見せたり、竹を細かく並べた «有楽窓» から、やわらかな光を取り入れたりしているからです。壁の下には古い暦が貼られ «暦張り» と呼ばれます。","明治時代、如庵は京都を離れ、三井家の手に渡って東京へ、さらに神奈川県の大磯へと移されました。そして1972年、名古屋鉄道によって犬山に移築され、有楽苑の中に落ち着きました。国宝の茶室は、何度も旅をしてきたのです。","如庵の名は、有楽斎のキリスト教の洗礼名 «ジョアン» に由来するという説があります。戦国の世を生きのびた武将の、静かな «心の部屋»。中へは特別公開のときなどに限られますが、外からでも、その品のよさを感じられます。"],"tl":[["1547年","織田有楽斎（長益）が生まれる"],["1582年","本能寺の変。有楽斎は二条御所から脱出"],["1618年ごろ","京都・建仁寺の正伝院に如庵を建てる"],["1621年","有楽斎が亡くなる"],["明治時代","三井家の手に渡り東京へ移る"],["1938年","神奈川県大磯へ移る"],["1951年","国宝に指定"],["1972年","犬山の有楽苑へ移築"]],"who":[["織田有楽斎（長益）","信長の弟。茶人として如庵をつくった"],["織田信長","有楽斎の兄"],["千利休","茶の湯の大成者。有楽斎の師とされる"],["三井家","明治以降、如庵を守った財閥の一族"]],"deep":["国宝の茶室は、如庵（犬山市）・待庵（京都府大山崎町）・密庵（京都・大徳寺龍光院）の3つです。","«二畳半台目» の «台目» は、ふつうの畳の約4分の3の長さの畳のこと。点前をする人の場所として使われます。","«有楽窓» は、窓の外側に竹を詰め打ちにして、差しこむ光の量を調整する工夫です。障子に竹の影が縞模様に映ります。","床の間の脇に斜めの壁を立てて、客の座る空間と点前の空間をやわらかく区切るのが如庵の大きな特徴で、«筋違いの壁» ともいわれます。","有楽斎の名は、東京の «有楽町» の由来になったという説がよく知られていますが、確かな根拠はないとも指摘されています。","«如庵» の名がキリスト教の洗礼名 «ジョアン» に由来するという説も有名ですが、確証はありません。"],"look":["国宝茶室 如庵の外観","重要文化財の旧正伝院書院","有楽苑の庭園と茶室 «元庵»","特別公開時の如庵内部（有楽窓・暦張り）"],"q":["日本に3つしかない国宝の茶室。如庵のほかの2つは？","待庵（京都府大山崎町）と密庵（京都・大徳寺龍光院）です。"],"koji":[{"w":"一期一会","m":"一生に一度の出会いと思って心をこめてもてなすこと。茶の湯の心を表すことば"}],"myth":"«ジョアン» 由来説、«有楽町» の由来説、本能寺の変での逸話は諸説・伝承。","img":["織田長益","待庵","有楽苑","建仁寺"],"wp":"如庵","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Joan_in_Urakuen%2C_Gomonsaki_Inuyama_Inuyama_City_2023.jpg",1500,1000,"如庵"],["c:2/24/Oda_Nagamasu.jpg",1412,2850,"織田長益"],["c:4/4d/060408_Myoki-an_Oyamazaki_Kyoto_pref_Japan01s3.jpg",2112,1408,"待庵"],["c:9/92/Iwasumon_%28Urakuen%29.jpg",4320,3240,"有楽苑"],["c:d/d6/150124_Kenninji_Kyoto_Japan01s3.jpg",5700,3800,"建仁寺"]]},{"id":"23_toyokawa_kosho","n":"豊川海軍工廠跡（昭和20年8月7日の空襲）","yomi":"とよかわかいぐんこうしょうあと","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"豊川市穂ノ原（豊川市平和公園）","st":"JR飯田線・名鉄豊川線の豊川駅方面からバスまたは車。平和公園は穂ノ原3丁目","la":34.844,"lo":137.378,"hook":"1945年8月7日、わずか数十分の空襲で2500人をこえる命が失われた。その多くが、学生や少年少女だった。","lead":"豊川海軍工廠は、太平洋戦争の時代に海軍の機銃や弾丸をつくった巨大な兵器工場です。終戦の8日前、1945年8月7日のアメリカ軍の空襲で、動員された学生をふくむ2500人以上が亡くなりました。跡地の一部は «豊川市平和公園» として、当時の建物が残されています。","story":["1939年、豊川の広い台地に、海軍の兵器工場が開かれました。«豊川海軍工廠» です。ここでは飛行機や艦船に積む機銃や、その弾丸が大量に作られました。«東洋一の兵器工場» と呼ばれたほどです。","戦争が激しくなると、働き手が足りなくなりました。そこで全国から学生や女学生、少年たちが «勤労動員» で集められました。多いときには数万人が働いていたといわれます。勉強のかわりに、機械の前に立つ毎日でした。","1945年8月7日の午前、アメリカ軍の爆撃機B-29の大編隊が工廠を襲いました。空襲はわずか数十分でしたが、工場は炎につつまれ、2500人をこえる人が亡くなったとされます。その中には400人以上の動員学徒がふくまれていました。終戦のわずか8日前のことです。","«あと少しで戦争が終わったのに» ——遺族や生き残った人々は、その悲しみを長く語り継いできました。工廠の跡地には慰霊の碑がたてられ、毎年8月7日には慰霊祭が行われています。","2018年、跡地の一部が «豊川市平和公園» として開かれました。火薬を扱った建物や防空壕などの遺構が保存され、ガイドの案内で見学できます。ここは、戦争の現実と命の重さを、静かに見つめる場所です。"],"tl":[["1939年","豊川海軍工廠が開庁"],["1941年","太平洋戦争が始まる"],["1944年ごろ","動員学徒などをふくめ多くの人が働く"],["1945年8月7日","アメリカ軍の空襲で2500人以上が亡くなる"],["1945年8月15日","終戦"],["戦後","跡地は自衛隊・工場・大学などに"],["2018年","豊川市平和公園が開園"]],"who":[["動員学徒たち","全国から集められ、工廠で働いた学生・生徒"],["工員・職員","工廠で働いた人々。多くが空襲の犠牲になった"],["遺族・語り部","体験を語り継ぎ、平和を願ってきた人々"]],"deep":["犠牲者の数は資料によって少しずつ異なりますが、2500人前後とされ、その中には多くの10代の学徒や女子挺身隊員がふくまれていました。","空襲は午前中に行われ、爆撃の時間はおよそ30分弱だったといわれます。工場の建物が集中していたため、被害が一気に広がりました。","平和公園には、第一火薬庫、信管置場、防空壕などの遺構が残されています。コンクリートの厚い壁が、火薬を扱う危険な仕事だったことを物語ります。","工廠の跡地は、戦後に陸上自衛隊豊川駐屯地、日本車輌の工場、名古屋大学の研究施設などに使われ、その敷地の中にも遺構が残っているといわれます。","平和公園の «平和交流館» では、遺品や写真、体験者の証言映像などを通して、空襲の日のことや工廠で働いた人々の暮らしを学ぶことができます。"],"look":["豊川市平和公園の遺構（火薬庫・信管置場など）","平和交流館の展示と証言映像","防空壕の跡","慰霊碑（手を合わせて）"],"q":["豊川海軍工廠が空襲を受けたのは、終戦の何日前？","8日前の1945年8月7日です。"],"koji":[],"myth":"犠牲者数・動員学徒数、働いていた人の数は資料により差がある。一部の遺構は私有地・施設内で非公開。","img":["豊川市","勤労動員"],"wp":"豊川海軍工廠","rel":{"ev":[],"grave":[]},"ph":[["c:6/6f/Toyokawainari_honden_%28cropped%29.jpg",4909,3682,"豊川市"]]},{"id":"23_shinojima","n":"篠島（伊勢神宮への御幣鯛）","yomi":"しのじま","cat":"島","rank":"A","y":1338,"era":["nara","muromachi","edo"],"sh":"","ad":"知多郡南知多町篠島","st":"名鉄河和駅から高速船で約25分。師崎港からは約10分","la":34.676,"lo":136.991,"hook":"1000年以上、伊勢の神さまに «干した鯛» を届けてきた島がある。","lead":"篠島は、知多半島の先に浮かぶ周囲約8キロメートルの小さな島です。古くから伊勢神宮と深く結びつき、神宮にそなえる干した鯛 «御幣鯛（おんべだい）» を今も奉納しています。南北朝時代に皇子の船が流れ着いたという伝説も残る、海の歴史の島です。","story":["伊勢湾の入り口、三河湾との境に浮かぶ篠島。ここは昔から魚の豊かな海に囲まれ、島の人々は漁をして暮らしてきました。そして、島は海をはさんだ伊勢神宮と深く結ばれていました。","伊勢神宮にそなえる鯛を、篠島から納める——。この習わしがいつ始まったかは、はっきりしませんが、倭姫命が島を訪れたことに由来するともいわれ、とても古くから続いていると伝わります。島では «御幣鯛» と呼ばれる干し鯛を、年に何度か神宮へ納めています。","鯛は、島の «中手島» にある施設で、塩をして干して作られます。完成した御幣鯛は船で伊勢へ運ばれます。«神さまへのおそなえだから、いちばんいい鯛を» ——漁師たちの気持ちがこめられています。","島の神明神社は、伊勢神宮の式年遷宮のあと、古い社殿の材木を受けついで建てかえる習わしがあるといわれます。20年ごとに伊勢の «おさがり» が島にやってくるのです。","南北朝時代の1338年、南朝の北畠親房らは後醍醐天皇の皇子・義良親王を奉じ、伊勢から船で東北をめざしました。ところが嵐にあい、親王の船が篠島に流れ着いたと伝わります。島には «帝井（みかどい）» など、そのときの伝承の場所が残ります。"],"tl":[["古代","伊勢神宮に鯛を納める習わしが始まったと伝わる"],["1338年","義良親王の船が嵐で篠島に流れ着いたと伝わる"],["その後","親王はのちに後村上天皇となる"],["江戸時代","尾張藩領の島として漁業で栄える"],["現在","御幣鯛の奉納が続けられている"]],"who":[["倭姫命","伊勢神宮の起こりにかかわる伝説の皇女。篠島を訪れたと伝わる"],["義良親王（後村上天皇）","嵐で篠島に流れ着いたと伝わる皇子"],["北畠親房","南朝の重臣。親王を奉じて東国へ向かった"],["篠島の漁師たち","御幣鯛をつくり、伊勢へ届けてきた"]],"deep":["御幣鯛の奉納は年に数回行われ、神宮の祭りに合わせて納められます。奉納の回数や時期は時代によって変わってきたといわれます。","1338年の義良親王一行の船団は、嵐で散り散りになり、親王の船は伊勢方面へ戻されたとも伝わります。篠島への漂着は地元に残る伝承として語られています。","神明神社の社殿に伊勢神宮の古材を使う習わしは、神宮とのつながりを示すものとして島の誇りになっています。","篠島はしらす漁でも知られ、島の漁業は今も盛んです。狭い路地が迷路のように続く漁村の町並みも魅力です。","篠島の周りには日間賀島・佐久島など «三河湾の島» があり、それぞれ独自の歴史と信仰を伝えています。","篠島は江戸時代には尾張藩の領地で、伊勢湾・三河湾の «海の交通路» の要所にありました。漁業だけでなく、船が風待ちをする港としての役割もあったといわれます。"],"look":["神明神社（伊勢神宮の古材で建てかえられる社）","中手島（御幣鯛の調製所がある島）","帝井（義良親王の伝承地）","八王子社と島の路地","島の港と海のながめ"],"q":["篠島が伊勢神宮に納めている、干した鯛を何という？","«御幣鯛（おんべだい）» です。"],"koji":[],"myth":"御幣鯛の起源（倭姫命）、義良親王漂着と帝井、神明神社の古材の習わしは伝承をふくむ。","img":["伊勢神宮","後村上天皇","北畠親房"],"wp":"篠島","rel":{"ev":[],"grave":[]},"ph":[["c:4/45/Shinojima_aerial_photograph.jpg",4611,3458,"篠島"],["c:e/e3/Naiku_001.jpg",4288,2848,"伊勢神宮"],["c:a/a0/Emperor_Go-Murakami.jpg",1537,2928,"後村上天皇"]]},{"id":"23_nishio_jo","n":"西尾城","yomi":"にしおじょう","cat":"城","rank":"A","y":1221,"era":["kamakura","azuchi","edo"],"sh":"","ad":"西尾市錦城町（西尾市歴史公園）","st":"名鉄西尾線 西尾駅から歩いて約15分","la":34.8615,"lo":137.0515,"hook":"足利氏が築き、吉良氏が治め、家康の家臣が守った城。«西尾» の名前は «西の城» から生まれた。","lead":"西尾城は、鎌倉時代に三河の守護となった足利義氏が築いたと伝わる «西条城» がもとになった城です。戦国時代には吉良氏や徳川家の家臣が城主となり、江戸時代は西尾藩の城でした。今は «西尾市歴史公園» として、櫓や門が復元されています。","story":["1221年の «承久の乱» のあと、足利義氏は三河国の守護になりました。義氏はこの地に城を築いたと伝わります。当時は «西条城» と呼ばれ、東にあった «東条城» と対になっていました。«西条» が、のちの «西尾» の名のもとになったといわれます。","義氏の子孫は、この地の «吉良» という土地の名を名のって «吉良氏» となりました。吉良氏は足利将軍家に近い名門の家柄で、室町時代を通してこの地方の重要な一族でした。","戦国時代、三河を統一していった徳川家康は、西尾城を自分の家臣にまかせました。やがて豊臣の時代を経て、江戸時代になると西尾藩の城となり、本多・松平・太田・井伊・大給松平など、たくさんの大名が入れかわり城主になりました。","明治になると城は取りこわされ、石垣や堀も多くが失われました。しかし1996年、本丸の «丑寅櫓» と «鍮石門（ちゅうじゃくもん）» が復元され、城の姿の一部がよみがえりました。","歴史公園には、京都から移した «旧近衛邸» の建物もあり、お茶を楽しむこともできます。«鎌倉から江戸まで、何百年も続いた城» ——城あとを歩くと、時代ごとの主の顔が見えてきます。"],"tl":[["1221年","承久の乱。のちに足利義氏が三河守護となる"],["鎌倉時代","義氏が西条城を築いたと伝わる"],["室町時代","吉良氏がこの地を治める"],["戦国時代","徳川家康の家臣が城をまかされる"],["江戸時代","西尾藩の城として多くの大名が入れかわる"],["明治時代","城が取りこわされる"],["1996年","丑寅櫓と鍮石門が復元される"]],"who":[["足利義氏","鎌倉時代の三河守護。西条城を築いたと伝わる"],["吉良氏","足利一門。この地を治めた名門"],["酒井正親","家康の家臣。西尾城をまかされたと伝わる"],["大給松平家","江戸時代後期の西尾藩主"]],"deep":["西尾城の «西条城» と、吉良町（今の西尾市）にあった «東条城» は、吉良氏の二つの流れ «西条吉良» と «東条吉良» の拠点として知られます。","酒井正親は、家康の家臣で初めて «城主» となった人物ともいわれますが、その評価には諸説があります。","«鍮石門» の «鍮石（ちゅうじゃく）» は真鍮のこと。門の飾りに真鍮の金具を使ったことに由来するといわれます。","江戸時代の西尾藩は、城主の交代が多い藩でした。最後の藩主は大給松平家で、明治まで治めました。","西尾は «抹茶» の産地としても知られ、城下の茶文化は、歴史公園の茶室での一服とともに今も味わえます。","«承久の乱» は1221年、後鳥羽上皇が鎌倉幕府に対して兵をあげ敗れた戦いです。この乱のあと、幕府側で手柄を立てた武士たちが西国や東海の守護・地頭に任じられ、足利義氏もその一人でした。"],"look":["復元された丑寅櫓","鍮石門","本丸の石垣と堀の跡","旧近衛邸（茶室）","西尾市資料館"],"q":["西尾城の前身とされる、足利義氏が築いたと伝わる城の名前は？","西条城です。«西条» がのちの «西尾» の名のもとになったといわれます。"],"koji":[],"myth":"足利義氏の築城、«西条→西尾» の由来、酒井正親の «初の城主» 説は伝承・諸説。","img":["足利義氏","吉良氏","西尾藩","西尾市"],"wp":"西尾城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c7/Nishio_Castle.jpg",5415,3615,"西尾城"],["c:f/f0/NIshio-Castle-4.jpg",3857,2754,"西尾市"]]},{"id":"23_kezoji","n":"華蔵寺（吉良上野介義央の墓所）","yomi":"けぞうじ","cat":"墓所","rank":"A","y":1702,"era":["edo"],"sh":"","ad":"西尾市吉良町岡山","st":"名鉄西尾線 上横須賀駅から歩いて約25〜30分（車が便利）","la":34.84275,"lo":137.0815,"hook":"忠臣蔵では «悪役» の吉良上野介。けれど、ふるさと三河の吉良では、いまも «殿さま» として静かに眠っている。","lead":"華蔵寺は、高家・吉良家の菩提寺（先祖をまつるお寺）です。境内の墓所には、寺を開いた吉良義定の父・義安から、上野介義央、その跡つぎ義周まで6代の墓が並びます。義央が50歳のときの姿を写したという木像も伝わり、«地元から見た吉良さん» に出会える場所です。","story":["お寺があるのは、三河湾に近い吉良の丘のふもと。吉良家は、足利将軍家の一族という、とても家柄の高い家でした。戦国時代にいったん力を失いましたが、義定が徳川家康に仕えて旗本として家を立て直します。そのとき、亡き父・義安をとむらうために開いたのが、この華蔵寺だと伝わります。","江戸時代の吉良家は «高家»。朝廷とのやりとりや、将軍家の儀式の作法を教える役目です。上野介義央は、その道のベテランでした。1701年、江戸城の松之大廊下で、赤穂藩主・浅野内匠頭に斬りつけられ、翌年の冬、赤穂浪士の討ち入りで命を落とします。«なぜ斬られたのか?» その理由は、今もはっきりしていません。","芝居の «忠臣蔵» では、吉良はいじわるな悪者として描かれてきました。ところが吉良の土地では話がちがいます。«水害から村を守る堤を築いてくださった»«赤い馬に乗って領地を見回っておられた» —— そんな言い伝えが、今も大切に語られているのです。","境内には、義央が寄進したという経蔵や、元禄3年の銘がある梵鐘、義央が作らせたとされる庭が残ります。本堂の奥には、義央50歳の姿という木像。ふっくらした穏やかな顔つきで、見た人の多くが «イメージとちがう» と驚くそうです。","墓所の石塔は、にぎやかな観光地のような飾り気はありません。江戸で亡くなった義央の遺体は江戸の万昌院に葬られましたが、ふるさとのこの寺にも墓が建てられました。討ち入りのあと家は取りつぶされ、跡つぎの義周も若くして亡くなります。静かな墓所は、もう一つの «忠臣蔵» を物語っています。"],"tl":[["1600年","吉良義定が父・義安の菩提をとむらうため華蔵寺を開いたと伝わる"],["1641年","吉良義央（上野介）が生まれる"],["1690年","元禄3年銘の梵鐘がつくられる（義央の寄進と伝わる）"],["1701年","江戸城松之大廊下で浅野内匠頭が義央に斬りつける"],["1702年12月","赤穂浪士の討ち入りで義央が討たれる（旧暦）"],["1706年","養子で跡つぎの義周が、預けられた先の信濃・高島で亡くなる"],["江戸時代中ごろ","画家・池大雅が寺をたびたび訪れ、襖絵や額を残す"]],"who":[["吉良義央（上野介）","高家の当主。忠臣蔵で討たれた人物で、ここに墓がある"],["吉良義定","義央の曾祖父。旗本として吉良家を再興し、寺を開いた"],["吉良義安","義定の父。この寺でとむらわれた"],["吉良義周","義央の養子（上杉家から入った孫）。討ち入り後に家は断絶"],["池大雅","江戸時代の文人画家。寺に襖絵と木額を残した"]],"deep":["吉良家墓所には、義安・義定・義弥・義冬・義央・義周の6代の墓がある。«江戸の高家» と «三河の領主» という二つの顔を、墓所がつないでいる。","義央の木像は愛知県指定文化財。50歳のときの姿とされ、衣冠をつけた正装の座像。芝居の敵役の顔とは正反対の、落ち着いた表情が見どころ。","池大雅の作と伝わる襖絵など40面が県指定文化財。山門の «片岡山»、中門の «華蔵世界» の額も大雅の筆とされる。ふだんは収蔵庫にあり、正月に本堂で公開されることがある。","寺の山号 «片岡山» は «へんこうざん» と読む。大雅の書いた額が今も山門にかかっていて、文字そのものが文化財という珍しい門。","義央の遺体は江戸の万昌院（現在は東京都中野区）に葬られた。華蔵寺の墓は、ふるさとに建てられたもう一つの墓所にあたる。","近くの «黄金堤» は、義央が水害を防ぐために築かせたと伝わる堤防。«赤馬» の郷土玩具も、義央が赤毛の馬で領内を回ったという伝承から生まれたといわれる。","討ち入り後、幕府は吉良家を取りつぶした。義周は信濃国の高島藩（長野県諏訪市）に預けられ、21歳ほどで亡くなった。被害を受けた側が罰せられたことも、この事件の不思議な一面。"],"look":["吉良家6代の墓が並ぶ墓所","義央が寄進したと伝わる経蔵と、元禄3年銘の梵鐘","池大雅の筆とされる山門の «片岡山» の額","義央が作らせたとされる庭園","近くの黄金堤（義央が築いたと伝わる堤防）"],"q":["華蔵寺に墓がある «忠臣蔵» の人物はだれ？","吉良上野介義央。芝居では悪役ですが、地元の吉良では名君として慕われています。"],"koji":[{"w":"判官びいき","m":"弱い立場や悲運の側に同情すること。忠臣蔵人気の背景にもこの気持ちがあるといわれ、そのぶん吉良は悪役にされがちだった"}],"myth":"黄金堤・赤馬の話、名君像は地元の伝承。刃傷の理由は諸説で不明。","img":["吉良義央","赤穂事件","池大雅"],"wp":"華蔵寺 (西尾市)","rel":{"ev":[],"grave":[]},"ph":[["c:e/e7/Kezouji1.jpg",5847,3898,"華蔵寺 (西尾市)"],["c:a/aa/Ohiroma_Honmaru_Edo_Castle_4.JPG",3567,2675,"赤穂事件"],["c:e/eb/A_portrait_of_Ike_Taiga_by_Fukuhara_Gogaku_%E6%B1%A0%E5%A4%A7%E9%9B%85%E5%83%8F_%E7%A6%8F%E5%8E%9F%E4%BA%94%E5%B2%B3.jpg",2363,3252,"池大雅"]]},{"id":"23_kariya_jo","n":"刈谷城（於大の方の実家・水野氏）","yomi":"かりやじょう","cat":"城","rank":"A","y":1533,"era":["muromachi","azuchi","edo"],"sh":"","ad":"刈谷市城町1丁目（亀城公園）","st":"名鉄三河線 刈谷市駅から歩いて約15分","la":34.98936,"lo":136.98522,"hook":"徳川家康のお母さん «於大の方» は、この城から嫁いでいった。天下人の物語は、衣ヶ浦の水辺の小さな城から始まる。","lead":"刈谷城は、1533年に水野忠政が築いた城で、別名を «亀城» といいます。忠政の娘・於大は、ここから岡崎の松平広忠に嫁ぎ、のちの徳川家康を産みました。いまは «亀城公園» になり、土塁や堀の名残、城のことがわかる歴史博物館があります。","story":["昔の刈谷は、衣ヶ浦という入江の奥に面した水辺の町でした。1533年、この地の武将・水野忠政は、ここに新しい城を築いて本拠を移します。水野氏は尾張と三河の境目にいて、西の織田、東の今川にはさまれた «板ばさみ» の立場でした。","忠政は、娘の於大を岡崎城主の松平広忠に嫁がせます。1542年、於大は男の子を産みました。のちの徳川家康、幼名・竹千代です。ところが忠政が亡くなると、跡を継いだ兄の水野信元は、今川方から織田方へ味方をかえてしまいます。«織田の味方の家の娘を、妻にしてはおけぬ» —— 今川方だった広忠は、於大を離縁しました。","於大は、まだ幼い竹千代を岡崎に残して刈谷へ帰ります。城の近くの «椎の木屋敷» で過ごし、やがて久松俊勝のもとに再び嫁ぎました。わが子と引きはなされた母は、遠くから竹千代に着物や菓子を送りつづけたと伝わります。","1560年、桶狭間の戦いのあと、今川方の岡部元信が刈谷を襲い、城主の水野信近（信元の弟）が討たれました。城に火が放たれたことは今川氏真の文書からわかりますが、城が落ちたかどうかは諸説あります。1575年には信元が内通を疑われて殺され、城は一時、織田家臣・佐久間信盛のものになりました。","その後、水野氏が城主に返り咲き、江戸時代は刈谷藩の城として、城主が何度も入れかわりながら明治まで続きました。1871年に廃城。公園になった城跡は戦争中に高射砲陣地が置かれて荒れましたが、戦後は桜の名所としてよみがえり、いま隅櫓や塀を復元する計画が進められています。"],"tl":[["1533年","水野忠政が刈谷城を築き、本拠を移す"],["1541年","忠政の娘・於大が松平広忠に嫁ぐ"],["1542年","於大が竹千代（のちの徳川家康）を産む"],["1544年ごろ","水野信元が織田方につき、於大が離縁されて刈谷へ戻る"],["1560年","今川方の岡部元信が刈谷を攻め、城主・水野信近が討たれる"],["1575年","水野信元が殺され、城は佐久間信盛の領地に"],["1747年","土井氏が城主となり、幕末まで続く"],["1871年","廃藩により廃城"],["1936年","刈谷町が城跡を譲り受け、公園に"],["2019年","刈谷市歴史博物館が開館"]],"who":[["水野忠政","刈谷城を築いた武将。於大の父で、家康の祖父"],["於大の方（伝通院）","忠政の娘。徳川家康の生母"],["水野信元","於大の兄。織田方につき、のちに殺される"],["水野勝成","信元の弟・忠重の子。のちに備後福山藩主となる猛将"],["松平広忠","岡崎城主。於大の夫で家康の父"]],"deep":["正しくは «刈屋城»。『三河物語』や『信長公記』にも «刈屋»«かり屋» と出てくる。«刈谷» の字が定着したのは1950年に刈谷市ができてからといわれる。","城の前身として «刈谷古城» があったとされ、市は水野貞守が15世紀後半に築いたとする。根拠は禅僧・万里集九の紀行文『梅花無尽蔵』だが、江戸時代の地誌には記述がなく、実態はよくわかっていない。","1560年の岡部元信の攻撃について、今川氏真の判物には «城主の水野藤九郎らを討ち取り、城内に放火» とある。«攻め落とした» とは書かれていないため、落城しなかったという説が近年は有力。","天守はなく、本丸の北西と南東に隅櫓があった。西側は衣ヶ浦に面し、他の三方を堀で囲む水城だった。","刈谷市の辰巳櫓が市内の妙福寺に移されて残っていると伝わる。本丸の土塁と、堀を広げた池が、今も城の形を伝えている。","於大が再婚した久松俊勝との子どもたちは、のちに «松平» の姓を許され、家康の異父弟として徳川家を支えた。"],"look":["本丸を囲む土塁","堀を広げた池（帯曲輪東側）","本丸跡に建つ再建の «十朋亭»","刈谷市歴史博物館（城の模型・絵図）","春の桜"],"q":["刈谷城主・水野忠政の孫にあたる天下人はだれ？","徳川家康。忠政の娘・於大が家康の母です。"],"koji":[],"myth":"於大が竹千代に品物を送った話は伝承。1560年の落城の有無は諸説。辰巳櫓の移築は伝承を含む。","img":["於大の方","水野忠政","水野信元","刈谷藩"],"wp":"刈谷城","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/140112Kijo_Park_Kariya_Aichi_pref_Japan01s5.jpg",4912,3264,"刈谷城"],["c:8/87/%E4%BC%9D%E9%80%9A%E9%99%A2.jpg",1426,2686,"於大の方"],["c:8/8c/Mizuno_Tadamasa01.jpg",1577,3477,"水野忠政"]]},{"id":"23_katsuhata_jo","n":"勝幡城跡（信長誕生の城とされる）","yomi":"しょばたじょうあと","cat":"城","rank":"A","y":1534,"era":["muromachi"],"sh":"市指定史跡（稲沢市）","ad":"稲沢市平和町六輪・愛西市勝幡町","st":"名鉄津島線 勝幡駅から歩いて約10分","la":35.19981,"lo":136.74381,"hook":"«信長は那古野城で生まれた» —— その常識が、いま揺らいでいる。有力候補は、川べりの小さな城跡だ。","lead":"勝幡城は、戦国時代のはじめに信長の祖父・織田信定が築いた城です。信長の父・信秀が本拠にし、近年の研究では信長もここで生まれたと考えられるようになりました。建物も堀も残っていませんが、日光川のほとりに2つの石碑が立っています。","story":["16世紀のはじめ、尾張の西部を流れる川のそばに、二重の堀で囲まれた館のような城が築かれました。築いたのは織田信定。尾張の守護代・織田大和守家に仕える «三奉行» の一家、織田弾正忠家の当主です。城のすぐ南には、港町・津島がありました。","津島は、津島神社の門前町で、川を使った物流の拠点。お金と物が集まる町です。信定と子の信秀は、この津島を押さえることで、ほかの武将よりもずっと豊かになりました。«戦に勝つには、まずお金» —— のちの信長の経済重視の考え方の原点が、ここにあるともいわれます。","1533年、京都の公家・山科言継がこの城に招かれました。言継は日記『言継卿記』に、城の立派さに驚いたことを書き残しています。都の人をもてなし、蹴鞠などの文化を学ぶ。信秀は、戦だけでなく «外交» にも力を入れる武将でした。","その翌年、1534年に信秀の子・吉法師、のちの信長が生まれます。長いあいだ、生まれた場所は那古野城（のちの名古屋城のあたり）だとされてきました。けれど、信秀が今川氏から那古野城を奪ったのは1538年ごろだという研究が出てきます。«それなら、1534年の信秀はまだ勝幡にいたはず» —— こうして勝幡城説が有力になったのです。","信秀が那古野に移ると、勝幡城には家臣の武藤雄政が置かれ、やがて城は使われなくなりました。江戸時代に日光川が新しく掘られ、城のあった土地の多くは川の下になったと考えられています。1979年、排水工事の最中に大きな石が見つかり、古い絵図と照らし合わせて、櫓台の石だとわかりました。"],"tl":[["1504〜1521年ごろ","織田信定（またはその父・良信）が勝幡城を築いたとされる"],["1533年","公家の山科言継が城を訪れ、日記に記す"],["1534年","信長（吉法師）が生まれる。勝幡城が生誕地とする説が有力に"],["1538年ごろ","信秀が那古野城を奪って移る（従来は1532年説）"],["江戸時代","日光川の開削で、城の跡の多くが川の下になる"],["1979年","排水工事で櫓台の基石が見つかる"]],"who":[["織田信定","勝幡城を築いたとされる。信長の祖父"],["織田信秀","信長の父。勝幡城を本拠に、津島の経済力で勢力を広げた"],["織田信長","近年の説で、この城で生まれたとされる"],["山科言継","京都の公家。『言継卿記』に勝幡城のことを書いた"],["武藤雄政","信秀が那古野に移ったあと、城を守った家臣"]],"deep":["規模は、江戸時代の『勝幡村古城絵図』に «本丸は東西29間・南北43間、幅3間の方形土塁»、『寛文村々覚書』に «東西48間・南北70間» とある。史料によって数字がちがう。","地名はもと «塩畑（しおばた）» で、縁起をかついで «勝ち旗» の意味の «勝幡» に改めたと伝わる。書きまちがいから変わったという話もある。","城のあたりの川は江戸時代の改修で大きく変わった。当時は三宅川が城のすぐ近くを流れ、外堀の役目をしていたと考えられている。","1979年に見つかった基石は、愛西市の佐織支所で保管されている。«城の数少ない実物» といえる。","石碑は、日光川の左岸に «織田弾正忠平朝臣信定古城蹟»（愛西市側）と «勝幡城址»（稲沢市側）の2つがある。市の境をまたぐ城跡。","那古野城を奪った年を1532年とする説と1538年とする説があり、どちらを取るかで信長の生誕地の答えが変わる。"],"look":["日光川左岸の2つの石碑","勝幡駅前の城の推定復元模型","近くの津島（津島神社・天王川公園）とあわせた散策"],"q":["勝幡城の近くにあり、織田家の経済を支えた港町はどこ？","津島。津島神社の門前町で、川の物流の拠点でした。"],"koji":[],"myth":"信長の生誕地は那古野城説と勝幡城説がある（近年は勝幡説が有力）。地名の由来も伝承。","img":["織田信秀","津島神社","那古野城"],"wp":"勝幡城","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Shobata_Castle_01.jpg",4000,2250,"勝幡城"],["c:1/15/Statue_of_Oda_Nobuhide_at_Bansh%C5%8D-ji.jpg",1740,1849,"織田信秀"],["c:a/a1/Tsushima-jinja_Shrine_Haiden_%281%29%2C_Shimmei-cho_Tsushima_City_2023.jpg",1500,1000,"津島神社"],["c:e/ee/Site_of_Nagoya_Castle.jpg",1280,960,"那古野城"]]},{"id":"23_jomokuji","n":"甚目寺観音","yomi":"じもくじかんのん","cat":"寺社","rank":"A","y":597,"era":["asuka","kamakura","edo"],"sh":"国の重要文化財（南大門・三重塔・東門）","ad":"あま市甚目寺東門前","st":"名鉄津島線 甚目寺駅から歩いて約5分","la":35.19514,"lo":136.82289,"hook":"漁師の網にかかったのは、魚ではなく観音さまだった —— 海辺の伝説から始まった、尾張でも指折りの古いお寺。","lead":"甚目寺観音は、飛鳥時代の597年に始まったと伝わる真言宗のお寺です。源頼朝の命で建てられた南大門（鎌倉時代）、江戸時代初めの三重塔と東門が国の重要文化財。福島正則が子どものころ手習いに通ったとも伝わる、あま市のシンボルです。","story":["お寺の言い伝えは、こんな話です。597年、伊勢の漁師の頭・甚目龍麿が、このあたりの海で網を引くと、重い手ごたえ。引き上げてみると、なんと観音さまでした。«これはただごとではない» —— 龍麿は近くの砂浜にお堂を建てて、観音さまをまつりました。今は海から遠い内陸ですが、昔はこのあたりまで海が入りこんでいたのです。","この観音さまには、もっと古い物語がついています。仏教を受け入れるかどうかで争いがあった時代、物部守屋らが仏像を海に投げ捨てたといいます。その3体のうちの1体がこの観音さまで、ほかの1体は信濃の善光寺の阿弥陀如来だと伝わります。«海を流れて尾張にたどりついた仏» という、壮大なお話です。","鎌倉時代、源頼朝の命令で、梶原景時が奉行となって南大門が建てられました。1196年のことです。800年以上たった今も、その門が立ち、両わきには福島正則が寄進した仁王像がにらみをきかせています。正則は近くの二ツ寺村の生まれで、子どものころこの寺で読み書きを習ったと伝わります。","江戸時代に入ると、1627年に三重塔、1634年に東門が再建されます。一方で、1873年の火事で本堂が焼け、1891年の濃尾地震では建物がこわれるなど、苦難も続きました。いまの本堂は1992年に再建されたものです。","境内は、門前町の雰囲気が残るにぎやかな場所。毎月12日には手づくり朝市が開かれ、節分には大勢の参拝者が集まります。名古屋の中心にある大須観音から見て «恵方» の方角にある年の節分は、とくににぎわうそうです。1300年以上つづく祈りの場は、今も町の暮らしのすぐそばにあります。"],"tl":[["597年","甚目龍麿が海で観音像を引き上げ、お堂を建てたと伝わる"],["1196年","源頼朝の命により南大門が再建される（現存）"],["1283年","一遍が鎌倉から京へ上る途中に訪れる"],["1337年","梵鐘（県指定文化財）がつくられる"],["1597年","福島正則が仁王像を寄進"],["1627年","三重塔が再建される（現存）"],["1634年","東門が再建される（現存）"],["1873年","火事で本堂が焼失"],["1992年","本堂が再建される"]],"who":[["甚目龍麿","伊勢の海人の豪族。観音像を引き上げ、寺を開いたと伝わる"],["源頼朝","鎌倉幕府を開いた人。南大門の再建を命じた"],["梶原景時","頼朝の家来。南大門建立の奉行をつとめた"],["福島正則","近くの生まれの戦国武将。仁王像を寄進した"],["一遍","時宗を開いた僧。寺を訪れ、念仏踊りの伝統を残したといわれる"]],"deep":["寺の名は、開いた龍麿の氏 «甚目（はだめ）» から。古くは «波陀米泥良（はだめでら）» と書かれ、«甚目寺（じもくじ）» の字と読みになったのは中世からとされる。","本尊の聖観音は高さ一尺一寸五分（約35cm）の秘仏で、本堂の十一面観音像（50年に1度の開帳）の胎内に納められているとされる。","考古学者・石田茂作の研究により、境内の歴史が奈良時代以前にさかのぼることが示されている。伝説だけの寺ではない可能性を示している。","南大門の仁王像は愛知県指定文化財で、安土桃山時代の作。1597年、福島正則の寄進と伝わる。","絹本著色不動尊像（平安時代）は愛知県内最古の仏教絵画とされる重要文化財で、東京国立博物館に寄託されている。","2011年、重要文化財の愛染明王坐像を解体修理したところ、胎内の容器（合子）の中から、もう1体の小さな愛染明王像が見つかった。","三重塔は高さ約25m。1627年に吉田半十郎の寄進で再建された。"],"look":["鎌倉時代の南大門と福島正則寄進の仁王像","江戸時代初めの三重塔（約25m）","1634年再建の東門","門前町の雰囲気と毎月12日の朝市","境内の小さなお堂めぐり（参拝捺印でお守りがもらえる）"],"q":["甚目寺の南大門を建てるよう命じた鎌倉幕府の将軍はだれ？","源頼朝。1196年に梶原景時を奉行として建てられ、今も残っています。"],"koji":[],"myth":"観音像を網で引き上げた話、物部氏が海に捨てた3体の一つという話は寺の伝承。正則の手習いも伝承。","img":["福島正則","源頼朝","尾張四観音"],"wp":"甚目寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Jimokuji_%28Hondo%29.JPG",4920,3200,"甚目寺"],["c:2/22/Masanori_Fukushima.JPG",517,658,"福島正則"],["c:0/08/%E5%B1%B1%E6%A2%A8%E7%B8%A3%E7%94%B2%E5%BA%9C%E5%B8%82%E5%96%84%E5%85%89%E5%AF%BA%E6%BA%90%E8%B3%B4%E6%9C%9D%E6%9C%A8%E5%83%8F.jpg",1792,2560,"源頼朝"],["c:a/a7/Shikannonmichi_01.jpg",1024,768,"尾張四観音"]]},{"id":"23_arako_kannon","n":"荒子観音（円空仏と前田利家の菩提）","yomi":"あらこかんのん","cat":"寺社","rank":"A","y":1536,"era":["nara","muromachi","edo"],"sh":"国の重要文化財（多宝塔）","ad":"名古屋市中川区荒子町宮窓","st":"地下鉄東山線 高畑駅から歩いて約9分／あおなみ線 荒子駅から歩いて約10分","la":35.13657,"lo":136.85823,"hook":"一本のヒノキから、千体をこえる仏さまが生まれた —— 旅の僧・円空が残した «木の仏» の宝庫。","lead":"荒子観音は、奈良時代に開かれたと伝わる天台宗のお寺です。1536年に建てられた多宝塔は名古屋市でいちばん古い建物で、国の重要文化財。江戸時代の僧・円空が彫った仏像が1200体以上も残り、加賀百万石の祖・前田利家が本堂を建て直した寺としても知られます。","story":["お寺の言い伝えでは、始まりは729年。白山を開いたとされる伝説の僧・泰澄が草創したといいます。昔は «七堂伽藍十二坊» をそろえた大寺だったと伝わりますが、戦乱で古い記録はほとんど失われました。今の場所に落ち着いたのは中世のことと考えられています。","荒子は、戦国武将・前田利家のふるさとです。利家は荒子の武士の家に生まれ、若いころは織田信長のそばで «槍の又左» と呼ばれる暴れん坊でした。1576年、利家はこの寺の本堂を建て直し、自分の甲冑も納めたと伝わります。のちに加賀百万石の大名となる利家にとって、ここは «ふるさとの寺» でした。","江戸時代の初めごろ、ぼろぼろの衣を着た一人の僧が寺を訪れます。美濃生まれの円空です。«一本の木の中には、仏さまが眠っている» —— そう言ったかどうかはわかりませんが、円空は大きなヒノキからまず仁王像を彫り、残りの木で次々に仏を刻み、最後は木切れにまで顔を彫りました。","1972年、境内の六角堂にあった木箱を開けてみると、中から千体をこえる小さな仏像があらわれました。«千面菩薩» と呼ばれる円空仏です。箱の中には、仏といっしょに削りくずまで入っていたといいます。いまこの寺には、全国に残る円空仏のおよそ4分の1が集まっています。","山門で見下ろす2体の仁王像も円空の作といわれ、円空仏で最大級の像です。ごつごつしたノミのあとが残る顔は、こわいというより、どこか笑っているよう。毎月第2土曜日の午後には円空仏が公開され、仏を彫る体験教室も開かれています。"],"tl":[["729年","泰澄が草創したと伝わる（寺伝）"],["1429年","«尾州一楊御厨観音寺» の銘がある鰐口がつくられる"],["1536年","多宝塔が再建される（現存。名古屋市内最古の建物）"],["1576年","前田利家が本堂を再建し、甲冑を納めたと伝わる"],["1676年ごろ","円空が滞在し、多くの仏像を彫る"],["1972年","六角堂の木箱から千体をこえる円空仏が見つかる"],["1994年","本堂が焼失（1997年に再建）"]],"who":[["円空","江戸時代前期の僧。全国を旅して «円空仏» を彫った。この寺に1200体以上が残る"],["前田利家","荒子出身の戦国武将。本堂を再建し、寺を菩提寺とした"],["泰澄","白山を開いたとされる奈良時代の僧。寺を開いたと伝わる"],["岡部甚四郎吉定","熱田の大工。多宝塔を建てたといわれる"]],"deep":["2014年の時点で、この寺には1255体の円空仏が現存。全国で確認されている円空仏約5374体のうち、4分の1以上がここにある。«円空研究は荒子観音に始まり荒子観音に終わる» といわれるほど。","寺の記録『淨海雑記』によると、円空は1676年に滞在した。大きなヒノキからまず仁王像を彫り、余った材で諸像、さらに板切れで «木端仏»（こっぱぶつ）や千面菩薩をつくったという。","«円空は仁王像を水に浮かべて彫った» という説が1979年に出されたが、技術面や記録がないことから否定する研究者も多い。","多宝塔は1536年、賢俊によって再建されたとされる。室町時代後期の禅宗様の特徴を持ち、名古屋市内に残る最古の建物。","1429年銘の鰐口に «一楊御厨»（伊勢神宮の領地）の名があり、当時の寺がその中の «東郷» にあったことがわかる、数少ない中世の手がかり。","本尊の聖観音は33年に1度だけ開帳される秘仏。寺は «尾張四観音» の一つで、節分などには多くの参拝者でにぎわう。"],"look":["国の重要文化財の多宝塔（1536年）","山門の円空作・仁王像","毎月第2土曜午後に公開される円空仏","円空仏が見つかった六角堂","利家ゆかりの寺としての展示・説明板"],"q":["荒子観音に残る円空仏は、全国の円空仏のおよそ何分の1？","およそ4分の1。1200体をこえる円空仏がこの寺にあります。"],"koji":[{"w":"槍の又左","m":"槍の名手だった若き日の前田利家（通称・又左衛門）のあだ名"}],"myth":"泰澄の草創、利家の甲冑奉納は寺伝。仁王像を水に浮かべて彫った説は異論が多い。","img":["円空","前田利家","尾張四観音"],"wp":"荒子観音","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Kannon-ji_Temple_Hondou%2C_Miyamado_Arako-cho_Nakagawa_Ward_Nagoya_2022.jpg",1500,1000,"荒子観音"],["c:9/95/Enk%C5%AB.jpg",3372,5788,"円空"],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:a/a7/Shikannonmichi_01.jpg",1024,768,"尾張四観音"]]},{"id":"23_takizanji","n":"滝山寺（鎌倉期の運慶仏）","yomi":"たきさんじ","cat":"寺社","rank":"A","y":1201,"era":["heian","kamakura"],"sh":"国の重要文化財（本堂・三門・観音菩薩立像ほか）","ad":"岡崎市滝町山籠","st":"名鉄 東岡崎駅から名鉄バスで «滝山寺下» 下車","la":34.98816,"lo":137.20563,"hook":"観音さまの口の中に、人の歯が —— 源頼朝をしのんで運慶が彫った、なぞの仏像がある山寺。","lead":"滝山寺は、岡崎の山あいにある天台宗の古いお寺です。鎌倉時代、源頼朝のいとこにあたる住職が、頼朝の三回忌のために仏師・運慶と湛慶に観音像を作らせたと伝わります。本堂・三門とともに国の重要文化財で、2月の «鬼まつり» でも知られます。","story":["お寺の縁起によると、始まりは奈良時代より前。修行者・役小角が青木川で拾った金色の薬師如来をまつったといいます。山の中、川の上流の寺は、昔から山や水をあがめる信仰の場所でした。平安時代の終わりごろ、比叡山で修行した僧・永救が寺を立て直し、天台宗の寺として整えました。","やがて寺を支えたのは、熱田神宮の大宮司の一族です。1151年には大宮司の藤原範忠が本堂を建て、その子・寛伝が住職になりました。寛伝の母方のいとこが、源頼朝。そう、鎌倉幕府を開いたあの頼朝です。«いとこの寺なら力を貸そう» —— 頼朝は大きな伽藍を建てたといわれます。","1199年、頼朝が亡くなります。寛伝は頼朝の供養のため、奈良の仏師・運慶と、その子・湛慶に仏像を頼みました。観音菩薩と、それを守る梵天・帝釈天の三体です。1201年、頼朝の三回忌に完成した像の中には、頼朝のあごひげと歯が納められたと縁起は伝えます。","«本当に歯が入っているの?» —— X線で調べたところ、観音像の口のあたりに、人の歯らしいものが固定されているのが確認されました。表面は江戸時代に塗り直されていますが、力強い顔つきや体つきから、運慶一派の作と認められています。","2017年、東京国立博物館の «運慶» 展で、この観音像は初めて寺の外へ出ました。今は境内の宝物殿で三体に会えます。また、旧正月のころに行われる «鬼まつり» では、たいまつを持った鬼が本堂のまわりをかけめぐり、山寺が炎と歓声に包まれます。"],"tl":[["673〜686年ごろ","役小角が薬師如来をまつって開いたと伝わる（縁起）"],["1120年代","僧・永救が寺を再興したと伝わる"],["1151年","熱田大宮司の藤原範忠が本堂を建てる"],["1201年","頼朝の三回忌に、運慶・湛慶作とされる観音・梵天・帝釈天像が完成"],["14世紀後半","現在の本堂が建てられたと考えられる（重要文化財）"],["1646年","徳川家光の命で滝山東照宮が創建される"],["2017年","観音像が東京国立博物館の «運慶» 展で初めて寺外に出る"]],"who":[["運慶","鎌倉時代の天才仏師。観音像などを作ったとされる"],["湛慶","運慶の長男。父とともに制作にあたったと伝わる"],["寛伝","熱田大宮司家出身の住職。頼朝の母方のいとこ"],["源頼朝","鎌倉幕府を開いた人。像は頼朝の供養のため作られた"],["藤原範忠","熱田大宮司。1151年に本堂を建てた"]],"deep":["観音像は高さ174.4cm、梵天像106.5cm、帝釈天像104.9cm。梵天は顔が4つ、腕が4本の «四面四臂»。観音の両脇に梵天・帝釈天を置く形は、宮中の清涼殿にあった «二間観音» と同じ構成。","頼朝の母は熱田大宮司・藤原季範の娘。つまり熱田大宮司家は頼朝の母方の実家で、滝山寺は «頼朝の母の一族の寺» ともいえる。","寛伝は頼朝の推薦で下野の日光山満願寺の座主になったが、寺の僧たちとうまくいかず、わずか2か月ほどで三河へ戻ったと伝わる。","本堂は縁起では1222年に足利義氏が建てたとされてきたが、建物の様式から現在の本堂は14世紀後半ごろの建築と考えられている。","2022年、愛知県の文化財に指定された «伝十一面観音» の菩薩立像は、X線調査などから快慶か、その工房の作の可能性が高いとされる。運慶と快慶、両方にゆかりのある寺。","三門は寺伝では1267年の建立だが、様式から鎌倉末〜室町前期と考えられている。本堂から少し離れた集落の入口に立つ。"],"look":["宝物殿の観音菩薩・梵天・帝釈天像","檜皮葺きの本堂（重要文化財）","集落の入口に立つ三門（重要文化財）","となりの滝山東照宮","旧正月ごろの鬼まつり（開催日を確認）"],"q":["滝山寺の観音像の中に納められたと伝わるのは、だれの歯とひげ？","源頼朝。X線調査で、観音像の口のあたりに人の歯らしいものが確認されています。"],"koji":[],"myth":"役小角の開山は伝承。頼朝の歯・ひげの納入は縁起の記述（歯らしいものは確認）。","img":["運慶","源頼朝","滝山寺鬼まつり","滝山東照宮"],"wp":"滝山寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Takisan-ji_Temple_Hondou%2C_Yamagomori_Taki-cho_Okazaki_2022.jpg",1500,1000,"滝山寺"],["c:8/88/%E9%81%8B%E6%85%B6.jpg",1284,1616,"運慶"],["c:0/08/%E5%B1%B1%E6%A2%A8%E7%B8%A3%E7%94%B2%E5%BA%9C%E5%B8%82%E5%96%84%E5%85%89%E5%AF%BA%E6%BA%90%E8%B3%B4%E6%9C%9D%E6%9C%A8%E5%83%8F.jpg",1792,2560,"源頼朝"],["c:6/69/Okazaki-Takisanji-3.jpg",1600,1148,"滝山寺鬼まつり"],["c:2/20/Okazaki-Takisantoshogu-4.jpg",4032,3024,"滝山東照宮"]]},{"id":"23_koromo_jo","n":"挙母城（七州城）","yomi":"ころもじょう（しちしゅうじょう）","cat":"城","rank":"A","y":1782,"era":["edo"],"sh":"市指定史跡（挙母城〈七州城〉隅櫓跡）","ad":"豊田市小坂本町（豊田市美術館の敷地）","st":"名鉄三河線 豊田市駅から歩いて約15分","la":35.08037,"lo":137.15069,"hook":"天守に登れば七つの国が見えた —— だから «七州城»。いまは美術館の庭で、隅櫓が町を見守る。","lead":"挙母城は、江戸時代の中ごろ、1782年に挙母藩主の内藤氏が築いた城です。丘の上から三河・尾張・美濃・信濃・伊賀・伊勢・近江の7つの国が見えたことから «七州城» と呼ばれました。いまは豊田市美術館の敷地になり、石垣の上に隅櫓が復興されています。","story":["豊田市は、昔は «挙母（ころも）» という名前の町でした。江戸時代のはじめ、三宅康貞がここに入り、矢作川の近くに陣屋を構えます。桜の木を植えたことから «桜城» と呼ばれました。","ところが桜城は、あばれ川として知られる矢作川のすぐそば。江戸時代の中ごろ、新しく入った内藤氏は城の改修に取りかかりますが、川があふれるたびに工事はだめになりました。«このままでは城が守れない。高い所へ移そう»。こうして選ばれたのが、西にある小高い丘・童子山でした。","1782年、内藤学文のもとで新しい城が築かれます。丘の上に立つと、三河だけでなく、尾張・美濃・信濃・伊賀・伊勢・近江の山々まで見わたせたといいます。«7つの国が見える城» —— それが «七州城» という名の由来です。","しかし城の歴史は短く、明治の廃藩で1871年に廃城となりました。跡地には小学校や高校が建ち、長いあいだ子どもたちの学び舎になります。1959年には挙母市が «豊田市» と名前をかえ、城の名前に残る «挙母» の地名は、町の中から少しずつ見えにくくなっていきました。","いま城跡には豊田市美術館と豊田市博物館が建っています。櫓台の石垣の上には1977年に隅櫓が復興され、そのとなりには別の城から移された書院 «又日亭» が建ちます。現代アートを見に来た人が、ふと振り返ると江戸時代の櫓がある —— 新旧が同居する不思議な城跡です。"],"tl":[["1604年","三宅康貞が挙母に入り、陣屋（桜城）を構える"],["1749年","内藤氏が城の改修に取りかかるが、矢作川の洪水に悩まされる"],["1782年","童子山に新しい挙母城（七州城）が築かれる"],["1871年","廃藩により廃城"],["1959年","挙母市が豊田市に名前を変える"],["1972年","隅櫓跡が豊田市指定史跡になる"],["1977年","隅櫓が復興され、又日亭が移築される"],["2024年","城跡に豊田市博物館が開館"]],"who":[["内藤学文","挙母藩主。七州城を築いた"],["三宅康貞","江戸時代のはじめに挙母に入り、桜城を構えた大名"],["内藤氏","挙母藩2万石の藩主家。明治まで続いた"]],"deep":["«七州» の7か国は、三河・尾張・美濃・信濃・伊賀・伊勢・近江。ただし実際にすべての国の山が見えたかは確かめようがなく、城の見晴らしのよさを表す呼び名と考えるのがよい。","城の前身として、鎌倉時代の1309年に中條景長が築いたとされる金谷城があった。桜城は金谷城の北約1kmに構えられた陣屋で、七州城はそこからさらに丘へ移った «3代目» にあたる。","現存する遺構は美術館敷地内の櫓台の石垣。隅櫓は1977年の復興で、もとの櫓の姿を正確に再現したものではないとされる。","隣の書院 «又日亭» は、もとは寺部城の城内にあった書院。明治に寺へ移され、解体されかけたところを1977年に豊田市が移築した。","挙母祭りの山車蔵に、城の建物をこわした材木が使われている。城の «かけら» が町のお祭りの中で生きている例。","«挙母»の読みは «ころも»。衣（ころも）とも書かれ、古くからの地名とされる。自動車の町・豊田市になったのは1959年から。"],"look":["櫓台の石垣と復興隅櫓","書院 «又日亭»","豊田市美術館からの眺め（丘の高さを体感）","豊田市博物館の展示"],"q":["七州城という名前の «七州» とは何のこと？","城から見えたという7つの国のこと。三河・尾張・美濃・信濃・伊賀・伊勢・近江です。"],"koji":[],"myth":"7か国すべてが見えたかは伝承的。","img":["挙母藩","豊田市美術館","桜城"],"wp":"挙母城","rel":{"ev":[],"grave":[]},"ph":[["c:4/44/Koromo-jo_Castle_Sumi-Yagura%2C_Kozakahonmachi_Toyota_2012.jpg",1600,1200,"挙母城"],["c:4/44/Toyota_museum_101.JPG",768,1024,"挙母藩"],["c:0/0c/Toyota_Municipal_Museum_of_Art%2C_Kozakahon-machi_Toyota_2012.JPG",1500,1000,"豊田市美術館"],["c:b/ba/Toyota_sakura_castle_01.jpg",3648,2736,"桜城"]]},{"id":"23_futaba_kan","n":"文化のみち二葉館（川上貞奴邸）","yomi":"ぶんかのみちふたばかん","cat":"近代","rank":"A","y":1920,"era":["taisho","showa"],"sh":"国の登録有形文化財","ad":"名古屋市東区橦木町3丁目","st":"地下鉄桜通線 高岳駅から歩いて約10分／市バス «飯田町» から約2分","la":35.18039,"lo":136.91867,"hook":"«日本の女優第1号» と «電力王»。大正の名古屋に建った «二葉御殿» は、ステンドグラスの光でいっぱいだった。","lead":"二葉館は、女優・川上貞奴と実業家・福沢桃介が1920年から1926年まで暮らした家を、移築・復元した建物です。和風と洋風がまざったハイカラな建物で、当時は «二葉御殿» と呼ばれました。今は貞奴の資料や、名古屋ゆかりの文学者を紹介する館になっています。","story":["川上貞奴は、東京の芸者から身を起こし、夫・川上音二郎の一座とともに海をわたりました。アメリカやヨーロッパで舞台に立ち、1900年のパリ万博のころには «マダム・サダヤッコ» として大評判に。日本人女優のさきがけとなった人です。","福沢桃介は、福沢諭吉の娘婿で、木曽川に次々と発電所を建てた «電力王»。二人は若いころに出会っていたといわれ、«野犬に追われた貞奴を、学生だった桃介が助けた» という話も伝わります。音二郎が亡くなったあと、貞奴は女優を引退し、桃介の事業を支えるパートナーになりました。","1920年、桃介は住宅会社 «あめりか屋» に頼んで、名古屋の東二葉町に大きな家を建てます。赤い瓦屋根に、洋風の大広間、そして色とりどりのステンドグラス。政財界の人たちが集まる «社交の場» にもなりました。«なぜ名古屋に?» —— 木曽川の電源開発の拠点が、この町だったからです。","ぜいたくな御殿の暮らしは6年ほど。桃介が引退して東京へ移ると、貞奴も名古屋を離れます。1937年、土地と建物は二つに分けて売られ、東半分はこわされました。残った西半分は会社の寮として使われ、名前を知る人も少なくなっていきました。","2000年、持ち主の会社から寄付を受けた名古屋市が、今の場所へ建物を移して復元します。2005年に «文化のみち二葉館» として開館し、翌日には国の登録有形文化財に。大広間に差しこむステンドグラスの光は、100年前の名古屋のモダンな空気を今に伝えています。"],"tl":[["1871年","川上貞奴が生まれる"],["1900年ごろ","貞奴が川上一座として欧米で公演し、評判になる"],["1920年","福沢桃介と貞奴の邸宅が東二葉町に完成"],["1926年","二人が名古屋を離れる"],["1937年","敷地と建物が分割して売られる"],["2000年","名古屋市が寄付を受け、現在地へ移築復元に着手"],["2005年","文化のみち二葉館が開館。国の登録有形文化財に"]],"who":[["川上貞奴","日本の女優の草分け。この家の女主人"],["福沢桃介","«電力王» と呼ばれた実業家。邸宅を建てた"],["川上音二郎","貞奴の夫。«オッペケペー節» で知られる興行師・俳優"],["城山三郎","名古屋出身の作家。館内に書斎が復元されている"]],"deep":["設計・施工は住宅専門会社 «あめりか屋»。大正期に洋風住宅を広めた会社で、和洋折衷の間取りに当時の «文化住宅» ブームがよく表れている。","もとの場所は東区東二葉町（現在の白壁三丁目）。«二葉御殿» の名もこの地名から。移築にあたって、失われた部分は古写真や資料をもとに復元された。","1937年に分割されたあと、西半分は大同製鋼の役員に売られ、のちに «大同特殊鋼二葉荘» として使われた。","館の2階は、坪内逍遙や城山三郎など郷土ゆかりの文学者を紹介する資料室。城山三郎が『男子の本懐』を書いたころの書斎が復元されている。","二葉館がある «文化のみち» は、名古屋城から徳川園にかけての明治・大正の建物が残る地域。近くの橦木館や市政資料館と合わせて歩ける。","貞奴はのちに、岐阜県各務原市に貞照寺を建てた。二葉館と合わせて、女優引退後の彼女の足あとがたどれる。"],"look":["大広間のステンドグラス","和洋折衷の室内","貞奴の愛用品や舞台資料の展示","2階の城山三郎書斎の再現","赤い瓦屋根の外観"],"q":["川上貞奴と暮らした «電力王» はだれ？","福沢桃介。福沢諭吉の娘婿で、木曽川に多くの発電所をつくりました。"],"koji":[],"myth":"野犬から桃介が貞奴を助けた話は伝承。","img":["川上貞奴","福沢桃介","川上音二郎"],"wp":"文化のみち二葉館","rel":{"ev":[],"grave":[]},"ph":[["c:d/de/Futaba_Museum_ac_%281%29.jpg",5856,3894,"文化のみち二葉館"],["c:2/22/Sadayakko_Kawakami.jpg",229,294,"川上貞奴"],["c:4/49/Fukuzawa_Momosuke_45-year-old.jpg",1050,1400,"福沢桃介"],["c:8/8c/Kawakami_Otojiro.jpg",463,647,"川上音二郎"]]},{"id":"23_shisei_shiryokan","n":"名古屋市市政資料館（旧名古屋控訴院）","yomi":"なごやししせいしりょうかん","cat":"近代","rank":"A","y":1922,"era":["taisho","showa"],"sh":"国の重要文化財","ad":"名古屋市東区白壁1丁目","st":"名鉄瀬戸線 東大手駅から歩いて約5分／地下鉄名城線 名古屋城駅から約8分","la":35.18121,"lo":136.91026,"hook":"赤レンガに白い石の帯。ステンドグラスには «天秤»。ここはかつて、人の運命が決まる裁判所だった。","lead":"名古屋市市政資料館は、1922年に建てられた裁判所の建物を使った資料館です。中部地方の裁判の «二審» をあつかう名古屋控訴院などが入っていました。国の重要文化財で、ステンドグラスの階段室、昔の法廷や留置場を無料で見学できます。","story":["大正時代、日本には全国に8つの «控訴院» がありました。地方の裁判所の判決に納得できないとき、もう一度審理をする上級の裁判所です。名古屋控訴院の庁舎は1922年、名古屋城の東に完成しました。赤いレンガの壁に白い花崗岩の帯をめぐらせた、堂々とした3階建てです。","正面から入ると、目の前に中央階段が広がります。大理石の手すり、マーブル模様に塗られた柱、そして天井と窓のステンドグラス。よく見ると、ガラスの模様には «天秤» が描かれています。«なぜ天秤?» —— 天秤は、公平な裁きのしるしだからです。","建物の中庭側のレンガには、当時の名古屋監獄の囚人たちが焼いたものが残っています。深い赤色は、ベンガラという顔料の色。裁判所を建てたレンガを、罪をつぐなう人びとが焼いた —— そう思うと、壁の見え方も少し変わってきます。","戦後、控訴院は名古屋高等裁判所となり、裁判所が新しい庁舎へ移ったあと、この建物は名古屋市に受け継がれました。1984年、外観や中央階段室などが国の重要文化財に指定され、1989年、名古屋市の公文書を保存する «市政資料館» として生まれ変わりました。","館内には、明治憲法の時代の法廷や、陪審制度の時代の法廷が再現され、実際に中に入れる留置場もあります。名古屋城の金鯱のうろこが盗まれた事件の証拠品も展示。2024年にはテレビドラマ『虎に翼』のロケ地にもなり、話題を集めました。"],"tl":[["1922年","名古屋控訴院・地方裁判所・区裁判所の庁舎が完成"],["1928年","陪審制度が始まる（1943年に停止）。館内に陪審法廷が再現されている"],["1947年","控訴院が名古屋高等裁判所に"],["1984年","外観・中央階段室・会議室が国の重要文化財に"],["1989年","名古屋市市政資料館として開館"],["2024年","連続テレビ小説『虎に翼』のロケ地に"]],"who":[["金刺森太郎","司法技師。設計監督の工事主任をつとめた"],["司法省営繕課","庁舎の設計を担当した役所の部署"],["名古屋監獄の人びと","中庭のレンガを焼いたとされる"]],"deep":["全国8か所に建てられた控訴院の建物のうち、現存するのは名古屋と札幌だけ。名古屋は現存最古の控訴院庁舎で、レンガ造の大規模な近代建築としても最末期の例。","重要文化財の指定対象は、外観・中央階段室・3階の復原会議室。それ以外の内装は指定外だが、当時のようすに近づけて整備されている。","中央階段室の様式は «ネオ・バロック» が基調。ステンドグラスは建てたときのもので、復元整備されている。","窓ガラスには、今は作られていないゆがんだガラスや模様ガラスが多く残り、«ガラスの博物館» とも呼ばれる。","陪審制度は1928年から1943年まで行われた。国民が裁判に参加する仕組みの先輩で、館内には裁判員制度までの流れがわかる展示がある。","本来の役割は公文書館。1889年の市制施行以後の公文書や行政資料を保存し、だれでも閲覧できる（多くは閉架）。"],"look":["中央階段室のステンドグラス（天秤の模様）","3階の復原会議室","再現された明治憲法下の法廷・陪審法廷","入ることのできる留置場","中庭の囚人が焼いたレンガ"],"q":["中央階段室のステンドグラスに描かれた «天秤» は何を表している？","公平な裁判のしるし。ここがもと裁判所だったことを物語っています。"],"koji":[],"myth":"","img":["控訴院","陪審制","虎に翼"],"wp":"名古屋市市政資料館","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Nagoya_City_Archives_%282%29%2C_Shirakabe_Higashi_Ward_Nagoya_2022.jpg",1500,1000,"名古屋市市政資料館"],["c:b/b7/The_Jury_by_John_Morgan.jpg",787,446,"陪審制"],["c:f/fe/Mibuchi_Yoshiko_circa_1938.jpg",1395,2048,"虎に翼"]]},{"id":"23_ejanaika","n":"牟呂八幡宮（ええじゃないか発祥の地）","yomi":"むろはちまんぐう","cat":"幕末","rank":"A","y":1867,"era":["edo"],"sh":"","ad":"豊橋市牟呂町郷社","st":"豊鉄バス «東脇口» から歩いて約5分","la":34.75619,"lo":137.36594,"hook":"«ええじゃないか、ええじゃないか»。幕府がたおれる直前、日本中を踊りの渦にまきこんだ大騒ぎは、この神社から始まったのかもしれない。","lead":"牟呂八幡宮は、豊橋市にある古い八幡さまです。1867年、空からお札が降ったといって人びとが «ええじゃないか» と歌い踊った騒ぎは、この神社のあたりが発祥だという説があります。神主の家に残されたメモが、その手がかりになりました。","story":["1867年の夏から冬にかけて、不思議なうわさが広がりました。«空から神さまのお札が降ってきた!» お札が降った家では、酒やごちそうを用意してお祝い。町の人たちは派手な着物で仮装し、«ええじゃないか、ええじゃないか» と歌いながら、夜も昼も踊りつづけました。","この年は、江戸幕府が政権を朝廷に返した «大政奉還» の年です。世の中がひっくり返りそうな不安と期待。«なぜ人びとは踊ったのか?» —— 世直しを願う民衆の気持ちの爆発だったという見方がある一方、倒幕派が世の中を混乱させるために仕組んだのでは、といううわさも当時からありました。答えは、今もはっきりしていません。","では、騒ぎはどこで始まったのでしょう。昔は京都・大坂が始まりと考えられていましたが、研究が進むと、東海地方のほうが早かったという説が出てきます。そこで注目されたのが、牟呂八幡宮の神主・森田光尋が書き残した «留記»（とめき）というメモでした。","そこには、慶応3年7月14日の日付で «御祓い» と記されていました。これが、降ってきたお札のことではないか —— 研究者の田村貞雄は1987年、牟呂村が «ええじゃないか» の最初の場所だと唱えます。京都の記録より1か月以上も早い日付でした。ほかにも、豊川市の御油宿や磐田市の見附宿などを発祥とする説があり、«発祥の地» 争いが続いています。","牟呂八幡宮そのものは、697年の創建と伝わる古い神社です。鎌倉時代には鎌倉の鶴岡八幡宮にならって境内を整えたといわれます。1945年の空襲で社殿が被害を受けましたが、戦後に再建されました。静かな境内で、150年以上前の熱狂を想像してみてください。"],"tl":[["697年","牟呂八幡宮が創建されたと伝わる"],["1222年","鎌倉の鶴岡八幡宮にならって境内を整えたと伝わる"],["1867年7月14日（旧暦）","神主・森田光尋のメモに «御祓い» の記録"],["1867年8〜12月","近畿・東海・四国などで «ええじゃないか» が広がる"],["1867年10月","大政奉還"],["1867年12月9日（旧暦）","王政復古の大号令。このころ騒ぎがおさまったとされる"],["1945年","空襲で社殿が被災（1949年に再建）"],["1987年","田村貞雄が牟呂発祥説を唱える"]],"who":[["森田光尋","幕末の牟呂八幡宮の神主。メモ «留記» を残した"],["田村貞雄","歴史学者。『ええじゃないか始まる』で牟呂発祥説を示した"],["岩倉具視","公家。『岩倉公実記』に京都の «ええじゃないか» の記録がある"],["福地源一郎","幕臣・ジャーナリスト。大坂で騒ぎを目撃し記録した"]],"deep":["『岩倉公実記』には、京都で «ヨイジャナイカ、エイジャナイカ» と叫んだとあり、8月下旬に始まって12月9日の王政復古の大号令の日にやんだと書かれている。","発祥をめぐる研究は、尾張説（1968年）、遠江見附説（1973年）、三河御油説（1973年）、三河吉田の羽田八幡宮説（1979年）、牟呂八幡宮説（1987年）と、新しい研究ほど日付が早くなっている。","じつは «お札降り» と «ええじゃないか» と «お蔭参り» は、もともと別の現象。東海地方ではお札降りの記録は多いが、«ええじゃないか» のかけ声は近畿・四国ほどはっきりしない、という指摘もある。","名古屋では、お札が降ったあとの祭りが7日間も続き、その間は町の暮らしが止まってしまったといわれる。","歌詞は土地ごとにちがい、«日本国の世直りはええじゃないか»（阿波）など世直しを願うもの、«長州がのぼた、物が安うなる»（西宮）など政治を歌ったものまであった。","神社の神事相撲は力くらべではなく、勝負で田畑の豊作・不作を占う神聖な行事として続いてきた。"],"look":["拝殿と静かな境内","ええじゃないか発祥にまつわる案内（碑・説明板）","境内の稲荷神社・牟呂御霊社などの末社","4月の例祭の神事相撲（開催時）"],"q":["«ええじゃないか» が起こった1867年、幕府が政権を朝廷に返したできごとを何という？","大政奉還。騒ぎは、この世の中の大きな変わり目と重なっていました。"],"koji":[{"w":"世直し","m":"世の中の悪いところを正して、よい世の中にすること。«ええじゃないか» の歌詞にもこの願いが込められた"}],"myth":"発祥地は諸説（京都・尾張・御油・見附・羽田・牟呂など）。倒幕派の仕掛け説もうわさの域。","img":["大政奉還","お蔭参り"],"wp":"ええじゃないか","rel":{"ev":[],"grave":[]},"ph":[["c:3/37/EeJaNaiKaScene.jpg",1300,929,"ええじゃないか"],["c:4/4e/Nijo_Castle.jpg",3888,1732,"大政奉還"],["c:8/8a/Ando_hiroshige_miyakawanowatashi.jpg",2400,1233,"お蔭参り"]]},{"id":"23_tobigasuyama","n":"鳶ヶ巣山砦跡（長篠の別動隊奇襲）","yomi":"とびがすやまとりであと","cat":"古戦場","rank":"B","y":1575,"era":["azuchi"],"sh":"","ad":"新城市乗本","st":"JR飯田線 長篠城駅から、豊川をはさんだ南の山。登り口まで車が便利（徒歩なら30分以上の目安）","la":34.917,"lo":137.562,"hook":"長篠の戦いは、夜明けの山の上から始まっていた。武田の砦を背後から襲った、4千の別動隊。","lead":"鳶ヶ巣山砦は、1575年の長篠の戦いで、武田勝頼の軍勢が長篠城を見張るために築いた砦です。決戦の日の夜明け、徳川家の重臣・酒井忠次が率いる別動隊が山伝いに背後から襲いかかり、砦を次々に落としました。今は戦いで亡くなった人びとの墓が静かに立っています。","story":["1575年5月、武田勝頼の大軍が長篠城を取り囲みました。城の南、川をはさんだ山の上に築かれたのが鳶ヶ巣山砦です。本砦のまわりには中山・久間山・姥ヶ懐・君ヶ伏床の4つの小さな砦があり、長篠城の動きを見張っていました。守る大将は、勝頼の叔父・河窪信実です。","5月20日の夜、設楽原に陣を構えた織田・徳川の軍議で、家康の重臣・酒井忠次が進み出ました。«鳶ヶ巣山の砦を後ろから襲えば、長篠城を救えます»。ところが信長は、«そのような小細工は用いるにあらず» と大声でしかりつけた、と伝わります。","軍議が終わると、信長はこっそり忠次を呼びました。«さっきはわざと叱った。敵に作戦がもれるのを恐れたのだ。お前の策こそ最善だ»。『常山紀談』に残るこの逸話が本当かどうかはわかりませんが、実際に忠次は、弓や鉄砲の得意な兵に信長の鉄砲隊500を加えた約4千の別動隊を率いて、その夜のうちに出発しました。","別動隊は武田軍の目を避けて川を渡り、暗い山道を尾根伝いに進みます。そして5月21日の夜明け、鳶ヶ巣山砦に背後から襲いかかりました。不意をつかれた武田方は総くずれ。河窪信実をはじめ、三枝昌貞、和田業繁らが討ち死にし、5つの砦はすべて落ちました。長篠城は、ついに救われたのです。","けれど、勝った側にも犠牲がありました。深追いした徳川方の松平伊忠は、武田方の反撃にあって命を落とします。退路をおびやかされた武田の本隊は、この日、設楽原で決戦にのぞむことになりました。今、山の上には «長篠之役鳶ヶ巣陣戦歿将士之墓» が立ち、敵味方の区別なく、戦いで倒れた人びとをしのんでいます。"],"tl":[["1575年5月","武田勝頼が長篠城を包囲し、鳶ヶ巣山などに砦を築く"],["1575年5月18日","織田・徳川連合軍が設楽原に着陣"],["1575年5月20日夜","酒井忠次の別動隊約4千が出発"],["1575年5月21日夜明け","鳶ヶ巣山砦など5砦を攻め落とし、長篠城を救う"],["1575年5月21日","設楽原の決戦で武田軍が大敗"]],"who":[["酒井忠次","家康の重臣。奇襲を発案し、別動隊を率いた"],["河窪信実","勝頼の叔父。鳶ヶ巣山砦の大将で、討ち死にした"],["金森長近","信長の家臣。検使として別動隊に加わった"],["松平伊忠","深溝松平家の当主。深追いして討ち死に。『家忠日記』を残した家忠の父"],["三枝昌貞","武田方の武将。姥ヶ懐砦を守り、討ち死にした"]],"deep":["『信長公記』によると別動隊は、徳川軍から選んだ弓・鉄砲の兵約2千に、信長の鉄砲隊500、金森長近らの検使を加えた約4千。武田方の守備兵は約3千とされる。","砦の構成は、本砦の鳶ヶ巣山のほか、中山・久間山・姥ヶ懐・君ヶ伏床の4つの支砦。«君ヶ伏床（きみがふしど）» など、風流な名前が多い。","信長が軍議で忠次を叱り、あとでほめたという話は、江戸時代の逸話集『常山紀談』に出てくるもの。徳川方の発案だったこと自体は、徳川側の遠江攻略の思惑と合わせて論じられる。","逃げる武田兵を追った酒井隊は、長篠城の西岸・有海村でも、春日虎綱（高坂昌信）の子とされる香坂源五郎を討ち取ったと伝わる。","戦死した松平伊忠の子・家忠は、のちに当時の暮らしや戦いを記した『家忠日記』を書いた。戦国時代を知る一級の史料の書き手が、この戦いで父を失っている。","この奇襲で退路と後方をおびやかされたことが、勝頼が設楽原で正面決戦にふみきった理由の一つとする見方がある。"],"look":["«長篠之役鳶ヶ巣陣戦歿将士之墓»","山の上から見下ろす長篠城跡と川の合流点","長篠城址史跡保存館（あわせて見学すると位置関係がわかる）"],"q":["鳶ヶ巣山砦を奇襲した別動隊を率いた徳川家の重臣はだれ？","酒井忠次。約4千の兵で夜明けに砦を背後から襲いました。"],"koji":[],"myth":"信長が忠次を叱ってからほめた話は『常山紀談』の逸話。兵数は諸説。","img":["酒井忠次","長篠城"],"wp":"長篠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/Sakai_Tadatsugu.jpg",710,595,"酒井忠次"],["c:d/d5/%E5%8F%B2%E8%B7%A1_%E9%95%B7%E7%AF%A0%E5%9F%8E%E5%9D%80.jpg",4032,3024,"長篠城"]]},{"id":"23_chausuyama","n":"茶臼山（設楽原の信長本陣）","yomi":"ちゃうすやま","cat":"古戦場","rank":"B","y":1575,"era":["azuchi"],"sh":"","ad":"新城市（茶臼山・新東名 長篠設楽原PA下り線のとなり）","st":"JR飯田線 茶臼山駅から歩いて約20〜25分（目安）。新東名 長篠設楽原PA（下り）から歩いて行ける","la":34.923,"lo":137.51,"hook":"丘の上から、信長は連吾川の向こうの武田軍を見すえていた。«鉄砲の戦い» の司令塔は、ここにあった。","lead":"茶臼山は、1575年の長篠・設楽原の戦いで、織田信長が本陣を置いたと伝わる丘です。信長はこの一帯に兵を隠すように並べ、連吾川ぞいに馬防柵を築いて、武田勝頼の軍勢を待ちかまえました。今は本陣跡の碑があり、戦場を見わたすことができます。","story":["1575年5月18日、長篠城を救うために、信長の約3万と家康の約8千が設楽原に着きました。設楽原は «原» といっても平らな野原ではなく、小さな川と丘がいくつも南北に並ぶ土地です。信長はこの地形を利用して、兵を敵から見えにくいように、とぎれとぎれに配置しました。","丘のふもとを流れる連吾川を堀に見立て、その手前には «馬防柵» が作られました。家康は家臣に «柵をよく念を入れて作れ。敵は馬で一筋に突っこんでくるぞ» という手紙を送ったといわれます。柵の後ろには、数多くの鉄砲隊が待ちかまえていました。","武田方の陣では、軍議が開かれていました。信玄の時代からの重臣たちは退くことをすすめたといわれますが、勝頼は決戦を選びます。«なぜ勝頼は戦ったのか?» —— 前の年の高天神城での勝利で自信があった、という説、後ろの鳶ヶ巣山が落とされて退けなくなった、という説など、答えは一つではありません。","5月21日の朝、武田軍は柵に向かって次々に攻めかかりました。戦いは昼過ぎまで、およそ8時間続いたといいます。山県昌景、馬場信春、内藤昌秀、真田信綱・昌輝の兄弟など、武田家を支えてきた名将たちが次々に倒れました。武田軍の犠牲は、鳶ヶ巣山もふくめて1万人をこえたとも伝わります。","戦いのあと、地元の人びとは亡くなった人たちを手あつく葬り、今もたいまつを振って霊をなぐさめる «火おんどり» という行事を伝えています。茶臼山の上に立ち、東の連吾川と、その向こうの武田方の陣地をながめてみてください。わずか数百mの距離に、何万もの兵が向かい合っていたのです。"],"tl":[["1575年5月","武田勝頼が長篠城を包囲"],["1575年5月18日","信長・家康が設楽原に着陣し、陣地を築く"],["1575年5月21日早朝","鳶ヶ巣山砦が落ちる。設楽原で決戦が始まる"],["1575年5月21日昼すぎ","武田軍が大敗し退却"],["1996年","近くに新城市設楽原歴史資料館が開館"],["2016年","新東名の長篠設楽原PAが開業。下り線から本陣跡へ歩けるように"]],"who":[["織田信長","連合軍の総大将。この一帯に本陣を置いたと伝わる"],["徳川家康","連合軍の一方の大将。長篠城の救援を信長に求めた"],["武田勝頼","武田家の当主。決戦を選び、大敗した"],["山県昌景","武田の重臣。この戦いで討ち死にした"],["馬場信春","武田の重臣。退く勝頼を守って討ち死にしたと伝わる"]],"deep":["『信長公記』には、信長が «極楽寺山» に陣を置いたとある。茶臼山を信長の本陣とするのは地元の伝承で、陣の位置が戦いの中で変わったかどうかも含め、細かい点は諸説ある。","有名な «鉄砲3千丁» は、甫庵本『信長記』などが出典。太田牛一の『信長公記』では «千挺計»（約1千丁）と別動隊の500丁で、3千丁とは書かれていない。","«三段撃ち» は『信長公記』に記述がなく、江戸時代の通俗的な書物に初めて現れ、明治の教科書が史実のように広めたとされる。今は実在を疑う研究者が多い。","設楽原の «柵» は、ただの柵ではなく、川をはさむ斜面を削った急な崖や土塁と組み合わせた «野戦陣地» だったとする見方もある。","兵力は通説で連合軍3万8千・武田1万5千だが、研究者によって数字は大きくちがう。いずれにせよ連合軍が大きく上回っていた。","新城市設楽原歴史資料館は、火縄銃・古式銃の収蔵で質・量ともに日本一級とされる。本陣跡とあわせて訪れると、戦いのイメージがつかみやすい。"],"look":["信長本陣跡の碑と丘の上からの眺め","連吾川の流れ（両軍をへだてた小川）","再現された馬防柵（竹広地区）","新城市設楽原歴史資料館","長篠設楽原PA（下り）の物見櫓"],"q":["『信長公記』に書かれている、決戦で使われた鉄砲の数は？","«千挺計»（約1千丁）。有名な «3千丁» は別の書物によるものです。"],"koji":[],"myth":"茶臼山が信長本陣という点は伝承（『信長公記』は «極楽寺山»）。鉄砲の数・三段撃ち・兵力は諸説。","img":["設楽原歴史資料館","武田勝頼","織田信長"],"wp":"長篠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:a/af/%E6%96%B0%E5%9F%8E%E5%B8%82%E8%A8%AD%E6%A5%BD%E5%8E%9F%E6%AD%B4%E5%8F%B2%E8%B3%87%E6%96%99%E9%A4%A8.JPG",4608,3456,"設楽原歴史資料館"],["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"],["c:5/5a/Oda_Nobunaga_Kaou_3.jpg",249,164,"織田信長"]]},{"id":"23_zenshoji_toride","n":"善照寺砦跡（信長が軍勢を整えた砦）","yomi":"ぜんしょうじとりであと","cat":"古戦場","rank":"B","y":1560,"era":["muromachi"],"sh":"","ad":"名古屋市緑区鳴海町砦","st":"名鉄名古屋本線 鳴海駅から歩いて約10分（坂道）","la":35.08158,"lo":136.9575,"hook":"桶狭間の日、信長はこの丘から戦場を見下ろし、«勝負どころ» を探していた。","lead":"善照寺砦は、1559年に織田信長が、今川方になった鳴海城を囲むために築いた砦の一つです。1560年の桶狭間の戦いの日、信長はここに入り、軍勢を集めて次の一手を考えました。今は «砦公園» となり、高台から鳴海の町が見わたせます。","story":["1550年代、尾張と三河の境目では、織田と今川がにらみ合っていました。信長の父・信秀が亡くなると、鳴海城主の山口教継は今川義元に寝返り、鳴海城と大高城は今川の城になってしまいます。«尾張の中に、今川のくさびが打ちこまれた» のです。","信長は負けていません。鳴海城のまわりに丹下砦・善照寺砦・中島砦の3つの砦を築いて包囲し、さらに大高城との連絡を断つため丸根砦・鷲津砦を築きました。善照寺砦は、鳴海城の東にのびる丘の東の端、古い寺の跡を利用したもので、佐久間信盛・信辰の兄弟が守りました。","1560年5月19日、夜明け前に清洲城を飛び出した信長は、熱田神宮で祈ったあと、丹下砦をへて善照寺砦に入ります。そのころ、南の丸根・鷲津の砦からは煙が上がっていました。«砦が落ちた» —— 知らせが届く中、信長はここで遅れてくる兵を待ち、軍勢を整えたと考えられています。","«このまま守るのか、打って出るのか»。家来たちが見守る中、信長は前へ進むことを選び、さらに南の低地にある中島砦へ向かいました。そして昼過ぎ、桶狭間で今川義元の本隊に襲いかかります。善照寺砦は、その «決断の場» の一つだったのです。","今の砦公園には、はっきりとした堀や土塁は見えません。けれど、坂を上って高台に立つと、ここが戦場を見わたすのにちょうどよい場所だったことが体でわかります。公園には案内板があり、住宅地の中で静かに歴史を伝えています。"],"tl":[["1559年","山口教継親子が切腹し、鳴海城・大高城が今川直轄に。信長が周囲に砦を築く"],["1560年5月19日未明","信長が清洲城を出陣。熱田神宮で祈る"],["1560年5月19日朝","丸根砦・鷲津砦が今川軍の攻撃で落ちる"],["1560年5月19日","信長が丹下砦をへて善照寺砦に入り、軍勢を集める"],["1560年5月19日昼すぎ","桶狭間で今川義元が討たれる"]],"who":[["織田信長","砦を築き、桶狭間の日にここへ入った"],["佐久間信盛","善照寺砦の守将。のちに織田家の重臣となる"],["佐久間信辰","信盛の弟。ともに砦を守った"],["山口教継","鳴海城主。今川方に寝返り、砦づくりのきっかけとなった"],["今川義元","駿河・遠江・三河の大名。桶狭間で討たれた"]],"deep":["砦は一辺約50mの堀と土塁をめぐらせた «館（やかた）型» と考えられている。西の尾根続きに出入口があり、その南側の土塁は櫓台のようになっていたとされる。","鳴海城包囲の3砦（丹下・善照寺・中島）と、大高城を切りはなす2砦（丸根・鷲津）。«付城（つけじろ）» で敵の城を囲むのは、のちの信長・秀吉が得意とした戦い方の早い例。","砦を築いたのは、孤立した前線に敵を引き寄せる狙いもあったという見方がある。実際、義元はこれらの砦を落とすために大軍で尾張に入った。","名前の «善照寺» は、この場所にあった寺の名にちなむ。寺はその後移ったとされ、地名 «砦» が今も町名に残っている。","『信長公記』によれば、信長は善照寺砦に入ったのち中島砦へ移っており、ここは出陣の «集合地点» の役割を果たしたと考えられる。"],"look":["砦公園の高台からの眺め","砦の説明板","鳴海城跡・中島砦跡をあわせて歩くと位置関係がよくわかる"],"q":["信長が鳴海城を囲むために築いた3つの砦は？","丹下砦・善照寺砦・中島砦です。"],"koji":[],"myth":"砦の構造は絵図などからの推定で、遺構は直接確認されていない。","img":["桶狭間の戦い","鳴海城","佐久間信盛"],"wp":"善照寺砦","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Zenshouji1.JPG",4608,3456,"善照寺砦"],["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"],["c:f/f7/Tenjin-sha_Shrine_Keidai_%281%29%2C_Shiro_Narumi-cho_Midori_Ward_Nagoya_2020.jpg",1500,1000,"鳴海城"],["c:e/e1/Sakuma_Nobumori.jpg",536,676,"佐久間信盛"]]},{"id":"23_nakajima_toride","n":"中島砦跡（桶狭間への前線）","yomi":"なかじまとりであと","cat":"古戦場","rank":"B","y":1560,"era":["muromachi"],"sh":"","ad":"名古屋市緑区鳴海町下中","st":"名鉄名古屋本線 鳴海駅から南東へ歩いて約5分","la":35.07694,"lo":136.95397,"hook":"«ここから先は、敵から丸見えです!»——止める家老をふり切って、信長は最前線の砦へ馬を進めた。","lead":"中島砦は、1559年に織田信長が鳴海城を囲むために築いた砦の一つで、扇川と手越川が合流する低い土地にありました。桶狭間の戦いの日、信長はここから今川義元の本隊へ向けて出撃したといわれます。今は住宅地の中に «中島城址» の石碑が立つだけです。","story":["鳴海の町の南、2本の川が合わさる場所に、中島砦はありました。まわりは深い田んぼ。高い丘の上の砦とちがい、川にはさまれた低地の砦で、守将は梶川高秀でした。今川方の鳴海城と大高城のあいだににらみをきかせる、最前線の砦です。","1560年5月19日。善照寺砦に入った信長は、さらに中島砦へ移ろうとします。家老たちはあわてて止めました。«中島へ向かう道は両側が深田で、一騎ずつしか通れません。しかも敵から丸見えです!» それでも信長は聞き入れず、馬を進めたと『信長公記』は伝えます。","中島砦に着いたとき、信長のもとにいた兵は2千にも満たなかったといいます。家老たちはもう一度止めますが、信長はこう考えました。«敵は朝から砦を攻めて、疲れている。こちらは新手だ»。そして «小軍ニシテ大敵ヲ怖ルルコト莫カレ»（少ない軍でも大敵をおそれるな）と兵をはげましたと伝わります。","信長の軍勢はここから出撃し、やがて降り出した激しい雨にまぎれて、義元の本隊に迫りました。昼過ぎ、義元は討たれ、今川軍は尾張から引き上げます。中島砦は、その役目をわずか1年ほどで終えました。«なぜ信長は、危険な低地の砦へ進んだのか?» —— 敵の様子を近くで見きわめ、一気に攻めかかるためだったと考えられています。","今、砦の跡は住宅地になり、個人のお宅の庭に、1927年に鳴海町が建てた «中島城址» の石碑が残っています。見学は道路からそっと。すぐ近くを流れる扇川と手越川の合流点に立つと、この場所が «川と田んぼに囲まれた砦» だったことが想像できます。"],"tl":[["1559年","信長が鳴海城包囲のため中島砦を築く。守将は梶川高秀"],["1560年5月19日","信長が善照寺砦から中島砦へ移る"],["1560年5月19日昼","中島砦から出撃し、桶狭間で今川義元を討つ"],["1560年","今川軍が撤退し、砦は役目を終える"],["1927年","鳴海町が «中島城址» の碑を建てる"]],"who":[["織田信長","家老の反対を押し切ってこの砦に入り、出撃した"],["梶川高秀","中島砦の守将"],["今川義元","桶狭間で討たれた駿河の大名"],["太田牛一","『信長公記』の著者。この日の信長の行動を書き残した"]],"deep":["『信長公記』は、中島砦への道を «脇は深田の足入れ、一騎打ちの道» と描く。田に足を取られる細い道を進むのは、敵から見れば格好の的だった。","信長が中島砦に入ったとき «二千に足らざる» 兵だったと『信長公記』は記す。今川軍は2万5千とも4万ともいわれるが、正確な数はわからない。","信長の激励の言葉は『信長公記』に記されたもので、«運は天にあり» の言葉も添えられている。実際にどこまでその通りに言ったかはわからない。","この日、信長の軍がどの道を通って義元に迫ったかは、«正面から攻めた» 説と «迂回して奇襲した» 説があり、今も論争が続く。中島砦はどちらの説でも出撃の起点とされる。","砦の名は «中嶋砦»«中島城» とも書かれる。遺構は地中に埋もれたと考えられ、発掘で確かめられてはいない。"],"look":["«中島城址» の石碑（個人宅の敷地。道路から見学）","扇川と手越川の合流点","善照寺砦跡（北東の高台）との高低差"],"q":["信長が中島砦に入ったとき、手もとの兵はおよそ何人？","2千人足らずと『信長公記』は伝えています。"],"koji":[{"w":"運は天にあり","m":"勝ち負けの運は天が決めるもの。だからこそ全力を尽くせ、という意味で、信長がこの日兵に語ったと『信長公記』にある"}],"myth":"信長の言葉は『信長公記』の記述。進軍ルートは正面攻撃説・迂回奇襲説など諸説。","img":["桶狭間の戦い","信長公記","鳴海城"],"wp":"中島砦","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/The_Monument_of_Nakajima_Fort_Site.jpg",1280,960,"中島砦"],["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"],["c:f/f7/Tenjin-sha_Shrine_Keidai_%281%29%2C_Shiro_Narumi-cho_Midori_Ward_Nagoya_2020.jpg",1500,1000,"鳴海城"]]},{"id":"23_marune_toride","n":"丸根砦跡（松平元康が落とした砦）","yomi":"まるねとりであと","cat":"古戦場","rank":"B","y":1560,"era":["muromachi"],"sh":"国指定史跡（大高城跡 附 丸根砦跡・鷲津砦跡）","ad":"名古屋市緑区大高町","st":"JR東海道本線 大高駅の東。市バス «丸根» からすぐ","la":35.06439,"lo":136.94533,"hook":"桶狭間の朝、この砦を攻め落としたのは、数え19歳の若武者・松平元康 —— のちの徳川家康だった。","lead":"丸根砦は、1559年に織田信長が今川方の大高城をおさえるために築いた砦です。桶狭間の戦いの朝、今川方の先鋒・松平元康（のちの徳川家康）に攻められ、守っていた佐久間盛重らは討ち死にしました。丘の上には堀や曲輪がよく残り、国の史跡になっています。","story":["大高城から東へ約800m。丘の先に、小さな砦が築かれました。東西36m、南北28mほどの曲輪を、幅3.6mほどの堀が囲みます。«大高城に兵糧を運ばせるな» —— 大高城と鳴海城の間を切りはなすのが、丸根砦と鷲津砦の役目でした。","このころ、三河の松平元康は今川義元のもとにいました。子どものころから人質として駿府で育ち、義元から名前の一字をもらった若武者です。1560年、今川の大軍が尾張へ向かうと、元康は重要な役目をまかされます。«囲まれた大高城に、兵糧を運び入れよ»。","元康は大高城に兵糧を入れることに成功したといわれます。そして5月19日の夜明け、丸根砦に攻めかかりました。守る佐久間盛重らは必死に戦いましたが、多勢に無勢。砦は落ち、盛重たちは討ち死にしたと伝わります。同じころ、北の鷲津砦も今川方の朝比奈泰朝に落とされました。","ところがその日の昼過ぎ、桶狭間で義元が討たれます。大高城で知らせを聞いた元康は、今川軍とともに退くのではなく、ふるさと岡崎へもどりました。«もう今川の人質ではない»。これが、元康が独立し、のちに天下人・家康となる第一歩でした。","やがて元康と信長は同盟を結び、丸根砦は必要なくなって、そのまま捨てられました。今、丘の上には «丸根砦址» の碑と、戦いで亡くなった人びとの霊をなぐさめる碑が立っています。住宅地の中の小さな森で、460年以上前の激しい戦いに思いをはせてみてください。"],"tl":[["1559年","信長が大高城をおさえるため丸根砦・鷲津砦を築く"],["1560年5月18日夜","松平元康が大高城に兵糧を運び入れたと伝わる"],["1560年5月19日早朝","元康が丸根砦を攻め落とし、佐久間盛重らが討ち死に"],["1560年5月19日昼すぎ","桶狭間で今川義元が討たれる。元康は岡崎へ"],["1562年","元康と信長が同盟を結ぶ（清洲同盟）"],["1938年","大高城跡とともに国の史跡に指定"]],"who":[["松平元康（徳川家康）","今川方の先鋒として丸根砦を攻め落とした"],["佐久間盛重","丸根砦の守将。この戦いで討ち死にしたといわれる"],["今川義元","元康の主君。桶狭間で討たれた"],["織田信長","砦を築いた尾張の大名"]],"deep":["大高城跡・丸根砦跡・鷲津砦跡は、1938年にまとめて国の史跡に指定された（丸根・鷲津は «附（つけたり）»）。桶狭間の前哨戦の場所が国の史跡として守られている。","砦の規模は東西36m・南北28mほどで、外側を幅約3.6mの堀が囲んでいたとされる。鷲津砦とちがい、曲輪や堀の形が今もよく残っている。","元康の兵糧入れは『三河物語』などに描かれ、のちに «家康の最初の手がら» として語られるようになった。細かい経過には伝説的な部分もある。","元康が大高城から岡崎へ戻ったあと、今川方が捨てた岡崎城に入ったことで、松平家の独立が始まった。1562年ごろ信長と同盟を結ぶ。","佐久間盛重は信長の父・信秀の代から仕えた織田家の武将。守備兵はほぼ全滅したといわれるが、人数は史料によってちがう。"],"look":["丘の上に残る曲輪と堀","«丸根砦址» の碑と殉難者の碑","大高城跡・鷲津砦跡とあわせた散策（大高駅から周遊できる）"],"q":["丸根砦を攻め落とした今川方の武将で、のちの天下人はだれ？","松平元康、のちの徳川家康です。当時数え19歳でした。"],"koji":[],"myth":"兵糧入れの経過や守備兵の人数は史料・伝承により差がある。","img":["大高城","徳川家康","桶狭間の戦い"],"wp":"丸根砦","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/Ruins_of_Marune_Toride_%281%29%2C_Marune_Odaka-cho_Midori_Ward_Nagoya_2020.jpg",1500,1000,"丸根砦"],["c:f/fd/Ruins_of_Odaka_Castle_%28Honmaru%29_02%2C_Odaka-cho_Midori_Ward_Nagoya_2014.jpg",1500,1000,"大高城"],["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"]]},{"id":"23_washizu_toride","n":"鷲津砦跡","yomi":"わしづとりであと","cat":"古戦場","rank":"B","y":1560,"era":["muromachi"],"sh":"国指定史跡（大高城跡 附 丸根砦跡・鷲津砦跡）","ad":"名古屋市緑区大高町鷲津山","st":"JR東海道本線 大高駅から東へ歩いて約5分","la":35.06956,"lo":136.94229,"hook":"国の史跡なのに、ほんとうの場所がわからない —— 桶狭間の朝に燃え落ちた «なぞの砦»。","lead":"鷲津砦は、1559年に織田信長が大高城を囲むために築いた砦です。桶狭間の戦いの朝、今川方の朝比奈泰朝の軍勢に攻められ、午前中に落ちました。国の史跡ですが、正確な場所ははっきりせず、今は «鷲津砦公園» として碑が立っています。","story":["大高駅の東、長寿寺の裏手の丘に、鷲津砦公園があります。ここが、桶狭間の戦いの前哨戦の舞台といわれる場所です。1559年、信長は今川方の大高城と鳴海城の連絡を断つため、丸根砦とともにこの砦を築きました。守将は信長の一族・織田秀敏と、飯尾定宗・尚清の父子でした。","1560年5月19日の夜明け前。今川方の重臣・朝比奈泰朝が率いる約2千の兵が、砦に攻めかかりました。門や柵に火がつけられ、激しい戦いになります。«砦を守れ!» 飯尾定宗たちは奮戦しましたが、多くが討ち死にし、生き残った兵は清洲の方へ逃れました。砦は午前10時ごろまでに落ちたといいます。","清洲から駆けつけた信長は、丸根・鷲津の方角に上がる煙を見たと伝わります。二つの砦の犠牲は、今川の大軍を足止めし、義元の本隊を桶狭間で休ませることにもつながりました。«なぜ信長は砦を助けに行かなかったのか?» —— 砦の兵が戦っている間に、別の場所で勝負をかける作戦だったという見方もあります。","ところで、この砦の «本当の場所» はなぞです。国の史跡に指定されたのは字 «鷲津山» の丘ですが、発掘調査は行われておらず、遺構は確認されていません。昭和のはじめの調査報告でさえ «だいたいこの辺を想像したにすぎない» と書かれていました。","近年の研究では、指定地の北どなり、明忠院の裏山のほうが砦の跡として有力だといわれています。徳川家に伝わった古い絵図には、約37m四方の曲輪と、その南北に並ぶ曲輪、それを囲む堀が描かれています。公園の碑の前に立ち、«砦はどこにあったのか» と考えてみるのも、歴史探偵の楽しみです。"],"tl":[["1559年","信長が丸根砦とともに鷲津砦を築く。守将は織田秀敏・飯尾定宗ら"],["1560年5月19日未明","朝比奈泰朝の軍勢約2千が攻撃を始める"],["1560年5月19日午前","砦が落ち、飯尾定宗らが討ち死にしたといわれる"],["1929年","県の調査報告で、碑の場所は «想像にすぎない» と指摘される"],["1938年","大高城跡の «附» として国の史跡に指定"]],"who":[["織田秀敏","信長の一族。鷲津砦の守将とされる"],["飯尾定宗","守将の一人。砦の戦いで討ち死にしたといわれる"],["飯尾尚清","定宗の子。この戦いを生きのび、のちも信長に仕えた"],["朝比奈泰朝","今川方の重臣。鷲津砦を攻め落とした"]],"deep":["江戸時代の『寛文村々覚書』『張州府志』『尾張志』は «鷲津古城» を東西14間（約25m）・南北15間（約27m）と記す。一方、蓬左文庫の『尾州知多郡大高之内鷲津丸根古城図』はもっと複雑な構造を描き、記録どうしが食いちがう。","1929年の『愛知県史蹟名勝天然記念物調査報告』で若山善三郎は、碑の場所を «大体この辺を想像したるに過ぎず» と書いた。史跡指定（1938年）より前から、場所には疑問があった。","現在、指定地の北にあたる字 «鷲津» の丘（明忠院の裏山）が最有力候補とされる。史跡の範囲と本当の場所がずれているかもしれない、珍しい例。","守備兵は520騎とする軍記（『中古日本治乱記』）もあるが、確かな数はわからない。","鷲津砦は大高城の北東約700m、丸根砦の北北西約600m。三つの場所は歩いて回れる距離で、«包囲戦» の近さが体感できる。"],"look":["鷲津砦公園の «鷲津砦址» 碑と表忠碑","長寿寺と、北どなりの明忠院の裏山（有力な候補地）","公園北側の観音坂","丸根砦跡・大高城跡とあわせた散策"],"q":["鷲津砦を攻め落とした今川方の武将はだれ？","朝比奈泰朝です。約2千の兵で攻めたといわれます。"],"koji":[],"myth":"砦の正確な位置は不明（明忠院裏山説が有力）。守備兵数は軍記による。","img":["大高城","桶狭間の戦い","朝比奈泰朝"],"wp":"鷲津砦","rel":{"ev":[],"grave":[]},"ph":[["c:a/a2/View_of_Myouchu-in_Urayama%2C_Washizu_Odaka-cho_Midori_Ward_Nagoya_2020.jpg",1500,1000,"鷲津砦"],["c:f/fd/Ruins_of_Odaka_Castle_%28Honmaru%29_02%2C_Odaka-cho_Midori_Ward_Nagoya_2014.jpg",1500,1000,"大高城"],["c:4/47/Okehazama_Old_Battlefield%2C_Sakae-cho_Toyoake_2012.JPG",1500,1000,"桶狭間の戦い"]]},{"id":"23_iwasaki_jo","n":"岩崎城（長久手の前哨戦）","yomi":"いわさきじょう","cat":"城","rank":"B","y":1584,"era":["muromachi","azuchi"],"sh":"","ad":"日進市岩崎町","st":"地下鉄鶴舞線 赤池駅から日進市の «くるりんばす» で約15分、«御岳口» 下車","la":35.14508,"lo":137.04258,"hook":"城を守るのは、16歳の城主の弟。秀吉方の大軍を足止めしたその戦いが、長久手の勝負を決めた。","lead":"岩崎城は、戦国時代に尾張と三河の境目に築かれた城です。1584年の小牧・長久手の戦いでは、秀吉方の池田恒興の軍勢に攻められて落ちましたが、その足止めが家康方の勝利につながったといわれます。いまは城址公園となり、空堀や土塁が残っています。","story":["岩崎城は、尾張の東のはし、三河へ抜ける道を見下ろす台地の先に築かれました。はじめは織田信秀の城でしたが、1529年、三河の松平清康（家康の祖父）が攻め取ります。その清康が1535年に «守山崩れ» で亡くなると、松平方は引き上げ、丹羽氏清が城主となりました。以後、丹羽氏が4代にわたって城を守ります。","1584年春、羽柴秀吉と徳川家康・織田信雄が尾張で向かい合い、にらみ合いが続いていました。秀吉方は動きます。«家康の本拠・岡崎を突けば、家康はあわてて動くはずだ» —— 池田恒興らの大軍が、ひそかに三河をめざしました。いわゆる «三河中入» です。","その通り道に岩崎城がありました。城主の丹羽氏次は家康とともに小牧に出ていて、城を守るのは弟の氏重、16歳。わずかな兵で、目の前を大軍が通りすぎようとしていました。«見逃すわけにはいかない» —— 城からは鉄砲が放たれ、池田の軍勢は足を止めて城を攻めます。","4月9日の早朝、激しい戦いの末に岩崎城は落ち、氏重をはじめ城兵は討ち死にしました。けれどこの時間かせぎが大きな意味を持ちました。そのあいだに家康の軍勢が追いつき、同じ日、長久手で池田恒興・森長可らを討ち取ったのです。","戦いのあと、丹羽氏次は関ヶ原の戦いの功で三河の伊保（豊田市）1万石の大名となり、岩崎城は1600年に廃城になりました。300年ほど畑になっていた本丸には、1910年に «表忠義» の碑が建てられ、今も毎年4月9日に慰霊祭が行われています。"],"tl":[["15世紀末〜16世紀前半","岩崎城が築かれる"],["1529年","松平清康が岩崎城を攻め取る"],["1535年","守山崩れで清康が死去。丹羽氏清が城主に"],["1584年4月9日","池田恒興の軍勢に攻められ落城。丹羽氏重らが討ち死に。同日、長久手の戦い"],["1600年","丹羽氏次が三河伊保へ移り、廃城"],["1910年","本丸に «表忠義» の碑が建てられる"],["1987年","模擬天守（展望塔）と歴史記念館ができ、城址公園に"]],"who":[["丹羽氏重","城主・氏次の弟。16歳で城を守り、討ち死にした"],["丹羽氏次","岩崎城主。家康について小牧に出陣し、のちに伊保1万石の大名に"],["池田恒興","秀吉方の武将。三河中入の途中で岩崎城を攻め、長久手で討たれた"],["徳川家康","長久手で秀吉方の別動隊をやぶった"],["松平清康","家康の祖父。1529年に岩崎城を攻め取った"]],"deep":["本丸の櫓台は標高約66m。台地の先を堀切で断ち切り、土塁・空堀・帯曲輪で本丸を囲んだ平山城。空堀ははじめ断面がV字の «薬研堀» で、のちに一部を平らな底の «箱堀» に作りかえたことが調査でわかった。","1910年に建てられた «表忠義» 碑の文には、氏重が病で寝ていたのに敵が来ると刀をとって起き上がり、母がよろいを授けて送り出した、という場面が記されている。美談として語り継がれた部分もある。","1987年に建てられた5層の天守は «模擬天守»。戦国時代の岩崎城に天守があったわけではなく、建設で遺構の一部がこわされたとして、城郭研究者の千田嘉博から批判を受けている。","公園の整備中、6世紀のものとされる古墳が偶然見つかり、公園内に再現展示されている。城よりずっと古い «先住者»。","1551年に丹羽氏の一族争いに信長が援軍を出して敗れた «横山の戦い» の話もあるが、18世紀末の『丹羽氏軍功録』にしか出てこず、事実かどうかはわからない。"],"look":["空堀と土塁（本丸まわり）","本丸の櫓台に建つ «表忠義» 碑","岩崎城歴史記念館の展示","再現された古墳","展望塔（模擬天守）からの眺め"],"q":["岩崎城を守って討ち死にした丹羽氏重は、そのとき何歳だった？","16歳。彼の奮戦が池田軍を足止めし、長久手の戦いにつながりました。"],"koji":[],"myth":"氏重の出陣の場面は碑文・伝承による。横山の戦いは真偽不明。","img":["小牧・長久手の戦い","池田恒興","丹羽氏次"],"wp":"岩崎城 (尾張国)","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/%E5%B2%A9%E5%B4%8E%E5%9F%8E_%E6%A8%A1%E6%93%AC%E5%A4%A9%E5%AE%88.jpg",2787,3716,"岩崎城 (尾張国)"],["c:7/74/Komaki_Nagakute_Kassen_Zu_Byoubu%2C_Toyota.jpg",3274,1426,"小牧・長久手の戦い"],["c:8/86/Ikeda_Tsuneoki.jpg",1029,1873,"池田恒興"],["c:2/26/Iwasaki_Castle1.jpg",3216,2136,"丹羽氏次"]]},{"id":"23_moriyama_jo","n":"守山城跡（守山崩れ・松平清康の死）","yomi":"もりやまじょうあと","cat":"城","rank":"B","y":1535,"era":["muromachi"],"sh":"","ad":"名古屋市守山区市場","st":"名鉄瀬戸線 矢田駅から北へ歩いて約10分","la":35.19712,"lo":136.94974,"hook":"家康のおじいさんは、この城を攻める陣の中で、自分の家来に斬られた。«なぜ?» はいまも謎のまま。","lead":"守山城は、矢田川の北の台地にあった戦国時代の城です。1535年、城を攻めに来た三河の松平清康（徳川家康の祖父）が、陣中で家臣に殺される «守山崩れ» が起こりました。のちに、お市の方と三人の娘がしばらく身を寄せたともいわれます。今は寺の境内に碑と空堀が残ります。","story":["1535年12月、三河の若き実力者・松平清康が、尾張の守山まで兵を進めてきました。清康はこのとき25歳。三河をほぼまとめ、«次は尾張» と勢いに乗っていました。守山城を守るのは、織田信秀の弟・信光です。","12月5日の早朝、清康の陣で馬が放れてさわぎになりました。そのとき、家臣の阿部正豊（弥七郎）が、いきなり清康に斬りつけたのです。正豊は «父が謀反の疑いで殺された» と思いこんだ、と伝わります。清康は命を落とし、正豊もその場で討たれました。","大将を失った松平軍は、戦わずに岡崎へ引き上げます。これが «守山崩れ»。この日から、松平家は長い苦難の時代に入りました。清康の子・広忠はまだ10歳。やがて孫の竹千代（家康）は人質として他国で育つことになります。«もし清康が生きていたら、歴史はどうなっていたか?» —— 歴史ファンがよく語り合う «if» です。","その後、守山城には信光の弟・信次が入りますが、信次の家来が信長の弟・秀孝を誤って殺してしまう事件が起き、信次は逃げ出しました。1573年、近江の浅井氏がほろびたあと、お市の方と茶々・初・江の三姉妹は、この信次に預けられ、守山城で1年ほど過ごしたことがわかっています。","城の跡には、のちに清康をとむらうための寺 «宝勝寺» が建てられました。寺の裏の竹やぶには空堀が残り、本丸の土壇の一部も見られます。住宅地のすぐそばの小さな丘に、戦国の悲劇の記憶が眠っています。"],"tl":[["1526年","連歌師・宗長が守山で連歌会を開く。«守山» の字の最初の記録"],["1535年12月5日","守山崩れ。松平清康が陣中で家臣に殺される"],["1555年","城主・織田信次の家臣が信長の弟・秀孝を誤殺。信次は出奔"],["1573年","お市の方と三姉妹が信次に預けられ、守山城に約1年滞在"],["1574年","信次が長島の戦いで戦死"],["1767年","矢田川の氾濫で流れが変わる"]],"who":[["松平清康","岡崎城主。家康の祖父。守山の陣中で殺された"],["阿部正豊","清康を斬った家臣（弥七郎）"],["織田信光","信長の叔父。当時の守山城主"],["織田信次","信光の弟。のちの城主。お市の方と三姉妹を預かった"],["お市の方","信長の妹。浅井氏滅亡後、娘たちとここに身を寄せた"]],"deep":["事件の名は『三河物語』では «森山崩れ»、『信長公記』では «守山»。どちらの表記も使われる。","実行犯の父・阿部定吉は、ふつうなら連座で罰せられるはずなのに、その後も広忠の重臣として重く用いられた。このため、定吉自身が関わった計画的な謀反だったとする説（村岡幹生）もある。","清康を斬った正豊をその場で討った植村氏明は、のちに広忠が襲われた時にも犯人を討ったとされる。偶然か、何かあるのか、昔から話題にされる。","清康の叔父・松平信定が、うわさを流して家督をねらったと古くから語られてきたが、近年は徳川家の記録に書きかえがあった可能性も指摘されている。","城の規模は『尾州古城志』に東西約58m・南北約51mとある。堀が一重か二重かは写本によってちがう。","お市の方と三姉妹が守山にいたことは、宮本義己の研究で『渓心院文』から明らかになった。"],"look":["宝勝寺の境内と城址碑","寺の裏手の空堀","本丸の土壇の一部","台地の上から見る矢田川方面"],"q":["守山崩れで亡くなった松平清康は、徳川家康から見てだれ？","祖父です。清康の死で、松平家は長い苦難の時代に入りました。"],"koji":[],"myth":"清康を斬った刀が «村正» で、徳川家にたたる «妖刀村正» 伝説の始まりとされる話は後世の伝説。事件の真相は諸説。","img":["森山崩れ","松平清康","お市の方"],"wp":"守山城 (尾張国)","rel":{"ev":[],"grave":[]},"ph":[["c:e/e4/The_Monument_of_Moriyama_Castle_Site.jpg",1280,960,"守山城 (尾張国)"],["c:5/5f/Matsudaira_Kiyoyasu.jpg",1552,3037,"松平清康"],["c:7/78/Oichinokata.jpg",1246,1726,"お市の方"]]},{"id":"23_suemori_jo","n":"末森城跡（織田信秀・信勝の城）","yomi":"すえもりじょうあと","cat":"城","rank":"B","y":1548,"era":["muromachi","azuchi"],"sh":"","ad":"名古屋市千種区城山町（城山八幡宮）","st":"地下鉄東山線 覚王山駅から歩いて約5分","la":35.1675,"lo":136.95972,"hook":"信長の父が最後に住み、信長の弟が兄にそむいた城。深さ7mの空堀が、兄弟の争いを今に伝える。","lead":"末森城は、1548年に織田信秀が東からの敵にそなえて築いた城です。信秀の死後は、信長の弟・信勝（信行）が城主となり、兄・信長と家督を争いました。今は城山八幡宮の境内となり、大きな空堀がよく残っています。","story":["1548年、信長の父・織田信秀は、東山丘陵の先の丘に新しい城を築きました。東には三河の松平、その後ろには駿河の今川がいます。«東からの敵を、ここで食い止める»。信秀はそれまでの古渡城を離れ、この末森城に移りました。","信秀は、信長が家督をつぐ前に亡くなります。末森城を受けついだのは、信長の弟・信勝でした。礼儀正しく、家臣の評判もよい弟。一方、兄の信長は «大うつけ»（大ばか者）と呼ばれていました。«家をつぐのは、弟のほうがよいのでは» —— 家臣たちの心は揺れていました。","1556年、信勝は重臣の林秀貞や柴田勝家とともに兵をあげます。稲生の戦いです。しかし信長にやぶれ、信勝は末森城に立てこもりました。信長は城下に火を放ちます。このとき城の中にいた母・土田御前が間に入り、信勝は許されました。","ところが信勝は、ふたたび謀反をたくらみます。今度は柴田勝家がそれを信長に知らせました。信長は病気のふりをして信勝を清洲城に呼びよせ、討ち果たしたと伝わります。兄弟の争いは、悲しい結末をむかえたのです。","城はその後使われなくなりましたが、1584年の小牧・長久手の戦いのとき、織田信雄が再び手を入れたと考えられています。本丸跡は城山八幡宮の境内になり、神社を囲むように深い空堀がめぐります。参道を歩くだけで、戦国の城の «守りのかたち» が体で感じられます。"],"tl":[["1548年","織田信秀が末森城を築き、古渡城から移る"],["1552年","信秀が死去（年は諸説）。信勝が末森城主に"],["1553年","信勝が加賀の白山社の分霊を城内にまつる"],["1556年","稲生の戦いで信勝が敗れ、末森城に籠城。母のとりなしで許される"],["1557〜1558年ごろ","信勝が再び謀反を企て、清洲城で討たれる"],["1584年","小牧・長久手の戦いで織田信雄が城を使ったとされる"]],"who":[["織田信秀","信長の父。末森城を築いて移り住んだ"],["織田信勝（信行）","信長の弟。末森城主として兄と争った"],["土田御前","信秀の妻。信長・信勝の母。信勝の命ごいをした"],["柴田勝家","はじめ信勝に仕え、のちに信長側について謀反を知らせた"],["織田信雄","信長の次男。小牧・長久手の戦いの際に城を使ったとされる"]],"deep":["標高43mの丘に、東西約180m・南北約150mの規模。斜面の中ほどに幅10〜16mの空堀をめぐらせ、今も深さ約7mの堀跡が残る。","内堀北側の出入口には、半月形の «丸馬出»（三日月堀）があったらしい。愛知県ではめずらしい構造だが、現在は残っていない。","馬出や総構えの形から、今見える遺構の多くは、1584年に織田信雄が小牧・長久手の戦いにそなえて整えたものと考えられている。","信勝が1553年にまつった白山社が、廃城後も人びとに守られ、明治に近くの神社とあわせて城山八幡宮になった。城の中の小さな社が、神社として生きのびた例。","信秀の霊廟は、もとは城の西北のふもとにあった。今は千種区の桃巌寺で、信勝とともに供養されている。","«末盛» とも書かれ、町の通りの名 «末盛通» に城の名が残っている。なお、能登（石川県）にも同じ名の末森城があり、1584年の «末森城の戦い» はそちらの話なので注意。"],"look":["城山八幡宮を囲む深い空堀","境内の «末森城址» 碑","二の丸跡に建つ旧昭和塾堂（外観）","近くの桃巌寺（信秀の供養）"],"q":["稲生の戦いのあと、信勝の命を救ったのはだれ？","母の土田御前。彼女のとりなしで、信勝は一度は許されました。"],"koji":[{"w":"大うつけ","m":"大ばか者のこと。若いころの信長は、ふるまいが型破りだったためこう呼ばれたと伝わる"}],"myth":"信秀の没年、信勝が討たれた年は諸説。信長が病気を装った話は伝承を含む。","img":["織田信勝","織田信秀","稲生の戦い","城山八幡宮"],"wp":"末森城 (尾張国)","rel":{"ev":[],"grave":[]},"ph":[["c:f/f4/Stone_Monument_of_Suemori_Castle_Ruins_in_Shiroyama_Hachiman-gu_Shrine_Keidai%2C_Shiroyama-cho_Chikusa_Ward_Nagoya_2022.jpg",1500,1000,"末森城 (尾張国)"],["c:8/83/Oda_Nobukatsu.jpg",2674,5257,"織田信勝"],["c:1/15/Statue_of_Oda_Nobuhide_at_Bansh%C5%8D-ji.jpg",1740,1849,"織田信秀"],["c:8/89/In%C5%8Dgahara_Battlefield.jpg",1280,960,"稲生の戦い"],["c:4/47/Shiroyama6.JPG",3600,2400,"城山八幡宮"]]},{"id":"23_kanie_jo","n":"蟹江城跡（蟹江合戦）","yomi":"かにえじょうあと","cat":"城","rank":"B","y":1584,"era":["muromachi","azuchi"],"sh":"","ad":"海部郡蟹江町城","st":"近鉄名古屋線 近鉄蟹江駅から歩いて約15〜20分（目安）","la":35.13656,"lo":136.79017,"hook":"«賤ヶ岳は秀吉一代の勝ち戦、蟹江は家康一代の勝ち戦» —— 江戸の人がそう評した、港の城の攻防戦。","lead":"蟹江城は、尾張の南西、かつて海に面した港町・蟹江にあった城です。1584年、小牧・長久手の戦いのさなか、秀吉方の滝川一益がこの城を奪いましたが、徳川家康・織田信雄の大軍に囲まれ、半月ほどで明けわたしました。今は住宅地に石碑と本丸井戸の跡が残ります。","story":["戦国時代の蟹江は、熱田・津島とならぶ尾張の港でした。蟹江城は本丸・二の丸・三の丸をもち、まわりの大野城・下市場城・前田城と連携していました。しかも、家康のいる清洲城と信雄のいる長島城の、ちょうど中間。«ここを取れば、二人の連絡を断ち切れる»。","1584年、長久手で敗れた秀吉は、ベテラン武将・滝川一益に目をつけます。一益はかつて蟹江城主だったこともある人物。6月16日、九鬼嘉隆の水軍とともに一益の兵が蟹江の浦に現れました。城を預かっていた前田長定は一益の誘いに応じ、城は戦わずして秀吉方の手に落ちます。","ところが、近くの大野城を守る山口重政は、母を人質に取られても寝返りませんでした。知らせを受けた信雄はその夜のうちに大野城へ、家康も翌朝には駆けつけます。2万ともいわれる大軍が蟹江城を囲み、海からの道も断たれました。«一益、袋のねずみ» です。","激しい攻防のすえ、7月3日に城は明けわたされました。一益は伊勢へ逃れましたが、寝返った前田長定は討たれました。秀吉は、伊勢に大軍を集めて尾張の西から総攻撃をかける計画を立てていましたが、間に合いませんでした。江戸時代の学者・江村専斎は «蟹江の軍は、東照宮（家康）一世の勝事» と評しています。","翌1585年、大地震（天正地震）が城と町をおそい、蟹江城は壊滅しました。今は住宅地の中に «蟹江城址» の碑と本丸井戸の跡があるだけ。けれど、近くの蟹江町歴史民俗資料館では城跡の地図がもらえ、港町の城のすがたを想像しながら歩くことができます。"],"tl":[["1429〜1440年ごろ","北条時任が築いたとの説（碑文による。地誌にはない）"],["1555年","今川方に攻め取られたと伝わる"],["1574年以降","滝川一益が蟹江城を支配"],["1584年6月16日","滝川一益が蟹江城を奪う（蟹江城合戦）"],["1584年6月18日","家康・信雄の大軍が蟹江城などを包囲"],["1584年7月3日","蟹江城が明けわたされ、一益は伊勢へ"],["1585年","天正地震で城が壊滅"]],"who":[["滝川一益","秀吉方として蟹江城を奪った武将。かつての蟹江城主"],["徳川家康","織田信雄とともに蟹江城を包囲し、取り返した"],["織田信雄","信長の次男。家康と組んで秀吉と戦った"],["九鬼嘉隆","水軍の将。一益とともに蟹江を攻めた"],["前田長定","城の留守を預かっていたが、一益に寝返った"],["山口重政","大野城主。寝返りを拒み、のちに常陸牛久藩の初代藩主となる"]],"deep":["江戸前期の儒医・江村専斎は «賤ヶ岳の軍は太閤一代の勝事、蟹江の軍は東照宮一世の勝事也» と語った（『老人雑話』）。長久手に比べ知名度は低いが、家康の重要な勝利とする見方がある。","北条時任が永享年間に築いたという説は、1915年建立の城址碑の文によるもの。『蟹江町史』は «明治以前にはなかった説だろう» と指摘している。","前田城を守っていた前田長種は、戦いのあと加賀の前田利家をたより、のちに加賀藩2代藩主・前田利常の養父となった。尾張の前田一族と加賀前田家のつながりがわかる。","前田長定がどう討たれたかは、史料で食いちがう。『三河物語』は家康方に討たれたとし、後世の記録では一益側が討ったことになっている。","戦いのあと、一益は伊勢の神戸城に逃れようとしたが入城を断られたという。一益は晩年、越前で亡くなったとされ、江戸時代の軍記は «餓死» と厳しく書いた。","秀吉が準備した尾張西からの総攻撃は、羽柴秀長らの6万2千の兵で7月15日に予定されていたが、蟹江の落城で中止となった。"],"look":["«蟹江城址» の碑","本丸井戸の跡","蟹江町歴史民俗資料館（城跡の地図がもらえる）","かつての港町の面影が残る蟹江川沿い"],"q":["蟹江城合戦で、秀吉方として蟹江城を奪った武将はだれ？","滝川一益。かつて蟹江城主だったこともあるベテランでした。"],"koji":[{"w":"袋のねずみ","m":"囲まれて逃げ場がないこと。海と陸をふさがれた蟹江城の滝川勢がまさにそうだった"}],"myth":"築城者（北条時任説・渡辺源十郎説など）は諸説。前田長定を討ったのがどちらかも史料により異なる。","img":["蟹江城合戦","滝川一益","小牧・長久手の戦い","九鬼嘉隆"],"wp":"蟹江城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Kanie_Castle_Ruins_ac.jpg",6016,4000,"蟹江城"],["c:4/44/Takigawa_Sakon.jpg",1926,2197,"滝川一益"],["c:7/74/Komaki_Nagakute_Kassen_Zu_Byoubu%2C_Toyota.jpg",3274,1426,"小牧・長久手の戦い"],["c:3/3c/Kukiyoshitaka2.jpg",1141,2101,"九鬼嘉隆"]]},{"id":"23_iwakura_jo","n":"岩倉城跡（尾張上四郡守護代）","yomi":"いわくらじょうあと","cat":"城","rank":"B","y":1559,"era":["muromachi"],"sh":"市指定史跡（岩倉市）","ad":"岩倉市下本町","st":"名鉄犬山線 岩倉駅から歩いて約15分","la":35.27522,"lo":136.87727,"hook":"信長が尾張をまとめる最後の相手は、同じ «織田» の本家筋だった。五条川のほとりの城に、焼けた土が眠る。","lead":"岩倉城は、15世紀の終わりごろに築かれた、尾張の北半分（上四郡）を治めた守護代・織田伊勢守家の城です。1559年、織田信長に攻められて落城し、信長の尾張統一が大きく前進しました。今は五条川のそばに石碑が立ち、発掘で当時の堀も見つかっています。","story":["戦国時代のはじめ、尾張は «上四郡» と «下四郡» に分かれ、それぞれを織田家の二つの家が治めていました。北を治めたのが、岩倉城の織田伊勢守家。南を治めたのが、清洲城の織田大和守家です。信長の家（弾正忠家）は、その大和守家の家来の一つにすぎませんでした。","1479年ごろ、伊勢守家の織田敏広が岩倉城を築いたといわれます。五条川のほとりの低い台地の上、二重の堀で囲まれた城で、清洲城とならぶ尾張の重要な城でした。まわりには武家屋敷や市場が広がり、にぎやかな城下町ができていたことが、地図の分析からわかっています。","やがて信長が力をつけると、岩倉の城主・織田信安は、信長の弟・信勝の側につきます。1558年、信安の子・信賢は浮野の戦いで信長にやぶれ、岩倉城に立てこもりました。«もはや、尾張に信長に逆らえる者はいない» —— その最後の砦が、この岩倉城でした。","1559年春、信長は城を囲み、火を放ったといわれます。数か月にわたる包囲のすえ、岩倉城は落ち、信賢は城を明けわたしました。こうして信長は、ほぼ尾張一国をまとめることになります。その翌年、信長は桶狭間で今川義元を討つことになるのです。","城の跡には今、«岩倉城址» の碑と、1860年に建てられた «織田伊勢守城址» の碑があります。発掘調査では、幅の広い堀や井戸、中国製の上等な焼き物、そして焼けた土の面が見つかりました。«信長の焼き討ちのあとかもしれない» —— 地面の下に、落城の記憶が残っていたのです。"],"tl":[["1479年ごろ","織田伊勢守家の織田敏広が岩倉城を築いたといわれる"],["1556年","城主・織田信安が稲生の戦いで信勝（信長の弟）に味方する"],["1558年","浮野の戦いで織田信賢が信長にやぶれる"],["1559年","信長の攻撃で岩倉城が落城（1558年説もある）"],["1560年","信長が桶狭間の戦いで今川義元を討つ"],["1860年","«織田伊勢守城址» の碑が建てられる"]],"who":[["織田敏広","織田伊勢守家の当主。岩倉城を築いたといわれる"],["織田信安","岩倉城主。信勝に味方し、信長と対立した"],["織田信賢","信安の子。浮野の戦いに敗れ、岩倉城を明けわたした"],["織田信長","岩倉城を落とし、尾張をほぼ統一した"],["山内盛豊","岩倉織田家の家老とされる。土佐藩祖・山内一豊の父"]],"deep":["城は標高約10mの低い台地の上にあり、規模は東西約104m・南北約169mとされる。南には小田井城があり、にらみ合う位置にあった。","発掘調査で、五条川の右岸から幅約10mと約23mの堀がそれぞれ2本ずつ見つかり、外堀と内堀と考えられている。内側からは東西約43mの区画、井戸、土師器の皿、上質な中国製陶磁器が出土した。","焼けた土の面が見つかり、信長による焼き討ちのあとと推定されている。文献だけでなく、地面の中からも落城の様子がうかがえる例。","地籍図の分析から、城のまわりに南北約900m・東西約400mの範囲で武家屋敷や町があったとされる。","土佐藩の藩祖・山内一豊は、父の盛豊が岩倉織田家に仕えていたため、岩倉で生まれたとする説がある（生誕地は諸説）。","五条川は今、桜並木で知られる。城の堀の役目をしていた川が、春には花見客でにぎわう。"],"look":["«岩倉城址» と «織田伊勢守城址»（1860年建立）の碑","城のそばを流れる五条川（春の桜並木）","岩倉市の史跡案内板"],"q":["岩倉城を拠点に、尾張の «上四郡» を治めた織田家の家は？","織田伊勢守家（岩倉織田氏）です。"],"koji":[],"myth":"築城者・落城年は諸説。山内一豊の岩倉生誕説も一説。","img":["織田信安","浮野の戦い","山内一豊"],"wp":"岩倉城","rel":{"ev":[],"grave":[]},"ph":[["c:1/19/%E6%B5%AE%E9%87%8E%E5%8F%A4%E6%88%A6%E5%A0%B4_%E6%B5%AE%E5%89%95%E9%A6%96%E5%A1%9A%E6%A1%88%E5%86%85%E7%9C%8B%E6%9D%BF.jpg",3024,4032,"浮野の戦い"],["c:5/5f/Yamauchi-Kazutoyo.jpg",1833,4000,"山内一豊"]]},{"id":"23_noda_jo","n":"野田城跡（武田信玄狙撃伝説）","yomi":"のだじょうあと","cat":"城","rank":"B","y":1573,"era":["muromachi"],"sh":"市指定史跡（新城市）","ad":"新城市豊島","st":"JR飯田線 野田城駅から歩いて約15分","la":34.88206,"lo":137.46831,"hook":"夜の城から流れる笛の音。聞きほれた信玄を、一発の銃弾がおそった —— 本当に?","lead":"野田城は、戦国時代に菅沼氏が築いた三河の城です。1573年、武田信玄の大軍に囲まれ、約1か月の籠城のすえに開城しました。このとき «城から聞こえる笛の音に聞きほれた信玄が鉄砲で撃たれ、それがもとで亡くなった» という有名な伝説が生まれました。今も土塁と空堀が残っています。","story":["野田城は、豊川の流れに近い台地に、本丸・二の丸・三の丸が一直線に並ぶ城でした。両側の深い淵が天然の堀です。城を築いたのは菅沼定則。孫の菅沼定盈は、桶狭間の戦いのあと今川家を離れ、徳川家康の味方になりました。","1572年、武田信玄は大軍を率いて甲斐を出発しました。遠江の三方ヶ原で家康をやぶり、翌1573年の正月、三河の野田城を取り囲みます。城を守る兵はわずか。けれど定盈はよく耐え、城はなかなか落ちませんでした。武田軍は金山で働く人たちを使って、城の水の手（水の通り道）を断ったといわれます。","ある夜のこと。城の中から、美しい笛の音が聞こえてきました。«あの音色を聞け» —— 毎晩のように笛を聞きに来ていた信玄を、城の鉄砲の名手が狙い撃ちにした、という伝説があります。笛を吹いたのは村松芳休という名手だったと伝わります。","水を断たれた城は、ついに開城しました。ところが武田軍はそこから先へ進まず、兵を引き上げます。そしてその帰り道、信玄は亡くなりました。«野田城で撃たれた傷のせいだ» —— 伝説はこうして広まりました。ただし、史料で確かめられるのは、信玄が病気で亡くなったことです。","狙撃の話は、江戸時代に定盈の子孫が書いた『菅沼家譜』に出てきますが、そこでも «夜の射撃のあと武田の陣がさわがしくなった» と書かれているだけで、命中したとは書かれていません。この伝説は、黒澤明の映画『影武者』のもとにもなりました。今、雑木林の中に土塁と空堀が残り、静かに伝説を見守っています。"],"tl":[["1508年","菅沼定則が野田城を築く（1505年とする記述もある）"],["1561年","今川方に攻められ開城。翌年、菅沼定盈が夜襲で奪い返す"],["1573年1〜2月","武田信玄に包囲され、水の手を断たれて開城（野田城の戦い）"],["1573年4月","信玄が甲斐へ帰る途中で死去"],["1590年","家康の関東移封にともない廃城"],["1719年","本丸の門が近くの法性寺の山門として移される"],["1980年","黒澤明の映画『影武者』公開。狙撃伝説がもとになった"]],"who":[["菅沼定盈","野田城主。武田信玄の大軍を相手に籠城した"],["武田信玄","甲斐の戦国大名。野田城を攻め落としたのち、帰る途中で死去"],["菅沼定則","野田城を築いた武将。定盈の祖父"],["村松芳休","城内で笛を吹いたと伝わる笛の名手"],["黒澤明","映画監督。狙撃伝説をもとに『影武者』を撮った"]],"deep":["狙撃伝説の出どころは、江戸時代に菅沼家の子孫がまとめた『菅沼家譜』。武田側の記録には見当たらない。","『菅沼家譜』でさえ «夜に鉄砲を撃ったあと、武田の陣中がさわがしくなった» という程度で、信玄に当たったとは書いていない。伝説はあとから大きくふくらんだと考えられる。","信玄の死因は、胃の病気や肺の病気など諸説ある。いずれにしても病死とする見方が一般的。","城の造りは、本丸・二の丸・三の丸・廓・侍屋敷が一直線に並ぶ «連郭式»。両側の淵が天然の堀になっていた。","野田城の戦いのあと、定盈は捕らえられたが、のちに人質交換で徳川方にもどり、長篠の戦いでも鳶ヶ巣山攻撃に加わった。","本丸の門は1719年に近くの法性寺の山門として移されたとされ、城の建物の «生き残り» として見ることができる。"],"look":["土塁と空堀（本丸・二の丸まわり）","城の両側の深い谷（天然の堀）","法性寺の山門（本丸の門を移したとされる）","野田城駅（城の名がついた駅）"],"q":["野田城で信玄が撃たれたという伝説で、信玄が聞きほれていたとされるものは？","城から聞こえる笛の音。ただし命中したという確かな記録はありません。"],"koji":[],"myth":"信玄狙撃・笛の名手の話は伝承。水の手を断った方法も伝承を含む。","img":["野田城の戦い","菅沼定盈","武田信玄"],"wp":"野田城 (三河国)","rel":{"ev":[],"grave":[]},"ph":[["c:c/cd/Suganuma_Sadamitsu.jpg",403,376,"菅沼定盈"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"]]},{"id":"23_kaminogo_jo","n":"上ノ郷城跡（鵜殿氏と人質交換）","yomi":"かみのごうじょうあと","cat":"城","rank":"B","y":1562,"era":["muromachi"],"sh":"市指定史跡（蒲郡市）","ad":"蒲郡市神ノ郷町","st":"JR・名鉄 蒲郡駅から北へ約2km（車が便利）","la":34.84226,"lo":137.22521,"hook":"城を落として手に入れたのは、敵の子ども2人。家康はその2人と、妻と子の命を取りかえた。","lead":"上ノ郷城は、蒲郡の丘にあった今川方の武将・鵜殿氏の城です。1562年、今川家から独立した松平元康（のちの徳川家康）が攻め落とし、捕らえた城主の子ども2人と引きかえに、駿府にいた自分の妻子を取りもどしました。今は大部分がミカン畑で、土塁や空堀が残ります。","story":["1560年、桶狭間で今川義元が討たれると、岡崎の松平元康は今川家から離れて独立の道を進みます。まわりの武将たちが次々に元康に従う中、上ノ郷城の鵜殿長照は今川方に残りました。長照の母は義元の妹。今川家とは «親せき» だったのです。","ところが、元康には大きな心配ごとがありました。妻の瀬名、長男の竹千代（のちの信康）、長女の亀姫が、今川家の本拠・駿府に残されたままだったのです。今川を裏切った元康の家族は、いつ命をうばわれてもおかしくありません。«なんとしても、家族を取りもどしたい»。","1562年、元康は上ノ郷城を攻めました。けれど城は堅く、なかなか落ちません。そこで元康は、甲賀の忍びの者たちを使ったと伝わります。伴与七郎らが夜に城へ忍びこみ、火を放ちました。«裏切り者が出たぞ!» 城の中は大混乱。そのすきに攻めこみ、城主の長照は討たれ、2人の息子・氏長と氏次は捕らえられました。","元康は今川氏真に申し入れます。«鵜殿の息子たちを返そう。そのかわり、わたしの妻と子を返してほしい»。氏真にとって鵜殿兄弟は、いとこの子にあたる大切な親族。見捨てるわけにはいかず、人質交換が成立しました。瀬名と子どもたちは、無事に岡崎へもどったのです。","その後、城は元康の母・於大の再婚相手である久松俊勝のものとなりました。今、城跡の大部分は私有地のミカン畑で、曲輪や空堀、土塁、井戸が残っています。見学は案内板のある場所から、畑に入らないよう気をつけましょう。戦国の «家族の物語» が刻まれた丘です。"],"tl":[["平安末〜戦国時代","築城年代は諸説"],["1560年","桶狭間の戦い。今川義元が討たれ、元康が独立へ"],["1562年","元康が上ノ郷城を攻め落とす。鵜殿長照が討ち死に"],["1562年","長照の子と元康の妻子との人質交換が成立"],["1590年","家康の関東移封後、池田輝政の領地に。のち廃城"],["1957年","蒲郡市の史跡に指定"]],"who":[["鵜殿長照","上ノ郷城主。今川義元のおい。城を守って討ち死にした"],["松平元康（徳川家康）","上ノ郷城を攻め落とし、人質交換で妻子を取りもどした"],["瀬名（築山殿）","元康の正室。駿府から岡崎へもどった"],["伴与七郎","甲賀衆。城に火を放ち、長照を討ったと伝わる"],["久松俊勝","於大の方の再婚相手。落城後に城主となった"]],"deep":["戦死した城主を鵜殿長持とする話があるが誤り。長持は長照の父で、1556年に亡くなっている。","甲賀衆の参加者として、伴与七郎（資定）のほか伴中務、伴太郎左衛門、伴伯耆守ら80人余りの名が伝わる。伯耆守資綱が長照の子どもたちを捕らえたという。","家康の伝記『烈祖成績』には、城内に火が上がると «内通者が出た» と勘ちがいして城兵が混乱し、逃げようとした長照を伴与七郎が討った、と書かれている。","人質交換で戻った竹千代（信康）と瀬名は、のちに1579年、信長との関係の中で悲劇的な最期をとげる。上ノ郷城で救われた命の、その後の運命にも目を向けたい。","別名が多い城で、西之郡之城・宇土城・鵜殿城・神ノ郷城とも呼ばれる。","鵜殿氏はこの城を拠点に、今の蒲郡市のほぼ全域と幸田町の一部を治めていたとされる。"],"look":["残る土塁・空堀・曲輪","井戸の跡","丘から見る蒲郡の町と三河湾","（私有地のミカン畑に入らないこと）"],"q":["元康が上ノ郷城の人質と交換で取りもどしたのはだれ？","妻の瀬名と、長男の竹千代（信康）、長女の亀姫です。"],"koji":[],"myth":"甲賀衆の火攻めの細部は後世の記録・伝承による。築城年は諸説。","img":["鵜殿長照","築山殿","松平信康","徳川家康"],"wp":"上ノ郷城","rel":{"ev":[],"grave":[]},"ph":[["c:2/29/Kaminogou_castle1.jpg",6048,4024,"上ノ郷城"],["c:6/6b/%E7%AF%89%E5%B1%B1%E6%AE%BF.jpg",3442,4586,"築山殿"],["c:2/22/Matsudaira_Nobuyasu.jpg",790,1649,"松平信康"]]},{"id":"23_ogyu_jo","n":"大給城跡（大給松平氏）","yomi":"おぎゅうじょうあと","cat":"城","rank":"B","y":1510,"era":["muromachi"],"sh":"国指定史跡（松平氏遺跡）","ad":"豊田市大内町","st":"車でないと行きにくい（散策路の入口に数台の駐車スペースあり）","la":35.05348,"lo":137.22771,"hook":"山の上の城に、ダムでせき止めた «水の曲輪»。家康の一族がきずいた、三河の山城の傑作。","lead":"大給城は、豊田市の山の上にあった戦国時代の山城です。徳川家の先祖・松平氏の一族、大給松平家の本拠でした。巨大な岩や石垣、谷をせき止めて水をためた «水ノ手曲輪» など、見どころが多く、国の史跡 «松平氏遺跡» の一つになっています。","story":["三河の山あいにある松平郷は、のちの徳川家のふるさとです。松平家はここから少しずつ領地を広げていきました。その途中、松平信光は、土地の豪族・長坂新左衛門がかまえていた館を攻め落とし、子の親忠に与えます。これが大給城の始まりと伝わります。","親忠の次男・乗元は、この地を受けつぎ «大給松平家» の初代となりました。1507年から1510年ごろにかけて、乗元とその子・乗正が、館を本格的な山城に作りかえたとされます。山の鞍部（くぼんだ所）を堀切で断ち切り、東西220m、南北280mほどの城ができあがりました。","城のいちばんの見どころは、北側の «水ノ手曲輪»。谷を堤防で区切り、井戸水と雨水をためて、水堀と水がめの両方の役割を持たせました。いちばん大きな堤防は幅30m、高さ5mもあります。«山の上でどうやって水を確保するか?» —— 山城の最大の悩みを、見事に解決していたのです。","けれど、松平一族どうしの争いは絶えませんでした。1575年、大給城は同じ松平一族の滝脇松平家に襲われ、放棄されたといいます。1590年、家康が関東に移ると、城はそのまま廃城になりました。大給松平家は江戸時代に大名となり、いくつもの藩を治めていきます。","今、城跡は公園としてよく整備され、縄張りの図や案内板がそろっています。主郭の近くの «物見岩» からは、豊田の町が一望できます。尾根の東のはしには、初代・乗元の墓も残っています。巨岩と石垣の間を歩けば、戦国の山城の迫力を体で感じられるでしょう。"],"tl":[["15世紀後半","松平信光が長坂新左衛門の館を攻め取り、子の親忠に与えたと伝わる"],["1507〜1510年ごろ","松平乗元・乗正が城郭として整える"],["1575年","滝脇松平家に襲われ、放棄されたとされる"],["1590年","家康の関東移封にともない廃城"],["2000年","«松平氏遺跡» の一つとして国の史跡に指定"]],"who":[["松平乗元","大給松平家の初代。城の東の尾根に墓がある"],["松平乗正","乗元の子。父とともに城を整えた"],["松平信光","松平家3代当主。この地を攻め取ったと伝わる"],["松平親忠","信光の子。乗元の父"],["長坂新左衛門","もとの館の主とされる地元の豪族"]],"deep":["«水ノ手曲輪» は、谷筋を堤防でいくつかに区切り、井戸水と雨水をためる仕組み。水堀（防御）と水の確保（生活）を一度に満たす、全国的にも珍しい工夫。","主郭は東西約45m・南北約20m。主郭と副郭が山頂付近にあり、その南に居館の曲輪があった。","石塁（石を積んだ塁）や櫓台が残り、三河の戦国山城としては石の使い方が目立つ城。巨岩を取りこんだ虎口（出入口）も見どころ。","«松平氏遺跡» は、松平郷の館跡などとともに指定された国の史跡。大給城は松平一族の広がりを示す場所。","大給松平家の子孫からは、江戸時代に老中を出した家もある。また幕末の奥殿藩主・大給恒（松平乗謨）は日本赤十字社の前身・博愛社の創設にかかわった。"],"look":["水ノ手曲輪の堤防","主郭と物見岩からの眺め","堀切と国史跡の碑","巨岩を使った虎口","松平乗元の墓"],"q":["大給城の北側にある、谷をせき止めて水をためた曲輪を何という？","«水ノ手曲輪»。水堀と水の確保の両方の役目がありました。"],"koji":[],"myth":"築城の経緯（長坂新左衛門の館を攻め取った話）は伝承を含む。","img":["大給松平家","松平氏遺跡","松平乗元"],"wp":"大給城","rel":{"ev":[],"grave":[]},"ph":[["c:b/bf/Ogyu-jo_Castle_Remains_01%2C_Ouchi-cho_Toyota_2019.jpg",1500,1000,"大給城"],["c:3/3a/%E4%B8%B8%E3%81%AB%E9%87%98%E6%8A%9C%E3%81%8D.jpg",158,158,"大給松平家"]]},{"id":"23_okudono_jinya","n":"奥殿陣屋（大給松平氏の陣屋）","yomi":"おくとのじんや","cat":"大名屋敷","rank":"B","y":1711,"era":["edo","meiji"],"sh":"","ad":"岡崎市奥殿町雑谷下","st":"名鉄 東岡崎駅から名鉄バス «奥殿陣屋» 行きで約30分","la":35.0275,"lo":137.196,"hook":"三河の小さな陣屋の殿さまは、のちに星形の城をきずき、赤十字の生みの親の一人になった。","lead":"奥殿陣屋は、江戸時代に奥殿藩1万6千石の大給松平家がおいた陣屋（小さな大名の役所兼屋敷）の跡です。今は、近くの寺に移されていた書院をもどして整えた観光施設になり、庭園や藩主の墓所、土塁が残っています。最後の藩主・大給恒は、日本赤十字社の前身・博愛社の創設にかかわりました。","story":["奥殿藩の始まりは、江戸時代のはじめ。大給松平家の松平真次が、大坂の陣の手がらで知行を増やされるとき、«先祖ゆかりの大給の地がほしい» と願い、大給（豊田市）に陣屋をかまえました。子の乗次の代に1万6千石の大名となります。","けれど大給は山の中で、交通も不便でした。«もっと広く、便利な場所へ»。18世紀のはじめ、藩主・松平乗真は藩の役所を奥殿に移しました。村積山のふもとに、御殿・役所・書院・学問所・馬場などが並ぶ陣屋が生まれます。","幕末、藩主となったのは松平乗謨。学問好きで、西洋の知識にも明るい人物でした。乗謨は幕府の若年寄・陸軍総裁などの重い役につく一方、藩の本拠を、領地の大部分があった信濃国佐久郡の田野口へ移します。そこに築いたのが、五稜郭と同じ星形の «龍岡城» です。三河の領民の多くは移転に反対し、嘆願書を出したといいます。","明治になると、乗謨は «大給恒» と名前を改めました。1877年、西南戦争の負傷者を敵味方なく救うため、佐野常民とともに «博愛社» をつくります。これが今の日本赤十字社のはじまりです。«敵であっても、けがをした人は助ける» —— 三河の小藩の殿さまが、新しい時代の考えを日本に広めたのです。","廃藩のあと、陣屋の建物は移されたり取りこわされたりして、跡地はほとんど田畑になりました。1985年、近くの龍渓院の庫裏になっていた書院が移され、«奥殿陣屋» として公開されます。今は日本庭園やバラ園もある観光施設で、裏手には歴代藩主の墓所と土塁が静かに残っています。"],"tl":[["江戸時代初め","松平真次が大給に陣屋をかまえる"],["17世紀後半","松平乗次が1万6千石の大名になる"],["1711年","松平乗真が藩庁を奥殿に移す（1707年に陣屋完成とする資料もある）"],["1863年","松平乗謨が藩庁を信濃・田野口に移す"],["1877年","大給恒（乗謨）らが博愛社を創設"],["1985年","書院が跡地に移され、«奥殿陣屋» として開館"]],"who":[["松平乗謨（大給恒）","最後の藩主。幕府の陸軍総裁。明治に博愛社（日本赤十字社の前身）を創設"],["松平乗真","藩庁を大給から奥殿に移した藩主"],["松平真次","大給に陣屋をかまえ、奥殿藩のもとをつくった"],["松平乗利","19世紀前半の藩主。藩校・明徳館をつくり、名君とされる"],["佐野常民","大給恒とともに博愛社を創設した人物"]],"deep":["奥殿藩の領地は三河よりも信濃・佐久郡のほうが大きかった。18世紀はじめに近畿方面の領地1万2千石が信濃の田野口に替えられたため。","龍岡城（田野口陣屋）は、函館の五稜郭とならび日本に2つしかない星形要塞。1867年に御殿ができたが、城郭としては未完成のまま明治を迎えたとされる。","藩主・松平乗利は、90歳以上のお年寄りに毎年米を贈り、1833年の凶作では困った人びとの救済に力を尽くしたと伝わる。","今の書院は、近くの龍渓院の庫裏として使われていたもの。陣屋の建物がふるさとにもどってきた例。","陣屋跡は村積山の北のふもと。歴代藩主は村積山の神社にのぼりや奉納を重ね、藩と山の信仰が結びついていた。","NHKの連続テレビ小説『純情きらり』のロケ地にもなった。"],"look":["移築された書院と日本庭園","裏手の歴代藩主の廟所","残る土塁","バラ園（季節による）","村積山の眺め"],"q":["奥殿藩最後の藩主・大給恒がつくった、日本赤十字社の前身は？","博愛社。西南戦争の負傷者を敵味方なく救うためにつくられました。"],"koji":[{"w":"博愛","m":"すべての人を分けへだてなく愛すること。博愛社の名前に込められた考え"}],"myth":"奥殿移転の年は資料により1707年・1711年と差がある。","img":["奥殿藩","大給恒","龍岡城","日本赤十字社"],"wp":"奥殿陣屋","rel":{"ev":[],"grave":[]},"ph":[["c:2/23/Okutono-Jinya-1.jpg",4032,3024,"奥殿陣屋"],["c:e/e0/Viscount_Ogyu_Uzuru.PNG",514,688,"大給恒"],["c:d/d0/%E9%BE%8D%E5%B2%A1%E5%9F%8E.jpg",1764,1355,"龍岡城"],["c:6/63/Headquarters_of_Japanese_Red_Cross_Society.jpg",4608,3456,"日本赤十字社"]]},{"id":"23_ogawa_jo","n":"緒川城跡（於大の方生誕地）","yomi":"おがわじょうあと","cat":"城","rank":"B","y":1528,"era":["muromachi","azuchi"],"sh":"","ad":"知多郡東浦町緒川（字古城）","st":"JR武豊線 緒川駅から歩いて約15分","la":34.9855,"lo":136.9585,"hook":"徳川家康の母・於大の方が生まれた城。天下人の物語は、知多半島のつけ根の小さな丘から始まった。","lead":"緒川城は、室町時代に水野氏がきずいた城です。1528年、ここで水野忠政の娘・於大の方が生まれました。於大はのちに岡崎の松平広忠にとつぎ、徳川家康を生みます。今は建物はなく、住宅地の中に城跡の碑が立っています。","story":["緒川城は、室町時代の中ごろに水野貞守がきずいたと伝わる城です。水野氏は知多半島のつけ根、衣浦湾に面したこの地を本拠にして力をのばしました。海と陸の道が交わる場所で、船で三河へも尾張へも出られる、小さいけれど大事な拠点でした。","1528年、城主・水野忠政に一人の娘が生まれました。名は於大。のちの «伝通院» です。当時の三河・尾張は、東の今川と西の織田にはさまれ、小さな武士たちはどちらにつくかで生き残りが決まる時代。水野家は、娘を西三河の松平家に嫁がせて手を結びました。於大は14歳で岡崎城の松平広忠にとつぎ、翌年、男の子を生みます。竹千代、のちの徳川家康です。","ところが幸せは長く続きませんでした。父・忠政が亡くなり、兄の水野信元があとをつぐと、水野家は今川方から織田方に乗りかえます。今川の力を頼っていた松平家にとって、水野の娘を妻にしておくことはできません。於大は離縁され、3歳の竹千代を岡崎に残して実家へ帰されました。«なぜ母と子が別れなければならないの?» その答えは、戦国の同盟という冷たい理屈でした。","於大はのちに阿古居（今の阿久比町）の久松俊勝と再婚しますが、人質として尾張や駿府を転々とするわが子に、着物やお菓子をこっそり届け続けたと伝わります。母の思いは、遠く離れた竹千代の心の支えになったことでしょう。","一方、緒川城を継いだ水野信元は、織田信長の同盟者として活躍し、家康と信長を結びつける役目も果たしました。しかし1576年、武田方と通じたという疑いをかけられ、信長の命令で命を落とします。やがて城は使われなくなり、今は住宅地の一角に碑と説明板だけが残ります。けれど近くには水野家の菩提寺・乾坤院や於大の像があり、町ぐるみで «家康の母のふるさと» を大切にしています。"],"tl":[["15世紀後半","水野貞守が緒川に城をきずいたと伝わる"],["1528年","水野忠政の娘・於大が緒川城で生まれる"],["1541年","於大が岡崎城主・松平広忠にとつぐ"],["1542年","於大が竹千代（徳川家康）を生む（旧暦12月、新暦では1543年1月）"],["1544年","兄・水野信元が織田方につき、於大は離縁される"],["1576年","水野信元が信長の命で殺される"],["1602年","於大（伝通院）が京都の伏見城で亡くなる"]],"who":[["於大の方（伝通院）","緒川城で生まれた。徳川家康の母"],["水野忠政","於大の父。緒川城主、のちに刈谷城もきずく"],["水野信元","於大の兄。織田方について家康と信長をつないだ"],["松平広忠","於大の最初の夫。家康の父"],["徳川家康","於大の子。母方の実家が水野家"]],"deep":["水野忠政は1533年ごろ、衣浦湾の対岸に刈谷城をきずいて本拠を移したとされます。そのため於大の «生誕地は緒川»、«少女時代を過ごしたのは刈谷» と語られることが多く、東浦町と刈谷市の両方に於大ゆかりの場所があります。","水野氏と松平氏の縁組は、今川方の松平と、どちらにつくか揺れる水野が結んだ «保険» のような同盟でした。忠政の死（1543年）と信元の織田寄りへの転換が、そのまま於大の離縁につながっています。","於大が再婚した久松俊勝との間には3人の男子が生まれ、のちに家康は異父弟たちに松平の姓を与えました。久松松平家は伊予松山藩などの大名となり、明治まで続きます。","水野信元の死については、武田氏との内通を佐久間信盛が信長に訴えたためといわれますが、実際に内通していたかは確かではなく、諸説があります。","於大の法名 «伝通院» は、江戸・小石川の寺の名にもなりました。東京の伝通院には於大の墓があり、緒川の城跡とは約350km離れた母子の «つながり» を感じられます。","江戸時代、水野家は家康の母の実家として大切にされ、分家も含めて多くの大名を出しました。天保の改革で有名な老中・水野忠邦も、この水野一族の流れをくむ人物です。"],"look":["«緒川城址» の碑と説明板（住宅地の中）","水野家の菩提寺・乾坤院（歩いて行ける距離）","東浦町の於大公園と於大の像","衣浦湾の方向をながめ、対岸の刈谷との近さを実感する"],"q":["於大の方が生んだ、のちの天下人はだれ？","徳川家康（幼名・竹千代）。於大は家康が3歳のときに離縁され、母子は長く離ればなれになりました。"],"koji":[],"myth":"緒川城の築城年と築城者、於大が竹千代に品物を届け続けた話は伝承を含む。","img":["於大の方","水野信元","乾坤院"],"wp":"緒川城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c1/Aichi_ogawa_castle_01.jpg",3600,2400,"緒川城"],["c:8/87/%E4%BC%9D%E9%80%9A%E9%99%A2.jpg",1426,2686,"於大の方"],["c:9/9f/Kenkon-in_hondo_ac_%281%29.jpg",5956,3960,"乾坤院"]]},{"id":"23_teranobe_jo","n":"寺部城跡（家康の初陣）","yomi":"てらべじょうあと","cat":"城","rank":"B","y":1558,"era":["muromachi","edo"],"sh":"","ad":"豊田市寺部町","st":"名鉄三河線 豊田市駅から車で約10分（バスは本数が少ない）","la":35.1115,"lo":137.1705,"hook":"17歳の若武者・松平元康――のちの家康が、生まれて初めて戦場に立った城。","lead":"寺部城は、矢作川のほとりにあった鈴木氏の城です。1558年、今川義元の命令を受けた松平元康（のちの徳川家康）がこの城を攻めました。これが家康の «初陣»（はじめての戦い）です。江戸時代には旗本の渡辺家の陣屋が置かれました。","story":["1558年、駿府で人質として育った松平元康は、まだ17歳（数え年）でした。主君・今川義元から与えられた最初の大仕事は、今川から織田へ寝返った寺部城の鈴木日向守を討つことでした。«人質の少年に本当に戦ができるのか?» 家臣たちも固唾をのんで見守ったことでしょう。","寺部城は矢作川の東岸、川と台地を利用してきずかれた城でした。元康は城下に火を放って攻めたて、さらに周りの城にも兵を向けたと伝わります。細かな戦いの様子ははっきりしませんが、今川方の指揮官として無事に役目を果たしたことで、元康は «松平の若殿はなかなかやる» と評価されるようになりました。","この初陣には、あとの家康らしい話も伝わっています。城を落とすことにこだわらず、城下を焼いて相手の力を弱めたうえで、深追いせずに兵を引いた、というものです。『三河物語』などの記録では、元康が古参の家臣の意見に耳を傾けた様子が語られます。«一人で決めず、経験者の知恵を借りる»。のちの天下人の用心深さの始まりだったのかもしれません。","戦国の城としての寺部城はやがて役目を終えますが、江戸時代になると、この地に «槍の半蔵» と呼ばれた渡辺守綱の子孫が旗本として陣屋を構えました。守綱は家康に仕えた猛将で、寺部渡辺家は尾張藩の重臣として幕末まで続きました。家康の初陣の地が、家康の家臣の子孫に受けつがれたのです。","今の寺部城跡は、石垣の一部や土地の高低差に面影を残すだけですが、矢作川の流れを見下ろすと、若き元康が川を越えて攻め寄せた光景が浮かびます。周辺には渡辺家ゆかりの寺もあり、戦国から江戸へと移る三河の歴史をたどることができます。"],"tl":[["戦国時代","鈴木氏が寺部城を本拠とする"],["1558年","松平元康（家康）が今川方として寺部城を攻める（初陣）"],["1560年","桶狭間の戦い。元康は岡崎城に戻り独立へ"],["江戸時代初め","渡辺守綱の子孫が寺部に陣屋を置く"],["1868年","明治維新。陣屋の時代が終わる"]],"who":[["徳川家康（松平元康）","この城を攻めたのが初陣"],["今川義元","元康に寺部攻めを命じた主君"],["鈴木日向守","寺部城主。織田方に寝返り攻められた"],["渡辺守綱","«槍の半蔵»。子孫が寺部で陣屋を営む"]],"deep":["家康の初陣の年は1558年（永禄元年）とするのが一般的ですが、月日や細かな経過は史料によって異なり、はっきりしません。","寺部城主の名は «鈴木日向守重辰» とされることが多いものの、系譜には混乱があり、人物の特定には諸説があります。三河の鈴木氏は足助・酒呑などにも分家があった一族です。","«服部半蔵» と並べて語られる «槍の半蔵» 渡辺守綱は、三河一向一揆では一揆方についたのち、家康のもとに戻った経歴をもちます。寺部渡辺家は尾張徳川家の付家老に次ぐ重臣として約1万石の格を持ったといわれます。","寺部の陣屋跡には堀や石垣の一部が残るとされ、地元では «寺部城» と «寺部陣屋» の遺構が重なって語られます。どこまでが戦国期の城でどこからが江戸期の陣屋かは、発掘で確かめきれていない部分があります。","初陣の相手が «今川から織田へ寝返った城» だった点は象徴的です。わずか2年後、元康自身が桶狭間の後に今川から離れ、織田と手を結ぶことになるからです。","豊田市は昔 «挙母» と呼ばれ、寺部はその北の矢作川沿い。川は物資を運ぶ大動脈で、ここを押さえることは西三河の支配に直結していました。"],"look":["寺部城跡の碑と説明板","陣屋時代の石垣・堀の名残","矢作川の堤防からのながめ（攻め手の目線で）","渡辺家ゆかりの寺院"],"q":["家康の初陣は何歳のとき？","数え年で17歳（1558年）。今川方の武将として寺部城を攻めました。"],"koji":[{"w":"初陣","m":"武士がはじめて戦いに出ること。その人の将来を占う大切な場とされた"}],"myth":"初陣の具体的な戦いぶり、城主の名、古参の意見を聞いた逸話は史料によって違いがある。","img":["徳川家康","渡辺守綱","今川義元"],"wp":"寺部城","rel":{"ev":[],"grave":[]},"ph":[["c:a/ae/Toyota_terabe_castle_01.jpg",4592,3056,"寺部城"],["c:d/d9/Shukouji4.jpg",6000,4005,"渡辺守綱"],["c:1/10/ImagawaYoshimoto.jpg",600,675,"今川義元"]]},{"id":"23_kogetsuin","n":"高月院（松平親氏の墓）","yomi":"こうげついん","cat":"墓所","rank":"B","y":1367,"era":["muromachi","edo"],"sh":"国指定史跡（松平氏遺跡の一部）","ad":"豊田市松平町寒ケ入","st":"名鉄豊田市駅からとよたおいでんバスで «松平郷» 下車、歩いて約10分","la":35.106,"lo":137.261,"hook":"山あいの小さな寺に眠るのは、徳川家のいちばん最初のご先祖さま。","lead":"高月院は、豊田市の山里・松平郷にある浄土宗のお寺です。徳川家（松平家）の始まりとされる松平親氏と、その子・泰親のお墓があります。江戸時代には徳川将軍家から大切にされ、今の山門と本堂は3代将軍家光のときに建て直されたものと伝わります。","story":["豊田市の中心から東へ、山道を分け入った先に松平郷はあります。棚田と杉林にかこまれた静かな里。ここが、江戸幕府を開いた徳川家の «ふるさと» です。その一番奥、ゆるやかな石段を登った先に高月院があります。","寺の始まりは南北朝時代の1367年、この地の領主・足助重政が建てた «寂静寺» だと伝わります。やがてこの里に、一人の旅の僧が流れつきました。名を徳阿弥。«自分は新田氏の子孫だ» と名乗る男は、里の有力者・松平太郎左衛門の婿となり、還俗して松平親氏と名のります。これが、のちの徳川家の祖とされる人物です。","親氏は寺を大切にし、自分の菩提寺としたと伝わります。«なぜ旅の僧が一族の祖になれたの?» 答えははっきりしません。けれど、親氏と子の泰親は周りの土地を広げ、松平家を西三河の有力な家へと育てました。その8代あとに生まれたのが家康です。","江戸時代、将軍家は «始まりの地» の寺を手厚く守りました。1641年、3代将軍家光の命で山門や本堂が建て直され、寺には朱印地が与えられます。門や本堂に輝く «三つ葉葵» の紋は、ここが将軍家とつながる特別な寺である証でした。","本堂の裏手には、親氏と泰親の墓と伝わる宝篋印塔がひっそりと並んでいます。天下を治めた一族の祖先の墓とは思えないほど、小さく素朴な石の塔です。石段の上からふり返ると、山にかこまれた松平の里が見わたせます。大きな歴史の «一滴目» が、この静かな谷から流れ出したのです。"],"tl":[["1367年","足助重政が寂静寺（のちの高月院）を開いたと伝わる"],["14世紀後半","徳阿弥（松平親氏）が松平郷に入ったと伝わる"],["室町時代","親氏が寺を菩提寺とし、高月院と呼ばれるようになる"],["1543年","8代あとの子孫として徳川家康が生まれる"],["1641年","家光の命で山門・本堂などが建て直される"],["1868年","明治維新。寺領を失うが寺は続く"]],"who":[["松平親氏","徳川家の祖とされる人物。墓がある"],["松平泰親","親氏の子（弟とも）。一族の勢力を広げた"],["足助重政","寺を開いたと伝わる領主"],["徳川家光","3代将軍。建物の再建を命じた"]],"deep":["親氏と泰親の関係は «親子» とする説と «兄弟» とする説があり、はっきりしません。さらに親氏の生年・没年も史料によって大きく食い違います。","«新田氏の子孫・得川（世良田）の流れ» という家系の話は、家康が朝廷から官位を得るために整えたものと考える研究者が多く、そのままの事実とはされていません。","松平郷には高月院のほか、松平東照宮（松平氏館跡）や、親氏が掘ったと伝わる井戸などが近くにあります。«松平氏遺跡» として、関連する場所がまとめて国の史跡に指定されています。","高月院の山門や本堂には、将軍家ゆかりを示す葵の紋がつけられています。寺は浄土宗で、徳川家の宗旨とも一致します（徳川家の菩提寺として有名な増上寺や大樹寺も浄土宗）。","墓とされる宝篋印塔の形式から、造られた時代は室町時代と考えられますが、本当に親氏・泰親その人の墓かどうかは確かめられていません。","松平家は «十八松平» と呼ばれるほど多くの分家に分かれました。その中で安城松平家が主流となり、清康・広忠・家康へとつながっていきます。"],"look":["家光が再建したと伝わる山門と三つ葉葵の紋","本堂裏の松平親氏・泰親の墓（宝篋印塔）","石段の上から見る松平郷の里山","近くの松平東照宮と松平郷館もあわせて"],"q":["徳川家の祖とされる松平親氏は、もともとどんな人だったと伝わる？","旅の僧（徳阿弥）。松平郷の有力者の婿になり、還俗して親氏と名のったと伝わります。"],"koji":[],"myth":"親氏の出自（新田氏の子孫とする話）や寺の創建年は伝承。親氏・泰親の続柄にも諸説。","img":["松平親氏","松平氏遺跡","松平郷"],"wp":"高月院","rel":{"ev":[],"grave":[]},"ph":[["c:e/ee/Kogetsu-in_Temple_Hondou%2C_Matsudaira-cho_Toyota_2019.jpg",1500,1000,"高月院"],["c:a/a2/%E6%9D%BE%E5%B9%B3%E5%A4%AA%E9%83%8E%E5%B7%A6%E8%A1%9B%E9%96%80%E8%A6%AA%E6%B0%8F.jpg",3024,4032,"松平親氏"]]},{"id":"23_iga_hachimangu","n":"伊賀八幡宮（松平家の氏神）","yomi":"いがはちまんぐう","cat":"寺社","rank":"B","y":1470,"era":["muromachi","edo"],"sh":"国の重要文化財（社殿）","ad":"岡崎市伊賀町東郷中","st":"名鉄東岡崎駅からバスで約10分、«伊賀八幡宮» 下車すぐ","la":34.9725,"lo":137.168,"hook":"蓮池にかかる朱の橋、その先にきらめく社殿。松平・徳川家が代々、戦の前に祈った «勝ち運の神社»。","lead":"伊賀八幡宮は、松平家4代目の松平親忠が、一族の守り神としてまつった神社です。家康も大事な戦の前にお参りしたと伝わります。今の社殿は3代将軍家光のころに整えられ、本殿・拝殿・随身門などが国の重要文化財になっています。","story":["岡崎の町の北、伊賀川のそばに、鮮やかな朱色の社殿が建っています。池には蓮の葉が浮かび、石の太鼓橋がかかる。夏には蓮の花が咲き、橋の向こうの随身門が水面にうつります。ここが松平・徳川家の «氏神» 伊賀八幡宮です。","室町時代の中ごろ、松平家4代目の親忠は、岡崎の周りへ勢力を広げていました。一族を守る神をまつろうと、伊賀国（今の三重県）の八幡宮から神を迎えたのが始まりと伝わります。«なぜわざわざ伊賀から?» はっきりした理由はわかっていませんが、この地が «伊賀町» と呼ばれるのはその縁だといわれます。","時は流れ、松平家から生まれた家康は、大きな戦いの前にこの神社で勝利を祈ったと伝わります。関ヶ原の戦いの前にも祈願したという話があり、勝つたびに «伊賀八幡のおかげ» と信じられるようになりました。","家康が亡くなり «東照大権現» としてまつられると、伊賀八幡宮にも家康が合わせてまつられました。1636年ごろ、3代将軍家光の命で社殿が大きく造りかえられ、今に残る華やかな姿になります。極彩色の彫刻や金の飾り金具は、日光東照宮と同じ時代の美意識を感じさせます。","境内には、随身門、透塀、そして本殿・幣殿・拝殿がつながった建物が並びます。どれも江戸時代初めの貴重な建築で、国の重要文化財です。今でも受験生やスポーツ選手が «勝ち運» を求めて訪れます。500年以上前に松平の殿さまが願った «一族の勝利» の祈りは、形を変えて今も続いているのです。"],"tl":[["1470年ごろ","松平親忠が伊賀国から八幡神を迎えてまつったと伝わる"],["戦国時代","松平家の氏神として崇敬される"],["1600年","家康が関ヶ原の前に祈願したと伝わる"],["1636年ごろ","家光の命で社殿が大きく造営される"],["江戸時代","家康（東照大権現）もあわせてまつられる"],["明治以降","社殿の多くが国の重要文化財に指定される"]],"who":[["松平親忠","松平家4代。神社を創建したと伝わる"],["徳川家康","戦の前に勝利を祈ったと伝わる"],["徳川家光","3代将軍。社殿を大きく造営"]],"deep":["創建年は1470年（文明2年）ごろとされますが、はっきりした記録は少なく、伝承の部分があります。","本殿・幣殿・拝殿が一つにつながった形は «権現造» とも呼ばれる形式で、日光東照宮などと共通します。江戸幕府が整えた神社建築の特徴がよく表れています。","重要文化財には社殿のほか、随身門、透塀、神橋などが含まれます。池にかかる石造の «神橋» も江戸時代のものです。","境内の蓮池は夏に見ごろを迎え、朱塗りの随身門と蓮のとり合わせは岡崎を代表する風景の一つです。","近くには松平家の菩提寺・大樹寺があり、大樹寺の山門から岡崎城が見通せるように町が設計されたと伝わる «ビスタライン» も有名です。伊賀八幡宮と合わせて «家康の岡崎» をめぐれます。","家康が戦のたびに参拝したという話や、関ヶ原前の祈願などは神社の由緒として伝わるもので、同時代の記録で確かめられるものは多くありません。"],"look":["蓮池と石造の神橋、朱の随身門のながめ","極彩色の彫刻が施された本殿・幣殿・拝殿","透塀の細かな装飾","夏（7月ごろ）の蓮の花"],"q":["伊賀八幡宮の名前の «伊賀» はどこから来た？","松平親忠が伊賀国（今の三重県）の八幡宮から神を迎えたことに由来すると伝わります。"],"koji":[],"myth":"創建の経緯・年代、家康の戦勝祈願の具体的な場面は神社の伝承による部分が大きい。","img":["松平親忠","権現造"],"wp":"伊賀八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:3/3f/Igahachimangu.jpg",3948,5922,"伊賀八幡宮"]]},{"id":"23_jokoji","n":"定光寺（尾張藩祖徳川義直の廟所）","yomi":"じょうこうじ","cat":"墓所","rank":"B","y":1650,"era":["muromachi","edo"],"sh":"国の重要文化財（本堂・源敬公廟）","ad":"瀬戸市定光寺町","st":"JR中央本線 定光寺駅から歩いて約30分（坂道。車が便利）","la":35.262,"lo":137.062,"hook":"尾張徳川家の初代・義直が «ここに眠りたい» と選んだ、山深い禅寺。","lead":"定光寺は、瀬戸市の山の中にある臨済宗の古いお寺です。尾張藩の初代藩主・徳川義直（家康の九男）がこの寺を気に入り、亡くなったあと寺の奥に «源敬公廟» がつくられました。本堂と廟は国の重要文化財です。","story":["庄内川が山あいを深く削る玉野渓谷。その上の山の中腹に、定光寺はあります。紅葉のころには参道が赤く染まり、名古屋の中心から電車で30分ほどとは思えない静けさです。","寺の始まりは南北朝時代の1336年、覚源禅師が開いたと伝わります。本堂（無為殿）は室町時代に建てられた禅宗様の建物で、屋根の反りやこまかな木組みに、中世の禅寺らしい美しさがあります。","江戸時代の初め、尾張藩初代藩主の徳川義直は、この辺りへ鷹狩りに来た折に寺を訪れ、景色をたいへん気に入ったといわれます。«この地に葬ってほしい» 1650年、義直が江戸で亡くなると、その願いのとおり定光寺の奥に廟がつくられました。","廟への道は長い石段です。その先の «源敬公廟» は、石と瓦を多く用いた、どこか中国風の重々しい造りです。義直は儒学を深く学び、明から来た学者とも交流しました。廟の形には、儒教の考え方が表れているといわれます。«なぜ日光のような派手な霊廟ではないの?» それは、学問を重んじた義直らしい選択だったのかもしれません。","義直は、名古屋城の城主として尾張藩の基礎を固め、学問所を開き、多くの書物を集めた人物でした。その蔵書は今、名古屋の蓬左文庫に伝わっています。山の上の廟に立つと、静かに眠る殿さまの人柄が伝わってくるようです。"],"tl":[["1336年","覚源禅師が定光寺を開いたと伝わる"],["室町時代","本堂（無為殿）が建てられる"],["1607年","徳川義直が尾張の領主となる（のち名古屋城へ）"],["1650年","義直が亡くなり、遺言により定光寺に葬られる"],["1652年","源敬公廟が完成"],["現代","本堂・源敬公廟が国の重要文化財に"]],"who":[["徳川義直","尾張藩初代藩主・家康の九男。廟に眠る"],["覚源禅師（平心処斉）","寺を開いたと伝わる禅僧"],["陳元贇","明から来た文化人。義直に仕え、廟の造営に関わったといわれる"]],"deep":["義直の諡（おくりな）は «源敬公»。そのため廟を «源敬公廟» と呼びます。廟の建築は、焼香殿・唐門などが連なる構成です。","廟の造営に、明から亡命してきた陳元贇が関わったという話が伝わり、中国風の意匠の理由として語られます。ただし関与の程度には諸説があります。","本堂（無為殿）は室町時代の禅宗様建築で、明治以降に修理を受けています。尾張・三河の中でも数少ない中世の禅宗仏殿の一つです。","義直は儒学を重んじ、名古屋城内に孔子をまつる聖堂を設けたとされます。儒教では «質素で礼にかなった墓» が理想とされ、廟の落ち着いた造りと重なります。","定光寺は尾張藩主の菩提寺である建中寺（名古屋市東区）とは別の寺です。義直だけが遺言で定光寺に葬られ、2代光友以降の多くは建中寺などに葬られました。","定光寺駅は、庄内川の渓谷の上にホームが張り出した珍しい駅として知られ、鉄道ファンにも人気があります。"],"look":["室町時代の本堂（無為殿）の屋根の反り","石段の上の源敬公廟と唐門","秋の紅葉に染まる参道","JR定光寺駅と玉野渓谷のながめ"],"q":["定光寺に眠る尾張藩の初代藩主はだれ？","徳川義直（家康の九男）。«源敬公» と呼ばれ、遺言でこの寺に葬られました。"],"koji":[],"myth":"義直が鷹狩りで寺を気に入った話、陳元贇の廟造営への関与は伝承・諸説。","img":["徳川義直","尾張藩"],"wp":"定光寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/13/J%C5%8Dk%C5%8Dji_hond%C5%8D_Seto.JPG",2400,1800,"定光寺"],["c:9/93/Tokugawa_Yoshinao.jpg",808,657,"徳川義直"]]},{"id":"23_seishuji","n":"政秀寺（平手政秀の諫死）","yomi":"せいしゅうじ","cat":"墓所","rank":"B","y":1553,"era":["muromachi","azuchi","edo"],"sh":"","ad":"名古屋市中区栄3丁目","st":"地下鉄 栄駅・矢場町駅から歩いて約5〜8分","la":35.1648,"lo":136.9028,"hook":"«うつけ» と呼ばれた若き信長をいさめ、自ら命を絶った守り役。その死をいたんで、信長が建てた寺。","lead":"政秀寺は、織田信長が守り役・平手政秀の菩提をとむらうために建てたお寺です。政秀は1553年に自ら命を絶ち、それは信長の行いをいさめるためだったと伝えられてきました。寺はのちに名古屋へ移り、今は栄のビル街の中に政秀の墓があります。","story":["名古屋いちばんのにぎやかな街、栄。デパートやオフィスビルのすき間に、静かな山門があります。ここが政秀寺。境内に入ると車の音が遠のき、奥には一人の武将の墓が立っています。平手中務丞政秀、若き日の織田信長を育てた «守り役»（傅役）です。","政秀は信長の父・織田信秀に仕えた重臣で、外交にも力を発揮しました。美濃の斎藤道三の娘・濃姫と信長の縁組をまとめたのも政秀だといわれます。けれど、その信長は «大うつけ»。髪を茶せんのように結い、腰に縄を巻き、町で柿や瓜をかじって歩く。父の葬儀では位牌に抹香を投げつけた――『信長公記』には、そんな姿が書き残されています。","1553年、政秀は自ら命を絶ちました。«殿、どうか行いを改めてくだされ» ――命をかけて主君をいさめた «諫死» だったと、後の世では語られてきました。一方で『信長公記』は、政秀の長男と信長が馬をめぐって仲たがいしていたことも記していて、本当の理由ははっきりしません。«なぜ政秀は死を選んだのか?» 今も議論が続いています。","信長は政秀の死を深く悲しみ、沢彦宗恩という禅僧を開山に招いて、政秀のための寺を建てました。寺の名は «政秀寺»。家臣の名前をそのまま寺の名にするのは珍しいことで、信長の思いの深さが伝わります。はじめは小木村（今の小牧市）にあり、のち清須を経て、江戸時代の初めの «清須越し» で名古屋に移りました。","信長が天下へ駆け上がっていく姿を、政秀は見ることができませんでした。それでも、«うつけ» の奥にある才能を信じ、最後まで見守った人がいたのです。ビル街にひっそりと残る墓は、主君と家臣の不思議な絆を今に伝えています。"],"tl":[["1534年","織田信長が生まれる。のちに平手政秀が守り役となる"],["1549年ごろ","政秀の仲立ちで信長と濃姫（帰蝶）の縁組が成ったとされる"],["1552年","父・織田信秀が亡くなる（年には諸説）"],["1553年","平手政秀が自害する"],["1553年ごろ","信長が沢彦宗恩を開山として政秀寺を建てる"],["1610年代","清須越しにともない名古屋へ移る"]],"who":[["平手政秀","信長の守り役。墓がある"],["織田信長","政秀の死をいたみ寺を建てた"],["沢彦宗恩","政秀寺の開山となった禅僧"],["織田信秀","信長の父。政秀が仕えた"]],"deep":["政秀の死の理由について、『信長公記』は信長の «不行儀» と、政秀の長男・五郎右衛門と信長の馬をめぐる不和の両方を記しています。«諫死» は後世に強調された見方ともいわれます。","開山の沢彦宗恩は、のちに信長に «岐阜» の地名や «天下布武» の印を進言したという話で有名です。ただしこれらは寺の伝承などによるもので、確かな同時代史料は乏しいとされます。","«清須越し» は、徳川家康が1610年ごろから名古屋城をきずくにあたり、清須の町を寺社・町人ごと名古屋に移した大移転です。政秀寺もその一つでした。","現在の政秀寺は太平洋戦争の空襲で被害を受け、戦後に再建されています。境内の墓や碑も、戦災をくぐりぬけたものと再建されたものが混じっています。","平手政秀は外交役として京都とのつながりも持っていたとされ、公家の山科言継の日記『言継卿記』には、政秀の屋敷の立派さに驚いた記述があります。","政秀寺のある栄3丁目のあたりは、江戸時代には寺が並ぶ地域でした。戦後の都市計画で周囲は大きく変わりましたが、寺の位置は受け継がれています。"],"look":["ビル街に残る山門と境内の静けさ","平手政秀の墓","信長と政秀の関係を伝える寺の由緒書き","近くの大須や万松寺（信長の父・信秀の菩提寺）もあわせて"],"q":["政秀寺の名前は、だれの名前からつけられた？","信長の守り役・平手政秀。家臣の名がそのまま寺の名になった珍しい例です。"],"koji":[{"w":"諫死（かんし）","m":"死をもって主君の過ちをいさめること"}],"myth":"政秀の自害が «諫死» だったかは諸説。沢彦が «岐阜»«天下布武» を進言した話も伝承。","img":["平手政秀","沢彦宗恩","清洲越し"],"wp":"政秀寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/14/Seishuji.jpg",6016,4016,"政秀寺"],["c:2/26/Statue_of_Hirate_Masahide.jpg",1788,1330,"平手政秀"],["c:5/56/Ngy_csl_from_kys_csl.jpg",3872,2592,"清洲越し"]]},{"id":"23_owari_kokubunji","n":"尾張国分寺跡","yomi":"おわりこくぶんじあと","cat":"遺跡","rank":"B","y":750,"era":["nara","heian"],"sh":"国指定史跡","ad":"稲沢市矢合町","st":"名鉄 国府宮駅から車で約10分（JR稲沢駅からも車で約10分）","la":35.233,"lo":136.765,"hook":"田んぼの中に残る巨大な礎石。ここには、奈良の都が全国に建てさせた «国の寺» がそびえていた。","lead":"尾張国分寺跡は、奈良時代に聖武天皇の命令で建てられた尾張国の国分寺の跡です。塔の礎石などが残り、国の史跡に指定されています。今は建物はなく、広い土地に «ここに寺があった» ことを伝える礎石と碑が残っています。","story":["奈良時代、日本は病気の流行や飢え、反乱に苦しんでいました。聖武天皇は «仏の力で国を守ろう» と考え、741年、全国の国ごとに寺を建てるよう命じます。それが国分寺（僧寺）と国分尼寺です。尾張国にも、その命を受けて大きな寺が建てられました。","寺が建てられたのは、今の稲沢市矢合町のあたり。近くには尾張の国府（今の県庁のような役所）があり、国府宮の名で知られる尾張大国霊神社もそばにあります。«なぜここに?» 国分寺は、都から派遣された役人のいる国府の近くに置かれるのがふつうでした。尾張の政治と信仰の中心が、この平野に集まっていたのです。","国分寺には、金堂や講堂、そして七重塔がそびえていたと考えられています。国分寺の塔は高さ60m近くあったともいわれ、平らな濃尾平野では遠くからでも見えたことでしょう。発掘では塔の土台や金堂の跡が見つかり、塔の心礎をはじめとする大きな礎石が今も残っています。","けれど、寺の栄華は長く続きませんでした。平安時代の884年、尾張国分寺が焼けたことが記録に残り、その役目は別の寺に移されたとされます。律令の仕組みがゆるみ、国の寺を支える力も弱まっていったのです。やがて建物は失われ、跡地は田畑になりました。","今、史跡には礎石と説明板が静かに置かれています。重さ何トンもありそうな石の上に、かつては太い柱が立ち、瓦ぶきの屋根が空を切っていました。石に触れて見上げると、1200年以上前、都から遠く離れたこの地で国家の平和を祈った人々の姿が想像できます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","尾張国分寺が建てられる"],["884年","尾張国分寺が焼失し、ほかの寺に国分寺の役目が移されたとされる"],["中世","跡地は寺としての姿を失い、田畑となる"],["近代以降","国の史跡に指定され、発掘調査が行われる"]],"who":[["聖武天皇","国分寺建立を命じた天皇"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立を後押ししたといわれる"],["行基","各地で布教し、大仏造立に協力した僧（国分寺と直接の関係は不明）"]],"deep":["国分寺の正式な名は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺»。お経の力で国を守るという考え方が名前に込められています。","884年の焼失と、国分寺の役目が別の寺（愛智郡の願興寺とされる）に移ったことは『日本三代実録』に記録があると考えられています。移転先の寺の場所については議論があります。","尾張国分寺跡では、塔跡・金堂跡・講堂跡などの位置が発掘で推定されています。伽藍配置は «国分寺式»（中門・金堂・講堂が一直線に並び、塔が東側に離れる型）だったと考えられています。","国分尼寺の跡は、僧寺からやや離れた場所にあったと推定されていますが、確定していません。","近くの尾張大国霊神社（国府宮）は、はだか祭で有名な尾張の総社です。国府・国分寺・総社がそろう稲沢は、古代尾張の «首都» でした。","国分寺の塔の高さを «60m近く» とするのは、東大寺の七重塔の記録などからの推定で、尾張国分寺の塔の本当の高さはわかっていません。"],"look":["塔跡の礎石（心礎を含む大きな石）","史跡の説明板と伽藍の配置図","周りの平野の広さ（塔が遠くから見えた景色を想像）","近くの尾張大国霊神社（国府宮）"],"q":["国分寺の建立を全国に命じた天皇はだれ？","聖武天皇（741年）。国ごとに国分寺と国分尼寺を建てさせました。"],"koji":[],"myth":"塔の高さ、移転先の寺の場所は推定・諸説。","img":["国分寺","聖武天皇","尾張大国霊神社"],"wp":"尾張国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/cc/Owari-kokubunji_hondou.JPG",6016,4000,"尾張国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"],["c:9/97/Konomiya-jinja_Hall_of_Worship_ac_%281%29.jpg",5956,3960,"尾張大国霊神社"]]},{"id":"23_aotsuka_kofun","n":"青塚古墳（犬山の前方後円墳）","yomi":"あおつかこふん","cat":"遺跡","rank":"B","y":350,"era":["kofun"],"sh":"国指定史跡","ad":"犬山市青塚","st":"名鉄小牧線 楽田駅から歩いて約20分","la":35.3285,"lo":136.966,"hook":"全長約123m。尾張で2番目に大きな前方後円墳に、4世紀の王が眠る。","lead":"青塚古墳は、犬山市にある古墳時代前期（4世紀ごろ）の前方後円墳です。全長は約123mで、尾張の古墳の中では2番目の大きさ。表面の葺石が復元され、そばのガイダンス施設で古墳のことを学べます。","story":["犬山市の南の田園地帯に、こんもりとした緑の丘があります。近づくと、それが «鍵穴» の形をしているのがわかります。青塚古墳、全長約123mの前方後円墳です。1600年以上前、この地をおさめた王のために、たくさんの人が土を運び、石を積んできずきました。","古墳の表面は、河原石でびっしりとおおわれていました。これを葺石といいます。«なぜ石でおおったの?» 雨で土が流れるのを防ぐためと、白く光る石で遠くからも古墳を目立たせるためだと考えられています。今は一部が復元され、当時の姿がよみがえっています。","発掘調査では、壺の形をした埴輪がたくさん見つかりました。ふつうの円筒埴輪ではなく、壺をかたどった埴輪が古墳のまわりに並べられていたのです。こうした特徴から、古墳は4世紀の中ごろから後半につくられたと考えられています。尾張で最大の断夫山古墳（名古屋市熱田区）より100年以上古い、地域の «大王» の墓です。","すぐ近くには大縣神社があり、古くから古墳は神社の祭神とゆかりのある人の墓だと語られてきました。«青塚» の名も、古墳をおおう木々の緑からついたといわれます。長い間、地元の人々は古墳を大切に守り、その姿を今に伝えてきました。","古墳のわきの «青塚古墳ガイダンス施設» では、出土した埴輪や古墳のつくり方がわかりやすく展示されています。墳丘の上に登ると、濃尾平野と遠くの山々が見わたせます。4世紀の王も、きっとこの景色を自分の国として見下ろしていたのでしょう。"],"tl":[["4世紀中ごろ〜後半","青塚古墳がつくられる"],["江戸時代","古墳は大縣神社ゆかりの塚として守られる"],["1983年","国の史跡に指定"],["平成時代","発掘調査と墳丘の整備。葺石の一部を復元"],["2000年代","ガイダンス施設が開館"]],"who":[["古墳の主（名前は不明）","4世紀に尾張北部をおさめた首長"],["大縣神社の祭神","古墳とゆかりがあると伝わる"],["尾張氏","古代尾張の有力豪族（青塚との直接の関係は不明）"]],"deep":["墳丘は前方部と後円部で段の数が違い、後円部は3段、前方部は2段につくられていたと考えられています。","«壺形埴輪» は、古墳時代前期に多い埴輪の形式で、東海地方の前期古墳によく見られます。青塚の年代を決める大きな手がかりになりました。","尾張最大の前方後円墳・断夫山古墳（全長約151m）は6世紀前半とされ、尾張氏の首長墓と考えられています。青塚は、それより古い時代の尾張北部の実力者の墓です。","大縣神社は尾張国二宮とされる古い神社で、青塚古墳を神社の祭神の墓とする伝承があります。ただし、考古学的に祭神と結びつける証拠はありません。","周りにはかつて小さな古墳もあったとされ、青塚を中心とする古墳群だったと考えられますが、多くは開発で失われました。","古墳の後円部の埋葬施設（棺を納めた場所）は発掘されておらず、どんな副葬品が眠っているかはわかっていません。"],"look":["復元された葺石の斜面","墳丘の上から見る濃尾平野","ガイダンス施設の壺形埴輪の展示","近くの大縣神社"],"q":["青塚古墳のまわりに並べられていた、特徴的な埴輪の形は？","壺の形をした «壺形埴輪»。古墳時代前期によく見られる形です。"],"koji":[],"myth":"古墳の主を大縣神社の祭神ゆかりの人物とするのは伝承。","img":["前方後円墳","大縣神社"],"wp":"青塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:2/20/%C5%8Cagata-jinja_Haiden.jpg",2048,1536,"大縣神社"]]},{"id":"23_umakoshi_nagahizuka","n":"馬越長火塚古墳（東三河の首長墓）","yomi":"まごしながひづかこふん","cat":"遺跡","rank":"B","y":590,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"豊橋市石巻本町","st":"JR豊橋駅から車で約20分（公共交通は不便）","la":34.7905,"lo":137.452,"hook":"全長約70mの石の «部屋»。東三河の王が最後に選んだ、国内でも指折りの巨大な横穴式石室。","lead":"馬越長火塚古墳は、豊橋市の石巻山のふもとにある6世紀末ごろの前方後円墳です。全長約70mで、中には長さ約17mの大きな横穴式石室があります。金色に輝く馬具などが見つかり、東三河をおさめた首長の墓と考えられています。","story":["豊橋市の北東、石灰岩の山・石巻山を望むふもとに、馬越長火塚古墳はあります。6世紀の終わりごろ、ここに一人の首長がほうむられました。その墓は全長約70mの前方後円墳。«前方後円墳の時代» が終わろうとするころ、東三河でつくられた最後の大きな前方後円墳の一つです。","古墳の中には、大きな石を積み上げてつくった横穴式石室があります。長さは約17m。入口から奥の部屋まで、大人が何人も並んで歩けるほどの広さです。«なぜこんなに大きな部屋をつくったの?» 横穴式石室は、あとから家族をほうむることができる «家族の墓» でもあり、その大きさは首長の力を見せつけるものでした。","石室からは、金の飾りのついた馬具や、きらびやかな大刀の飾りなどが見つかりました。馬具は、首長が馬に乗って人々の前に現れたときの姿を物語ります。金や銅でかざられた品々は、ヤマト王権ともつながる力をもった人物だったことを示しています。","古代の東三河は «穂の国» と呼ばれ、穂国造という豪族がおさめていたと伝わります。馬越長火塚古墳の主は、その穂の国の王だったのではないかと考えられています。«豊橋» の «穂» の字に、その名残を感じる人もいます。","古墳のまわりには、少し小さな古墳もいくつか残り、«馬越長火塚古墳群» と呼ばれています。前方後円墳のあとに、一族の墓が円墳などの形で続いていきました。石巻山の姿を背に、何世代にもわたる首長たちが眠るこの地は、東三河の古代史を語る大切な場所です。"],"tl":[["6世紀末〜7世紀初め","馬越長火塚古墳がつくられる"],["7世紀","周辺に大塚南古墳などが続いてつくられる"],["2000年代","豊橋市が発掘調査を行い、石室や出土品の全体像が明らかになる"],["2014年ごろ","古墳群が国の史跡に指定される"],["その後","出土品が国の重要文化財に指定される"]],"who":[["古墳の主（名前は不明）","東三河（穂の国）をおさめた首長と考えられる"],["穂国造","古代の東三河をおさめたと伝わる豪族"]],"deep":["横穴式石室の全長約17mは、東海地方でも最大級です。石室は奥の «玄室» と入口側の «羨道» に分かれ、大きな石を積み上げて天井を架けています。","出土した金銅装の馬具や装飾大刀は、当時の最高級品です。こうした品は、ヤマト王権から地方の有力者に与えられたと考えられています。","前方後円墳は6世紀の末ごろを最後に、全国でつくられなくなります。馬越長火塚古墳は、東三河における «最後の大型前方後円墳» の一つと位置づけられます。","«穂国造» は、平安時代にまとめられた『先代旧事本紀』の «国造本紀» に名前が見えます。ただし、古墳の主を穂国造と特定する証拠はありません。","古墳群には大塚南古墳や口明塚南古墳なども含まれ、前方後円墳から円墳へと墓の形が移り変わる様子が一か所でわかる点が評価されています。","«長火塚» という名の由来ははっきりしていません。"],"look":["前方後円墳の墳丘の形","横穴式石室の入口（公開は限られる）","背後にそびえる石巻山","豊橋市美術博物館などでの出土品の展示（開催時）"],"q":["馬越長火塚古墳の石室の長さはおよそ何m？","約17m。東海地方でも最大級の横穴式石室です。"],"koji":[],"myth":"古墳の主を穂国造とする説は推定。名の由来は不明。","img":["横穴式石室","穂国"],"wp":"馬越長火塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Magoshinagahizuka_Tomb.JPG",1408,1056,"馬越長火塚古墳"],["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"],["c:f/f9/ToyohashiSkyline03.jpg",1024,768,"穂国"]]},{"id":"23_ikawazu_kaizuka","n":"伊川津貝塚（抜歯・叉状研歯の縄文人骨）","yomi":"いかわづかいづか","cat":"遺跡","rank":"B","y":-800,"era":["jomon"],"sh":"","ad":"田原市伊川津町","st":"豊橋鉄道渥美線 三河田原駅から車で約15分","la":34.667,"lo":137.156,"hook":"前歯を抜き、前歯に «フォーク» の刻みを入れた人々。3000年前の縄文人は、何を伝えたかったのか。","lead":"伊川津貝塚は、渥美半島にある縄文時代の終わりごろの貝塚です。貝がらとともに、たくさんの縄文人の骨が見つかりました。歯を抜く «抜歯» や、前歯をフォークのように刻む «叉状研歯» のあとがあり、当時の風習を知る手がかりになっています。","story":["渥美半島の三河湾側、伊川津の海辺。今から3000年ほど前、ここには縄文人のむらがありました。人々は海で貝をとり、魚をつり、食べたあとの貝がらを一か所に捨てていきました。その貝がらの山が «貝塚» です。貝がらのカルシウムのおかげで、骨がとけずに残りやすく、貝塚は昔の暮らしの «タイムカプセル» になりました。","伊川津貝塚からは、たくさんの人の骨が見つかりました。その歯を調べると、ふしぎなことがわかります。健康な前歯や犬歯が、わざと抜かれているのです。これを «抜歯» といいます。«なぜ健康な歯を抜いたの?» 大人になる儀式や、結婚、家族が亡くなったときのしるしだったと考えられていますが、はっきりした答えはわかっていません。","さらに驚くのは、上の前歯の先を、フォークのように縦に刻んだ人がいることです。«叉状研歯» と呼ばれるこの加工は、とても珍しく、渥美半島や三河の貝塚で多く見つかっています。特別な役目をもつ人、たとえば祭りを担う人のしるしだったのではないか、ともいわれています。","貝塚からは、屈葬（手足を折り曲げた姿）でほうむられた人や、犬の骨も見つかっています。縄文人にとって犬は、狩りの仲間であり、家族のような存在でした。ていねいにほうむられた犬の骨は、人と動物のあたたかな関係を伝えています。","伊川津のまわりには、吉胡貝塚や保美貝塚など、縄文時代の大きな貝塚がいくつもあります。渥美半島は、海の恵みにあふれた «縄文人のふるさと» だったのです。貝塚の上に立って三河湾をながめると、3000年前と同じ潮の香りがしてきます。"],"tl":[["縄文時代後期〜晩期","伊川津に集落が営まれ、貝塚が形づくられる"],["大正時代","学者による発掘が行われ、人骨が見つかる"],["昭和時代","くり返し発掘調査が行われる"],["2010年ごろ","新たな発掘で多数の人骨が見つかる"]],"who":[["伊川津の縄文人","この地で暮らし、ほうむられた人々"],["吉胡貝塚の人々","近くの貝塚に暮らした同じ時代の人々"]],"deep":["«抜歯» は縄文時代後期〜晩期に西日本〜東海で広く見られる風習で、抜く歯の組み合わせにいくつかの型があります。型の違いが出身や所属集団を示すという説もあります。","«叉状研歯» は上の前歯に2〜3本の切れこみを入れるもので、三河地方の貝塚（伊川津・吉胡・稲荷山など）に特に多いとされています。","貝塚が人骨を残しやすいのは、貝がらのカルシウムが土の酸性を中和するからです。日本の酸性の土では、ふつう骨はほとんど残りません。","伊川津貝塚では、複数の人の骨をまとめて埋めた «盤状集骨葬» と呼ばれる埋葬例も知られています。いったん埋めた骨を掘り出して並べ直す «再葬» の一種と考えられています。","犬の埋葬は縄文時代の各地で見られます。弥生時代になると犬を食べた跡も見られるようになり、人と犬の関係の変化として注目されています。","近くの吉胡貝塚（国指定史跡）には史跡公園と資料館があり、渥美半島の縄文文化をまとめて学ぶことができます。"],"look":["貝塚があった場所と周りの地形（海からの距離）","三河湾のながめ","近くの吉胡貝塚史跡公園と資料館","田原市博物館などの展示（開催時）"],"q":["前歯をフォークのように刻む、縄文時代の珍しい風習を何という？","«叉状研歯»。三河の貝塚で多く見つかっています。"],"koji":[],"myth":"抜歯や叉状研歯の意味は推定で、確かな答えは出ていない。","img":["貝塚","縄文時代","吉胡貝塚"],"wp":"伊川津貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:3/3e/Yoshigo_kaizuka.JPG",6000,4000,"吉胡貝塚"]]},{"id":"23_sugoyama_jaana","n":"嵩山蛇穴（縄文草創期の洞窟遺跡）","yomi":"すせのじゃあな","cat":"遺跡","rank":"B","y":-10000,"era":["jomon"],"sh":"国指定史跡","ad":"豊橋市嵩山町","st":"JR豊橋駅から車で約30分（公共交通は不便。洞窟内は立入禁止）","la":34.806,"lo":137.496,"hook":"«大蛇がすむ» と恐れられた石灰岩の洞窟は、1万年以上前の人々の «すみか» だった。","lead":"嵩山蛇穴は、豊橋市の山あいにある石灰岩の洞窟遺跡です。縄文時代のはじめごろ（草創期〜早期）の土器や石器、動物の骨などが見つかり、国の史跡になっています。«蛇穴» の名は、大蛇がすむという言い伝えからついたといわれます。","story":["豊橋の東、静岡県との境に近い嵩山の里。昔の姫街道が本坂峠へ向かう山すそに、ぽっかりと口をあけた洞窟があります。地元では古くから «蛇穴» と呼ばれ、中には大蛇がすんでいると恐れられてきました。子どもたちは «近づいてはいけない» と言い聞かされたことでしょう。","ところが昭和の時代に学者たちが調べてみると、洞窟の土の中から、思いもよらないものが出てきました。とても古い形の土器のかけら、石でつくった矢じりや道具、そしてシカやイノシシなどの動物の骨です。«大蛇のすみか» は、じつは1万年以上前の人々のすみかだったのです。","縄文時代の草創期は、氷河時代が終わりに近づき、気候が大きく変わっていったころです。人々はまだ決まった村をつくらず、獲物を追って移動しながら暮らしていました。雨や風をしのげる洞窟や岩かげは、そんな人々にとって大切な «仮の家» でした。«なぜ洞窟を選んだの?» 石灰岩の洞窟は中が乾いていて、火をたけば冬でも暖かく過ごせたからだと考えられます。","洞窟の土は、何千年もの間に少しずつ積み重なっています。下の層ほど古く、上の層ほど新しい。その順番どおりに出てくる土器の形を比べることで、縄文時代のはじめの土器がどのように移り変わったかがわかります。嵩山蛇穴は、そんな «土器の年表» を読みとるための大切な遺跡なのです。","今は洞窟の中へは入れませんが、入口の近くには説明板が立っています。静かな山の中で耳をすますと、たき火を囲んで獲物を分け合う、はるか昔の家族の声が聞こえてくるようです。"],"tl":[["約1万数千年前","縄文時代草創期。洞窟が人に使われはじめる"],["縄文時代早期","引き続き洞窟が利用される"],["江戸時代","«蛇穴» として大蛇の伝説が語られる"],["昭和時代","発掘調査で土器・石器・動物骨が見つかる"],["昭和時代","国の史跡に指定"]],"who":[["縄文草創期の人々","洞窟を住まいや狩りの拠点として使った"],["地元の人々","«蛇穴» の伝説を語り継いできた"]],"deep":["洞窟は石灰岩が雨水や地下水で溶かされてできた «鍾乳洞» の一種です。嵩山のあたりは石灰岩の地層が広がり、近くの石巻山も石灰岩の山として知られます。","縄文草創期の遺跡は全国でも数が限られます。洞窟や岩陰の遺跡は、土の層が乱されにくく、時代の順番を確かめやすいのが強みです。","出土した土器には、縄文草創期〜早期の特徴をもつものが含まれるとされます。具体的な型式名や層ごとの内容は報告書で確認が必要です。","動物の骨からは、当時の人々がシカやイノシシなどを狩っていたことがうかがえます。洞窟は狩りの季節に使われた «キャンプ地» だった可能性もあります。","嵩山は、浜名湖の北を通る姫街道（本坂通）の宿場・嵩山宿があった場所です。1万年前の洞窟と江戸時代の街道が同じ里にあるのも面白いところです。","洞窟の奥行きなどの規模は資料によって書き方が異なり、はっきりとはいえません。"],"look":["洞窟の入口と石灰岩の岩肌（外から見学）","史跡の説明板","周辺の姫街道・嵩山宿の面影","遠くに見える石巻山"],"q":["嵩山蛇穴の «蛇穴» という名前の由来は？","洞窟に大蛇がすむという言い伝えから、といわれます。"],"koji":[],"myth":"大蛇の伝説は言い伝え。出土品の細かな年代・型式は専門の報告書で確認が必要。","img":["縄文時代","姫街道"],"wp":"嵩山蛇穴","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Susejaana.JPG",5184,3456,"嵩山蛇穴"],["c:4/49/%E6%9C%AC%E5%9D%82%E9%80%9A%E3%81%A8%E6%9D%B1%E6%B5%B7%E9%81%93.png",1088,972,"姫街道"]]},{"id":"23_sanage_yo","n":"猿投窯跡（古代の灰釉陶器）","yomi":"さなげようあと","cat":"遺跡","rank":"B","y":850,"era":["kofun","nara","heian"],"sh":"","ad":"瀬戸市南山口町（愛知県陶磁美術館）ほか、名古屋市東部〜豊田市・みよし市一帯","st":"リニモ 陶磁資料館南駅から歩いて約10分（愛知県陶磁美術館）","la":35.177,"lo":137.094,"hook":"平安の貴族が愛した «灰の釉(うわぐすり)» の器。そのふるさとは、名古屋の東の丘に広がる1000基をこえる窯の跡。","lead":"猿投窯は、名古屋市の東部から豊田市・みよし市・瀬戸市などに広がる、古代の焼き物の窯跡の集まりです。古墳時代から鎌倉時代ごろまで焼き物がつくられ、とくに平安時代の «灰釉陶器» は日本で最初の本格的な釉をかけた焼き物として知られます。","story":["名古屋の東に連なるなだらかな丘。今は住宅地や大学、公園が広がるこの一帯の地面の下には、千数百年前の窯の跡がびっしり眠っています。その数は1000基をこえるともいわれ、北にそびえる猿投山にちなんで «猿投窯» と呼ばれています。","古墳時代、朝鮮半島から «須恵器» という固い焼き物の技術が伝わりました。山の斜面にトンネルのような «あな窯» をつくり、高い温度で焼き上げる方法です。この丘には焼き物にぴったりの粘土と、燃料になる木がたっぷりありました。«なぜここで焼き物が栄えたの?» 土と木と、人の技がそろっていたからです。","やがて平安時代になると、猿投の職人たちは新しい焼き物を生み出します。窯の中で燃えた木の灰が器にかかると、とけてガラスのようなつやが出ることに気づいたのです。そこで、わざと植物の灰を器にかけて焼く «灰釉陶器» が生まれました。淡い緑色にかがやく器は、中国の青磁にあこがれた都の貴族たちに喜ばれました。","猿投の器は、都や各地の役所・寺へと運ばれ、東海地方は日本の焼き物づくりの中心になっていきます。のちに窯の技術は瀬戸や常滑へ受けつがれ、«せともの» という言葉が生まれるほどの一大産地へと育ちました。","窯跡の多くは開発で失われましたが、瀬戸市の愛知県陶磁美術館には、猿投窯の器や窯の構造がわかる展示があります。灰の釉のやわらかな緑を見つめると、1000年以上前、煙の立ちのぼる丘で火の番をしていた職人の姿が浮かんできます。"],"tl":[["5世紀ごろ","この地で須恵器の生産が始まる"],["8世紀","奈良時代。須恵器の大産地となる"],["9世紀","灰釉陶器の生産が本格化する"],["10〜11世紀","灰釉陶器が各地へ広まる"],["12世紀ごろ","釉をかけない «山茶碗» の生産へ移り変わる"],["昭和時代","開発に先立つ大規模な発掘調査が行われる"]],"who":[["猿投の陶工たち","名もなき職人たち。灰釉陶器を生み出した"],["平安の貴族たち","猿投の器を使った人々"]],"deep":["«灰釉陶器» は、人がわざと釉をかけた日本で最初の本格的な施釉陶器の一つとされます。奈良時代の «奈良三彩» などの鉛釉とは別の系統です。","窯の数を «1000基以上» とする数字は分布調査にもとづく推定で、資料によって数が異なります。","猿投窯の編年には «黒笹»«折戸» など、代表的な窯跡の名をとった型式名が使われ、全国の遺跡の年代を決めるものさしにもなっています。","平安時代の法令集『延喜式』には、尾張から陶器を納めることが書かれた条文があるとされ、猿投窯の製品を指すと考えられています。","12世紀ごろから、釉をかけない素朴な «山茶碗» の生産が主流になり、窯は丘陵地のあちこちに広がっていきました。","愛知県陶磁美術館の敷地内などには、復元・保存された窯跡があり、あな窯の構造を実際に見ることができます（見学方法は美術館で確認）。"],"look":["愛知県陶磁美術館の猿投窯の器の展示","あな窯の構造がわかる窯跡の保存・復元展示","灰釉陶器の淡い緑色のつや","北にそびえる猿投山の姿"],"q":["植物の灰を釉にして焼いた、猿投窯を代表する平安時代の焼き物を何という？","«灰釉陶器»。淡い緑色のつやが特徴で、都の貴族に好まれました。"],"koji":[{"w":"せともの","m":"焼き物（陶磁器）のこと。瀬戸の焼き物が全国に広まったことから生まれた言葉"}],"myth":"窯の総数は推定で資料により異なる。","img":["灰釉陶器","須恵器","愛知県陶磁美術館"],"wp":"猿投窯","rel":{"ev":[],"grave":[]},"ph":[["c:3/37/Kurozasa_Kiln_No.7_%281%29%2C_Dodo_Morowa_Togo_Town_2023.jpg",1500,1000,"猿投窯"],["c:0/05/Ash-glaze-ware.jpg",2835,2126,"灰釉陶器"],["c:4/47/131123_Hyogo_Prefectural_Museum_of_Archaeology_Japan24s5.jpg",4912,3264,"須恵器"],["c:6/6c/Aichi_Prefectural_Ceramic_Museum-01.jpg",1600,1200,"愛知県陶磁美術館"]]},{"id":"23_yatsuhashi","n":"八橋 無量寿寺（業平のかきつばた）","yomi":"やつはし むりょうじゅじ","cat":"伝承","rank":"B","y":900,"era":["heian","edo"],"sh":"","ad":"知立市八橋町","st":"名鉄三河線 三河八橋駅から歩いて約10分","la":35.027,"lo":137.062,"hook":"«から衣 きつつなれにし…» 都を離れた男が、かきつばたの花に故郷の妻を思った場所。","lead":"八橋は、平安時代の歌物語『伊勢物語』に登場する場所です。在原業平と考えられる «むかし男» が、かきつばたの花を見て、都に残した妻を思う歌をよみました。無量寿寺の庭には今もかきつばたが咲き、毎年春に多くの人が訪れます。","story":["今から1000年以上前のこと。都での暮らしに «もう自分の居場所はない» と感じた一人の男が、友と連れだって東へ旅に出ました。三河の国まで来たとき、川の流れがクモの足のように8つに分かれ、それぞれに橋がかけられている場所に着きます。«八つの橋があるから、ここを八橋というのだ»――『伊勢物語』は、そう語ります。","水辺には、紫のかきつばたが美しく咲いていました。一行は木かげで乾飯（ほした米）を食べながら、ある人が言います。«かきつばた、の5文字を句の頭において、旅の心をよんでごらん»。男はよみました。«からころも きつつなれにし つましあれば はるばるきぬる たびをしぞおもふ»。","«着なれた衣のように、なれ親しんだ妻を都に残して、はるばる遠くまで来てしまった旅を思う»。歌を聞いた人々は、乾飯の上に涙をこぼし、乾飯がふやけてしまったといいます。«なぜ泣いたの?» 旅のさびしさと、会えない家族への思いは、みんなが同じだったからです。","この «むかし男» は、平安時代の歌人・在原業平だと考えられてきました。やがて八橋は歌枕（和歌によまれる名所）となり、多くの旅人や歌人が訪れるようになります。江戸時代には無量寿寺の住職・方巌売茶が庭を整え、かきつばたの名所としてよみがえらせました。","今、無量寿寺の庭園では、毎年4月末から5月にかけて «かきつばたまつり» が開かれ、紫の花が池をうめつくします。近くには業平をしのぶ «業平塚» もあります。花の前に立って、声に出して歌をよんでみてください。1000年前の旅人の心が、そっと重なってくるはずです。"],"tl":[["平安時代前期","『伊勢物語』の «東下り» の話が成立"],["9世紀","在原業平が活躍（825〜880年）"],["中世以降","八橋が歌枕として知られる"],["1812年ごろ","方巌売茶が無量寿寺の庭園を整えたとされる"],["現代","毎年春に «かきつばたまつり» が開かれる"]],"who":[["在原業平","«むかし男» のモデルと考えられる歌人"],["方巌売茶","江戸時代の住職。かきつばたの庭を整えたとされる"],["尾形光琳","八橋の場面を題材に «燕子花図屏風» などを描いた江戸時代の絵師"]],"deep":["«かきつばた» の5音を各句の頭に置く技法を «折句» といいます。«か・き・つ・は・た» の «は» は、当時は «ば» と清音・濁音を区別せずに書いたため成り立ちます。","『伊勢物語』の主人公は «むかし男» とだけ書かれていて、在原業平と明記されていません。業平の歌が多く含まれることから、業平がモデルと考えられています。","«東下り» が史実かどうかはわかっていません。業平が実際に東国へ旅した記録はなく、物語としての創作を含むと考えられています。","京都の銘菓 «八ツ橋» の名の由来には、この三河の八橋から来たという説と、箏曲の祖・八橋検校から来たという説があり、諸説あります。","尾形光琳の «燕子花図屏風»（国宝）や «八橋図屏風» は、この『伊勢物語』の八橋の場面を題材にした作品として知られます。","無量寿寺の庭園は、江戸時代に煎茶の文化と結びついて整えられたとされ、«売茶» の名にその名残があります。"],"look":["無量寿寺の庭園と池をうめるかきつばた（4月末〜5月）","八つの橋をイメージした池の橋","業平塚","歌碑を探して、折句を声に出してよむ"],"q":["«からころも…» の歌の各句の頭をつなげると、何という花の名前になる？","«かきつばた»。こうした技法を «折句» といいます。"],"koji":[{"w":"歌枕","m":"和歌によくよまれる名所。八橋はその代表の一つ"}],"myth":"«むかし男» を業平とするのは推定。東下りが史実かは不明で、物語の話。","img":["伊勢物語","在原業平","カキツバタ","燕子花図"],"wp":"無量寿寺 (知立市)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c4/Chiryu_Yatsuhashi_Muryojuji_ac_%284%29.JPG",6014,3996,"無量寿寺 (知立市)"],["c:d/de/Shunsho-ise-monogatari.jpg",686,956,"伊勢物語"],["c:6/65/Sanj%C5%ABrokkasen-gaku_-_7_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ariwara_no_Narihira_Ason.jpg",450,640,"在原業平"],["c:3/3c/Kakitsubata1.jpg",1296,1440,"カキツバタ"],["c:e/e9/KORIN-Irises-L.jpg",3890,1630,"燕子花図"]]},{"id":"23_akasaka_juku","n":"赤坂宿 旅籠大橋屋","yomi":"あかさかじゅく おおはしや","cat":"街道","rank":"B","y":1716,"era":["edo"],"sh":"","ad":"豊川市赤坂町","st":"名鉄名古屋本線 名電赤坂駅から歩いて約10分","la":34.8585,"lo":137.3145,"hook":"江戸時代から平成まで、およそ300年近く旅人を泊め続けた宿。広重も描いた «赤坂» の旅籠。","lead":"赤坂宿は、東海道五十三次の36番目の宿場です。そこに残る旅籠 «大橋屋» は、江戸時代の建物で2015年まで旅館として営業を続けていました。今は豊川市が公開していて、江戸の宿の雰囲気を体験できます。","story":["東海道を江戸から京へ向かう旅人は、御油の宿を出てすぐ、次の赤坂の宿に着きました。御油と赤坂の間は、わずか1.7kmほど。五十三次の中でいちばん短い区間です。松並木を抜ければもう次の宿。«なぜこんなに近いのに2つも宿場があるの?» 昔から旅人の多い土地で、どちらの宿もにぎわっていたからです。","江戸時代の赤坂は、宿屋がずらりと並ぶにぎやかな宿場でした。旅籠の前では、客引きの女性たちが «お泊まりなさいませ» と旅人の袖を引いたといいます。歌川広重の浮世絵 «東海道五十三次・赤坂» には、旅籠の中でくつろぐ客や、化粧をする女性たちが生き生きと描かれています。この絵のモデルは大橋屋だともいわれています。","大橋屋は、もとは «伊右衛門鯉屋» という名の旅籠でした。今の建物は江戸時代の中ごろ（1716年ごろ）に建てられたと伝わり、表の格子や、2階の手すりなど、旅籠らしい造りをよく残しています。泊まり客は、ここで足を洗い、食事をとり、翌朝また次の宿場へと歩いていきました。","松尾芭蕉もこの道を通り、«夏の月 御油より出でて 赤坂や» という句を残しました。夏の夜は短く、御油で出た月が赤坂に着くころにはもう沈みそうだ――短い区間と短い夏の夜をかけた、しゃれた一句です。","大橋屋は明治・大正・昭和、そして平成まで旅館を続け、2015年に営業を終えました。その後、豊川市が建物を受け継いで修理し、見学できるようにしています。畳の部屋に座って格子の外をながめれば、わらじの音が行き交う江戸の街道が、すぐそこにあるように感じられます。"],"tl":[["1601年","東海道の宿駅制度が始まり、赤坂も宿場となる"],["1716年ごろ","大橋屋（当時は鯉屋）の今の建物が建てられたと伝わる"],["1833年ごろ","広重の «東海道五十三次» が刊行され、赤坂も描かれる"],["明治以降","旅館として営業を続ける"],["2015年","大橋屋が旅館の営業を終える"],["その後","豊川市が取得・修理し、一般公開"]],"who":[["歌川広重","浮世絵 «東海道五十三次・赤坂» を描いた"],["松尾芭蕉","御油と赤坂を詠んだ句を残す"],["大橋屋の歴代の主人","約300年、旅人をもてなし続けた"]],"deep":["赤坂宿は御油宿とともに、東海道でも旅籠の数が多い宿場として知られました。宿場の規模は時期によって変わり、数字は資料によって異なります。","広重の «赤坂 旅舎招婦ノ図» には、庭のソテツが描かれています。近くの浄泉寺にあるソテツがそのモデルと伝わり、今も見ることができます。","御油〜赤坂の間の «御油の松並木» は国の天然記念物で、約600mにわたって松が並び、江戸の街道の姿をよく残しています。","大橋屋の建築年は、改修の際に見つかった記録などから1716年（正徳6年）ごろとされていますが、伝承の部分も含みます。","«伊右衛門鯉屋» の «鯉屋» という屋号から、大橋屋は «鯉屋» とも呼ばれていました。表の «鯉屋» の看板も見どころの一つです。","赤坂宿には «赤坂陣屋» が置かれ、周辺の幕府領を治めていました。宿場は旅人のためだけでなく、地域支配の拠点でもありました。"],"look":["大橋屋の格子のある表構えと2階の手すり","旅籠の客室（見学可能な範囲で）","浄泉寺のソテツ（広重の絵のモデルと伝わる）","御油の松並木（国の天然記念物）"],"q":["東海道五十三次で、宿場と宿場の間がいちばん短いのはどこ？","御油宿と赤坂宿の間。約1.7kmしかありません。"],"koji":[],"myth":"広重の絵のモデルを大橋屋とするのは伝承。建築年も伝承を含む。","img":["御油の松並木","東海道五十三次 (浮世絵)"],"wp":"赤坂宿 (東海道)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c0/Tokaido36_Akasaka.jpg",883,600,"赤坂宿 (東海道)"],["c:a/a9/Goyuno-Matsunamiki-1.jpg",4032,3024,"御油の松並木"],["c:a/ad/Catalogue_of_HIROSHIGE.jpg",4408,3052,"東海道五十三次 (浮世絵)"]]},{"id":"23_fujikawa_juku","n":"藤川宿（脇本陣跡と棒鼻）","yomi":"ふじかわしゅく","cat":"街道","rank":"B","y":1601,"era":["edo"],"sh":"","ad":"岡崎市藤川町","st":"名鉄名古屋本線 藤川駅から歩いて約10分","la":34.911,"lo":137.228,"hook":"宿場の入口を示す «棒鼻»、脇本陣の門、紫の麦。東海道の小さな宿場に、江戸の旅がそのまま残る。","lead":"藤川宿は、東海道五十三次の37番目の宿場です。宿場の入口を示す «棒鼻» が復元され、脇本陣の門が残る跡地には資料館があります。芭蕉の句にちなんだ «むらさき麦» も育てられ、道の駅とあわせて楽しめます。","story":["東海道を西へ、赤坂宿から山あいの道を越えると、藤川宿に着きます。宿場の入口には、木の柵と石垣でつくられた «棒鼻» が立っています。ここから先が宿場、という «しるし» です。今あるものは復元ですが、旅人にとってはここが «やっと着いた» とほっとする場所でした。","江戸時代の藤川宿は、本陣と脇本陣を中心に旅籠が並ぶ宿場でした。本陣は大名や公家が泊まる宿、脇本陣はその予備の宿です。藤川の脇本陣があった場所には、今も立派な門が残り、その奥が «藤川宿資料館» になっています。中では、宿場の模型や古い道具が見られます。","歌川広重は «東海道五十三次・藤川» で、この棒鼻を描きました。絵の中では、幕府から朝廷へ馬を献上する «八朔御馬進献» の一行と考えられる行列が、宿場の人々に迎えられています。«なぜ馬を運んでいたの?» 毎年、幕府が朝廷へ馬を献上する行事があり、その一行が東海道を通って京へ向かったのです。宿場の人々がかしこまって迎える姿から、行列の格式の高さが伝わります。","宿場のはずれには、松尾芭蕉の句碑が立っています。«爰も三河 むらさき麦の かきつばた»。三河といえば『伊勢物語』のかきつばた。その花の色のように紫色に実る麦が、ここ藤川にもある――という句です。この «むらさき麦» は一時途絶えましたが、地元の人々が復活させ、今では初夏に畑を紫に染めています。","宿場の東には、古い松並木も残っています。国道1号の車の流れのすぐそばで、道の駅 «藤川宿» が旅人を迎えるのも、江戸の宿場と同じ役目かもしれません。棒鼻から脇本陣へ、ゆっくり歩けば、わらじで歩いた旅人の目線で町を見ることができます。"],"tl":[["1601年","東海道の宿駅伝馬制度が始まり、藤川が宿場となる"],["江戸時代","本陣・脇本陣を中心に宿場がにぎわう"],["1833年ごろ","広重が «藤川» の棒鼻を描く"],["明治以降","鉄道の開通で宿場の役割が終わる"],["平成時代","棒鼻の復元、資料館の開館、道の駅の開業"]],"who":[["歌川広重","«東海道五十三次・藤川» で棒鼻を描いた"],["松尾芭蕉","«むらさき麦» の句を残した"],["藤川宿の人々","むらさき麦を復活させ、宿場の面影を守る"]],"deep":["«棒鼻» は宿場の出入口を指す言葉で、«傍示杭»（境を示す杭）がなまったものともいわれます。藤川では西の棒鼻などが復元されています。","広重の «藤川 棒鼻ノ図» に描かれた行列は、幕府から朝廷へ馬を献上する «八朔御馬進献» と解釈されるのが一般的です。","«むらさき麦» は、穂が紫色になる麦の品種です。芭蕉の句をきっかけに地元で復活が進められ、岡崎市の特産としても紹介されています。","藤川宿資料館は脇本陣跡にあり、門は江戸時代の脇本陣の門と伝わります。","藤川宿は、1601年に家康が東海道に宿駅伝馬制度を定めたときの最初の宿場の一つとされます。ほかの宿場より遅れて定められた宿（庄野宿など）もあります。","藤川の松並木は、宿場の東側に残っています。東海道の松並木は、夏の日差しや冬の風から旅人を守るために植えられました。"],"look":["復元された棒鼻（西棒鼻）","脇本陣の門と藤川宿資料館","芭蕉の句碑と、初夏のむらさき麦の畑","藤川の松並木と道の駅 «藤川宿»"],"q":["宿場の出入口を示すしるしを何という？","«棒鼻»。広重の «東海道五十三次・藤川» にも描かれています。"],"koji":[],"myth":"広重の絵の行列の解釈、棒鼻の語源には諸説。","img":["東海道五十三次 (浮世絵)","岡崎市"],"wp":"藤川宿","rel":{"ev":[],"grave":[]},"ph":[["c:b/bc/Tokaido37_Fujikawa.jpg",896,600,"藤川宿"],["c:a/ad/Catalogue_of_HIROSHIGE.jpg",4408,3052,"東海道五十三次 (浮世絵)"],["c:7/74/Okazakijo-3-cropped.jpg",2621,1704,"岡崎市"]]},{"id":"23_chiryu_juku","n":"池鯉鮒宿と知立神社","yomi":"ちりゅうしゅく と ちりゅうじんじゃ","cat":"街道","rank":"B","y":1601,"era":["muromachi","edo"],"sh":"国の重要文化財（知立神社多宝塔）","ad":"知立市西町・宝町ほか（知立神社は西町神田）","st":"名鉄 知立駅から歩いて約15分（知立神社）","la":35.003,"lo":137.048,"hook":"池に鯉と鮒があふれていたから «池鯉鮒»。初夏には数百頭の馬が集まる、東海道きっての «馬のまち»。","lead":"池鯉鮒宿は、東海道五十三次の39番目の宿場で、今の知立市にあたります。毎年初夏に開かれた «馬市» で有名でした。宿場の近くの知立神社は三河国の二宮とされる古い神社で、境内の多宝塔は国の重要文化財です。","story":["«ちりゅう» を «池鯉鮒» と書くのは、ちょっと不思議ですね。一説には、知立神社の池に鯉と鮒がたくさんすんでいたから、この字があてられたといわれます。江戸時代の旅人は、道中記でこの字を見て、きっと «どんな池があるんだろう» と楽しみにしたことでしょう。","池鯉鮒宿の名物は、なんといっても «馬市» でした。毎年、初夏になると宿場の東の原っぱに数百頭もの馬が集められ、各地から馬を買いに人が集まりました。歌川広重の «東海道五十三次・池鯉鮒» には、広い野原につながれた馬たちと、大きな木の下で取り引きをする人々がのびやかに描かれています。«なぜ馬がそんなに大事だったの?» 馬は田畑を耕し、荷物を運ぶ、暮らしに欠かせない «働き手» だったからです。","宿場の北には、知立神社があります。古くから三河国の二宮とされ、東海道を行き来する旅人や武士たちも、道中の無事を祈って参拝しました。平安時代の在原業平も、東下りの途中でここに立ち寄ったという言い伝えがあります。","境内でひときわ目を引くのが、朱色の多宝塔です。室町時代の1509年に建てられたと伝わる塔で、上が丸く下が四角い、優美な姿をしています。明治時代の «神仏分離» で、神社の境内にある仏教の建物の多くが取りこわされましたが、この塔は工夫を重ねて守られ、今も残っています。","今の知立は、名鉄の線路が交わる交通の町です。昔は東海道の馬、今は電車と車。«人やものが行き交う町» という性格は、江戸時代からずっと変わっていないのかもしれません。名物の «あんまき» を手に、宿場の面影を探して歩いてみましょう。"],"tl":[["古代","知立神社がまつられる（三河国二宮とされる）"],["1509年","知立神社の多宝塔が建てられたと伝わる"],["1601年","東海道の宿駅制度が始まり、池鯉鮒が宿場となる"],["江戸時代","毎年初夏に馬市が開かれる"],["1833年ごろ","広重が «池鯉鮒 首夏馬市» を描く"],["明治時代","神仏分離の中で多宝塔が守られる"]],"who":[["歌川広重","馬市のようすを浮世絵に描いた"],["在原業平","東下りの途中に立ち寄ったと伝わる"],["池鯉鮒の馬喰（ばくろう）たち","馬市で馬の売り買いをした商人"]],"deep":["«池鯉鮒» は江戸時代の表記で、中世以前は «知立»«智鯉鮒» などとも書かれました。明治時代以降は «知立» の字に統一されています。","広重の作品名は «池鯉鮒 首夏馬市»。«首夏» は初夏のこと。馬市は旧暦の4月末から5月初めにかけて開かれたとされます。","知立神社の多宝塔は、明治の神仏分離の際に相輪（塔の先の金属の飾り）を外すなどして仏塔らしさを弱め、取りこわしを免れたと伝わります。","知立神社は延喜式の神名帳に名前が見える «式内社» で、三河国の二宮とされてきました。一宮は豊川市の砥鹿神社です。","池鯉鮒宿の東には «八橋» があり、『伊勢物語』のかきつばたの地として、宿場とあわせて名所めぐりをする旅人が多かったといわれます。","知立の名物 «あんまき» は、明治時代に知立駅の立ち売りから広まったとされる菓子で、宿場の «旅人のおやつ» の伝統を受けつぐものといえます。"],"look":["知立神社の多宝塔（国の重要文化財）","知立神社の池（«池鯉鮒» の名の由来と伝わる）","旧東海道沿いの馬市の碑","宿場の常夜燈や一里塚の跡"],"q":["«池鯉鮒» の宿場で、毎年初夏に開かれた有名な市は？","«馬市»。数百頭の馬が集まり、広重も浮世絵に描きました。"],"koji":[],"myth":"«池鯉鮒» の字の由来、業平の参拝は言い伝え。多宝塔の建立年も伝承による。","img":["知立神社","東海道五十三次 (浮世絵)"],"wp":"池鯉鮒宿","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Tokaido39_Chiryu.jpg",874,600,"池鯉鮒宿"],["c:1/1f/Chiryu_Jinja_Haiden.jpg",5710,3797,"知立神社"],["c:a/ad/Catalogue_of_HIROSHIGE.jpg",4408,3052,"東海道五十三次 (浮世絵)"]]},{"id":"23_narumi_juku","n":"鳴海宿（鳴海城跡と常夜燈）","yomi":"なるみじゅく","cat":"街道","rank":"B","y":1560,"era":["muromachi","edo"],"sh":"","ad":"名古屋市緑区鳴海町","st":"名鉄名古屋本線 鳴海駅から歩いて約5〜10分","la":35.0815,"lo":136.951,"hook":"桶狭間の戦いの後も城を守りぬき、主君の首と引きかえに城を明け渡した武将がいた――その鳴海城のふもとに開けた宿場。","lead":"鳴海宿は、東海道五十三次の40番目の宿場です。すぐそばの丘には、桶狭間の戦いで今川方の最前線となった鳴海城がありました。宿場には常夜燈や寺社が残り、近くの有松とともに «絞り染め» の里としても知られます。","story":["名鉄の鳴海駅から少し北へ歩くと、小さな丘の上に «鳴海城跡公園» があります。今は住宅にかこまれた静かな公園ですが、戦国時代には、尾張と三河の境で激しい争いの舞台になった城でした。","1560年、駿河の今川義元は大軍をひきいて尾張へ攻めこみました。そのとき今川方の最前線となっていたのが鳴海城です。城を守っていたのは今川の重臣・岡部元信。信長は鳴海城をかこむように善照寺砦や中島砦などをきずき、にらみ合いを続けていました。","ところが、桶狭間で今川義元が討たれてしまいます。主君を失っても、岡部元信は鳴海城を守りぬきました。«城を明け渡すかわりに、殿の首を返してほしい»――元信はそう交渉し、義元の首を受け取って駿河へ引き上げたと伝わります。«なぜそこまで?» 家臣として主君を故郷にかえしたいという、武士の意地だったのでしょう。","江戸時代になると、城のふもとには東海道の宿場が開かれました。鳴海宿は、西の宮宿（熱田）へ向かう最後のひと休みの場所でもあり、旅籠や茶屋でにぎわいました。宿場の東側の有松や鳴海では «絞り染め» の手ぬぐいや浴衣がつくられ、旅人たちの人気のおみやげになりました。","松尾芭蕉も鳴海をたびたび訪れ、地元の俳人たちと句会を開いています。宿場の町並みには、寺や神社、江戸時代の常夜燈などが今も残り、ゆるやかに曲がる旧東海道の道すじをたどることができます。戦国の城から江戸の宿場へ、そして絞りの町へ。鳴海は時代ごとに違う顔を見せてくれる町です。"],"tl":[["室町時代","鳴海城（根古屋城）がきずかれたと伝わる"],["1560年","桶狭間の戦い。岡部元信が鳴海城を守りぬく"],["1560年","元信が義元の首と引きかえに城を明け渡したと伝わる"],["1601年","東海道の宿駅制度が始まり、鳴海が宿場となる"],["1688年","芭蕉ゆかりの句碑 «千鳥塚» が建てられたと伝わる"],["江戸時代","鳴海・有松の絞りが東海道の名産となる"]],"who":[["岡部元信","今川方の武将。桶狭間の後も鳴海城を守った"],["今川義元","桶狭間で討たれた駿河の大名"],["織田信長","鳴海城をかこむ砦をきずいた"],["松尾芭蕉","鳴海の俳人たちと交流した"]],"deep":["鳴海城は «根古屋城» とも呼ばれました。室町時代の応永年間に安原宗範がきずいたと伝わりますが、はっきりした記録は少ないです。","戦国時代、鳴海城主の山口教継は織田方から今川方に寝返り、これが今川軍の尾張進出の足がかりになったといわれます。","岡部元信が義元の首を受け取った話は『信長公記』などには詳しく書かれておらず、後世の軍記物などによって広まった部分もあります。","元信は鳴海から駿河へ引き上げる途中、刈谷城を攻めて城主の水野信近を討ったと伝わります。","芭蕉ゆかりの «千鳥塚» は、芭蕉が生きているうちに建てられた唯一の句碑ともいわれますが、評価には諸説あります。","有松・鳴海絞は、江戸時代初めに有松で始まったとされ、尾張藩の保護を受けて東海道のおみやげとして広まりました。"],"look":["鳴海城跡公園（城跡の碑）","旧東海道沿いの常夜燈と寺社","芭蕉ゆかりの千鳥塚","近くの有松の町並み（絞りの商家）"],"q":["桶狭間の戦いのあとも鳴海城を守り、義元の首と引きかえに城を明け渡したと伝わる武将は？","岡部元信。主君の首を駿河に持ち帰ったと伝わります。"],"koji":[],"myth":"元信が首と引きかえに開城した話は後世の記録による部分がある。築城者・千鳥塚の評価にも諸説。","img":["鳴海城","岡部元信","有松・鳴海絞"],"wp":"鳴海宿","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:0/01/Tokaido40_Narumi.jpg",864,600,"鳴海宿"],["c:f/f7/Tenjin-sha_Shrine_Keidai_%281%29%2C_Shiro_Narumi-cho_Midori_Ward_Nagoya_2020.jpg",1500,1000,"鳴海城"]]},{"id":"23_okoshi_juku","n":"起宿（美濃路の渡し場）","yomi":"おこしじゅく","cat":"街道","rank":"B","y":1700,"era":["edo"],"sh":"","ad":"一宮市起","st":"名鉄 尾張一宮駅からバスで約20分","la":35.3065,"lo":136.7485,"hook":"大河・木曽川に、何百艘もの船を並べて橋にした――将軍や朝鮮通信使を渡した «船橋» の宿場。","lead":"起宿は、名古屋と大垣を結ぶ «美濃路» の宿場で、木曽川の渡し場として栄えました。大切な行列が通るときには、船をつないで川に «船橋» をかけました。脇本陣だった旧林家住宅が残り、資料館とあわせて見学できます。","story":["東海道の宮宿（熱田）から北へ、名古屋・清須を通って美濃の垂井で中山道に合流する道があります。これが «美濃路» です。その途中、尾張と美濃の境を流れる大河・木曽川のほとりにあったのが起宿でした。","木曽川には橋がありませんでした。旅人たちは «渡し船» で川を渡ります。起には «定渡船場» があり、船頭たちが一日中、人や荷物を向こう岸へ運んでいました。川の水が増えると渡しは止まり、宿場は足止めされた旅人でいっぱいになりました。","ところが、特別な行列のときだけは違いました。将軍の上洛や、朝鮮通信使が通るとき、木曽川に何百艘もの船を横一列に並べ、その上に板をわたして «船橋» をつくったのです。«なぜ本物の橋をかけなかったの?» 木曽川は尾張藩にとって西からの攻撃を防ぐ «守りの堀» でもあり、ふだん橋をかけることは許されていなかったからです。","船橋をかけるには、たくさんの船と人手が必要でした。周りの村々から船や人が集められ、何日もかけて準備したといわれます。朝鮮通信使の一行は、壮大な船橋に驚いたと記録に残ります。国と国の友好の使節を迎える、尾張藩の «おもてなし» の見せ場でした。","今の起には、脇本陣をつとめた林家の住宅が残り、隣の尾西歴史民俗資料館で美濃路や船橋の歴史を学べます。堤防に上がって広い木曽川をながめれば、川いっぱいに並んだ船の上を、きらびやかな行列が渡っていく光景が目に浮かびます。"],"tl":[["江戸時代初め","美濃路が整えられ、起が宿場となる"],["江戸時代","木曽川の定渡船場として栄える"],["江戸時代","朝鮮通信使の往来の際に船橋がかけられる"],["1891年","濃尾地震。起の町も大きな被害を受ける"],["現代","旧林家住宅（脇本陣）と資料館が公開される"]],"who":[["朝鮮通信使","朝鮮王朝からの使節。船橋を渡った"],["尾張藩","船橋をかけ、使節や将軍を迎えた"],["林家","起宿の脇本陣をつとめた家"]],"deep":["美濃路の宿場は、宮（熱田）・名古屋・清須・稲葉・萩原・起・墨俣・大垣・垂井の順に並びます（数え方には諸説あり）。","船橋に使った船の数は数百艘規模とされ、記録によって数字が異なります。大規模な船橋は日本でも珍しいものでした。","木曽川に橋をかけなかった理由として、尾張藩の防衛上の配慮が挙げられますが、大きな川に橋をかける技術や費用の問題もあったと考えられます。","旧林家住宅は、濃尾地震のあとに建て直された建物で、国の登録有形文化財です。脇本陣としての格式を伝える造りが見られます。","起は、江戸時代から織物の町としても知られ、明治以降は毛織物（尾州ウール）の産地・尾西の中心として発展しました。","起の渡しの跡には碑が立ち、堤防の上からかつての渡し場の位置を確認できます。"],"look":["旧林家住宅（脇本陣）","尾西歴史民俗資料館の船橋の展示","木曽川の堤防と起の渡し跡の碑","起の町並みに残る古い家"],"q":["木曽川で、特別な行列のときだけ船を並べてかけた橋を何という？","«船橋»。将軍や朝鮮通信使が通るときにかけられました。"],"koji":[],"myth":"船橋の船の数や準備の日数は記録によって違いがある。","img":["美濃路","朝鮮通信使","木曽川"],"wp":"起宿","rel":{"ev":[],"grave":[]},"ph":[["c:b/ba/Bisaiminzokuhakubutkan1.jpg",6048,4024,"起宿"],["c:d/db/Mino-ji_%28Nagoya_City_Road_Nagono_1-chome_No.2_Line%29%2C_Nagono_Nishi_Ward_Nagoya_2021.jpg",1500,1000,"美濃路"],["c:8/8f/KoreanEmbassy1655KanoTounYasunobu.jpg",2552,1056,"朝鮮通信使"],["c:8/88/View_of_Kiso-gawa_River_from_the_Top_of_Gensai-bashi_Bridge_%282%29%2C_Nakatsugawa_2014.jpg",1500,1000,"木曽川"]]},{"id":"23_irukaike","n":"入鹿池（江戸初期の巨大ため池）","yomi":"いるかいけ","cat":"産業","rank":"B","y":1633,"era":["edo","meiji"],"sh":"","ad":"犬山市今井・池野ほか","st":"名鉄 犬山駅から明治村行きバスで約20分","la":35.3345,"lo":136.997,"hook":"村を一つ沈めてつくった巨大なため池は、尾張北部の田畑をうるおし続けた。けれど明治元年、堤が切れた。","lead":"入鹿池は、江戸時代の初め、1633年に完成した巨大なため池です。村をまるごと移してつくられ、周りの新田に水を送りました。1868年には堤防が決壊し、大きな被害が出ました。2015年に «世界かんがい施設遺産» に登録されています。","story":["犬山市の東、山々にかこまれた谷に、青い水をたたえた大きな池があります。入鹿池です。今はワカサギ釣りやボートでにぎわうのどかな池ですが、じつは江戸時代の人々が知恵と汗でつくった «人工の湖» なのです。","江戸時代の初め、尾張北部の村々は水不足に苦しんでいました。そこで地元の有力者たち «入鹿六人衆» が、山あいの入鹿村を流れる川をせき止めて、大きな池をつくる計画を立てました。尾張藩もこれを認め、工事が始まります。«でも、村はどうするの?» 入鹿村の人々は、先祖代々の土地を離れ、別の場所へ移り住むことになりました。","工事でいちばん難しかったのは、川の水をせき止める最後の堤防づくりでした。何度やっても水の勢いで崩されてしまう。そこで、河内（今の大阪府）から来た技術者が、独特の工法でようやく堤をしめきったと伝わります。1633年、池は完成し、周りに新田が広がっていきました。","ところが1868年、明治と元号が変わるその年、長雨で池の水があふれ、堤防が切れてしまいます。«入鹿切れ» と呼ばれるこの大水害では、下流の村々が濁流にのみこまれ、多くの人が亡くなりました。その数は900人をこえるともいわれます。人々の暮らしを支えた池は、同時に大きな危険も抱えていたのです。","その後、堤防は修復・強化され、池は今も農業用水として田畑をうるおしています。2015年には、歴史ある農業用の水の施設として «世界かんがい施設遺産» に登録されました。静かな湖面を見つめるとき、池をつくった人々、村を離れた人々、そして水害で亡くなった人々のことにも思いを寄せたいものです。"],"tl":[["1628年ごろ","入鹿六人衆が池づくりを計画し、工事が始まったとされる"],["1633年","入鹿池が完成"],["江戸時代","新田開発が進み、多くの村が潤う"],["1868年","長雨で堤防が決壊（入鹿切れ）。大きな被害が出る"],["明治以降","堤防の修復・改修が重ねられる"],["2015年","世界かんがい施設遺産に登録"]],"who":[["入鹿六人衆","池づくりを計画した地元の有力者たち"],["入鹿村の人々","池の底に沈む村から移り住んだ"],["河内から来た技術者","堤防の締め切り工事を成功させたと伝わる"],["尾張藩","工事を認め、支援した"]],"deep":["入鹿池は、ため池としては国内でも最大級の規模とされ、讃岐の満濃池と並んで語られることがあります。","«入鹿» の名は、池の底に沈んだ入鹿村に由来します。村人たちは周辺の新しい土地に移り住んだとされます。","堤防の締め切りに活躍した河内の技術者の名や工法については、伝承の要素が強く、記録によって異なります。","1868年の «入鹿切れ» の死者数は900人以上とする資料が多いものの、正確な数字ははっきりしません。浸水は下流の広い範囲に及びました。","入鹿池のほとりには «博物館明治村» があり、池の景色を背景に明治時代の建物を見学できます。","入鹿池の水は、用水路を通じて犬山・小牧・大口方面などの田畑へ送られてきました。のちには木曽川から水を引く用水とも結びつけられています。"],"look":["入鹿池の堤防と湖面のながめ","池のほとりの由来を記した碑","博物館明治村（すぐそば）","ワカサギ釣りのボート（冬）"],"q":["1868年に入鹿池の堤防が決壊した水害は、何と呼ばれている？","«入鹿切れ»。下流の村々に大きな被害が出ました。"],"koji":[],"myth":"河内の技術者の話は伝承。工事開始年や入鹿切れの死者数は資料によって異なる。","img":["博物館明治村","世界かんがい施設遺産"],"wp":"入鹿池","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/%E5%85%A5%E9%B9%BF%E6%B1%A0%E3%81%AE%E8%88%AA%E7%A9%BA%E5%86%99%E7%9C%9F.jpg",591,589,"入鹿池"],["c:4/43/Meijimura1.jpg",6048,4024,"博物館明治村"]]},{"id":"23_ohama_sodo","n":"大浜騒動の地（明治初年の護法一揆）","yomi":"おおはまそうどう","cat":"近代","rank":"B","y":1871,"era":["meiji"],"sh":"","ad":"碧南市鷲塚町・大浜地区ほか","st":"名鉄三河線 碧南中央駅から車で約10分","la":34.896,"lo":136.987,"hook":"«寺をまとめよ» という新政府の役人の命令に、念仏の門徒たちが立ち上がった――明治初年、三河の一揆。","lead":"大浜騒動は、明治4年（1871年）に今の碧南市周辺で起きた一揆です。この地を治めた菊間藩の役人が寺の整理を進めたことに、浄土真宗の門徒たちが反発しました。役人が殺される事件となり、首謀者とされた僧が処刑されました。","story":["明治維新のあと、新しい政府は «神道を国の中心に» という考えのもとで、寺や仏教への圧力を強めました。各地で仏像やお寺がこわされた «廃仏毀釈» の動きです。三河の大浜（今の碧南市）でも、この波が押しよせてきました。","そのころ大浜の一帯は、上総（今の千葉県）の菊間藩の領地になっていました。大浜に置かれた藩の役所の役人たちは、寺を合併させたり、葬式のやり方を改めさせたりする方針を打ち出します。«このままでは、わしらの寺がなくなってしまう»。西三河は浄土真宗の信仰があつい土地で、門徒たちの不安は一気にふくらみました。","1871年3月、門徒たちは鷲塚の寺に集まり、藩の役所へ向かおうとしました。竹やりやむしろ旗を手にした人々と、それを止めようとした役人たちがぶつかり、その中で役人の一人が命を落とします。«なぜ祈りの人々が、刃を向けることになったのか?» 信仰を守りたいという思いと、急に変わっていく世の中への恐れが、悲しい結果を生んでしまったのです。","騒動はまもなくしずめられ、多くの人がとらえられました。首謀者とされた僧・石川台嶺は死罪となり、ほかにも罰を受けた人がいました。一揆に加わった人々の多くは、ふつうの農民や町の人々でした。","大浜騒動は、明治のはじめの宗教政策が、地方の人々の暮らしや心をどれほど揺さぶったかを伝える出来事です。碧南の町には、騒動で亡くなった人々をしのぶ碑が残されています。立場は違っても、命を落とした人々への敬意を忘れずに、この出来事をふり返りたいものです。"],"tl":[["1868年","神仏分離令が出され、各地で廃仏毀釈が起こる"],["1869〜1870年ごろ","大浜周辺が菊間藩の領地となる"],["1870〜1871年","菊間藩の役人が寺院の整理を進める"],["1871年3月","門徒たちが集まり、役人一人が殺される（大浜騒動）"],["1871年","首謀者とされた石川台嶺らが処罰される"],["1871年7月","廃藩置県で菊間藩が廃止される"]],"who":[["石川台嶺","首謀者とされ処刑された浄土真宗の僧"],["菊間藩の役人たち","寺院整理を進めた"],["西三河の門徒たち","信仰を守ろうと立ち上がった人々"]],"deep":["大浜騒動は «護法一揆» とも呼ばれ、明治初年に越前・信濃などで起きた真宗門徒の一揆と並んで語られます。","菊間藩は、もと駿河国沼津藩の水野家で、明治維新のときに上総国菊間へ移され、三河の旧領の一部を飛び地として持っていました。","騒動のきっかけとして、寺の合併（合寺）の方針や、役人による説諭（説明会）が門徒の反発を招いたことが挙げられますが、細かな経過は資料によって違いがあります。","亡くなった役人の名は «藤岡薫» と伝えられ、騒動の舞台となった地には関係する碑があるとされます。","石川台嶺については、首謀者だったのか、責任を負わされたのかという点で評価が分かれており、後に地元で «殉教者» としてしのばれるようになりました。","廃藩置県の直前に起きた事件で、新政府の宗教政策が地方でどう受け止められたかを示す例として研究されています。"],"look":["騒動に関わる寺院と記念碑（碧南市内）","碧南市の郷土資料の展示（開催時）","大浜の古い町並みと寺の多さ（真宗の信仰のあつさを感じる）"],"q":["大浜騒動で、門徒たちが反発した藩の方針は何に関するものだった？","寺の整理（合併など）や仏教への統制。信仰を守ろうとする門徒が立ち上がりました。"],"koji":[],"myth":"騒動の経過、役人殺害の状況、台嶺の役割は資料によって違いがあり、諸説。","img":["廃仏毀釈","菊間藩","浄土真宗"],"wp":"大浜騒動","rel":{"ev":[],"grave":[]},"ph":[["c:5/5a/Ohama_Riot.jpg",1105,746,"大浜騒動"]]},{"id":"23_kazan_yukyo","n":"渡辺崋山幽居跡（蛮社の獄後の蟄居）","yomi":"わたなべかざんゆうきょあと","cat":"幕末","rank":"B","y":1841,"era":["edo"],"sh":"","ad":"田原市田原町（池ノ原）","st":"豊橋鉄道渥美線 三河田原駅から歩いて約15分","la":34.669,"lo":137.266,"hook":"«不忠不孝 渡辺登»――世界を見つめた画家で家老は、ふるさとの小さな家で、自ら命を絶った。","lead":"渡辺崋山は、田原藩の家老であり、すぐれた画家、そして西洋の学問を学んだ «蘭学者» でした。幕府の政策を批判したとして «蛮社の獄» でとらえられ、ふるさと田原の池ノ原の屋敷で蟄居（外出禁止）となります。1841年、崋山はこの地で自ら命を絶ちました。","story":["渡辺崋山（本名・登）は、江戸の田原藩邸で、貧しい下級武士の家に生まれました。家計を助けるために絵を学び、やがて江戸でも指折りの画家になります。国宝の «鷹見泉石像» は、まるで写真のように人物の心まで描き出した傑作です。一方で崋山は、田原藩の家老として、藩の財政立て直しや飢饉対策にも力をつくしました。","崋山は、西洋の学問（蘭学）を学ぶ仲間たちとも交わりました。高野長英らと «世界の中の日本» を語り合ううちに、日本の近海に外国船が現れるようになった時代の危うさを強く感じるようになります。1837年、アメリカの船モリソン号が幕府の命令で砲撃されると、崋山はその政策を批判する文章『慎機論』を書きました。","1839年、崋山は長英らとともにとらえられます。これが «蛮社の獄» です。『慎機論』は人に見せるつもりのない下書きでしたが、幕府を批判したとされ、崋山はふるさと田原での蟄居を命じられました。«なぜ、国を思って書いた文章が罪になるの?» 当時の幕府は、外国のことを自由に語ることを強く警戒していたのです。","田原の池ノ原の屋敷での暮らしは、とても貧しいものでした。見かねた弟子たちが、崋山の絵を売って生活を助けようと «画会» を開きます。ところが «罪人が絵を売ってもうけている» といううわさが立ち、それが藩主に迷惑をかけることを崋山はおそれました。1841年、崋山は «不忠不孝渡辺登» と書き残し、自ら命を絶ちます。49歳でした。","今、幽居の跡の近くには崋山をまつる崋山神社があり、田原城跡には田原市博物館が建っています。崋山の墓は近くの城宝寺にあります。世界に目を開き、ふるさとの人々を思い続けた崋山の生き方は、今も多くの人の心をとらえています。静かな跡地で、その無念と誇りに思いを寄せたいものです。"],"tl":[["1793年","渡辺崋山が江戸の田原藩邸で生まれる"],["1832年","田原藩の年寄役（家老職）となる"],["1837年","«鷹見泉石像» を描く。モリソン号事件が起こる"],["1839年","蛮社の獄でとらえられ、田原での蟄居を命じられる"],["1840年","田原の池ノ原の屋敷に移る"],["1841年","池ノ原の幽居で自刃（49歳）"]],"who":[["渡辺崋山","田原藩家老・画家・蘭学者。ここで蟄居し、亡くなった"],["高野長英","蘭学仲間。蛮社の獄で永牢となる"],["鷹見泉石","古河藩家老。崋山が肖像画を描いた"],["福田半香","崋山の弟子。画会を開いて師を助けようとした"]],"deep":["«蛮社» は «蛮学（洋学）の仲間» を悪く言った言葉です。蘭学者たちの勉強会 «尚歯会» が、敵対する人々からこう呼ばれました。","蛮社の獄の背景には、幕府の目付・鳥居耀蔵らの蘭学者への反感があったとされます。捜査の過程で、でっちあげに近い告発があったとも指摘されています。","『慎機論』は未完成の原稿で、崋山は発表していませんでした。家宅捜索で見つかったことが罪の決め手になったとされます。","«鷹見泉石像»（1837年）は国宝で、西洋画の陰影法を取り入れた肖像画の代表作です。東京国立博物館に所蔵されています。","崋山の墓は田原市の城宝寺にあり、国の史跡に指定されています。田原市博物館では、崋山の作品や資料を見ることができます。","崋山は田原藩で飢饉に備えた «報民倉» という蔵を設けたとされ、天保の飢饉では藩内から餓死者を出さなかったと伝えられています。"],"look":["幽居跡の碑と崋山神社","田原城跡と田原市博物館（崋山の作品展示）","城宝寺の崋山の墓","池ノ原の静かな周辺の町並み"],"q":["渡辺崋山が描いた国宝の肖像画は？","«鷹見泉石像»。古河藩家老・鷹見泉石を描いた、写実的な傑作です。"],"koji":[{"w":"不忠不孝","m":"主君にも親にも尽くせなかったという意味。崋山が最後に自らを責めて書き残したことば"}],"myth":"報民倉で餓死者を出さなかった話は伝えられる評価。蛮社の獄の経緯には諸説。","img":["蛮社の獄","鷹見泉石像","高野長英"],"wp":"渡辺崋山","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/Watanabe_Kazan.jpg",1524,2248,"渡辺崋山"],["c:2/21/Takano_Tyouei.jpg",1372,1976,"高野長英"]]},{"id":"23_dai15shidan","n":"陸軍第十五師団跡（愛知大学豊橋校舎）","yomi":"りくぐんだいじゅうごしだんあと","cat":"昭和","rank":"B","y":1908,"era":["meiji","taisho","showa"],"sh":"","ad":"豊橋市町畑町（愛知大学豊橋校舎）","st":"豊橋鉄道 東田本線（市電） «愛知大学前» 下車すぐ","la":34.732,"lo":137.406,"hook":"軍の司令部だった建物は、戦後、平和を学ぶ大学の校舎になった。","lead":"豊橋には明治時代の終わりから、陸軍の第十五師団の司令部が置かれていました。師団は1925年に廃止されましたが、跡地は軍の学校などとして使われ、戦後は愛知大学のキャンパスになりました。司令部の建物などが今も大学の中に残っています。","story":["1905年、日露戦争のさなか、日本陸軍は新しい師団をいくつもつくりました。その一つが第十五師団です。戦争のあと、1908年に師団の司令部は豊橋に置かれました。«なぜ豊橋に?» 東海道の交通の要所で、近くには演習のできる広い原野（高師原）があったからだと考えられます。","師団が来ると、豊橋の町は大きく変わりました。何千人もの兵士が暮らし、商店や旅館がにぎわい、市電が兵営の方へのびていきました。«軍都・豊橋» と呼ばれるようになったのです。今も走る路面電車の路線には、その時代の名残があります。","ところが1925年、軍の予算を減らす «宇垣軍縮» によって、第十五師団は廃止されてしまいます。町の人々は大きなショックを受けました。跡地はその後も陸軍の施設として使われ、昭和の戦争の時代には、若い将校を育てる予備士官学校が置かれました。多くの若者がここで訓練を受け、戦地へ送られていきました。","1945年、戦争が終わりました。翌1946年、この跡地に愛知大学が生まれます。中国・上海にあった東亜同文書院などから引き揚げてきた先生や学生たちが中心となって、新しい大学をつくったのです。«もう二度と戦争をくり返さない»。軍の建物は、平和と国際理解を学ぶ場所に生まれ変わりました。","今、大学の構内には、師団司令部だった洋風の建物が «記念館» として残り、そのほかにも軍の時代の建物が大切に使われています。学生たちが行き交うキャンパスで古い建物を見上げると、この場所が歩んできた «戦争から平和へ» の道のりが感じられます。"],"tl":[["1905年","日露戦争中に第十五師団が編成される"],["1908年","第十五師団の司令部が豊橋に置かれる"],["1925年","宇垣軍縮で第十五師団が廃止される"],["昭和時代（戦中）","跡地に陸軍の予備士官学校などが置かれる"],["1946年","跡地に愛知大学が開学"],["現代","旧司令部庁舎などが国の登録有形文化財として残る"]],"who":[["宇垣一成","陸軍大臣。軍縮で第十五師団を廃止した"],["愛知大学の創立者たち","東亜同文書院などから引き揚げ、大学をつくった"],["豊橋の人々","«軍都» の時代と戦後を生きた"]],"deep":["1925年の «宇垣軍縮» では、第十五師団のほか第十三・第十七・第十八師団の計4個師団が廃止されました。浮いた予算は、兵器の近代化にあてられました。","1938年、同じ «第十五師団» の番号をもつ師団が改めて編成され、中国戦線やビルマのインパール作戦に加わりました。ただしこの師団は、豊橋にあった師団とは編成の経緯が異なります。","師団の廃止後、豊橋には陸軍の教導学校や予備士官学校が置かれ、跡地は軍の教育施設として使われました。","旧司令部庁舎（現・愛知大学記念館）や旧師団長官舎などは国の登録有形文化財で、明治時代の洋風建築として価値があります。","愛知大学は、上海の東亜同文書院大学の教職員・学生を受け入れる形で1946年に創立されました。中国研究の伝統は、今も同大学の特色です。","豊橋の市電（東田本線）は1925年に開業し、今も «愛知大学前» 停留場が大学の正門前にあります。"],"look":["愛知大学記念館（旧師団司令部庁舎）","旧師団長官舎などの近代建築","大学構内の案内板（軍の時代の説明）","市電 «愛知大学前» 停留場"],"q":["1925年、第十五師団を廃止した軍縮を何という？","«宇垣軍縮»。陸軍大臣・宇垣一成のもとで4個師団が廃止されました。"],"koji":[],"myth":"豊橋が選ばれた理由は推定。建物の用途・名称は大学の案内で確認のこと。","img":["愛知大学","宇垣軍縮","豊橋市電"],"wp":"第15師団 (日本軍)","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/15th_Division_%28Imperial_Japanese_Army%29.jpg",1130,649,"第15師団 (日本軍)"],["c:7/71/University_Memorial_Hall_of_Aichi_University_100822.jpg",2048,1536,"愛知大学"],["c:4/4f/T1000_toyohashi.jpg",645,457,"豊橋市電"]]},{"id":"23_sakushima","n":"佐久島（三河湾の海の民と古墳）","yomi":"さくしま","cat":"島","rank":"B","y":700,"era":["kofun","nara","heisei"],"sh":"","ad":"西尾市一色町佐久島","st":"一色港（一色さかな広場の近く）から船で約20〜25分","la":34.727,"lo":137.039,"hook":"奈良の都へ «海の幸» を届けた島。黒い板壁の集落と、島のあちこちに眠る古墳。","lead":"佐久島は、三河湾に浮かぶ小さな島です。島には古墳がいくつも残り、奈良時代には都へ海産物を納めていたことが木簡（文字を書いた木の札）からわかっています。黒い板壁の家が並ぶ集落や、島じゅうに置かれたアート作品でも知られます。","story":["西尾市の一色港から船に乗って20分ほど。三河湾のまん中に、緑の小さな島が見えてきます。佐久島です。港に着くと、黒くぬられた板壁の家々が細い路地にぎっしりと並んでいます。潮風から家を守るため、板にコールタールをぬったこの集落は «三河湾の黒真珠» とも呼ばれます。","島を歩くと、林の中や丘の上に、こんもりとした古墳があるのに気づきます。小さな島に、いくつもの古墳。«なぜ、こんな小さな島に古墳があるの?» それは、古墳時代の佐久島に、海を舞台に活躍した «海の民» の有力者がいたからだと考えられています。船をあやつり、魚や貝をとる人々にとって、島は海の «基地» でした。","奈良時代、都の平城京には全国から «贄»（天皇に納める食べ物）が届けられました。平城宮の跡から見つかった木簡には、三河国の島々から海産物が納められたことが記されています。その中に佐久島を指すと考えられる島の名もあり、島の海人たちが、はるばる奈良まで海の幸を送っていたことがわかります。","時代がくだっても、島の人々は漁業や海運で暮らしを立ててきました。江戸時代には船で物資を運ぶ仕事でにぎわい、島には寺や神社が大切に守られてきました。けれど昭和の後半から人口がへり、島はさびしくなっていきます。","そこで平成になって始まったのが、島をまるごと美術館にする取り組みです。海辺の «おひるねハウス» など、島のあちこちにアート作品が置かれ、多くの人が訪れるようになりました。古墳時代の海の民、奈良の都へ贄を運んだ海人、そして今の島の人々。佐久島は、いつの時代も海とともに生きてきたのです。"],"tl":[["古墳時代後期","島に古墳がつくられる"],["奈良時代","三河国の島々から都へ贄が納められる（平城宮木簡）"],["江戸時代","漁業・海運の島としてにぎわう"],["昭和時代後半","人口がへりはじめる"],["2000年代","島の芸術祭・アートの取り組みが本格化"]],"who":[["佐久島の海人たち","古代から海の幸をとり、都へ納めた"],["島の人々","黒壁の集落と伝統を守り、アートの島づくりを進めた"]],"deep":["平城宮跡出土の木簡には、三河国播豆郡の島々（篠島・析島・比莫島など）から «贄» として海産物が納められたことが記されており、«析島» が佐久島、«比莫島» が日間賀島にあたると考えられています。","島内の古墳は主に古墳時代後期のもので、横穴式石室をもつものもあると報告されています。数は資料によって異なります。","黒壁の家は、潮風や雨から木材を守るためにコールタールをぬったものです。同じような黒い板壁は、日本の海辺の集落で広く見られます。","篠島・日間賀島とともに «三河湾三島» の一つとして、古代から «海の道» で結ばれていたと考えられています。","佐久島は西尾市（旧・一色町）に属し、車がほとんど走らない島として、歩いてめぐる観光が中心です。","島のアート作品は屋外にあるものが多く、自然の中に置かれた作品と古い集落の景色の組み合わせが特色です。"],"look":["黒壁の集落と細い路地","島内の古墳（案内に従って）","海辺のアート作品（おひるねハウスなど）","島の神社・寺と海のながめ"],"q":["奈良時代、佐久島などの島々から都へ納められたものは？","«贄»（天皇に納める食べ物）。海産物だったことが木簡からわかります。"],"koji":[],"myth":"木簡の島名と現在の島の対応は研究にもとづく推定。古墳の数は資料で異なる。","img":["三河湾","木簡","日間賀島"],"wp":"佐久島","rel":{"ev":[],"grave":[]},"ph":[["c:6/6c/Sakushima_aerial_photograph.jpg",4620,3465,"佐久島"],["c:2/2c/Mikawa_Bay_Aichi_Japan_SRTM.jpg",794,898,"三河湾"],["c:5/5d/Wooden_tablets_%28copy%29_in_7-8th_c.jpg",3112,1535,"木簡"],["c:2/21/Himakajima_aerial_photograph.jpg",3376,2532,"日間賀島"]]},{"id":"23_iragomisaki","n":"伊良湖岬（芭蕉・椰子の実の伝承）","yomi":"いらごみさき","cat":"伝承","rank":"B","y":1687,"era":["asuka","edo","meiji"],"sh":"","ad":"田原市伊良湖町","st":"豊橋鉄道渥美線 三河田原駅からバスで約1時間、«伊良湖岬» 下車","la":34.579,"lo":137.014,"hook":"«名も知らぬ遠き島より 流れ寄る椰子の実一つ»――あの歌は、この浜辺から生まれた。","lead":"伊良湖岬は、渥美半島の先にある岬です。万葉集の歌、松尾芭蕉の句、そして島崎藤村の詩 «椰子の実» にゆかりのある場所として知られます。岬の近くの «恋路ヶ浜» は白い砂浜が続く美しい海岸です。","story":["渥美半島の先端、太平洋と伊勢湾が出会う場所に伊良湖岬はあります。白い灯台の向こうに、伊勢の神島がぽっかりと浮かび、秋には南へ渡るタカの群れが空を舞います。古くから多くの人が、この岬の景色に心をうたれてきました。","いちばん古いのは、奈良時代にまとめられた『万葉集』の歌です。«麻続王» という人が罪を受けて «伊良虞の島» に流され、海藻をとって食べながら暮らしたと歌われています。«うつせみの 命を惜しみ 波に濡れ 伊良虞の島の 玉藻刈り食む»。都を追われた人の悲しみが、波の音とともに伝わってきます。","江戸時代の1687年、松尾芭蕉が、近くの保美村に暮らす弟子の杜国を訪ねて渥美半島にやってきました。杜国は罪を受けてこの地に移り住んでいたのです。芭蕉は伊良湖の岬まで足をのばし、空に一羽のタカを見つけてよみました。«鷹一つ 見付てうれし いらご崎»。不遇の弟子と再会できた喜びを、タカに重ねたともいわれます。","明治時代の1898年、若き民俗学者・柳田国男がこの地に滞在し、恋路ヶ浜で、はるか南の島から流れついた椰子の実を見つけました。«どんなに遠い海を旅してきたのだろう»。柳田からこの話を聞いた友人の詩人・島崎藤村は、詩 «椰子の実» を書きます。のちに曲がつけられ、日本じゅうで歌われるようになりました。","今、恋路ヶ浜には «椰子の実» の歌碑が立ち、毎年、南の島から椰子の実を流して伊良湖への漂着を願う取り組みも行われています。万葉の流人、芭蕉と弟子、柳田と藤村――この岬にはいつも、遠くを思う人の心が流れついてきたのです。"],"tl":[["飛鳥時代","麻続王が «伊良虞の島» に流されたと『万葉集』に歌われる"],["1687年","松尾芭蕉が杜国を訪ね、伊良湖崎で句をよむ"],["1898年","柳田国男が伊良湖に滞在し、椰子の実を見つける"],["1901年","島崎藤村の詩 «椰子の実» を収めた『落梅集』が出る"],["1936年","大中寅二が曲をつけ、歌として広まる"]],"who":[["麻続王","『万葉集』で伊良虞の島に流されたと歌われた人物"],["松尾芭蕉","伊良湖崎で «鷹一つ» の句をよんだ"],["坪井杜国","芭蕉の弟子。保美村に移り住んでいた"],["柳田国男","椰子の実を見つけた民俗学者"],["島崎藤村","詩 «椰子の実» の作者"]],"deep":["麻続王が流された場所について、『日本書紀』は因幡国、『万葉集』の歌は伊勢国の «伊良虞の島» とし、記録が食い違っています。伊良虞を伊良湖岬とするか、別の島とするかにも諸説あります。","芭蕉の渥美半島への旅は、紀行文『笈の小文』に記されています。杜国は名古屋の米商人でしたが、空米売買の罪で領地を追われ、保美村に移り住んでいました。","柳田国男は、椰子の実の漂着から «日本人の祖先は南の海から来たのではないか» という考えをあたため、晩年の著書『海上の道』にまとめました。","伊良湖岬は、タカの一種サシバなどが秋に大群で渡っていく «タカの渡り» の観察地として有名で、芭蕉の句とも響き合っています。","伊良湖岬の沖の «伊良湖水道» は、伊勢湾の入口にあたる潮の流れの速い海峡で、古くから航海の難所として知られてきました。","恋路ヶ浜の名は、身分違いの恋に落ちた男女がここに逃れたという言い伝えに由来するとされます。"],"look":["恋路ヶ浜の白い砂浜と «椰子の実» の歌碑","伊良湖岬灯台と、海の向こうの神島","芭蕉の «鷹一つ» の句碑","秋のタカの渡り（9〜10月ごろ）"],"q":["島崎藤村の詩 «椰子の実» のもとになった話を藤村に伝えたのはだれ？","民俗学者の柳田国男。1898年に伊良湖に滞在し、流れついた椰子の実を見つけました。"],"koji":[],"myth":"麻続王の配流地、恋路ヶ浜の名の由来には諸説・伝承がある。","img":["椰子の実 (歌曲)","恋路ヶ浜","柳田國男"],"wp":"伊良湖岬","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Iragomisaki5.jpg",5686,3783,"恋路ヶ浜"],["c:2/25/Kunio_Yanagita.jpg",543,726,"柳田國男"]]},{"id":"23_morikoro","n":"愛・地球博記念公園（愛知万博の会場跡）","yomi":"あいちきゅうはくきねんこうえん","cat":"近代","rank":"B","y":2005,"era":["showa","heisei","reiwa"],"sh":"","ad":"長久手市茨ケ廻間","st":"リニモ «愛・地球博記念公園» 駅からすぐ","la":35.172,"lo":137.09,"hook":"185日間で2200万人。21世紀最初の万博が開かれた森は、いまジブリの世界へつながっている。","lead":"愛・地球博記念公園（モリコロパーク）は、2005年に開かれた日本国際博覧会 «愛・地球博»（愛知万博）の長久手会場の跡地にある公園です。もとは «愛知青少年公園» でした。会場で建てられた «サツキとメイの家» が残り、2022年にはジブリパークも開園しました。","story":["2005年3月25日、長久手の丘で «愛・地球博» が幕を開けました。テーマは «自然の叡智»。地球の環境をどう守り、自然とどう付き合っていくか――それを世界の国々といっしょに考える、21世紀最初の万博でした。9月25日までの185日間に、約2200万人もの人が訪れました。","じつは万博の会場は、はじめ瀬戸市の «海上の森» に予定されていました。ところが、森で絶滅のおそれのあるオオタカの巣が見つかります。«自然を大切にする万博が、森をこわしていいの?» 大きな議論がおこり、計画は見直されました。こうして、もとからあった愛知青少年公園がメイン会場になったのです。","会場には、世界の国々のパビリオンが並び、未来の乗り物やロボットが話題を集めました。マスコットの «モリゾー» と «キッコロ» は森の精。万博の会場を結んだ磁気浮上式の «リニモ» は、日本で初めての常設の磁気浮上式鉄道として、今も走り続けています。","会場で大人気だったのが、映画『となりのトトロ』に出てくる «サツキとメイの家» です。昭和の古い家を、細かいところまで本物そっくりに再現した建物で、万博が終わったあとも公園に残されました。まるで映画の中に入りこんだような家に、多くの人が足を運び続けました。","万博のあと、公園は «愛・地球博記念公園» として生まれ変わり、愛称 «モリコロパーク» で親しまれています。2022年11月には公園の中に «ジブリパーク» が開園し、再び世界から人が集まる場所になりました。自然を大切にしようという万博の願いは、森と遊びがとけあう公園の中に、今も生き続けています。"],"tl":[["1970年","愛知青少年公園が開園"],["1997年","2005年の万博の開催地が愛知に決まる"],["2000年ごろ","海上の森の計画が見直され、青少年公園がメイン会場に"],["2005年","愛・地球博（3月25日〜9月25日）"],["2006年","愛・地球博記念公園として再オープン"],["2022年","ジブリパークが開園"]],"who":[["モリゾーとキッコロ","万博のマスコット。森の精"],["宮崎駿","«サツキとメイの家» の元になった映画『となりのトトロ』の監督"],["万博を訪れた人々","185日間で約2200万人"]],"deep":["愛・地球博の正式名は «2005年日本国際博覧会»。長久手会場と瀬戸会場の2会場で開かれました。","入場者数は目標の1500万人を大きく上回る約2200万人でした。1970年の大阪万博（約6400万人）に比べると少ないものの、大成功とされています。","海上の森でオオタカの営巣が確認されたことは、会場計画見直しの大きなきっかけとなり、万博と環境保全を考える象徴的な出来事になりました。","リニモ（愛知高速交通東部丘陵線）は万博にあわせて2005年に開業した、日本初の常設の磁気浮上式リニアモーターカーの営業路線です。","«サツキとメイの家» は、昭和初期の建築技術や古材を使って建てられ、万博後も公園の中で公開されてきました。現在はジブリパークの一部となっています。","公園内には万博当時の «グローバル・ループ» の一部や、日本館の跡など、万博の名残をいくつか見ることができます。"],"look":["サツキとメイの家（ジブリパークの予約が必要）","万博の名残（グローバル・ループの一部など）","リニモの車両と駅","公園の森と池（自然の叡智のテーマを感じる）"],"q":["愛・地球博のメイン会場が、最初の予定地 «海上の森» から変わったきっかけは？","森でオオタカの巣が見つかったこと。自然保護のため計画が見直されました。"],"koji":[],"myth":"","img":["2005年日本国際博覧会","ジブリパーク","リニモ"],"wp":"愛・地球博記念公園","rel":{"ev":["aichi05"],"grave":[]},"ph":[["c:f/fb/%E3%83%A2%E3%83%AA%E3%82%B3%E3%83%AD%E3%83%91%E3%83%BC%E3%82%AF1.JPG",1600,1200,"愛・地球博記念公園"],["c:d/d6/Expo_2005_in_Nagakute_01.jpg",1280,960,"2005年日本国際博覧会"],["c:b/ba/Linimo-2.jpg",721,450,"リニモ"]]}];
